  `error_text` longtext,
  `executed_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`run_checkpoint_id`,`run_month`),
  UNIQUE KEY `uq_run_checkpoint` (`run_id`,`run_month`,`checkpoint_id`)
