re substr(version,1,4) > \'12.1\'','== 1','','select version from v$instance','The installed Oracle  version is in acceptable version\r\n','The installed Oracle  version is not acceptable version ; it  is recommended that you upgrade this oracle instance to  at least 12.2 or higher version.','pass',NULL,NULL,'2026-01-01 12:47:09'),(46,202601,3,90,'AA_Oracle_330_11_No Authorization to GRANT ANY ROLE','critical','OTHER','This test checks for grants of system privilege \'GRANT ANY ROLE\' to unauthorized grantees.  This privilege can allow unauthorized user to access or modify confidential data. This capability should be restricted.    CIS: 5.2.15','','SELECT count(*)   FROM DBA_SYS_PRIVS   WHERE PRIVILEGE=\'GRANT ANY ROLE\'   AND GRANTEE NOT IN  (   \'MF_DBSPI\',   \'ANONYMOUS\',   \'CTXSYS\',   \'DBSNMP\',   \'EXFSYS\',   \'LBACSYS\',   \'MDSYS\',   \'MGMT_VIEW\',   \'OLAPSYS\',   \'OWBSYS\',   \'ORDPLUGINS\',   \'ORDSYS\',   \'OUTLN\',   \'SI_INFORMTN_SCHEMA\',   \'SYS\',   \'SYSMAN\',   \'SYSTEM\',   \'TSMSYS\',   \'WK_TEST\',   \'WKSYS\',   \'WKPROXY\',   \'WMSYS\',   \'XDB\',   \'APEX_PUBLIC_USER\',   \'DIP\',   \'FLOWS_30000\',   \'FLOWS_FILES\',   \'MDDATA\',   \'ORACLE_OCM\',   \'SPATIAL_CSW_ADMIN_USR\',   \'SPATIAL_WFS_ADMIN_USR\',   \'XS$NULL\',   \'OWBSYS_AUDIT\',   \'ORDDATA\',   \'APEX_030200\',   \'APPQOSSYS\',   \'DVSYS\',   \'DVF\',   \'CONNECT\',   \'RESOURCE\',   \'DBA\',   \'PDB_DBA\',   \'AUDIT_ADMIN\',   \'AUDIT_VIEWER\',   \'SELECT_CATALOG_ROLE\',   \'EXECUTE_CATALOG_ROLE\',   \'CAPTURE_ADMIN\',   \'EXP_FULL_DATABASE\',   \'IMP_FULL_DATABASE\',   \'CDB_DBA\',   \'APPLICATION_TRACE_VIEWER\',   \'LOGSTDBY_ADMINISTRATOR\',   \'DBFS_ROLE\',   \'GSMUSER_ROLE\',   \'GSMROOTUSER_ROLE\',   \'AQ_ADMINISTRATOR_ROLE\',   \'AQ_USER_ROLE\',   \'DATAPUMP_EXP_FULL_DATABASE\',   \'DATAPUMP_IMP_FULL_DATABASE\',   \'ADM_PARALLEL_EXECUTE_TASK\',   \'PROVISIONER\',   \'XS_SESSION_ADMIN\',   \'XS_NAMESPACE_ADMIN\',   \'XS_CACHE_ADMIN\',   \'XS_CONNECT\',   \'GATHER_SY