_privs where grantee =\'PUBLIC\'                AND OWNER NOT IN              (   \'MF_DBSPI\',   \'ANONYMOUS\',   \'CTXSYS\',   \'DBSNMP\',   \'EXFSYS\',   \'LBACSYS\',   \'MDSYS\',   \'MGMT_VIEW\',   \'OLAPSYS\',   \'OWBSYS\',   \'ORDPLUGINS\',   \'ORDSYS\',   \'OUTLN\',   \'SI_INFORMTN_SCHEMA\',   \'SYS\',   \'SYSMAN\',   \'SYSTEM\',   \'TSMSYS\',   \'WK_TEST\',   \'WKSYS\',   \'WKPROXY\',   \'WMSYS\',   \'XDB\',   \'APEX_PUBLIC_USER\',   \'DIP\',   \'FLOWS_30000\',   \'FLOWS_FILES\',   \'MDDATA\',   \'ORACLE_OCM\',   \'SPATIAL_CSW_ADMIN_USR\',   \'SPATIAL_WFS_ADMIN_USR\',   \'XS$NULL\',   \'OWBSYS_AUDIT\',   \'ORDDATA\',   \'APEX_030200\',   \'APPQOSSYS\',   \'DVSYS\',   \'DVF\',   \'CONNECT\',   \'RESOURCE\',   \'DBA\',   \'PDB_DBA\',   \'AUDIT_ADMIN\',   \'AUDIT_VIEWER\',   \'SELECT_CATALOG_ROLE\',   \'EXECUTE_CATALOG_ROLE\',   \'CAPTURE_ADMIN\',   \'EXP_FULL_DATABASE\',   \'IMP_FULL_DATABASE\',   \'CDB_DBA\',   \'APPLICATION_TRACE_VIEWER\',   \'LOGSTDBY_ADMINISTRATOR\',   \'DBFS_ROLE\',   \'GSMUSER_ROLE\',   \'GSMROOTUSER_ROLE\',   \'AQ_ADMINISTRATOR_ROLE\',   \'AQ_USER_ROLE\',   \'DATAPUMP_EXP_FULL_DATABASE\',   \'DATAPUMP_IMP_FULL_DATABASE\',   \'ADM_PARALLEL_EXECUTE_TASK\',   \'PROVISIONER\',   \'XS_SESSION_ADMIN\',   \'XS_NAMESPACE_ADMIN\',   \'XS_CACHE_ADMIN\',   \'XS_CONNECT\',   \'GATHER_SYSTEM_STATISTICS\',   \'OPTIMIZER_PROCESSING_RATE\',   \'DBMS_MDX_INTERNAL\',   \'BDSQL_ADMIN\',   \'BDSQL_USER\',   \'RECOVERY_CATALOG_OWNER\',   \'RECOVERY_CATALOG_OWNER_VPD\',   \'RECOVERY_CATALOG_USER\',   \'EM_EXPRESS_BASIC\',   \'EM_EXPRESS_ALL\',   \'SYSUMF_ROLE\',   \'SCHEDULER_ADMIN\',   \'HS_ADMIN_SELECT_ROLE\',   \'HS_ADMIN_EXECUTE_ROLE\',   \'HS_ADMIN_ROLE\',   \'GLOBAL_AQ_USER_ROLE\',   \'OEM_ADVISOR\',   \'OEM_MONITOR\',   \'GSMADMIN_ROLE\',   \'GSM_POOLADMIN_ROLE\',   \'GDS_CATALOG_SELECT\',   \'GGSYS_ROLE\',   \'XDBADMIN\',   \'XDB_SET_INVOKER\',   \'AUTHENTICATEDUSER\',   \'XDB_WEBSERVICES\',   \'XDB_WEBSERVICES_WITH_PUBLIC\',   \'XDB_WEBSERVICES_OVER_HTTP\',   \'SODA_APP\',   \'DATAPATCH_ROLE\',   \'WM_ADMIN_ROLE\',   \'JAVAUSERPRIV\',   \'JAVAIDPRIV\',   \'JAVASYSPRIV\',   \'JAVADEBUGPRIV\',   \'EJBCLIENT\',   \'JMXSERVER\',   \'DBJAVASCRIPT\',   \'JAVA_ADMIN\',   \'CTXAPP\',   \'ORDADMIN\',   \'OLAP_XS_ADMIN\',   \'OLAP_DBA\',   \'OLAP_USER\',   \'RDFCTX_ADMIN\',   \'LBAC_DBA\',   \'DV_REALM_RESOURCE\',   \'DV_REALM_OWNER\',   \'APEX_ADMINISTRATOR_READ_ROLE\',   \'APEX_ADMINISTRATOR_ROLE\',   \'APEX_GRANTS_FOR_NEW_USERS_ROLE\',   \'DV_ACCTMGR\',   \'DV_OWNER\',   \'DV_ADMIN\',   \'DV_SECANALYST\',   \'DV_PUBLIC\',   \'DV_PATCH_ADMIN\',   \'DV_MONITOR\',   \'DV_STREAMS_ADMIN\',   \'DV_GOLDENGATE_ADMIN\',   \'DV_XSTREAM_ADMIN\',   \'DV_GOLDENGATE_REDO_ACCESS\',   \'DV_AUDIT_CLEANUP\',   \'DV_DATAPUMP_NETWORK_LINK\',   \'DV_POLICY_OWNER\',   \'GSMADMIN_INTERNAL\'   )   AND OWNER not like \'APEX%\'   AND TABLE_NAME NOT LIKE (\'TOAD_PLAN%\')   ','There is no any object privilege which is granted to PUBLIC role\r','There are some object privileges which are granted to PUBLIC role. Revoke all these privileges','pass',NULL,NULL,'2026-01-01 18:38:46'),(148,202601,5,107,'AA_Oracle_440_12_object privileges granted to PUBLIC role','critical','OTHER','Permissions on objects may be granted to the user group PUBLIC. Because every database user is a member of the PUBLIC group, granting object permissions to PUBLIC gives all users in the database access to that object. In a secure environment, granting object permissions to PUBLIC should be restricted to those objects that all users are allowed to access. The policy does not require object permissions assigned to PUBLIC by the installation of Oracle Database server components be revoked. Object permissions granted to PUBLIC should be restricted.','','SELECT count(*)     FROM dba_tab_privs where grantee =\'PUBLIC\'             AND OWNER NOT IN (SELECT USERNAME                                FROM DBA_USERS                               WHERE ORACLE_MAINTAINED = \'Y\')          AND OWNER NOT IN (SELECT ROLE                                FROM DBA_ROLES                               WHERE ORACLE_MAINTAINED = \'Y\')          AND TABLE_NAME NOT IN (\'TOAD_PLAN_TABLE\', \'TOAD_PLAN_SQL\')         AND OWNER NOT LIKE \'APEX%\'','== 0','','select  \'OWNER :\'||OWNER||\' TABLE NAME : \'||TABLE_NAME     FROM dba_tab_privs where grantee =\'PUBLIC\'             AND OWNER NOT IN (SELECT USERNAME                                FROM DBA_USERS                               WHERE ORACLE_MAINTAINED = \'Y\')          AND OWNER NOT IN (SELECT ROLE                                FROM DBA_ROLES                               WHERE ORACLE_MAINTAINED = \'Y\')          AND TABLE_NAME NOT IN (\'TOAD_PLAN_TABLE\',\'TOAD_PLAN_SQL\')          AND OWNER NOT LIKE \'APEX%\'','There is no any object privilege which is granted to PUBLIC role\r','There are some object privileges which are granted to PUBLIC role. Revoke all these privileges','pass',NULL,NULL,'2026-01-01 18:38:46'),(149,202601,5,109,'AA_Oracle_460_Minimum SYSDBA privilege assignment','critical','OTHER','Oracle SYSDBA privileges include privileges to administer the database outside of database controls (when the database is shut down or open in restricted mode). These privileges are in addition to all privileges controlled under database operation. Assignment of SYSDBA privileges in the Oracle password file to unauthorized persons can compromise all DBMS activities. ','','SELECT count(*)     FROM v$pwfile_users    WHERE     SYSDBA = \'TRUE\'          AND username NOT IN (\'SYS\',                               \'SYSTEM\',                               \'RCAKIR\',                               \'MERCAKMAK\',                               \'OELMAS\',                               \'OZENGINBA\',                               \'BGDB\',\'SRV_MXEOD\',\'OBA12609\',\'OBA12854\',\'OBA12656\')','== 0','','SELECT username     FROM v$pwfile_users    WHERE     SYSDBA = \'TRUE\'          AND username NOT IN (\'SYS\',                               \'SYSTEM\',                                \'RCAKIR\',                               \'MERCAKMAK\',                               \'OELMAS\',                               \'OZENGINBA\',                               \'BGDB\',\'SRV_MXEOD\',\'OBA12609\',\'OBA12854\', \'OBA12656\')','SYSDBA role is assigned to correct users.\r','SYSDBA role is not  assigned to correct users. Revoke the unnecessary users','pass',NULL,NULL,'2026-01-01 18:38:46'),(150,202601,5,110,'AA_Oracle_470_AUDIT_SYS_OPERATIONS parameter','critical','OTHER','The AUDIT_SYS_OPERATIONS parameter is used to enable auditing of actions taken by the user SYS. The SYS user account is a shared account by definition and holds all privileges in the Oracle database. It is the account accessed by users connecting to the database with SYSDBA or SYSOPER privileges.','','select count(*)  from v$parameter where name = \'audit_sys_operations\' and value=\'TRUE\'','== 1','','select value from v$parameter where name = \'audit_sys_operations\'','AUDIT_SYS_OPERATIONS parameter is correctly set.\r','AUDIT_SYS_OPERATIONS parameter is not correctly set.  Set this Parameter to TRUE','pass',NULL,NULL,'2026-01-01 18:38:46'),(151,202601,5,113,'AA_Oracle_490_PUBLIC DB Links','critical','OTHER','This test checks for PUBLIC DB links. All users can use Public DB links without any grants. Therefore Public DB links usage should not be used','','SELECT COUNT (*)     FROM DBA_DB_LINKS    WHERE OWNER = \'PUBLIC\' AND USERNAME IS NOT NULL','== 0','','SELECT    \'OWNER: \'          || OWNER          || \' DB_LINK : \'          || DB_LINK          || \'  USERNAME : \'          || USERNAME          || \'  HOST : \'          || HOST     FROM DBA_DB_LINKS    WHERE OWNER = \'PUBLIC\' AND USERNAME IS NOT NULL','Public DB link is not found in the database.\r','Some public DB links are found in the database. These links should be removed.','pass',NULL,NULL,'2026-01-01 18:38:46'),(152,202601,5,115,'AA_Oracle_505_Personal user DB links','critical','OTHER','This test checks for DB links which are defined in personal users. Personal users should not have any DB links.','','select count(*) from dba_db_links where   owner in (   \'AOZCAM\',   \'BACOSKUN\',   \'BASEZGIN\',   \'BECE\',   \'BKOCADAG\',   \'BTIMUR\',   \'COZBAKAN\',   \'CZGHEIB\',   \'DAKSOY\',   \'DISIK\',   \'DKAHRAMANL\',   \'EALGUL\',   \'EARTUC\',   \'EGURLEYEN\',   \'EOZKAL\',   \'EZCALIS\',   \'FHELVACIOG\',   \'FLOGOGLU\',   \'FSSARIKAYA\',   \'HBINGOL\',   \'HCENGIZ\',   \'HTOPTAS\',   \'HYASSIBAS_EM\',   \'IDEMIRTAS\',   \'JNASR\',   \'KABICHEDID\',   \'KKALAANY\',   \'KKARAGOZ\',   \'MEVREN\',   \'MSUSAKLI\',   \'MUSSIMSEK\',   \'NAKSOY\',   \'NOYAT\',   \'OBAYDIN\',   \'OFSACIOBANU\',   \'OFSACOLNICEANU\',   \'OFSAMARASOIU\',   \'OFSAMIHAI\',   \'OFSANICULAE\',   \'OFSAOHII\',   \'OFSAPANTILIE\',   \'OKARACA\',   \'OMCETIN\',   \'ONBOZKAYA\',   \'OPERCIN\',   \'OSARICAOGL\',   \'OYURDUSEV\',   \'OZGDURAK\',   \'PEKMEKCI\',   \'PIYALDIZ\',   \'SBAYRAKTAR\',   \'SDESEN\',   \'SEONEY\',   \'SKIZILKAYA\',   \'SOFLAS\',   \'SOZORAL\',   \'SSAROHAN\',   \'SSUSLER\',   \'TAKTURK\',   \'TKASDAS\',   \'TSAYAN\',   \'TUVURAL\',   \'UEMRE\',   \'VDEMIR\',   \'YBOZCAM\',   \'EOGRETEN\',   \'OZENGINBA\',   \'OELMAS\',   \'MERCAKMAK\')   ','== 0','','SELECT    \'OWNER: \'          || OWNER          || \' DB_LINK : \'          || DB_LINK          || \'  USERNAME : \'          || USERNAME          || \'  HOST : \'          || HOST    from dba_db_links     where  owner in (   \'AOZCAM\',   \'BACOSKUN\',   \'BASEZGIN\',   \'BECE\',   \'BKOCADAG\',   \'BTIMUR\',   \'COZBAKAN\',   \'CZGHEIB\',   \'DAKSOY\',   \'DISIK\',   \'DKAHRAMANL\',   \'EALGUL\',   \'EARTUC\',   \'EGURLEYEN\',   \'EOZKAL\',   \'EZCALIS\',   \'FHELVACIOG\',   \'FLOGOGLU\',   \'FSSARIKAYA\',   \'HBINGOL\',   \'HCENGIZ\',   \'HTOPTAS\',   \'HYASSIBAS_EM\',   \'IDEMIRTAS\',   \'JNASR\',   \'KABICHEDID\',   \'KKALAANY\',   \'KKARAGOZ\',   \'MEVREN\',   \'MSUSAKLI\',   \'MUSSIMSEK\',   \'NAKSOY\',   \'NOYAT\',   \'OBAYDIN\',   \'OFSACIOBANU\',   \'OFSACOLNICEANU\',   \'OFSAMARASOIU\',   \'OFSAMIHAI\',   \'OFSANICULAE\',   \'OFSAOHII\',   \'OFSAPANTILIE\',   \'OKARACA\',   \'OMCETIN\',   \'ONBOZKAYA\',   \'OPERCIN\',   \'OSARICAOGL\',   \'OYURDUSEV\',   \'OZGDURAK\',   \'PEKMEKCI\',   \'PIYALDIZ\',   \'SBAYRAKTAR\',   \'SDESEN\',   \'SEONEY\',   \'SKIZILKAYA\',   \'SOFLAS\',   \'SOZORAL\',   \'SSAROHAN\',   \'SSUSLER\',   \'TAKTURK\',   \'TKASDAS\',   \'TSAYAN\',   \'TUVURAL\',   \'UEMRE\',   \'VDEMIR\',   \'YBOZCAM\',   \'EOGRETEN\',   \'OZENGINBA\',   \'OELMAS\',   \'MERCAKMAK\')   ','Personal users have not any DB links\r','Some personal users have DB links These links should be removed.','pass',NULL,NULL,'2026-01-01 18:38:46'),(153,202601,5,116,'AA_Oracle_510_DBA role','critical','OTHER','This test checks for DBA role grants. Only Database administrators could have this role. Other users should not have this priviliged','','SELECT COUNT (C.DBA_USER)     FROM (SELECT DISTINCT GRANTEE     DBA_USER             FROM (    SELECT DISTINCT LEVEL LEVEL_DEEP, GRANTEE, GRANTED_ROLE                         FROM DBA_ROLE_PRIVS                   START WITH GRANTED_ROLE = \'DBA\'                   CONNECT BY PRIOR GRANTEE = GRANTED_ROLE)            WHERE GRANTEE IN (SELECT USERNAME FROM DBA_USERS)) C,          DBA_USERS  B    WHERE     C.DBA_USER = B.USERNAME          AND USERNAME NOT IN (\'SYSTEM\',                               \'SYS\',                               \'BGDB\',                               \'MERCAKMAK\',                               \'OZENGINBA\',                               \'RCAKIR\',                               \'OELMAS\',                               \'NAKSOY\',                                \'ODI_DBA\', \'SCH2\',                                \'ODI_DBA\', \'OFSAEPM\',\'OBA12609\',\'OBA12854\',\'OBA12656\'   )','== 0','','SELECT C.DBA_USER  FROM   (    SELECT DISTINCT GRANTEE DBA_USER   FROM ( SELECT DISTINCT LEVEL LEVEL_DEEP, GRANTEE, GRANTED_ROLE   FROM DBA_ROLE_PRIVS   START WITH GRANTED_ROLE = \'DBA\'   CONNECT BY PRIOR GRANTEE = GRANTED_ROLE)   WHERE GRANTEE IN (SELECT USERNAME FROM DBA_USERS) )    C , DBA_USERS B   WHERE   C.DBA_USER=B.USERNAME     AND USERNAME NOT IN (\'SYSTEM\',                               \'SYS\',                               \'BGDB\',                               \'MERCAKMAK\',                               \'OZENGINBA\',                               \'RCAKIR\',                               \'OELMAS\',                               \'NAKSOY\',                                \'ODI_DBA\', \'SCH2\',                                \'ODI_DBA\', \'OFSAEPM\',\'OBA12609\',\'OBA12854\',\'OBA12656\'   )','DBA role is assigned to admin users\r','DBA role is not assigned to asmin users. Please revoke DBA role from these users','fail','SQL_DETAIL OUTPUT\n\nDBA_USER\n--------\nDBVULSCAN',NULL,'2026-01-01 18:38:46'),(154,202601,5,118,'AA_Oracle_520_Oracle  Object privileges for Developers and Analysts','critical','OTHER','Production databases should be protected from unauthorized access by developers on shared production/development host systems. Developers should not have object privileges except SELECT privilege.','','SELECT count(*)     FROM dba_tab_privs    WHERE     privilege IN (\'INSERT\',                            \'UPDATE\',                            \'DELETE\',                            \'ALTER\',                            \'EXECUTE\',                            \'DROP\',                            \'WRITE\',                            \'READ\')          AND grantee IN (\'AOZCAM\',                          \'BACOSKUN\',                          \'BASEZGIN\',                          \'BECE\',                          \'BKOCADAG\',                          \'BTIMUR\',                          \'COZBAKAN\',                          \'CZGHEIB\',                          \'DAKSOY\',                          \'DISIK\',                          \'