rs    WHERE     default_tablespace IN (\'SYSTEM\', \'SYSAUX\')          AND username NOT IN (SELECT USERNAME                                 FROM DBA_USERS                                WHERE ORACLE_MAINTAINED = \'Y\')   AND username not like \'APEX%\'   ','Default Tablespaces are correctly set.\r','Default Tablespaces are  not correctly set. Some app user deafult tablespace is set to SYTEM or SYSAUX','pass',NULL,NULL,'2026-01-03 08:36:13'),(221,202601,6,45,'AA_Oracle_001_Version','critical','PRIV','This test cheks Database version whether is acceptable version.','drop table DBVULSCAN_TMP_USERS\r\n','select count(substr(version,1,4)) from v$instance  where substr(version,1,4) > \'12.1\'','== 1','create table DBVULSCAN_TMP_USERS AS SELECT * FROM DUAL','select version from v$instance','The installed Oracle  version is in acceptable version\r\n','The installed Oracle  version is not acceptable version ; it  is recommended that you upgrade this oracle instance to  at least 12.2 or higher version.','error',NULL,'ORA-00942: table or view does not exist\nHelp: https://docs.oracle.com/error-help/db/ora-00942/','2026-01-03 08:36:13'),(222,202601,7,90,'AA_Oracle_330_11_No Authorization to GRANT ANY ROLE','critical','OTHER','This test checks for grants of system privilege \'GRANT ANY ROLE\' to unauthorized grantees.  This privilege can allow unauthorized user to access or modify confidential data. This capability should be restricted.    CIS: 5.2.15','','SELECT count(*)   FROM DBA_SYS_PRIVS   WHERE PRIVILEGE=\'GRANT ANY ROLE\'   AND GRANTEE NOT IN  (   \'MF_DBSPI\',   \'ANONYMOUS\',   \'CTXSYS\',   \'DBSNMP\',   \'EXFSYS\',   \'LBACSYS\',   \'MDSYS\',   \'MGMT_VIEW\',   \'OLAPSYS\',   \'OWBSYS\',   \'ORDPLUGINS\',   \'ORDSYS\',   \'OUTLN\',   \'SI_INFORMTN_SCHEMA\',   \'SYS\',   \'SYSMAN\',   \'SYSTEM\',   \'TSMSYS\',   \'WK_TEST\',   \'WKSYS\',   \'WKPROXY\',   \'WMSYS\',   \'XDB\',   \'APEX_PUBLIC_USER\',   \'DIP\',   \'FLOWS_30000\',   \'FLOWS_FILES\',   \'MDDATA\',   \'OR