              \'SSAROHAN\',                                                 \'SSUSLER\',                                                 \'TAKTURK\',                                                 \'TKASDAS\',                                                 \'TSAYAN\',                                                 \'TUVURAL\',                                                 \'UEMRE\',                                                 \'VDEMIR\',                                                 \'YBOZCAM\'))          AND PRIVILEGE not in ( \'SELECT\',\'READ\',\'EXECUTE\')','== 0','','SELECT  \'Grantee : \'||GRANTEE||\' Owner : \'||OWNER||\' Table Name : \'||TABLE_NAME||\' Privilige \'||PRIVILEGE     FROM DBA_TAB_PRIVS    WHERE     GRANTEE IN (SELECT DISTINCT GRANTED_ROLE                            FROM DBA_ROLE_PRIVS                             WHERE     GRANTED_ROLE NOT IN (\'CONNECT\')                                 AND GRANTEE IN (\'AOZCAM\',                                                 \'BACOSKUN\',                                                 \'BASEZGIN\',                                                 \'BECE\',                                                 \'BKOCADAG\',                                                 \'BTIMUR\',                                                 \'COZBAKAN\',                                                 \'CZGHEIB\',                                                 \'DAKSOY\',                                                 \'DISIK\',                                                 \'DKAHRAMANL\',                                                 \'EALGUL\',                                                 \'EARTUC\',                                                 \'EGURLEYEN\',                                                 \'EOZKAL\',                                                 \'EZCALIS\',                                                 \'FHELVACIOG\',                                                 \'FLOGOGLU\', 