  \'CDB_DBA\',   \'APPLICATION_TRACE_VIEWER\',   \'LOGSTDBY_ADMINISTRATOR\',   \'DBFS_ROLE\',   \'GSMUSER_ROLE\',   \'GSMROOTUSER_ROLE\',   \'AQ_ADMINISTRATOR_ROLE\',   \'AQ_USER_ROLE\',   \'DATAPUMP_EXP_FULL_DATABASE\',   \'DATAPUMP_IMP_FULL_DATABASE\',   \'ADM_PARALLEL_EXECUTE_TASK\',   \'PROVISIONER\',   \'XS_SESSION_ADMIN\',   \'XS_NAMESPACE_ADMIN\',   \'XS_CACHE_ADMIN\',   \'XS_CONNECT\',   \'GATHER_SYSTEM_STATISTICS\',   \'OPTIMIZER_PROCESSING_RATE\',   \'DBMS_MDX_INTERNAL\',   \'BDSQL_ADMIN\',   \'BDSQL_USER\',   \'RECOVERY_CATALOG_OWNER\',   \'RECOVERY_CATALOG_OWNER_VPD\',   \'RECOVERY_CATALOG_USER\',   \'EM_EXPRESS_BASIC\',   \'EM_EXPRESS_ALL\',   \'SYSUMF_ROLE\',   \'SCHEDULER_ADMIN\',   \'HS_ADMIN_SELECT_ROLE\',   \'HS_ADMIN_EXECUTE_ROLE\',   \'HS_ADMIN_ROLE\',   \'GLOBAL_AQ_USER_ROLE\',   \'OEM_ADVISOR\',   \'OEM_MONITOR\',   \'GSMADMIN_ROLE\',   \'GSM_POOLADMIN_ROLE\',   \'GDS_CATALOG_SELECT\',   \'GGSYS_ROLE\',   \'XDBADMIN\',   \'XDB_SET_INVOKER\',   \'AUTHENTICATEDUSER\',   \'XDB_WEBSERVICES\',   \'XDB_WEBSERVICES_WITH_PUBLIC\',   \'XDB_WEBSERVICES_OVER_HTTP\',   \'SODA_APP\',   \'DATAPATCH_ROLE\',   \'WM_ADMIN_ROLE\',   \'JAVAUSERPRIV\',   \'JAVAIDPRIV\',   \'JAVASYSPRIV\',   \'JAVADEBUGPRIV\',   \'EJBCLIENT\',   \'JMXSERVER\',   \'DBJAVASCRIPT\',   \'JAVA_ADMIN\',   \'CTXAPP\',   \'ORDADMIN\',   \'OLAP_XS_ADMIN\',   \'OLAP_DBA\',   \'OLAP_USER\',   \'RDFCTX_ADMIN\',   \'LBAC_DBA\',   \'DV_REALM_RESOURCE\',   \'DV_REALM_OWNER\',   \'APEX_ADMINISTRATOR_READ_ROLE\',   \'APEX_ADMINISTRATOR_ROLE\',   \'APEX_GRANTS_FOR_NEW_USERS_ROLE\',   \'DV_ACCTMGR\',   \'DV_OWNER\',   \'DV_ADMIN\',   \'DV_SECANALYST\',   \'DV_PUBLIC\',   \'DV_PATCH_ADMIN\',   \'DV_MONITOR\',   \'DV_STREAMS_ADMIN\',   \'DV_GOLDENGATE_ADMIN\',   \'DV_XSTREAM_ADMIN\',   \'DV_GOLDENGATE_REDO_ACCESS\',   \'DV_AUDIT_CLEANUP\',   \'DV_DATAPUMP_NETWORK_LINK\',   \'DV_POLICY_OWNER\',   \'DBSFWUSER\',   \'GGSYS\',   \'OJVMSYS\',   \'GSMADMIN_INTERNAL\',   \'SYS$UMF\'   )   AND username not like \'APEX%\'   ','Default Tablespaces are correctly set.\r','Default Tablespaces are  not correctly set. Some app user deafult tablespace is set to SYTEM or SYSAUX','pass',NULL,NULL,'2026-01-10 14:29:12'),(352,202601,11,76,'AA_Oracle_240_12_Oracle default tablespace assignment','major','OTHER','The Oracle SYSTEM and SYSAUX  tablespace is used by the database to store all DBMS system objects. Other use of the system tablespace may compromise system availability and the effectiveness of host system access controls to the tablespace files.  This test excludes default object owners from a predefined Guardium group called \"Oracle exclude default system grantees\".','','SELECT  count(*)     FROM dba_users    WHERE     default_tablespace IN (\'SYSTEM\', \'SYSAUX\')          AND username NOT IN (SELECT USERNAME                                 FROM DBA_USERS                                WHERE ORACLE_MAINTAINED = \'Y\')   AND username not like \'APEX%\'','== 0','','SELECT username||\'  \'||default_tablespace     FROM dba_users    WHERE     default_tablespace IN (\'SYSTEM\', \'SYSAUX\')          AND username NOT IN (SELECT USERNAME                                 FROM DBA_USERS                                WHERE ORACLE_MAINTAINED = \'Y\')   AND username not like \'APEX%\'   ','Default Tablespaces are correctly set.\r','Default Tablespaces are  not correctly set. Some app user deafult tablespace is set to SYTEM or SYSAUX','pass',NULL,NULL,'2026-01-10 14:29:12'),(353,202601,11,45,'AA_Oracle_001_Version','critical','PRIV','This test cheks Database version whether is acceptable version.','\r\n','select count(substr(version,1,4)) from v$instance  where substr(version,1,4) > \'12.1\'','== 1','','select version from v$instance','The installed Oracle  version is in acceptable version\r\n','The installed Oracle  version is not acceptable version ; it  is recommended that you upgrade this oracle instance to  at least 12.2 or higher version.','pass',NULL,NULL,'2026-01-10 14:29:12');
