E(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'\r\nAND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')\r\nAND STATE_DESC=\'\'\'\'GRANT\'\'\'\'\r\n;\r\n\'\'\r\nselect count(*) from #TEMP;\r\n\'','== 0','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP ( row varchar(500));\r\n\r\nexec sp_MSforeachdb \'\'\r\nUSE [?]\r\niNSERT iNTO #TEMP\r\nSELECT\r\n\'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +\r\n\'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +\r\n\'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +\r\n\'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )\r\nFROM\r\nsys.database_permissions\r\nWHERE\r\nUSER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'guest\'\'\'\' )\r\nAND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'\r\nAND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')\r\nAND STATE_DESC=\'\'\'\'GRANT\'\'\'\'\r\n;\r\n\'\'\r\nselect * from #TEMP;\r\n\'','There are no permissions which are assigned to guest.\r\n','There are some persmissions which are assigned to guest\r\n','pass',NULL,NULL,'2026-01-22 15:15:23'),(1110,202601,28,31,'AA_SqlServer_240_guest Database Permissions','critical','PRIV','This test checks database permisions for guest . guest is a special user and permissions should not be granted to guest user.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      exec sp_msforeachdb \'\'   USE [?]     iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'guest\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select count(*) from #TEMP;   \' \r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      exec sp_msforeachdb \'\'   USE [?]     iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'guest\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select  *  from #TEMP;   \' \r\n','There are no permissions which are assigned to guest.\r\n','There are some persmissions which are assigned to guest\r\n','pass',NULL,NULL,'2026-01-22 15:15:23'),(1111,202601,28,32,'AA_SqlServer_250_Database Role members for guest','critical','PRIV','This test checks database role members for guest  user. Database roles  could not be assigned to guest role.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      EXEC sp_MSforeachdb \'\' USE [?]    INSERT INTO #TEMP   SELECT \'\'\'\'DB Name : \'\'\'\'+Cast (DB_NAME() as varchar)+\'\'\'\' Role Name : \'\'\'\'+USER_NAME(role_principal_id)  +\'\'\'\' User Name \'\'\'\'+  USER_NAME(member_principal_id)    from  sys.database_role_members   	Where     USER_NAME(member_principal_id)  = \'\'\'\'guest\'\'\'\'     ;   \'\'      Select count(*)  from #TEMP;   \'\r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      EXEC sp_MSforeachdb \'\' USE [?]    INSERT INTO #TEMP   SELECT \'\'\'\'DB Name : \'\'\'\'+Cast (DB_NAME() as varchar)+\'\'\'\' Role Name : \'\'\'\'+USER_NAME(role_principal_id)  +\'\'\'\' User Name \'\'\'\'+  USER_NAME(member_principal_id)    from  sys.database_role_members   	Where     USER_NAME(member_principal_id)  = \'\'\'\'guest\'\'\'\'     ;   \'\'      Select  *  from #TEMP;   \'\r\n','Database role member usage for guest user  is correct\r\n','Database role member usage for guest user  is not correct\r\n','pass',NULL,NULL,'2026-01-22 15:15:23'),(1112,202601,28,33,'AA_SqlServer_260_SQL Logins with Null Password','critical','ACCOUNT','This test checks sql logins with null password. SQL Logins should not have null passwords.\r\n','','SELECT      count(name)   from      sys.sql_logins    WHERE      PWDCOMPARE(\'\', password_hash)= 1\r\n','== 0','','SELECT      name    from      sys.sql_logins    WHERE      PWDCOMPARE(\'\', password_hash)= 1   \r\n','There are no sql logins with null paswords\r\n','There are some sql logins with null passwords.\r\n','pass',NULL,NULL,'2026-01-22 15:15:23'),(1113,202601,28,34,'AA_SqlServer_270_SQL Logins with username and passwords are equal','critical','ACCOUNT','This test checks sql login password which are egual to username. Username and password must be different for SQL logins.\r\n','','SELECT      count(name)   from      sys.sql_logins    WHERE      PWDCOMPARE(name,password_hash)=1 \r\n','== 0','','SELECT      name    from      sys.sql_logins    WHERE      PWDCOMPARE(name,password_hash)=1    \r\n','There is no SQL login name which is equal to password.\r\n','There are some sql logins whose passwords are egual to usernames.\r\n','pass',NULL,NULL,'2026-01-22 15:15:23'),(1114,202601,28,35,'AA_SqlServer_280_No Sample Databases','critical','CONFIG','This test checks whether the sample databases created optionally on installation are present.  These sample databases contain many default permissions, and can be used as an entry point to your systems. \r\n','','select      count(name)    from      sys.databases    where      name in (       \'AdventureWorks\', \'AdventureWorksDW\',        \'Northwind\', \'Pubs\'     )   \r\n','== 0','','select      name    from      sys.databases    where      name in (       \'AdventureWorks\', \'AdventureWorksDW\',        \'Northwind\', \'Pubs\'     )   \r\n','There are no sample databases in the server\r\n','There are some sample databases in the server\r\n','pass',NULL,NULL,'2026-01-22 15:15:23'),(1115,202601,28,43,'AA_SqlServer_350_User Password Policy Is Checked','critical','ACCOUNT','This test checks that CHECK_POLICY is enabled for all users.  Enabling CHECK_POLICY ensures that Windows passwords policies are enforced.','','select count(*) from sys.sql_logins  \r\nwhere \r\nis_policy_checked=0 and\r\nname not like \'##%\'','== 0','','select name from sys.sql_logins  \r\nwhere \r\nis_policy_checked=0 and\r\nname not like \'##%\'','CHECK_POLICY is enabled for all users','CHECK_POLICY is not enabled for all users','pass',NULL,NULL,'2026-01-22 15:15:23'),(1116,202601,28,44,'AA_SqlServer_360_CHECK_EXPIRATION Is Checked','critical','ACCOUNT','This test checks that CHECK_EXPIRATION is enabled for all users.  Passwords that have been in use for long periods of time are likely to become known to unauthorized users.\r\n','','select count(*) from sys.sql_logins     where    is_expiration_checked=0 and   name not like \'##%\'\r\n','== 0','','select name from sys.sql_logins     where    is_expiration_checked=0 and   name not like \'##%\'\r\n','CHECK_EXPIRATION is enabled for all users\r\n','CHECK_EXPIRATION is not enabled for all users\r\n','fail','name\n----\n\'sa\'',NULL,'2026-01-22 15:15:23'),(1117,202601,28,22,'AA_SqlServer_170_Windows Authentication','major','AUTH','This test checks that the authentication mode is set to Windows authentication only.  Windows provides a more robust authentication mechanism than SQL Server authentication.','',' SELECT cast( SERVERPROPERTY(\'IsIntegratedSecurityOnly\') as int) ','==1','','SELECT cast( SERVERPROPERTY(\'IsIntegratedSecurityOnly\') as varchar)','The authentication mode is set to Windows authentication only. ','The authentication mode is not set to Windows authentication only.','fail','\n---\n\'0\'',NULL,'2026-01-22 15:15:23'),(1118,202601,28,23,'AA_SqlServer_180_No Guest User Accounts','major','ACCOUNT','This test checks for the existence of guest user accounts with CONNECT permission in database other than master, msdb and tempdb.  This test also exclude databases that are flagged as distributor. If the GUEST user exists and a specific login has not been granted to a database, a login will be mapped to GUEST. The presence of the GUEST user allows all logins to access the database.\r\n','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP  ( row int);\r\n\r\nEXEC sp_MSforeachdb \'\' USE [?]\r\n	INSERT INTO #TEMP\r\n	SELECT count(*) \r\n	FROM sys.database_permissions\r\n	WHERE [grantee_principal_id] = DATABASE_PRINCIPAL_ID(\'\'\'\'guest\'\'\'\')\r\n	AND [state_desc] LIKE \'\'\'\'GRANT%\'\'\'\'\r\n	AND [permission_name] = \'\'\'\'CONNECT\'\'\'\'\r\n	AND DB_NAME() NOT IN (\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'msdb\'\'\'\') ;\r\n\'\'\r\n\r\nSelect sum(row) from #TEMP;\r\ndrop table #TEMP;\r\n\'','== 0','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP  ( row varchar(500));\r\n\r\nEXEC sp_MSforeachdb \'\' USE  [?] \r\n	INSERT INTO #TEMP\r\n	SELECT \'\'\'\' DB NAME : \'\'\'\' + Cast (DB_NAME() as varchar) + \'\'\'\' guest user has CONNECT permission \'\'\'\'\r\n	FROM sys.database_permissions\r\n	WHERE [grantee_principal_id] = DATABASE_PRINCIPAL_ID(\'\'\'\'guest\'\'\'\')\r\n	AND [state_desc] LIKE \'\'\'\'GRANT%\'\'\'\'\r\n	AND [permission_name] = \'\'\'\'CONNECT\'\'\'\'\r\n	AND DB_NAME() NOT IN (\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'msdb\'\'\'\') ;\r\n\'\'\r\n\r\nSelect * from #TEMP;\r\ndrop table #TEMP;\r\n\'','There is no guest user with CONNECT permission. ','There are   guest users with CONNECT permission. Remove these users','pass',NULL,NULL,'2026-01-22 15:15:24'),(1119,202601,28,36,'AA_SqlServer_290_2_No Permissions with GRANT Option','major','PRIV','This test checks database permisions  with grant option. No permission with grant option should be defined in the database.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP ( row varchar(500));      exec sp_MSforeachdb \'\'   USE [?]   iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   STATE_DESC like \'\'\'\'%WITH_GRANT%\'\'\'\'   ;   \'\'   select count(*) from #TEMP;   \'\r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP ( row varchar(500));      exec sp_MSforeachdb \'\'   USE [?]   iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   STATE_DESC like \'\'\'\'%WITH_GRANT%\'\'\'\'   ;   \'\'   select * from #TEMP;   \'\r\n','There are no permissions with grant option.\r\n','There are some persmissions  with grant option.\r\n','pass',NULL,NULL,'2026-01-22 15:15:24'),(1120,202601,28,37,'AA_SqlServer_290_No Permissions with GRANT Option','major','PRIV','','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP  ( row varchar(500));\r\n\r\nexec sp_msforeachdb \'\'\r\nUSE [?]  \r\niNSERT iNTO #TEMP\r\nSELECT\r\n\'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +\r\n\'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +\r\n\'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +\r\n\'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )\r\nFROM\r\nsys.database_permissions\r\nWHERE\r\nSTATE_DESC like \'\'\'\'%WITH_GRANT%\'\'\'\'\r\n;\r\n\'\'\r\nselect  count(*)  from #TEMP;\r\n\' ','== 0','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP  ( row varchar(500));\r\n\r\nexec sp_msforeachdb \'\'\r\nUSE [?]  \r\niNSERT iNTO #TEMP\r\nSELECT\r\n\'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +\r\n\'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +\r\n\'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +\r\n\'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )\r\nFROM\r\nsys.database_permissions\r\nWHERE\r\nSTATE_DESC like \'\'\'\'%WITH_GRANT%\'\'\'\'\r\n;\r\n\'\'\r\nselect * from #TEMP;\r\n\' ','There are no permissions with grant option.\r\n','There are some persmissions  with grant option.\r\n','pass',NULL,NULL,'2026-01-22 15:15:24'),(1121,202601,28,40,'AA_SqlServer_320_No Access to Registry Access Extended procedures','major','PRIV','This test checks for the existence of, and user permissions on, registry access extended stored procedures.  Either these procedures should be completely dropped, or access to them should be strictly limited. xp_reg%,xp_instance_reg%\r\n','','SELECT \r\ncount(*) \r\nFROM \r\n  [master].sys.system_objects o \r\n  JOIN [master].sys.database_permissions p ON o.object_id = p.major_id \r\n  JOIN [master].sys.database_principals u ON p.grantee_principal_id = u.principal_id \r\nWHERE \r\n( o.name LIKE \'xp_reg%\' OR o.name LIKE \'xp_instance_reg%\')\r\n  AND p.type = \'EX\' ','== 0','','SELECT \r\n  \'Principal : \'+u.name  COLLATE DATABASE_DEFAULT +\r\n  \' Extended Procedure Name : \'+o.name COLLATE DATABASE_DEFAULT +\r\n  \' Type : \'+ u.type_desc COLLATE DATABASE_DEFAULT \r\nFROM \r\n  [master].sys.system_objects o \r\n  JOIN [master].sys.database_permissions p ON o.object_id = p.major_id \r\n  JOIN [master].sys.database_principals u ON p.grantee_principal_id = u.principal_id \r\nWHERE \r\n( o.name LIKE \'xp_reg%\' OR o.name LIKE \'xp_instance_reg%\')\r\n  AND p.type = \'EX\' ','There are no permissions on registry access extended stored procedures\r\n','There are some persmissions permissions on registry access extended stored procedures\r\n','fail','\n---------------------------------------------------------------------------------------\n\'Principal : public Extended Procedure Name : xp_instance_regread Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_regread Type : DATABASE_ROLE\'',NULL,'2026-01-22 15:15:24'),(1122,202601,28,41,'AA_SqlServer_330_Revoke public login from SQL Server agent proxy account','major','PRIV','The public database role contains every user in the msdb database. SQL Agent proxies   define a security context in which a job step can run.Granting access to SQL Agent proxies for the public role would allow all users to utilize the proxy which may have high privileges. This would likely break the principle of least   privileges.\r\n','','SELECT count(*)\r\nFROM msdb.dbo.sysproxylogin spl\r\nJOIN sys.database_principals dp\r\nON dp.sid = spl.sid\r\nJOIN msdb.dbo.sysproxies sp\r\nON sp.proxy_id = spl.proxy_id\r\nWHERE principal_id = USER_ID(\'public\')','== 0','','SELECT \'proxyname : \'+CAST(sp.name  as varchar)\r\nFROM msdb.dbo.sysproxylogin spl\r\nJOIN sys.database_principals dp\r\nON dp.sid = spl.sid\r\nJOIN msdb.dbo.sysproxies sp\r\nON sp.proxy_id = spl.proxy_id\r\nWHERE principal_id = USER_ID(\'public\')','There are no public permissions on SQL Server agent proxy account\r\n','There are some public permissions on SQL Server agent proxy account\r\n','pass',NULL,NULL,'2026-01-22 15:15:24'),(1123,202601,28,42,'AA_SqlServer_340_No Individual User Access To syscomment and sp_helptext','minor','PRIV','This test checks for grants on SYSCOMMENTS.TEXT.  Such grants allow any user to read the text comments associated with a database object, making the text publicly viewable.\r\n','','SELECT count(*)\r\nFROM msdb.dbo.sysproxylogin spl\r\nJOIN sys.database_principals dp\r\nON dp.sid = spl.sid\r\nJOIN msdb.dbo.sysproxies sp\r\nON sp.proxy_id = spl.proxy_id\r\nWHERE principal_id = USER_ID(\'public\')\r\n','== 0','','SELECT count(*)\r\nFROM msdb.dbo.sysproxylogin spl\r\nJOIN sys.database_principals dp\r\nON dp.sid = spl.sid\r\nJOIN msdb.dbo.sysproxies sp\r\nON sp.proxy_id = spl.proxy_id\r\nWHERE principal_id = USER_ID(\'public\')','There are no public permissions on SQL Server agent proxy account','There are some public permissions on SQL Server agent proxy account','pass',NULL,NULL,'2026-01-22 15:15:24'),(1124,202601,28,10,'AA_SqlServer_050_Disable Ad hoc distributed queries option','major','CONFIG','Adhoc queries allow undefined access to remote database sources.  Access to untrusted databases could result in execution of malicious applications and/or a compromise of local data confidentiality and integrity. The DBA will configure the database to disable access from the database to objects stored externally to the database on the local host unless mission and/or operationally required and documented.\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Ad Hoc Distributed Queries\'','== 0','','SELECT name + \' Value : \'+ cast( value as varchar ) + \' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'Ad Hoc Distributed Queries\'','Ad Hoc Distributed Queries is disabled','Ad Hoc Distributed Queries is not disabled. Disable this option','pass',NULL,NULL,'2026-01-22 15:15:24'),(1125,202601,28,11,'AA_SqlServer_060_Disable CLR option','major','CONFIG','The clr_enabled parameter configures SQL Server to allow or disallow use of Command Language Runtime objects.  CLR objects is managed code that integrates with the .NET Framework.  This is a more secure method than external stored procedures, although it still contains some risk.  Where no external application execution requirements are required, disallowing use of any improves the overall security posture of the database.\r\n\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'clr enabled\'','== 0','','SELECT name + \' Value : \'+ cast( value as varchar ) + \' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'clr enabled\'','CLR option is disabled','CLR option is not disabled. Disable this option','pass',NULL,NULL,'2026-01-22 15:15:24'),(1126,202601,28,12,'AA_SqlServer_070_Disable Cross db ownership chaining option','major','CONFIG','Cross database ownership chaining allows permissions to objects to be assigned by users other than the Information Owner.  This allows access to objects that are not authorized directly by the Information Owner based on job functions defined by the owner.  Unauthorized access may lead to a compromise of data integrity or confidentiality. The DBA will ensure database privileges are assigned via roles and not directly assigned to database accounts. Privileges may be assigned directly to application owner accounts where the DBMS does not otherwise support access via roles.\r\n\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'cross db ownership chaining\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'cross db ownership chaining\'','Cross db ownership chaining  option is disabled','Cross db ownership chaining option  is not disabled. Disable this option','pass',NULL,NULL,'2026-01-22 15:15:24'),(1127,202601,28,13,'AA_SqlServer_080_Disable Database Mail XPs option','major','CONFIG','SQL Mail accepts incoming database commands via email. This can introduce malicious codes or viruses into the SQL server environment.','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Database Mail XPs\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \'Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'Database Mail XPs\'','Database Mail XPs option is disabled','Database Mail XPs option  is not disabled. Disable this option','pass',NULL,NULL,'2026-01-22 15:15:24'),(1128,202601,28,14,'AA_SqlServer_100_Disable xp_cmdshell Server Configuration option','major','CONFIG','The xp_cmdshell extended stored procedures allows execution of host executables outside the controls of database access permissions.  This access may be exploited by malicious users who have compromised the integrity of the SQL Server database process to control the host operating system to perpetrate additional malicious activity. The DBA should disable the use of external procedures by the database unless it is mission critical or operationally required','','SELECT CAST(value as int) +\r\n       CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'xp_cmdshell\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) +\r\n\' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'xp_cmdshell\'','xp_cmdshell Server Configuration option is disabled','xp_cmdshell Server Configuration option is not disabled. This option must be disabled','pass',NULL,NULL,'2026-01-22 15:15:24'),(1129,202601,28,15,'AA_SqlServer_110_Disable Remote Access option','major','CONFIG','The remote access option controls the execution of local stored procedures on remote\r\nservers or remote stored procedures on local server.Functionality can be abused to launch a Denial-of-Service (DoS) attack on remote servers\r\nby off-loading query processing to a target.\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'remote access\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \' Value in use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'remote access\'','Remote Access option is disabled','Remote Access option  is not disabled. Disable this option','fail','\n------------------------------------------\n\'remote access Value : 1 Value in use : 1\'',NULL,'2026-01-22 15:15:24'),(1130,202601,28,16,'AA_SqlServer_120_Disable Remote Admin Connections option','major','CONFIG','The remote admin connections option controls whether a client application on a remote\r\ncomputer can use the Dedicated Administrator Connection (DAC).The Dedicated Administrator Connection (DAC) lets an administrator access a running\r\nserver to execute diagnostic functions or Transact-SQL statements, or to troubleshoot\r\nproblems on the server, even when the server is locked or running in an abnormal state\r\nand not responding to a SQL Server Database Engine connection. In a cluster scenario, the\r\nadministrator may not actually be logged on to the same node that is currently hosting the\r\nSQL Server instance and thus is considered \"remote\". Therefore, this setting should usually\r\nbe enabled (1) for SQL Server failover clusters; otherwise it should be disabled (0) which is\r\nthe default.\r\n','','execute sp_executesql N\'\r\n\r\nDECLARE @x int;\r\n\r\nSELECT @x=isnull(CAST(value as int) + CAST(value_in_use as int),100)\r\nFROM sys.configurations\r\nWHERE name = \'\'remote admin connections\'\'\r\n\r\nIF @x = 100\r\n       SELECT 0 ;\r\nELSE \r\n   SELECT CAST(value as int) + CAST(value_in_use as int) \r\n   FROM sys.configurations\r\n   WHERE name = \'\'remote admin connections\'\'\r\n\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'remote admin connections\'','Remote Admin Connections option is disabled','Remote Admin Connections option  is not disabled. Disable this option','pass',NULL,NULL,'2026-01-22 15:15:24'),(1131,202601,28,19,'AA_SqlServer_150_Disable database trustworthy status','major','CONFIG','The TRUSTWORTHY database setting restricts access to database resources by databases that contain assemblies with the EXTERNAL_ACCESS or UNSAFE permission settings and modules that use impersonation of accounts assigned elevated privileges.  Unless all assemblies and code for the database have been reviewed, especially in the case where databases have been detached and attached between server instances, leaving the TRUSTWORTHY status to off can help reduce threats from malicious assemblies or modules.','','SELECT count(name)\r\nFROM sys.databases\r\nWHERE is_trustworthy_on = 1\r\nAND name != \'msdb\';','== 0','','SELECT name\r\nFROM sys.databases\r\nWHERE is_trustworthy_on = 1\r\nAND name != \'msdb\';','database trustworthy status is disabled','database trustworthy status is not disabled. Disable this option','pass',NULL,NULL,'2026-01-22 15:15:24'),(1132,202601,28,20,'Checkpoint başarıyla oluşturuldu.','major','CONFIG','This test checks if SQL Server Instance is not advertised by the SQL Server Browser service. To maintain a higher level of protection for database instances, we recommend that SQL Server Instance be hidden when it is not required. Please note that this test does not include Clustered Instances as turning off this feature may cause issues with the Clustered environment.\r\n\r\n','','execute sp_executesql N\'\r\n\r\nDECLARE @getValue INT\r\n\r\nEXEC master.sys.xp_instance_regread\r\n@rootkey = N\'\'HKEY_LOCAL_MACHINE\'\',\r\n@key = N\'\'SOFTWARE\\Microsoft\\Microsoft SQL Server\\MSSQLServer\\SuperSocketNetLib\'\',\r\n@value_name = N\'\'HideInstance\'\',\r\n@value = @getValue OUTPUT\r\n\r\nSELECT isnull(@getvalue,0)\'','==1','','execute sp_executesql N\'\r\n\r\nDECLARE @getValue INT\r\n\r\nEXEC master.sys.xp_instance_regread\r\n@rootkey = N\'\'HKEY_LOCAL_MACHINE\'\',\r\n@key = N\'\'SOFTWARE\\Microsoft\\Microsoft SQL Server\\MSSQLServer\\SuperSocketNetLib\'\',\r\n@value_name = N\'\'HideInstance\'\',\r\n@value = @getValue OUTPUT\r\n\r\nSELECT isnull(@getvalue,0)\'','SQL Server Instance is  hidden.\r\n','SQL Server Instance is not hidden. Hide the instance','fail','\n-\n0',NULL,'2026-01-22 15:15:24'),(1133,202601,28,21,'AA_SqlServer_160_Hide SQL Server Instance','major','CONFIG','This test checks if SQL Server Instance is not advertised by the SQL Server Browser service. To maintain a higher level of protection for database instances, we recommend that SQL Server Instance be hidden when it is not required. Please note that this test does not include Clustered Instances as turning off this feature may cause issues with the Clustered environment.\r\n\r\n','','execute sp_executesql N\'\r\n\r\nDECLARE @getValue INT\r\n\r\nEXEC master.sys.xp_instance_regread\r\n@rootkey = N\'\'HKEY_LOCAL_MACHINE\'\',\r\n@key = N\'\'SOFTWARE\\Microsoft\\Microsoft SQL Server\\MSSQLServer\\SuperSocketNetLib\'\',\r\n@value_name = N\'\'HideInstance\'\',\r\n@value = @getValue OUTPUT\r\n\r\nSELECT isnull(@getvalue,0)\'','==1','','execute sp_executesql N\'\r\n\r\nDECLARE @getValue INT\r\n\r\nEXEC master.sys.xp_instance_regread\r\n@rootkey = N\'\'HKEY_LOCAL_MACHINE\'\',\r\n@key = N\'\'SOFTWARE\\Microsoft\\Microsoft SQL Server\\MSSQLServer\\SuperSocketNetLib\'\',\r\n@value_name = N\'\'HideInstance\'\',\r\n@value = @getValue OUTPUT\r\n\r\nSELECT isnull(@getvalue,0)\'','SQL Server Instance is  hidden.','SQL Server Instance is not hidden. Hide the instance','fail','\n-\n0',NULL,'2026-01-22 15:15:24'),(1134,202601,28,38,'AA_SqlServer_300_No Access To General Extended procedures','major','PRIV','This test checks for the existence of, and user permissions on, extended stored procedures.  Either these procedures should be completely dropped, or access to them should be strictly limited. xp_cmdshell, xp_enumgroups, xp_grantlogin ,xp_logevent, xp_logininfo,    xp_msver, xp_revokelogin, xp_sprintf, xp_sqlmaint, xp_sscanf\r\n','','SELECT \r\ncount(*) \r\nFROM \r\n  [master].sys.system_objects o \r\n  JOIN [master].sys.database_permissions p ON o.object_id = p.major_id \r\n  JOIN [master].sys.database_principals u ON p.grantee_principal_id = u.principal_id \r\nWHERE \r\n    o.name in ( \r\n	\'xp_cmdshell\', \r\n	\'xp_enumgroups\', \r\n    \'xp_grantlogin\' ,\r\n	\'xp_logevent\', \r\n	\'xp_logininfo\', \r\n    \'xp_msver\', \r\n	\'xp_revokelogin\', \r\n	\'xp_sprintf\', \r\n    \'xp_sqlmaint\', \r\n	\'xp_sscanf\' )\r\n  AND p.type = \'EX\' ','== 0','','SELECT \r\n  \'Principal : \'+u.name  COLLATE DATABASE_DEFAULT +\r\n  \' Extended Procedure Name : \'+o.name COLLATE DATABASE_DEFAULT +\r\n  \' Type : \'+ u.type_desc COLLATE DATABASE_DEFAULT \r\nFROM \r\n  [master].sys.system_objects o \r\n  JOIN [master].sys.database_permissions p ON o.object_id = p.major_id \r\n  JOIN [master].sys.database_principals u ON p.grantee_principal_id = u.principal_id \r\nWHERE \r\n    o.name in ( \r\n	\'xp_cmdshell\', \r\n	\'xp_enumgroups\', \r\n    \'xp_grantlogin\' ,\r\n	\'xp_logevent\', \r\n	\'xp_logininfo\', \r\n    \'xp_msver\', \r\n	\'xp_revokelogin\', \r\n	\'xp_sprintf\', \r\n    \'xp_sqlmaint\', \r\n	\'xp_sscanf\' )\r\n  AND p.type = \'EX\' ','There are no permissions on general extended stored procedures\r\n','There are some persmissions permissions on general extended stored procedures.\r\n','fail','\n----------------------------------------------------------------------------------\n\'Principal : public Extended Procedure Name : xp_msver Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_sscanf Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_revokelogin Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_grantlogin Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_sprintf Type : DATABASE_ROLE\'',NULL,'2026-01-22 15:15:25'),(1135,202601,28,39,'AA_SqlServer_310_No Access to OLE Automation procedures','major','CONFIG','This test checks for the existence of,and user permissions on OLE automation extended stored procedures.  Either these procedures should be completely dropped, or access to them should be strictly limited.      \r\n','','SELECT CAST(value as int) +\r\n       CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Ole Automation Procedures\'   \r\n','== 0','','SELECT CAST(value as int) +\r\n       CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Ole Automation Procedures\'\r\n  \r\n','OLE Automation procedures  option is disabled\r\n','OLE Automation procedures  option  is not disabled. Disable this option\r\n','pass',NULL,NULL,'2026-01-22 15:15:25'),(1136,202601,28,17,'AA_SqlServer_130_Disable Ole Automation Procedures option','minor','CONFIG','This test checks if Ole Automation Procedures option is disabled. Ole Automation Procedures option allows SQL Server users to execute functions external to SQL Server. Enabling this option will increase the attack surface of SQL Server and allow users to execute functions in the security context of SQL Server. We recommend that the Ole Automation Procedures option to be disabled when it is not document as a requirement.\r\n\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Ole Automation Procedures\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \'Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'Ole Automation Procedures\'',' Ole Automation Procedures option is disabled',' Ole Automation Procedures option  is not disabled. Disable this option','pass',NULL,NULL,'2026-01-22 15:15:25'),(1137,202601,28,18,'AA_SqlServer_140_Disable Scan for Startup Procedures option','minor','CONFIG','This test checks if scan for startup procedures is disabled. This feature causes SQL Server to scan for and automatically run all stored procedures that are set to execute upon service startup. If there are no user-defined stored procedures set to execute when SQL server starts, we recommend this feature to be disabled.\r\n\r\n','','SELECT CAST(value as int) +\r\n       CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'scan for startup procs\'','== 0','','SELECT name + \' value : \'+cast( value as varchar ) +\r\n\' value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'scan for startup procs\'','Scan for Startup Procedures  option is disabled','Scan for Startup Procedures  option  is not disabled. Disable this option','pass',NULL,NULL,'2026-01-22 15:15:25'),(1138,202601,28,9,'AA_SqlServer_040_Rename the sa Login Account','major','ACCOUNT','The \'sa\' account is a well-known account.  Well-known account names provide an easier target for attack.  Renaming the sa account helps reduce the risk of an attack to this built-in account.','','SELECT count(*)\r\nFROM sys.server_principals\r\nWHERE sid = 0x01 and name=\'sa\'','== 0','','SELECT name\r\nFROM sys.server_principals\r\nWHERE sid = 0x01','sa Login Account is renamed','sa Login Account is not renamed. Rename this account','fail','name\n----\n\'sa\'',NULL,'2026-01-22 15:15:25'),(1139,202601,29,24,'AA_SqlServer_190_Public server role permision','critical','PRIV','public is a special fixed server role containing all logins. Unlike other fixed server roles,\r\npermissions can be changed for the public role. In keeping with the principle of least\r\nprivileges, the public server role should not be used to grant permissions at the server\r\nscope as these would be inherited by all users.\r\n\r\nEvery SQL Server login belongs to the public role and cannot be removed from this role.\r\nTherefore, any permissions granted to this role will be available to all logins unless they\r\nhave been explicitly denied to specific logins or user-defined server roles.','','Select \r\n  count (permission_name) \r\nfrom \r\n  sys.server_permissions \r\nwhere \r\n  SUSER_NAME(grantee_principal_id) = \'public\' \r\n  and permission_name not in (\'VIEW ANY DATABASE\', \'CONNECT\')\r\n','== 0','','Select \r\n  permission_name \r\nfrom \r\n  sys.server_permissions \r\nwhere \r\n  SUSER_NAME(grantee_principal_id) = \'public\' \r\n  and permission_name not in (\'VIEW ANY DATABASE\', \'CONNECT\')\r\n\r\n','No server permissions are granted to public.','Some server permissions are granted to public.','pass',NULL,NULL,'2026-01-22 15:15:56'),(1140,202601,29,5,'AA_SqlServer_010_Supported SQL Server version','critical','PATCH','This test checks whether your current SQL Server version is a vendor-supported version.  Microsoft does not provide security fixes or software updates to unsupported software versions','','SELECT cast(ISNULL(SERVERPROPERTY(\'ProductMajorVersion\'),0) as int)   ','>=11','','SELECT \'Product Major version \' +  cast(ISNULL(SERVERPROPERTY(\'ProductMajorVersion\'),\'Null\' ) as  char ) ','The version of the database is acceptable.','The version of the database is not acceptable. The database version should SQL Sever 2012 or upper.','pass',NULL,NULL,'2026-01-22 15:15:57'),(1141,202601,29,6,'AA_SqlServer_020_Disable the sa Login Account','critical','ACCOUNT','This test checks if the \'sa\' Login Account is disabled. The sa account is a widely known and often widely used SQL Server account with sysadmin privileges. Enforcing this control reduces the probability of an attacker executing brute force attacks against a well-known principal.','','SELECT  count(*)\r\nFROM sys.server_principals\r\nWHERE sid = 0x01\r\nAND is_disabled = 0','== 0','','SELECT \'sa user name : \'+ name+\' is disabled : \' +  cast( is_disabled as char)\r\nFROM sys.server_principals\r\nWHERE sid = 0x01\r\n','sa Login Account is disabled','Disable sa login account','fail','\n----------------------------------------------------------------\n\'sa user name : sa is disabled : 0                             \'',NULL,'2026-01-22 15:15:57'),(1142,202601,29,7,'AA_SqlServer_025_sa Change password','critical','ACCOUNT','This test checks that sa password change . The sa password should be changed in every two days','','select datediff( day,  modify_date , getdate() ) FROM sys.server_principals\r\nWHERE sid = 0x01  ','< 3','','select datediff( day,  modify_date , getdate() ) FROM sys.server_principals\r\nWHERE sid = 0x01 ','sa password was changed in two days','','fail','\n-\n8',NULL,'2026-01-22 15:15:57'),(1143,202601,29,8,'AA_SqlServer_030_Ensure no Login exists with sa Login Account','critical','ACCOUNT','The \'sa\' account is a well-known account.  Well-known account names provide an easier target for attack. The lack of the sa account helps reduce the risk of an attack to this built-in account.','','SELECT count(*)\r\nFROM sys.server_principals\r\nWHERE name = \'sa\'','== 0','','SELECT name\r\nFROM sys.server_principals\r\nWHERE name = \'sa\'','There is no the sa account in the database.','There is the sa Login account in the database.Drop this user or rename et.','fail','name\n----\n\'sa\'',NULL,'2026-01-22 15:15:57'),(1144,202601,29,25,'AA_SqlServer_200_Fixed Server Role members for users','critical','PRIV','This test checks fixed server roles for analyst , developers and real persons. Fixed server roles could not be assigned to real person users ( Developer, Analyst users ) . Only Admin can use fixed server role.\r\n','','Select     count(*)   from      sys.server_role_members    where      (       suser_name(member_principal_id) like \'ODEABANK%.%\'    	AND       suser_name(member_principal_id) not like \'%admin%\'         AND       suser_name(member_principal_id) not like \'%t.coban%\'     )      OR (       suser_name(member_principal_id) like \'ODEABANK\\Cyberark_Intertech%\'     )      \r\n','== 0','','Select      suser_name(role_principal_id) + \'   \' + suser_name(member_principal_id)    from      sys.server_role_members    where      (       suser_name(member_principal_id) like \'ODEABANK%.%\'    	AND       suser_name(member_principal_id) not like \'%admin%\'         AND       suser_name(member_principal_id) not like \'%t.coban%\'     )      OR (       suser_name(member_principal_id) like \'ODEABANK\\Cyberark_Intertech%\'     )          \r\n','Fixed Server role usage is correct.\r\n','Fixed Server role usage is not correct.\r\n','pass',NULL,NULL,'2026-01-22 15:15:57'),(1145,202601,29,26,'AA_SqlServer_210_Database Role members for users','critical','PRIV','This test checks database role members for analyst and real person users. Database roles  except  db_datareader could not be assigned to real person users ( Developer, Analyst users ) .\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      EXEC sp_MSforeachdb \'\' USE [?]    INSERT INTO #TEMP   SELECT \'\'\'\'DB Name : \'\'\'\'+Cast (DB_NAME() as varchar)+\'\'\'\' Role Name : \'\'\'\'+USER_NAME(role_principal_id)  +\'\'\'\' User Name \'\'\'\'+  USER_NAME(member_principal_id)    from  sys.database_role_members   	Where   	(   	( USER_NAME(member_principal_id)  like \'\'\'\'%ODEABANK%.%\'\'\'\'  and   USER_NAME(member_principal_id)  not like \'\'\'\'%admin%\'\'\'\' )     	OR   	  (suser_name(member_principal_id) like \'\'\'\'%ODEABANK%Cyberark%\'\'\'\')       )    	AND   	DB_NAME() <> \'\'\'\'master\'\'\'\' and   	USER_NAME(role_principal_id) not in (\'\'\'\'db_datareader\'\'\'\',\'\'\'\'db_viewdefinition\'\'\'\',\'\'\'\'db_denydatareader\'\'\'\',\'\'\'\'db_deny_maas\'\'\'\');   \'\'      Select  count(*)  from #TEMP;   \'\r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      EXEC sp_MSforeachdb \'\' USE [?]    INSERT INTO #TEMP   SELECT \'\'\'\'DB Name : \'\'\'\'+Cast (DB_NAME() as varchar)+\'\'\'\' Role Name : \'\'\'\'+USER_NAME(role_principal_id)  +\'\'\'\' User Name \'\'\'\'+  USER_NAME(member_principal_id)    from  sys.database_role_members   	Where   (   	( USER_NAME(member_principal_id)  like \'\'\'\'%ODEABANK%.%\'\'\'\'  and   USER_NAME(member_principal_id)  not like \'\'\'\'%admin%\'\'\'\' )     	OR   	(suser_name(member_principal_id) like \'\'\'\'%ODEABANK%Cyberark%\'\'\'\')   )    	AND   	DB_NAME() <> \'\'\'\'master\'\'\'\' and   	USER_NAME(role_principal_id) not in  (\'\'\'\'db_datareader\'\'\'\',\'\'\'\'db_viewdefinition\'\'\'\',\'\'\'\'db_denydatareader\'\'\'\',\'\'\'\'db_deny_maas\'\'\'\');   \'\'      Select  * from #TEMP;   \'\r\n','Database role member usage for users  is correct\r\n','Database role member usage for users  is not correct\r\n','pass',NULL,NULL,'2026-01-22 15:15:57'),(1146,202601,29,27,'AA_SqlServer_220_2_Public Database Permissions','critical','PRIV','This test checks database permisions for public . Public is a special role and permissions should not be granted to public role.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP ( row varchar(500));          exec sp_MSforeachdb \'\'   USE [?]   iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'public\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND OBJECT_NAME(MAJOR_iD) NOT LiKE (\'\'\'\'%fn_cdc_get_net_changes_application_data%\'\'\'\')   AND NOT (OBJECT_SCHEMA_NAME(MAJOR_iD) = \'\'\'\'cdc\'\'\'\' and PERMiSSiON_NAME=\'\'\'\'SELECT\'\'\'\')   AND NOT (PERMiSSiON_NAME IN (\'\'\'\'REFERENCES\'\'\'\',\'\'\'\'SEND\'\'\'\',   \'\'\'\'VIEW ANY COLUMN ENCRYPTION KEY DEFINITION\'\'\'\',   \'\'\'\'VIEW ANY COLUMN MASTER KEY DEFINITION\'\'\'\' ) and OBJECT_SCHEMA_NAME(MAJOR_iD) IS NULL)   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select count(*) from #TEMP;   \'\r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP ( row varchar(500));          exec sp_MSforeachdb \'\'   USE [?]   iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'public\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND OBJECT_NAME(MAJOR_iD) NOT LiKE (\'\'\'\'%fn_cdc_get_net_changes_application_data%\'\'\'\')   AND NOT (OBJECT_SCHEMA_NAME(MAJOR_iD) = \'\'\'\'cdc\'\'\'\' and PERMiSSiON_NAME=\'\'\'\'SELECT\'\'\'\')   AND NOT (PERMiSSiON_NAME IN (\'\'\'\'REFERENCES\'\'\'\',\'\'\'\'SEND\'\'\'\',   \'\'\'\'VIEW ANY COLUMN ENCRYPTION KEY DEFINITION\'\'\'\',   \'\'\'\'VIEW ANY COLUMN MASTER KEY DEFINITION\'\'\'\' ) and OBJECT_SCHEMA_NAME(MAJOR_iD) IS NULL)   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select * from #TEMP;   \'','There are no permissions which are assigned to public.\r\n','There are some persmissions which are assigned to public\r\n','pass',NULL,NULL,'2026-01-22 15:15:57'),(1147,202601,29,28,'AA_SqlServer_220_Public Database Permissions','critical','PRIV','This test checks database permisions for public . Public is a special role and permissions should not be granted to public role.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      exec sp_msforeachdb \'\'   USE [?]     iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'public\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND OBJECT_NAME(MAJOR_iD) NOT LiKE (\'\'\'\'%fn_cdc_get_net_changes_application_data%\'\'\'\')   AND NOT (OBJECT_SCHEMA_NAME(MAJOR_iD) = \'\'\'\'cdc\'\'\'\' and PERMiSSiON_NAME=\'\'\'\'SELECT\'\'\'\')   AND NOT (PERMiSSiON_NAME IN (\'\'\'\'REFERENCES\'\'\'\',\'\'\'\'SEND\'\'\'\',   \'\'\'\'VIEW ANY COLUMN ENCRYPTION KEY DEFINITION\'\'\'\',   \'\'\'\'VIEW ANY COLUMN MASTER KEY DEFINITION\'\'\'\' ) and OBJECT_SCHEMA_NAME(MAJOR_iD) IS NULL)   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select count(*) from #TEMP;   \' \r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      exec sp_msforeachdb \'\'   USE [?]     iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'public\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND OBJECT_NAME(MAJOR_iD) NOT LiKE (\'\'\'\'%fn_cdc_get_net_changes_application_data%\'\'\'\')   AND NOT (OBJECT_SCHEMA_NAME(MAJOR_iD) = \'\'\'\'cdc\'\'\'\' and PERMiSSiON_NAME=\'\'\'\'SELECT\'\'\'\')   AND NOT (PERMiSSiON_NAME IN (\'\'\'\'REFERENCES\'\'\'\',\'\'\'\'SEND\'\'\'\',   \'\'\'\'VIEW ANY COLUMN ENCRYPTION KEY DEFINITION\'\'\'\',   \'\'\'\'VIEW ANY COLUMN MASTER KEY DEFINITION\'\'\'\' ) and OBJECT_SCHEMA_NAME(MAJOR_iD) IS NULL)   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select * from #TEMP;   \' \r\n','There are no permissions which are assigned to public.\r\n','There are some persmissions which are assigned to public\r\n','pass',NULL,NULL,'2026-01-22 15:15:57'),(1148,202601,29,29,'AA_SqlServer_230_Real person users','critical','ACCOUNT','All logins to the database should be made with AD groups, real person users should  not be connected database directly\r\n','','Select      count(*)   from      sys.server_principals    where      name like \'ODEABANK%.%\'      and is_disabled = 0   \r\n','== 0','','Select      name     from      sys.server_principals    where      name like \'ODEABANK%.%\'      and is_disabled = 0;\r\n','Real person users are not found in the logins\r\n','Some real person users are found in the logins\r\n','pass',NULL,NULL,'2026-01-22 15:15:57'),(1149,202601,29,30,'AA_SqlServer_240_2_guest Database Permissions','critical','ACCOUNT','This test checks database permisions for guest . guest is a special user and permissions should not be granted to guest user.\r\n','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP ( row varchar(500));\r\n\r\nexec sp_MSforeachdb \'\'\r\nUSE [?]\r\niNSERT iNTO #TEMP\r\nSELECT\r\n\'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +\r\n\'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +\r\n\'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +\r\n\'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )\r\nFROM\r\nsys.database_permissions\r\nWHERE\r\nUSER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'guest\'\'\'\' )\r\nAND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'\r\nAND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')\r\nAND STATE_DESC=\'\'\'\'GRANT\'\'\'\'\r\n;\r\n\'\'\r\nselect count(*) from #TEMP;\r\n\'','== 0','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP ( row varchar(500));\r\n\r\nexec sp_MSforeachdb \'\'\r\nUSE [?]\r\niNSERT iNTO #TEMP\r\nSELECT\r\n\'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +\r\n\'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +\r\n\'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +\r\n\'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )\r\nFROM\r\nsys.database_permissions\r\nWHERE\r\nUSER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'guest\'\'\'\' )\r\nAND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'\r\nAND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')\r\nAND STATE_DESC=\'\'\'\'GRANT\'\'\'\'\r\n;\r\n\'\'\r\nselect * from #TEMP;\r\n\'','There are no permissions which are assigned to guest.\r\n','There are some persmissions which are assigned to guest\r\n','pass',NULL,NULL,'2026-01-22 15:15:57'),(1150,202601,29,31,'AA_SqlServer_240_guest Database Permissions','critical','PRIV','This test checks database permisions for guest . guest is a special user and permissions should not be granted to guest user.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      exec sp_msforeachdb \'\'   USE [?]     iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'guest\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select count(*) from #TEMP;   \' \r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      exec sp_msforeachdb \'\'   USE [?]     iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'guest\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select  *  from #TEMP;   \' \r\n','There are no permissions which are assigned to guest.\r\n','There are some persmissions which are assigned to guest\r\n','pass',NULL,NULL,'2026-01-22 15:15:57'),(1151,202601,29,32,'AA_SqlServer_250_Database Role members for guest','critical','PRIV','This test checks database role members for guest  user. Database roles  could not be assigned to guest role.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      EXEC sp_MSforeachdb \'\' USE [?]    INSERT INTO #TEMP   SELECT \'\'\'\'DB Name : \'\'\'\'+Cast (DB_NAME() as varchar)+\'\'\'\' Role Name : \'\'\'\'+USER_NAME(role_principal_id)  +\'\'\'\' User Name \'\'\'\'+  USER_NAME(member_principal_id)    from  sys.database_role_members   	Where     USER_NAME(member_principal_id)  = \'\'\'\'guest\'\'\'\'     ;   \'\'      Select count(*)  from #TEMP;   \'\r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      EXEC sp_MSforeachdb \'\' USE [?]    INSERT INTO #TEMP   SELECT \'\'\'\'DB Name : \'\'\'\'+Cast (DB_NAME() as varchar)+\'\'\'\' Role Name : \'\'\'\'+USER_NAME(role_principal_id)  +\'\'\'\' User Name \'\'\'\'+  USER_NAME(member_principal_id)    from  sys.database_role_members   	Where     USER_NAME(member_principal_id)  = \'\'\'\'guest\'\'\'\'     ;   \'\'      Select  *  from #TEMP;   \'\r\n','Database role member usage for guest user  is correct\r\n','Database role member usage for guest user  is not correct\r\n','pass',NULL,NULL,'2026-01-22 15:15:57'),(1152,202601,29,33,'AA_SqlServer_260_SQL Logins with Null Password','critical','ACCOUNT','This test checks sql logins with null password. SQL Logins should not have null passwords.\r\n','','SELECT      count(name)   from      sys.sql_logins    WHERE      PWDCOMPARE(\'\', password_hash)= 1\r\n','== 0','','SELECT      name    from      sys.sql_logins    WHERE      PWDCOMPARE(\'\', password_hash)= 1   \r\n','There are no sql logins with null paswords\r\n','There are some sql logins with null passwords.\r\n','pass',NULL,NULL,'2026-01-22 15:15:57'),(1153,202601,29,34,'AA_SqlServer_270_SQL Logins with username and passwords are equal','critical','ACCOUNT','This test checks sql login password which are egual to username. Username and password must be different for SQL logins.\r\n','','SELECT      count(name)   from      sys.sql_logins    WHERE      PWDCOMPARE(name,password_hash)=1 \r\n','== 0','','SELECT      name    from      sys.sql_logins    WHERE      PWDCOMPARE(name,password_hash)=1    \r\n','There is no SQL login name which is equal to password.\r\n','There are some sql logins whose passwords are egual to usernames.\r\n','pass',NULL,NULL,'2026-01-22 15:15:57'),(1154,202601,29,35,'AA_SqlServer_280_No Sample Databases','critical','CONFIG','This test checks whether the sample databases created optionally on installation are present.  These sample databases contain many default permissions, and can be used as an entry point to your systems. \r\n','','select      count(name)    from      sys.databases    where      name in (       \'AdventureWorks\', \'AdventureWorksDW\',        \'Northwind\', \'Pubs\'     )   \r\n','== 0','','select      name    from      sys.databases    where      name in (       \'AdventureWorks\', \'AdventureWorksDW\',        \'Northwind\', \'Pubs\'     )   \r\n','There are no sample databases in the server\r\n','There are some sample databases in the server\r\n','pass',NULL,NULL,'2026-01-22 15:15:57'),(1155,202601,29,43,'AA_SqlServer_350_User Password Policy Is Checked','critical','ACCOUNT','This test checks that CHECK_POLICY is enabled for all users.  Enabling CHECK_POLICY ensures that Windows passwords policies are enforced.','','select count(*) from sys.sql_logins  \r\nwhere \r\nis_policy_checked=0 and\r\nname not like \'##%\'','== 0','','select name from sys.sql_logins  \r\nwhere \r\nis_policy_checked=0 and\r\nname not like \'##%\'','CHECK_POLICY is enabled for all users','CHECK_POLICY is not enabled for all users','pass',NULL,NULL,'2026-01-22 15:15:57'),(1156,202601,29,44,'AA_SqlServer_360_CHECK_EXPIRATION Is Checked','critical','ACCOUNT','This test checks that CHECK_EXPIRATION is enabled for all users.  Passwords that have been in use for long periods of time are likely to become known to unauthorized users.\r\n','','select count(*) from sys.sql_logins     where    is_expiration_checked=0 and   name not like \'##%\'\r\n','== 0','','select name from sys.sql_logins     where    is_expiration_checked=0 and   name not like \'##%\'\r\n','CHECK_EXPIRATION is enabled for all users\r\n','CHECK_EXPIRATION is not enabled for all users\r\n','fail','name\n----\n\'sa\'',NULL,'2026-01-22 15:15:57'),(1157,202601,29,22,'AA_SqlServer_170_Windows Authentication','major','AUTH','This test checks that the authentication mode is set to Windows authentication only.  Windows provides a more robust authentication mechanism than SQL Server authentication.','',' SELECT cast( SERVERPROPERTY(\'IsIntegratedSecurityOnly\') as int) ','==1','','SELECT cast( SERVERPROPERTY(\'IsIntegratedSecurityOnly\') as varchar)','The authentication mode is set to Windows authentication only. ','The authentication mode is not set to Windows authentication only.','fail','\n---\n\'0\'',NULL,'2026-01-22 15:15:57'),(1158,202601,29,23,'AA_SqlServer_180_No Guest User Accounts','major','ACCOUNT','This test checks for the existence of guest user accounts with CONNECT permission in database other than master, msdb and tempdb.  This test also exclude databases that are flagged as distributor. If the GUEST user exists and a specific login has not been granted to a database, a login will be mapped to GUEST. The presence of the GUEST user allows all logins to access the database.\r\n','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP  ( row int);\r\n\r\nEXEC sp_MSforeachdb \'\' USE [?]\r\n	INSERT INTO #TEMP\r\n	SELECT count(*) \r\n	FROM sys.database_permissions\r\n	WHERE [grantee_principal_id] = DATABASE_PRINCIPAL_ID(\'\'\'\'guest\'\'\'\')\r\n	AND [state_desc] LIKE \'\'\'\'GRANT%\'\'\'\'\r\n	AND [permission_name] = \'\'\'\'CONNECT\'\'\'\'\r\n	AND DB_NAME() NOT IN (\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'msdb\'\'\'\') ;\r\n\'\'\r\n\r\nSelect sum(row) from #TEMP;\r\ndrop table #TEMP;\r\n\'','== 0','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP  ( row varchar(500));\r\n\r\nEXEC sp_MSforeachdb \'\' USE  [?] \r\n	INSERT INTO #TEMP\r\n	SELECT \'\'\'\' DB NAME : \'\'\'\' + Cast (DB_NAME() as varchar) + \'\'\'\' guest user has CONNECT permission \'\'\'\'\r\n	FROM sys.database_permissions\r\n	WHERE [grantee_principal_id] = DATABASE_PRINCIPAL_ID(\'\'\'\'guest\'\'\'\')\r\n	AND [state_desc] LIKE \'\'\'\'GRANT%\'\'\'\'\r\n	AND [permission_name] = \'\'\'\'CONNECT\'\'\'\'\r\n	AND DB_NAME() NOT IN (\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'msdb\'\'\'\') ;\r\n\'\'\r\n\r\nSelect * from #TEMP;\r\ndrop table #TEMP;\r\n\'','There is no guest user with CONNECT permission. ','There are   guest users with CONNECT permission. Remove these users','pass',NULL,NULL,'2026-01-22 15:15:57'),(1159,202601,29,36,'AA_SqlServer_290_2_No Permissions with GRANT Option','major','PRIV','This test checks database permisions  with grant option. No permission with grant option should be defined in the database.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP ( row varchar(500));      exec sp_MSforeachdb \'\'   USE [?]   iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   STATE_DESC like \'\'\'\'%WITH_GRANT%\'\'\'\'   ;   \'\'   select count(*) from #TEMP;   \'\r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP ( row varchar(500));      exec sp_MSforeachdb \'\'   USE [?]   iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   STATE_DESC like \'\'\'\'%WITH_GRANT%\'\'\'\'   ;   \'\'   select * from #TEMP;   \'\r\n','There are no permissions with grant option.\r\n','There are some persmissions  with grant option.\r\n','pass',NULL,NULL,'2026-01-22 15:15:57'),(1160,202601,29,37,'AA_SqlServer_290_No Permissions with GRANT Option','major','PRIV','','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP  ( row varchar(500));\r\n\r\nexec sp_msforeachdb \'\'\r\nUSE [?]  \r\niNSERT iNTO #TEMP\r\nSELECT\r\n\'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +\r\n\'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +\r\n\'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +\r\n\'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )\r\nFROM\r\nsys.database_permissions\r\nWHERE\r\nSTATE_DESC like \'\'\'\'%WITH_GRANT%\'\'\'\'\r\n;\r\n\'\'\r\nselect  count(*)  from #TEMP;\r\n\' ','== 0','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP  ( row varchar(500));\r\n\r\nexec sp_msforeachdb \'\'\r\nUSE [?]  \r\niNSERT iNTO #TEMP\r\nSELECT\r\n\'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +\r\n\'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +\r\n\'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +\r\n\'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )\r\nFROM\r\nsys.database_permissions\r\nWHERE\r\nSTATE_DESC like \'\'\'\'%WITH_GRANT%\'\'\'\'\r\n;\r\n\'\'\r\nselect * from #TEMP;\r\n\' ','There are no permissions with grant option.\r\n','There are some persmissions  with grant option.\r\n','pass',NULL,NULL,'2026-01-22 15:15:58'),(1161,202601,29,40,'AA_SqlServer_320_No Access to Registry Access Extended procedures','major','PRIV','This test checks for the existence of, and user permissions on, registry access extended stored procedures.  Either these procedures should be completely dropped, or access to them should be strictly limited. xp_reg%,xp_instance_reg%\r\n','','SELECT \r\ncount(*) \r\nFROM \r\n  [master].sys.system_objects o \r\n  JOIN [master].sys.database_permissions p ON o.object_id = p.major_id \r\n  JOIN [master].sys.database_principals u ON p.grantee_principal_id = u.principal_id \r\nWHERE \r\n( o.name LIKE \'xp_reg%\' OR o.name LIKE \'xp_instance_reg%\')\r\n  AND p.type = \'EX\' ','== 0','','SELECT \r\n  \'Principal : \'+u.name  COLLATE DATABASE_DEFAULT +\r\n  \' Extended Procedure Name : \'+o.name COLLATE DATABASE_DEFAULT +\r\n  \' Type : \'+ u.type_desc COLLATE DATABASE_DEFAULT \r\nFROM \r\n  [master].sys.system_objects o \r\n  JOIN [master].sys.database_permissions p ON o.object_id = p.major_id \r\n  JOIN [master].sys.database_principals u ON p.grantee_principal_id = u.principal_id \r\nWHERE \r\n( o.name LIKE \'xp_reg%\' OR o.name LIKE \'xp_instance_reg%\')\r\n  AND p.type = \'EX\' ','There are no permissions on registry access extended stored procedures\r\n','There are some persmissions permissions on registry access extended stored procedures\r\n','fail','\n---------------------------------------------------------------------------------------\n\'Principal : public Extended Procedure Name : xp_instance_regread Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_regread Type : DATABASE_ROLE\'',NULL,'2026-01-22 15:15:58'),(1162,202601,29,41,'AA_SqlServer_330_Revoke public login from SQL Server agent proxy account','major','PRIV','The public database role contains every user in the msdb database. SQL Agent proxies   define a security context in which a job step can run.Granting access to SQL Agent proxies for the public role would allow all users to utilize the proxy which may have high privileges. This would likely break the principle of least   privileges.\r\n','','SELECT count(*)\r\nFROM msdb.dbo.sysproxylogin spl\r\nJOIN sys.database_principals dp\r\nON dp.sid = spl.sid\r\nJOIN msdb.dbo.sysproxies sp\r\nON sp.proxy_id = spl.proxy_id\r\nWHERE principal_id = USER_ID(\'public\')','== 0','','SELECT \'proxyname : \'+CAST(sp.name  as varchar)\r\nFROM msdb.dbo.sysproxylogin spl\r\nJOIN sys.database_principals dp\r\nON dp.sid = spl.sid\r\nJOIN msdb.dbo.sysproxies sp\r\nON sp.proxy_id = spl.proxy_id\r\nWHERE principal_id = USER_ID(\'public\')','There are no public permissions on SQL Server agent proxy account\r\n','There are some public permissions on SQL Server agent proxy account\r\n','pass',NULL,NULL,'2026-01-22 15:15:58'),(1163,202601,29,42,'AA_SqlServer_340_No Individual User Access To syscomment and sp_helptext','minor','PRIV','This test checks for grants on SYSCOMMENTS.TEXT.  Such grants allow any user to read the text comments associated with a database object, making the text publicly viewable.\r\n','','SELECT count(*)\r\nFROM msdb.dbo.sysproxylogin spl\r\nJOIN sys.database_principals dp\r\nON dp.sid = spl.sid\r\nJOIN msdb.dbo.sysproxies sp\r\nON sp.proxy_id = spl.proxy_id\r\nWHERE principal_id = USER_ID(\'public\')\r\n','== 0','','SELECT count(*)\r\nFROM msdb.dbo.sysproxylogin spl\r\nJOIN sys.database_principals dp\r\nON dp.sid = spl.sid\r\nJOIN msdb.dbo.sysproxies sp\r\nON sp.proxy_id = spl.proxy_id\r\nWHERE principal_id = USER_ID(\'public\')','There are no public permissions on SQL Server agent proxy account','There are some public permissions on SQL Server agent proxy account','pass',NULL,NULL,'2026-01-22 15:15:58'),(1164,202601,29,10,'AA_SqlServer_050_Disable Ad hoc distributed queries option','major','CONFIG','Adhoc queries allow undefined access to remote database sources.  Access to untrusted databases could result in execution of malicious applications and/or a compromise of local data confidentiality and integrity. The DBA will configure the database to disable access from the database to objects stored externally to the database on the local host unless mission and/or operationally required and documented.\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Ad Hoc Distributed Queries\'','== 0','','SELECT name + \' Value : \'+ cast( value as varchar ) + \' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'Ad Hoc Distributed Queries\'','Ad Hoc Distributed Queries is disabled','Ad Hoc Distributed Queries is not disabled. Disable this option','pass',NULL,NULL,'2026-01-22 15:15:58'),(1165,202601,29,11,'AA_SqlServer_060_Disable CLR option','major','CONFIG','The clr_enabled parameter configures SQL Server to allow or disallow use of Command Language Runtime objects.  CLR objects is managed code that integrates with the .NET Framework.  This is a more secure method than external stored procedures, although it still contains some risk.  Where no external application execution requirements are required, disallowing use of any improves the overall security posture of the database.\r\n\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'clr enabled\'','== 0','','SELECT name + \' Value : \'+ cast( value as varchar ) + \' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'clr enabled\'','CLR option is disabled','CLR option is not disabled. Disable this option','pass',NULL,NULL,'2026-01-22 15:15:58'),(1166,202601,29,12,'AA_SqlServer_070_Disable Cross db ownership chaining option','major','CONFIG','Cross database ownership chaining allows permissions to objects to be assigned by users other than the Information Owner.  This allows access to objects that are not authorized directly by the Information Owner based on job functions defined by the owner.  Unauthorized access may lead to a compromise of data integrity or confidentiality. The DBA will ensure database privileges are assigned via roles and not directly assigned to database accounts. Privileges may be assigned directly to application owner accounts where the DBMS does not otherwise support access via roles.\r\n\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'cross db ownership chaining\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'cross db ownership chaining\'','Cross db ownership chaining  option is disabled','Cross db ownership chaining option  is not disabled. Disable this option','pass',NULL,NULL,'2026-01-22 15:15:58'),(1167,202601,29,13,'AA_SqlServer_080_Disable Database Mail XPs option','major','CONFIG','SQL Mail accepts incoming database commands via email. This can introduce malicious codes or viruses into the SQL server environment.','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Database Mail XPs\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \'Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'Database Mail XPs\'','Database Mail XPs option is disabled','Database Mail XPs option  is not disabled. Disable this option','pass',NULL,NULL,'2026-01-22 15:15:58'),(1168,202601,29,14,'AA_SqlServer_100_Disable xp_cmdshell Server Configuration option','major','CONFIG','The xp_cmdshell extended stored procedures allows execution of host executables outside the controls of database access permissions.  This access may be exploited by malicious users who have compromised the integrity of the SQL Server database process to control the host operating system to perpetrate additional malicious activity. The DBA should disable the use of external procedures by the database unless it is mission critical or operationally required','','SELECT CAST(value as int) +\r\n       CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'xp_cmdshell\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) +\r\n\' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'xp_cmdshell\'','xp_cmdshell Server Configuration option is disabled','xp_cmdshell Server Configuration option is not disabled. This option must be disabled','pass',NULL,NULL,'2026-01-22 15:15:58'),(1169,202601,29,15,'AA_SqlServer_110_Disable Remote Access option','major','CONFIG','The remote access option controls the execution of local stored procedures on remote\r\nservers or remote stored procedures on local server.Functionality can be abused to launch a Denial-of-Service (DoS) attack on remote servers\r\nby off-loading query processing to a target.\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'remote access\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \' Value in use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'remote access\'','Remote Access option is disabled','Remote Access option  is not disabled. Disable this option','fail','\n------------------------------------------\n\'remote access Value : 1 Value in use : 1\'',NULL,'2026-01-22 15:15:58'),(1170,202601,29,16,'AA_SqlServer_120_Disable Remote Admin Connections option','major','CONFIG','The remote admin connections option controls whether a client application on a remote\r\ncomputer can use the Dedicated Administrator Connection (DAC).The Dedicated Administrator Connection (DAC) lets an administrator access a running\r\nserver to execute diagnostic functions or Transact-SQL statements, or to troubleshoot\r\nproblems on the server, even when the server is locked or running in an abnormal state\r\nand not responding to a SQL Server Database Engine connection. In a cluster scenario, the\r\nadministrator may not actually be logged on to the same node that is currently hosting the\r\nSQL Server instance and thus is considered \"remote\". Therefore, this setting should usually\r\nbe enabled (1) for SQL Server failover clusters; otherwise it should be disabled (0) which is\r\nthe default.\r\n','','execute sp_executesql N\'\r\n\r\nDECLARE @x int;\r\n\r\nSELECT @x=isnull(CAST(value as int) + CAST(value_in_use as int),100)\r\nFROM sys.configurations\r\nWHERE name = \'\'remote admin connections\'\'\r\n\r\nIF @x = 100\r\n       SELECT 0 ;\r\nELSE \r\n   SELECT CAST(value as int) + CAST(value_in_use as int) \r\n   FROM sys.configurations\r\n   WHERE name = \'\'remote admin connections\'\'\r\n\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'remote admin connections\'','Remote Admin Connections option is disabled','Remote Admin Connections option  is not disabled. Disable this option','pass',NULL,NULL,'2026-01-22 15:15:58'),(1171,202601,29,19,'AA_SqlServer_150_Disable database trustworthy status','major','CONFIG','The TRUSTWORTHY database setting restricts access to database resources by databases that contain assemblies with the EXTERNAL_ACCESS or UNSAFE permission settings and modules that use impersonation of accounts assigned elevated privileges.  Unless all assemblies and code for the database have been reviewed, especially in the case where databases have been detached and attached between server instances, leaving the TRUSTWORTHY status to off can help reduce threats from malicious assemblies or modules.','','SELECT count(name)\r\nFROM sys.databases\r\nWHERE is_trustworthy_on = 1\r\nAND name != \'msdb\';','== 0','','SELECT name\r\nFROM sys.databases\r\nWHERE is_trustworthy_on = 1\r\nAND name != \'msdb\';','database trustworthy status is disabled','database trustworthy status is not disabled. Disable this option','pass',NULL,NULL,'2026-01-22 15:15:58'),(1172,202601,29,20,'Checkpoint başarıyla oluşturuldu.','major','CONFIG','This test checks if SQL Server Instance is not advertised by the SQL Server Browser service. To maintain a higher level of protection for database instances, we recommend that SQL Server Instance be hidden when it is not required. Please note that this test does not include Clustered Instances as turning off this feature may cause issues with the Clustered environment.\r\n\r\n','','execute sp_executesql N\'\r\n\r\nDECLARE @getValue INT\r\n\r\nEXEC master.sys.xp_instance_regread\r\n@rootkey = N\'\'HKEY_LOCAL_MACHINE\'\',\r\n@key = N\'\'SOFTWARE\\Microsoft\\Microsoft SQL Server\\MSSQLServer\\SuperSocketNetLib\'\',\r\n@value_name = N\'\'HideInstance\'\',\r\n@value = @getValue OUTPUT\r\n\r\nSELECT isnull(@getvalue,0)\'','==1','','execute sp_executesql N\'\r\n\r\nDECLARE @getValue INT\r\n\r\nEXEC master.sys.xp_instance_regread\r\n@rootkey = N\'\'HKEY_LOCAL_MACHINE\'\',\r\n@key = N\'\'SOFTWARE\\Microsoft\\Microsoft SQL Server\\MSSQLServer\\SuperSocketNetLib\'\',\r\n@value_name = N\'\'HideInstance\'\',\r\n@value = @getValue OUTPUT\r\n\r\nSELECT isnull(@getvalue,0)\'','SQL Server Instance is  hidden.\r\n','SQL Server Instance is not hidden. Hide the instance','fail','\n-\n0',NULL,'2026-01-22 15:15:58'),(1173,202601,29,21,'AA_SqlServer_160_Hide SQL Server Instance','major','CONFIG','This test checks if SQL Server Instance is not advertised by the SQL Server Browser service. To maintain a higher level of protection for database instances, we recommend that SQL Server Instance be hidden when it is not required. Please note that this test does not include Clustered Instances as turning off this feature may cause issues with the Clustered environment.\r\n\r\n','','execute sp_executesql N\'\r\n\r\nDECLARE @getValue INT\r\n\r\nEXEC master.sys.xp_instance_regread\r\n@rootkey = N\'\'HKEY_LOCAL_MACHINE\'\',\r\n@key = N\'\'SOFTWARE\\Microsoft\\Microsoft SQL Server\\MSSQLServer\\SuperSocketNetLib\'\',\r\n@value_name = N\'\'HideInstance\'\',\r\n@value = @getValue OUTPUT\r\n\r\nSELECT isnull(@getvalue,0)\'','==1','','execute sp_executesql N\'\r\n\r\nDECLARE @getValue INT\r\n\r\nEXEC master.sys.xp_instance_regread\r\n@rootkey = N\'\'HKEY_LOCAL_MACHINE\'\',\r\n@key = N\'\'SOFTWARE\\Microsoft\\Microsoft SQL Server\\MSSQLServer\\SuperSocketNetLib\'\',\r\n@value_name = N\'\'HideInstance\'\',\r\n@value = @getValue OUTPUT\r\n\r\nSELECT isnull(@getvalue,0)\'','SQL Server Instance is  hidden.','SQL Server Instance is not hidden. Hide the instance','fail','\n-\n0',NULL,'2026-01-22 15:15:58'),(1174,202601,29,38,'AA_SqlServer_300_No Access To General Extended procedures','major','PRIV','This test checks for the existence of, and user permissions on, extended stored procedures.  Either these procedures should be completely dropped, or access to them should be strictly limited. xp_cmdshell, xp_enumgroups, xp_grantlogin ,xp_logevent, xp_logininfo,    xp_msver, xp_revokelogin, xp_sprintf, xp_sqlmaint, xp_sscanf\r\n','','SELECT \r\ncount(*) \r\nFROM \r\n  [master].sys.system_objects o \r\n  JOIN [master].sys.database_permissions p ON o.object_id = p.major_id \r\n  JOIN [master].sys.database_principals u ON p.grantee_principal_id = u.principal_id \r\nWHERE \r\n    o.name in ( \r\n	\'xp_cmdshell\', \r\n	\'xp_enumgroups\', \r\n    \'xp_grantlogin\' ,\r\n	\'xp_logevent\', \r\n	\'xp_logininfo\', \r\n    \'xp_msver\', \r\n	\'xp_revokelogin\', \r\n	\'xp_sprintf\', \r\n    \'xp_sqlmaint\', \r\n	\'xp_sscanf\' )\r\n  AND p.type = \'EX\' ','== 0','','SELECT \r\n  \'Principal : \'+u.name  COLLATE DATABASE_DEFAULT +\r\n  \' Extended Procedure Name : \'+o.name COLLATE DATABASE_DEFAULT +\r\n  \' Type : \'+ u.type_desc COLLATE DATABASE_DEFAULT \r\nFROM \r\n  [master].sys.system_objects o \r\n  JOIN [master].sys.database_permissions p ON o.object_id = p.major_id \r\n  JOIN [master].sys.database_principals u ON p.grantee_principal_id = u.principal_id \r\nWHERE \r\n    o.name in ( \r\n	\'xp_cmdshell\', \r\n	\'xp_enumgroups\', \r\n    \'xp_grantlogin\' ,\r\n	\'xp_logevent\', \r\n	\'xp_logininfo\', \r\n    \'xp_msver\', \r\n	\'xp_revokelogin\', \r\n	\'xp_sprintf\', \r\n    \'xp_sqlmaint\', \r\n	\'xp_sscanf\' )\r\n  AND p.type = \'EX\' ','There are no permissions on general extended stored procedures\r\n','There are some persmissions permissions on general extended stored procedures.\r\n','fail','\n----------------------------------------------------------------------------------\n\'Principal : public Extended Procedure Name : xp_msver Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_sscanf Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_revokelogin Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_grantlogin Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_sprintf Type : DATABASE_ROLE\'',NULL,'2026-01-22 15:15:58'),(1175,202601,29,39,'AA_SqlServer_310_No Access to OLE Automation procedures','major','CONFIG','This test checks for the existence of,and user permissions on OLE automation extended stored procedures.  Either these procedures should be completely dropped, or access to them should be strictly limited.      \r\n','','SELECT CAST(value as int) +\r\n       CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Ole Automation Procedures\'   \r\n','== 0','','SELECT CAST(value as int) +\r\n       CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Ole Automation Procedures\'\r\n  \r\n','OLE Automation procedures  option is disabled\r\n','OLE Automation procedures  option  is not disabled. Disable this option\r\n','pass',NULL,NULL,'2026-01-22 15:15:58'),(1176,202601,29,17,'AA_SqlServer_130_Disable Ole Automation Procedures option','minor','CONFIG','This test checks if Ole Automation Procedures option is disabled. Ole Automation Procedures option allows SQL Server users to execute functions external to SQL Server. Enabling this option will increase the attack surface of SQL Server and allow users to execute functions in the security context of SQL Server. We recommend that the Ole Automation Procedures option to be disabled when it is not document as a requirement.\r\n\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Ole Automation Procedures\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \'Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'Ole Automation Procedures\'',' Ole Automation Procedures option is disabled',' Ole Automation Procedures option  is not disabled. Disable this option','pass',NULL,NULL,'2026-01-22 15:15:58'),(1177,202601,29,18,'AA_SqlServer_140_Disable Scan for Startup Procedures option','minor','CONFIG','This test checks if scan for startup procedures is disabled. This feature causes SQL Server to scan for and automatically run all stored procedures that are set to execute upon service startup. If there are no user-defined stored procedures set to execute when SQL server starts, we recommend this feature to be disabled.\r\n\r\n','','SELECT CAST(value as int) +\r\n       CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'scan for startup procs\'','== 0','','SELECT name + \' value : \'+cast( value as varchar ) +\r\n\' value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'scan for startup procs\'','Scan for Startup Procedures  option is disabled','Scan for Startup Procedures  option  is not disabled. Disable this option','pass',NULL,NULL,'2026-01-22 15:15:58'),(1178,202601,29,9,'AA_SqlServer_040_Rename the sa Login Account','major','ACCOUNT','The \'sa\' account is a well-known account.  Well-known account names provide an easier target for attack.  Renaming the sa account helps reduce the risk of an attack to this built-in account.','','SELECT count(*)\r\nFROM sys.server_principals\r\nWHERE sid = 0x01 and name=\'sa\'','== 0','','SELECT name\r\nFROM sys.server_principals\r\nWHERE sid = 0x01','sa Login Account is renamed','sa Login Account is not renamed. Rename this account','fail','name\n----\n\'sa\'',NULL,'2026-01-22 15:15:58'),(1179,202601,30,24,'AA_SqlServer_190_Public server role permision','critical','PRIV','public is a special fixed server role containing all logins. Unlike other fixed server roles,\r\npermissions can be changed for the public role. In keeping with the principle of least\r\nprivileges, the public server role should not be used to grant permissions at the server\r\nscope as these would be inherited by all users.\r\n\r\nEvery SQL Server login belongs to the public role and cannot be removed from this role.\r\nTherefore, any permissions granted to this role will be available to all logins unless they\r\nhave been explicitly denied to specific logins or user-defined server roles.','','Select \r\n  count (permission_name) \r\nfrom \r\n  sys.server_permissions \r\nwhere \r\n  SUSER_NAME(grantee_principal_id) = \'public\' \r\n  and permission_name not in (\'VIEW ANY DATABASE\', \'CONNECT\')\r\n','== 0','','Select \r\n  permission_name \r\nfrom \r\n  sys.server_permissions \r\nwhere \r\n  SUSER_NAME(grantee_principal_id) = \'public\' \r\n  and permission_name not in (\'VIEW ANY DATABASE\', \'CONNECT\')\r\n\r\n','No server permissions are granted to public.','Some server permissions are granted to public.','pass',NULL,NULL,'2026-01-22 15:25:43'),(1180,202601,30,5,'AA_SqlServer_010_Supported SQL Server version','critical','PATCH','This test checks whether your current SQL Server version is a vendor-supported version.  Microsoft does not provide security fixes or software updates to unsupported software versions','','SELECT cast(ISNULL(SERVERPROPERTY(\'ProductMajorVersion\'),0) as int)   ','>=11','','SELECT \'Product Major version \' +  cast(ISNULL(SERVERPROPERTY(\'ProductMajorVersion\'),\'Null\' ) as  char ) ','The version of the database is acceptable.','The version of the database is not acceptable. The database version should SQL Sever 2012 or upper.','pass',NULL,NULL,'2026-01-22 15:25:43'),(1181,202601,30,6,'AA_SqlServer_020_Disable the sa Login Account','critical','ACCOUNT','This test checks if the \'sa\' Login Account is disabled. The sa account is a widely known and often widely used SQL Server account with sysadmin privileges. Enforcing this control reduces the probability of an attacker executing brute force attacks against a well-known principal.','','SELECT  count(*)\r\nFROM sys.server_principals\r\nWHERE sid = 0x01\r\nAND is_disabled = 0','== 0','','SELECT \'sa user name : \'+ name+\' is disabled : \' +  cast( is_disabled as char)\r\nFROM sys.server_principals\r\nWHERE sid = 0x01\r\n','sa Login Account is disabled','Disable sa login account','fail','\n----------------------------------------------------------------\n\'sa user name : sa is disabled : 0                             \'',NULL,'2026-01-22 15:25:43'),(1182,202601,30,7,'AA_SqlServer_025_sa Change password','critical','ACCOUNT','This test checks that sa password change . The sa password should be changed in every two days','','select datediff( day,  modify_date , getdate() ) FROM sys.server_principals\r\nWHERE sid = 0x01  ','< 3','','select datediff( day,  modify_date , getdate() ) FROM sys.server_principals\r\nWHERE sid = 0x01 ','sa password was changed in two days','','fail','\n-\n8',NULL,'2026-01-22 15:25:43'),(1183,202601,30,8,'AA_SqlServer_030_Ensure no Login exists with sa Login Account','critical','ACCOUNT','The \'sa\' account is a well-known account.  Well-known account names provide an easier target for attack. The lack of the sa account helps reduce the risk of an attack to this built-in account.','','SELECT count(*)\r\nFROM sys.server_principals\r\nWHERE name = \'sa\'','== 0','','SELECT name\r\nFROM sys.server_principals\r\nWHERE name = \'sa\'','There is no the sa account in the database.','There is the sa Login account in the database.Drop this user or rename et.','fail','name\n----\n\'sa\'',NULL,'2026-01-22 15:25:43'),(1184,202601,30,25,'AA_SqlServer_200_Fixed Server Role members for users','critical','PRIV','This test checks fixed server roles for analyst , developers and real persons. Fixed server roles could not be assigned to real person users ( Developer, Analyst users ) . Only Admin can use fixed server role.\r\n','','Select     count(*)   from      sys.server_role_members    where      (       suser_name(member_principal_id) like \'ODEABANK%.%\'    	AND       suser_name(member_principal_id) not like \'%admin%\'         AND       suser_name(member_principal_id) not like \'%t.coban%\'     )      OR (       suser_name(member_principal_id) like \'ODEABANK\\Cyberark_Intertech%\'     )      \r\n','== 0','','Select      suser_name(role_principal_id) + \'   \' + suser_name(member_principal_id)    from      sys.server_role_members    where      (       suser_name(member_principal_id) like \'ODEABANK%.%\'    	AND       suser_name(member_principal_id) not like \'%admin%\'         AND       suser_name(member_principal_id) not like \'%t.coban%\'     )      OR (       suser_name(member_principal_id) like \'ODEABANK\\Cyberark_Intertech%\'     )          \r\n','Fixed Server role usage is correct.\r\n','Fixed Server role usage is not correct.\r\n','pass',NULL,NULL,'2026-01-22 15:25:43'),(1185,202601,30,26,'AA_SqlServer_210_Database Role members for users','critical','PRIV','This test checks database role members for analyst and real person users. Database roles  except  db_datareader could not be assigned to real person users ( Developer, Analyst users ) .\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      EXEC sp_MSforeachdb \'\' USE [?]    INSERT INTO #TEMP   SELECT \'\'\'\'DB Name : \'\'\'\'+Cast (DB_NAME() as varchar)+\'\'\'\' Role Name : \'\'\'\'+USER_NAME(role_principal_id)  +\'\'\'\' User Name \'\'\'\'+  USER_NAME(member_principal_id)    from  sys.database_role_members   	Where   	(   	( USER_NAME(member_principal_id)  like \'\'\'\'%ODEABANK%.%\'\'\'\'  and   USER_NAME(member_principal_id)  not like \'\'\'\'%admin%\'\'\'\' )     	OR   	  (suser_name(member_principal_id) like \'\'\'\'%ODEABANK%Cyberark%\'\'\'\')       )    	AND   	DB_NAME() <> \'\'\'\'master\'\'\'\' and   	USER_NAME(role_principal_id) not in (\'\'\'\'db_datareader\'\'\'\',\'\'\'\'db_viewdefinition\'\'\'\',\'\'\'\'db_denydatareader\'\'\'\',\'\'\'\'db_deny_maas\'\'\'\');   \'\'      Select  count(*)  from #TEMP;   \'\r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      EXEC sp_MSforeachdb \'\' USE [?]    INSERT INTO #TEMP   SELECT \'\'\'\'DB Name : \'\'\'\'+Cast (DB_NAME() as varchar)+\'\'\'\' Role Name : \'\'\'\'+USER_NAME(role_principal_id)  +\'\'\'\' User Name \'\'\'\'+  USER_NAME(member_principal_id)    from  sys.database_role_members   	Where   (   	( USER_NAME(member_principal_id)  like \'\'\'\'%ODEABANK%.%\'\'\'\'  and   USER_NAME(member_principal_id)  not like \'\'\'\'%admin%\'\'\'\' )     	OR   	(suser_name(member_principal_id) like \'\'\'\'%ODEABANK%Cyberark%\'\'\'\')   )    	AND   	DB_NAME() <> \'\'\'\'master\'\'\'\' and   	USER_NAME(role_principal_id) not in  (\'\'\'\'db_datareader\'\'\'\',\'\'\'\'db_viewdefinition\'\'\'\',\'\'\'\'db_denydatareader\'\'\'\',\'\'\'\'db_deny_maas\'\'\'\');   \'\'      Select  * from #TEMP;   \'\r\n','Database role member usage for users  is correct\r\n','Database role member usage for users  is not correct\r\n','pass',NULL,NULL,'2026-01-22 15:25:43'),(1186,202601,30,27,'AA_SqlServer_220_2_Public Database Permissions','critical','PRIV','This test checks database permisions for public . Public is a special role and permissions should not be granted to public role.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP ( row varchar(500));          exec sp_MSforeachdb \'\'   USE [?]   iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'public\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND OBJECT_NAME(MAJOR_iD) NOT LiKE (\'\'\'\'%fn_cdc_get_net_changes_application_data%\'\'\'\')   AND NOT (OBJECT_SCHEMA_NAME(MAJOR_iD) = \'\'\'\'cdc\'\'\'\' and PERMiSSiON_NAME=\'\'\'\'SELECT\'\'\'\')   AND NOT (PERMiSSiON_NAME IN (\'\'\'\'REFERENCES\'\'\'\',\'\'\'\'SEND\'\'\'\',   \'\'\'\'VIEW ANY COLUMN ENCRYPTION KEY DEFINITION\'\'\'\',   \'\'\'\'VIEW ANY COLUMN MASTER KEY DEFINITION\'\'\'\' ) and OBJECT_SCHEMA_NAME(MAJOR_iD) IS NULL)   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select count(*) from #TEMP;   \'\r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP ( row varchar(500));          exec sp_MSforeachdb \'\'   USE [?]   iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'public\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND OBJECT_NAME(MAJOR_iD) NOT LiKE (\'\'\'\'%fn_cdc_get_net_changes_application_data%\'\'\'\')   AND NOT (OBJECT_SCHEMA_NAME(MAJOR_iD) = \'\'\'\'cdc\'\'\'\' and PERMiSSiON_NAME=\'\'\'\'SELECT\'\'\'\')   AND NOT (PERMiSSiON_NAME IN (\'\'\'\'REFERENCES\'\'\'\',\'\'\'\'SEND\'\'\'\',   \'\'\'\'VIEW ANY COLUMN ENCRYPTION KEY DEFINITION\'\'\'\',   \'\'\'\'VIEW ANY COLUMN MASTER KEY DEFINITION\'\'\'\' ) and OBJECT_SCHEMA_NAME(MAJOR_iD) IS NULL)   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select * from #TEMP;   \'','There are no permissions which are assigned to public.\r\n','There are some persmissions which are assigned to public\r\n','pass',NULL,NULL,'2026-01-22 15:25:44'),(1187,202601,30,28,'AA_SqlServer_220_Public Database Permissions','critical','PRIV','This test checks database permisions for public . Public is a special role and permissions should not be granted to public role.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      exec sp_msforeachdb \'\'   USE [?]     iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'public\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND OBJECT_NAME(MAJOR_iD) NOT LiKE (\'\'\'\'%fn_cdc_get_net_changes_application_data%\'\'\'\')   AND NOT (OBJECT_SCHEMA_NAME(MAJOR_iD) = \'\'\'\'cdc\'\'\'\' and PERMiSSiON_NAME=\'\'\'\'SELECT\'\'\'\')   AND NOT (PERMiSSiON_NAME IN (\'\'\'\'REFERENCES\'\'\'\',\'\'\'\'SEND\'\'\'\',   \'\'\'\'VIEW ANY COLUMN ENCRYPTION KEY DEFINITION\'\'\'\',   \'\'\'\'VIEW ANY COLUMN MASTER KEY DEFINITION\'\'\'\' ) and OBJECT_SCHEMA_NAME(MAJOR_iD) IS NULL)   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select count(*) from #TEMP;   \' \r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      exec sp_msforeachdb \'\'   USE [?]     iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'public\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND OBJECT_NAME(MAJOR_iD) NOT LiKE (\'\'\'\'%fn_cdc_get_net_changes_application_data%\'\'\'\')   AND NOT (OBJECT_SCHEMA_NAME(MAJOR_iD) = \'\'\'\'cdc\'\'\'\' and PERMiSSiON_NAME=\'\'\'\'SELECT\'\'\'\')   AND NOT (PERMiSSiON_NAME IN (\'\'\'\'REFERENCES\'\'\'\',\'\'\'\'SEND\'\'\'\',   \'\'\'\'VIEW ANY COLUMN ENCRYPTION KEY DEFINITION\'\'\'\',   \'\'\'\'VIEW ANY COLUMN MASTER KEY DEFINITION\'\'\'\' ) and OBJECT_SCHEMA_NAME(MAJOR_iD) IS NULL)   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select * from #TEMP;   \' \r\n','There are no permissions which are assigned to public.\r\n','There are some persmissions which are assigned to public\r\n','pass',NULL,NULL,'2026-01-22 15:25:44'),(1188,202601,30,29,'AA_SqlServer_230_Real person users','critical','ACCOUNT','All logins to the database should be made with AD groups, real person users should  not be connected database directly\r\n','','Select      count(*)   from      sys.server_principals    where      name like \'ODEABANK%.%\'      and is_disabled = 0   \r\n','== 0','','Select      name     from      sys.server_principals    where      name like \'ODEABANK%.%\'      and is_disabled = 0;\r\n','Real person users are not found in the logins\r\n','Some real person users are found in the logins\r\n','pass',NULL,NULL,'2026-01-22 15:25:44'),(1189,202601,30,30,'AA_SqlServer_240_2_guest Database Permissions','critical','ACCOUNT','This test checks database permisions for guest . guest is a special user and permissions should not be granted to guest user.\r\n','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP ( row varchar(500));\r\n\r\nexec sp_MSforeachdb \'\'\r\nUSE [?]\r\niNSERT iNTO #TEMP\r\nSELECT\r\n\'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +\r\n\'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +\r\n\'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +\r\n\'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )\r\nFROM\r\nsys.database_permissions\r\nWHERE\r\nUSER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'guest\'\'\'\' )\r\nAND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'\r\nAND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')\r\nAND STATE_DESC=\'\'\'\'GRANT\'\'\'\'\r\n;\r\n\'\'\r\nselect count(*) from #TEMP;\r\n\'','== 0','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP ( row varchar(500));\r\n\r\nexec sp_MSforeachdb \'\'\r\nUSE [?]\r\niNSERT iNTO #TEMP\r\nSELECT\r\n\'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +\r\n\'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +\r\n\'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +\r\n\'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )\r\nFROM\r\nsys.database_permissions\r\nWHERE\r\nUSER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'guest\'\'\'\' )\r\nAND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'\r\nAND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')\r\nAND STATE_DESC=\'\'\'\'GRANT\'\'\'\'\r\n;\r\n\'\'\r\nselect * from #TEMP;\r\n\'','There are no permissions which are assigned to guest.\r\n','There are some persmissions which are assigned to guest\r\n','pass',NULL,NULL,'2026-01-22 15:25:44'),(1190,202601,30,31,'AA_SqlServer_240_guest Database Permissions','critical','PRIV','This test checks database permisions for guest . guest is a special user and permissions should not be granted to guest user.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      exec sp_msforeachdb \'\'   USE [?]     iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'guest\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select count(*) from #TEMP;   \' \r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      exec sp_msforeachdb \'\'   USE [?]     iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'guest\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select  *  from #TEMP;   \' \r\n','There are no permissions which are assigned to guest.\r\n','There are some persmissions which are assigned to guest\r\n','pass',NULL,NULL,'2026-01-22 15:25:44'),(1191,202601,30,32,'AA_SqlServer_250_Database Role members for guest','critical','PRIV','This test checks database role members for guest  user. Database roles  could not be assigned to guest role.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      EXEC sp_MSforeachdb \'\' USE [?]    INSERT INTO #TEMP   SELECT \'\'\'\'DB Name : \'\'\'\'+Cast (DB_NAME() as varchar)+\'\'\'\' Role Name : \'\'\'\'+USER_NAME(role_principal_id)  +\'\'\'\' User Name \'\'\'\'+  USER_NAME(member_principal_id)    from  sys.database_role_members   	Where     USER_NAME(member_principal_id)  = \'\'\'\'guest\'\'\'\'     ;   \'\'      Select count(*)  from #TEMP;   \'\r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      EXEC sp_MSforeachdb \'\' USE [?]    INSERT INTO #TEMP   SELECT \'\'\'\'DB Name : \'\'\'\'+Cast (DB_NAME() as varchar)+\'\'\'\' Role Name : \'\'\'\'+USER_NAME(role_principal_id)  +\'\'\'\' User Name \'\'\'\'+  USER_NAME(member_principal_id)    from  sys.database_role_members   	Where     USER_NAME(member_principal_id)  = \'\'\'\'guest\'\'\'\'     ;   \'\'      Select  *  from #TEMP;   \'\r\n','Database role member usage for guest user  is correct\r\n','Database role member usage for guest user  is not correct\r\n','pass',NULL,NULL,'2026-01-22 15:25:44'),(1192,202601,30,33,'AA_SqlServer_260_SQL Logins with Null Password','critical','ACCOUNT','This test checks sql logins with null password. SQL Logins should not have null passwords.\r\n','','SELECT      count(name)   from      sys.sql_logins    WHERE      PWDCOMPARE(\'\', password_hash)= 1\r\n','== 0','','SELECT      name    from      sys.sql_logins    WHERE      PWDCOMPARE(\'\', password_hash)= 1   \r\n','There are no sql logins with null paswords\r\n','There are some sql logins with null passwords.\r\n','pass',NULL,NULL,'2026-01-22 15:25:44'),(1193,202601,30,34,'AA_SqlServer_270_SQL Logins with username and passwords are equal','critical','ACCOUNT','This test checks sql login password which are egual to username. Username and password must be different for SQL logins.\r\n','','SELECT      count(name)   from      sys.sql_logins    WHERE      PWDCOMPARE(name,password_hash)=1 \r\n','== 0','','SELECT      name    from      sys.sql_logins    WHERE      PWDCOMPARE(name,password_hash)=1    \r\n','There is no SQL login name which is equal to password.\r\n','There are some sql logins whose passwords are egual to usernames.\r\n','pass',NULL,NULL,'2026-01-22 15:25:44'),(1194,202601,30,35,'AA_SqlServer_280_No Sample Databases','critical','CONFIG','This test checks whether the sample databases created optionally on installation are present.  These sample databases contain many default permissions, and can be used as an entry point to your systems. \r\n','','select      count(name)    from      sys.databases    where      name in (       \'AdventureWorks\', \'AdventureWorksDW\',        \'Northwind\', \'Pubs\'     )   \r\n','== 0','','select      name    from      sys.databases    where      name in (       \'AdventureWorks\', \'AdventureWorksDW\',        \'Northwind\', \'Pubs\'     )   \r\n','There are no sample databases in the server\r\n','There are some sample databases in the server\r\n','pass',NULL,NULL,'2026-01-22 15:25:44'),(1195,202601,30,43,'AA_SqlServer_350_User Password Policy Is Checked','critical','ACCOUNT','This test checks that CHECK_POLICY is enabled for all users.  Enabling CHECK_POLICY ensures that Windows passwords policies are enforced.','','select count(*) from sys.sql_logins  \r\nwhere \r\nis_policy_checked=0 and\r\nname not like \'##%\'','== 0','','select name from sys.sql_logins  \r\nwhere \r\nis_policy_checked=0 and\r\nname not like \'##%\'','CHECK_POLICY is enabled for all users','CHECK_POLICY is not enabled for all users','pass',NULL,NULL,'2026-01-22 15:25:44'),(1196,202601,30,44,'AA_SqlServer_360_CHECK_EXPIRATION Is Checked','critical','ACCOUNT','This test checks that CHECK_EXPIRATION is enabled for all users.  Passwords that have been in use for long periods of time are likely to become known to unauthorized users.\r\n','','select count(*) from sys.sql_logins     where    is_expiration_checked=0 and   name not like \'##%\'\r\n','== 0','','select name from sys.sql_logins     where    is_expiration_checked=0 and   name not like \'##%\'\r\n','CHECK_EXPIRATION is enabled for all users\r\n','CHECK_EXPIRATION is not enabled for all users\r\n','fail','name\n----\n\'sa\'',NULL,'2026-01-22 15:25:44'),(1197,202601,30,22,'AA_SqlServer_170_Windows Authentication','major','AUTH','This test checks that the authentication mode is set to Windows authentication only.  Windows provides a more robust authentication mechanism than SQL Server authentication.','',' SELECT cast( SERVERPROPERTY(\'IsIntegratedSecurityOnly\') as int) ','==1','','SELECT cast( SERVERPROPERTY(\'IsIntegratedSecurityOnly\') as varchar)','The authentication mode is set to Windows authentication only. ','The authentication mode is not set to Windows authentication only.','fail','\n---\n\'0\'',NULL,'2026-01-22 15:25:44'),(1198,202601,30,23,'AA_SqlServer_180_No Guest User Accounts','major','ACCOUNT','This test checks for the existence of guest user accounts with CONNECT permission in database other than master, msdb and tempdb.  This test also exclude databases that are flagged as distributor. If the GUEST user exists and a specific login has not been granted to a database, a login will be mapped to GUEST. The presence of the GUEST user allows all logins to access the database.\r\n','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP  ( row int);\r\n\r\nEXEC sp_MSforeachdb \'\' USE [?]\r\n	INSERT INTO #TEMP\r\n	SELECT count(*) \r\n	FROM sys.database_permissions\r\n	WHERE [grantee_principal_id] = DATABASE_PRINCIPAL_ID(\'\'\'\'guest\'\'\'\')\r\n	AND [state_desc] LIKE \'\'\'\'GRANT%\'\'\'\'\r\n	AND [permission_name] = \'\'\'\'CONNECT\'\'\'\'\r\n	AND DB_NAME() NOT IN (\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'msdb\'\'\'\') ;\r\n\'\'\r\n\r\nSelect sum(row) from #TEMP;\r\ndrop table #TEMP;\r\n\'','== 0','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP  ( row varchar(500));\r\n\r\nEXEC sp_MSforeachdb \'\' USE  [?] \r\n	INSERT INTO #TEMP\r\n	SELECT \'\'\'\' DB NAME : \'\'\'\' + Cast (DB_NAME() as varchar) + \'\'\'\' guest user has CONNECT permission \'\'\'\'\r\n	FROM sys.database_permissions\r\n	WHERE [grantee_principal_id] = DATABASE_PRINCIPAL_ID(\'\'\'\'guest\'\'\'\')\r\n	AND [state_desc] LIKE \'\'\'\'GRANT%\'\'\'\'\r\n	AND [permission_name] = \'\'\'\'CONNECT\'\'\'\'\r\n	AND DB_NAME() NOT IN (\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'msdb\'\'\'\') ;\r\n\'\'\r\n\r\nSelect * from #TEMP;\r\ndrop table #TEMP;\r\n\'','There is no guest user with CONNECT permission. ','There are   guest users with CONNECT permission. Remove these users','pass',NULL,NULL,'2026-01-22 15:25:44'),(1199,202601,30,36,'AA_SqlServer_290_2_No Permissions with GRANT Option','major','PRIV','This test checks database permisions  with grant option. No permission with grant option should be defined in the database.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP ( row varchar(500));      exec sp_MSforeachdb \'\'   USE [?]   iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   STATE_DESC like \'\'\'\'%WITH_GRANT%\'\'\'\'   ;   \'\'   select count(*) from #TEMP;   \'\r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP ( row varchar(500));      exec sp_MSforeachdb \'\'   USE [?]   iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   STATE_DESC like \'\'\'\'%WITH_GRANT%\'\'\'\'   ;   \'\'   select * from #TEMP;   \'\r\n','There are no permissions with grant option.\r\n','There are some persmissions  with grant option.\r\n','pass',NULL,NULL,'2026-01-22 15:25:44'),(1200,202601,30,37,'AA_SqlServer_290_No Permissions with GRANT Option','major','PRIV','','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP  ( row varchar(500));\r\n\r\nexec sp_msforeachdb \'\'\r\nUSE [?]  \r\niNSERT iNTO #TEMP\r\nSELECT\r\n\'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +\r\n\'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +\r\n\'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +\r\n\'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )\r\nFROM\r\nsys.database_permissions\r\nWHERE\r\nSTATE_DESC like \'\'\'\'%WITH_GRANT%\'\'\'\'\r\n;\r\n\'\'\r\nselect  count(*)  from #TEMP;\r\n\' ','== 0','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP  ( row varchar(500));\r\n\r\nexec sp_msforeachdb \'\'\r\nUSE [?]  \r\niNSERT iNTO #TEMP\r\nSELECT\r\n\'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +\r\n\'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +\r\n\'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +\r\n\'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )\r\nFROM\r\nsys.database_permissions\r\nWHERE\r\nSTATE_DESC like \'\'\'\'%WITH_GRANT%\'\'\'\'\r\n;\r\n\'\'\r\nselect * from #TEMP;\r\n\' ','There are no permissions with grant option.\r\n','There are some persmissions  with grant option.\r\n','pass',NULL,NULL,'2026-01-22 15:25:44'),(1201,202601,30,40,'AA_SqlServer_320_No Access to Registry Access Extended procedures','major','PRIV','This test checks for the existence of, and user permissions on, registry access extended stored procedures.  Either these procedures should be completely dropped, or access to them should be strictly limited. xp_reg%,xp_instance_reg%\r\n','','SELECT \r\ncount(*) \r\nFROM \r\n  [master].sys.system_objects o \r\n  JOIN [master].sys.database_permissions p ON o.object_id = p.major_id \r\n  JOIN [master].sys.database_principals u ON p.grantee_principal_id = u.principal_id \r\nWHERE \r\n( o.name LIKE \'xp_reg%\' OR o.name LIKE \'xp_instance_reg%\')\r\n  AND p.type = \'EX\' ','== 0','','SELECT \r\n  \'Principal : \'+u.name  COLLATE DATABASE_DEFAULT +\r\n  \' Extended Procedure Name : \'+o.name COLLATE DATABASE_DEFAULT +\r\n  \' Type : \'+ u.type_desc COLLATE DATABASE_DEFAULT \r\nFROM \r\n  [master].sys.system_objects o \r\n  JOIN [master].sys.database_permissions p ON o.object_id = p.major_id \r\n  JOIN [master].sys.database_principals u ON p.grantee_principal_id = u.principal_id \r\nWHERE \r\n( o.name LIKE \'xp_reg%\' OR o.name LIKE \'xp_instance_reg%\')\r\n  AND p.type = \'EX\' ','There are no permissions on registry access extended stored procedures\r\n','There are some persmissions permissions on registry access extended stored procedures\r\n','fail','\n---------------------------------------------------------------------------------------\n\'Principal : public Extended Procedure Name : xp_instance_regread Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_regread Type : DATABASE_ROLE\'',NULL,'2026-01-22 15:25:44'),(1202,202601,30,41,'AA_SqlServer_330_Revoke public login from SQL Server agent proxy account','major','PRIV','The public database role contains every user in the msdb database. SQL Agent proxies   define a security context in which a job step can run.Granting access to SQL Agent proxies for the public role would allow all users to utilize the proxy which may have high privileges. This would likely break the principle of least   privileges.\r\n','','SELECT count(*)\r\nFROM msdb.dbo.sysproxylogin spl\r\nJOIN sys.database_principals dp\r\nON dp.sid = spl.sid\r\nJOIN msdb.dbo.sysproxies sp\r\nON sp.proxy_id = spl.proxy_id\r\nWHERE principal_id = USER_ID(\'public\')','== 0','','SELECT \'proxyname : \'+CAST(sp.name  as varchar)\r\nFROM msdb.dbo.sysproxylogin spl\r\nJOIN sys.database_principals dp\r\nON dp.sid = spl.sid\r\nJOIN msdb.dbo.sysproxies sp\r\nON sp.proxy_id = spl.proxy_id\r\nWHERE principal_id = USER_ID(\'public\')','There are no public permissions on SQL Server agent proxy account\r\n','There are some public permissions on SQL Server agent proxy account\r\n','pass',NULL,NULL,'2026-01-22 15:25:44'),(1203,202601,30,42,'AA_SqlServer_340_No Individual User Access To syscomment and sp_helptext','minor','PRIV','This test checks for grants on SYSCOMMENTS.TEXT.  Such grants allow any user to read the text comments associated with a database object, making the text publicly viewable.\r\n','','SELECT count(*)\r\nFROM msdb.dbo.sysproxylogin spl\r\nJOIN sys.database_principals dp\r\nON dp.sid = spl.sid\r\nJOIN msdb.dbo.sysproxies sp\r\nON sp.proxy_id = spl.proxy_id\r\nWHERE principal_id = USER_ID(\'public\')\r\n','== 0','','SELECT count(*)\r\nFROM msdb.dbo.sysproxylogin spl\r\nJOIN sys.database_principals dp\r\nON dp.sid = spl.sid\r\nJOIN msdb.dbo.sysproxies sp\r\nON sp.proxy_id = spl.proxy_id\r\nWHERE principal_id = USER_ID(\'public\')','There are no public permissions on SQL Server agent proxy account','There are some public permissions on SQL Server agent proxy account','pass',NULL,NULL,'2026-01-22 15:25:44'),(1204,202601,30,10,'AA_SqlServer_050_Disable Ad hoc distributed queries option','major','CONFIG','Adhoc queries allow undefined access to remote database sources.  Access to untrusted databases could result in execution of malicious applications and/or a compromise of local data confidentiality and integrity. The DBA will configure the database to disable access from the database to objects stored externally to the database on the local host unless mission and/or operationally required and documented.\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Ad Hoc Distributed Queries\'','== 0','','SELECT name + \' Value : \'+ cast( value as varchar ) + \' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'Ad Hoc Distributed Queries\'','Ad Hoc Distributed Queries is disabled','Ad Hoc Distributed Queries is not disabled. Disable this option','pass',NULL,NULL,'2026-01-22 15:25:44'),(1205,202601,30,11,'AA_SqlServer_060_Disable CLR option','major','CONFIG','The clr_enabled parameter configures SQL Server to allow or disallow use of Command Language Runtime objects.  CLR objects is managed code that integrates with the .NET Framework.  This is a more secure method than external stored procedures, although it still contains some risk.  Where no external application execution requirements are required, disallowing use of any improves the overall security posture of the database.\r\n\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'clr enabled\'','== 0','','SELECT name + \' Value : \'+ cast( value as varchar ) + \' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'clr enabled\'','CLR option is disabled','CLR option is not disabled. Disable this option','pass',NULL,NULL,'2026-01-22 15:25:44'),(1206,202601,30,12,'AA_SqlServer_070_Disable Cross db ownership chaining option','major','CONFIG','Cross database ownership chaining allows permissions to objects to be assigned by users other than the Information Owner.  This allows access to objects that are not authorized directly by the Information Owner based on job functions defined by the owner.  Unauthorized access may lead to a compromise of data integrity or confidentiality. The DBA will ensure database privileges are assigned via roles and not directly assigned to database accounts. Privileges may be assigned directly to application owner accounts where the DBMS does not otherwise support access via roles.\r\n\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'cross db ownership chaining\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'cross db ownership chaining\'','Cross db ownership chaining  option is disabled','Cross db ownership chaining option  is not disabled. Disable this option','pass',NULL,NULL,'2026-01-22 15:25:44'),(1207,202601,30,13,'AA_SqlServer_080_Disable Database Mail XPs option','major','CONFIG','SQL Mail accepts incoming database commands via email. This can introduce malicious codes or viruses into the SQL server environment.','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Database Mail XPs\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \'Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'Database Mail XPs\'','Database Mail XPs option is disabled','Database Mail XPs option  is not disabled. Disable this option','pass',NULL,NULL,'2026-01-22 15:25:44'),(1208,202601,30,14,'AA_SqlServer_100_Disable xp_cmdshell Server Configuration option','major','CONFIG','The xp_cmdshell extended stored procedures allows execution of host executables outside the controls of database access permissions.  This access may be exploited by malicious users who have compromised the integrity of the SQL Server database process to control the host operating system to perpetrate additional malicious activity. The DBA should disable the use of external procedures by the database unless it is mission critical or operationally required','','SELECT CAST(value as int) +\r\n       CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'xp_cmdshell\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) +\r\n\' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'xp_cmdshell\'','xp_cmdshell Server Configuration option is disabled','xp_cmdshell Server Configuration option is not disabled. This option must be disabled','pass',NULL,NULL,'2026-01-22 15:25:44'),(1209,202601,30,15,'AA_SqlServer_110_Disable Remote Access option','major','CONFIG','The remote access option controls the execution of local stored procedures on remote\r\nservers or remote stored procedures on local server.Functionality can be abused to launch a Denial-of-Service (DoS) attack on remote servers\r\nby off-loading query processing to a target.\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'remote access\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \' Value in use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'remote access\'','Remote Access option is disabled','Remote Access option  is not disabled. Disable this option','fail','\n------------------------------------------\n\'remote access Value : 1 Value in use : 1\'',NULL,'2026-01-22 15:25:44'),(1210,202601,30,16,'AA_SqlServer_120_Disable Remote Admin Connections option','major','CONFIG','The remote admin connections option controls whether a client application on a remote\r\ncomputer can use the Dedicated Administrator Connection (DAC).The Dedicated Administrator Connection (DAC) lets an administrator access a running\r\nserver to execute diagnostic functions or Transact-SQL statements, or to troubleshoot\r\nproblems on the server, even when the server is locked or running in an abnormal state\r\nand not responding to a SQL Server Database Engine connection. In a cluster scenario, the\r\nadministrator may not actually be logged on to the same node that is currently hosting the\r\nSQL Server instance and thus is considered \"remote\". Therefore, this setting should usually\r\nbe enabled (1) for SQL Server failover clusters; otherwise it should be disabled (0) which is\r\nthe default.\r\n','','execute sp_executesql N\'\r\n\r\nDECLARE @x int;\r\n\r\nSELECT @x=isnull(CAST(value as int) + CAST(value_in_use as int),100)\r\nFROM sys.configurations\r\nWHERE name = \'\'remote admin connections\'\'\r\n\r\nIF @x = 100\r\n       SELECT 0 ;\r\nELSE \r\n   SELECT CAST(value as int) + CAST(value_in_use as int) \r\n   FROM sys.configurations\r\n   WHERE name = \'\'remote admin connections\'\'\r\n\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'remote admin connections\'','Remote Admin Connections option is disabled','Remote Admin Connections option  is not disabled. Disable this option','pass',NULL,NULL,'2026-01-22 15:25:44'),(1211,202601,30,19,'AA_SqlServer_150_Disable database trustworthy status','major','CONFIG','The TRUSTWORTHY database setting restricts access to database resources by databases that contain assemblies with the EXTERNAL_ACCESS or UNSAFE permission settings and modules that use impersonation of accounts assigned elevated privileges.  Unless all assemblies and code for the database have been reviewed, especially in the case where databases have been detached and attached between server instances, leaving the TRUSTWORTHY status to off can help reduce threats from malicious assemblies or modules.','','SELECT count(name)\r\nFROM sys.databases\r\nWHERE is_trustworthy_on = 1\r\nAND name != \'msdb\';','== 0','','SELECT name\r\nFROM sys.databases\r\nWHERE is_trustworthy_on = 1\r\nAND name != \'msdb\';','database trustworthy status is disabled','database trustworthy status is not disabled. Disable this option','pass',NULL,NULL,'2026-01-22 15:25:44'),(1212,202601,30,20,'Checkpoint başarıyla oluşturuldu.','major','CONFIG','This test checks if SQL Server Instance is not advertised by the SQL Server Browser service. To maintain a higher level of protection for database instances, we recommend that SQL Server Instance be hidden when it is not required. Please note that this test does not include Clustered Instances as turning off this feature may cause issues with the Clustered environment.\r\n\r\n','','execute sp_executesql N\'\r\n\r\nDECLARE @getValue INT\r\n\r\nEXEC master.sys.xp_instance_regread\r\n@rootkey = N\'\'HKEY_LOCAL_MACHINE\'\',\r\n@key = N\'\'SOFTWARE\\Microsoft\\Microsoft SQL Server\\MSSQLServer\\SuperSocketNetLib\'\',\r\n@value_name = N\'\'HideInstance\'\',\r\n@value = @getValue OUTPUT\r\n\r\nSELECT isnull(@getvalue,0)\'','==1','','execute sp_executesql N\'\r\n\r\nDECLARE @getValue INT\r\n\r\nEXEC master.sys.xp_instance_regread\r\n@rootkey = N\'\'HKEY_LOCAL_MACHINE\'\',\r\n@key = N\'\'SOFTWARE\\Microsoft\\Microsoft SQL Server\\MSSQLServer\\SuperSocketNetLib\'\',\r\n@value_name = N\'\'HideInstance\'\',\r\n@value = @getValue OUTPUT\r\n\r\nSELECT isnull(@getvalue,0)\'','SQL Server Instance is  hidden.\r\n','SQL Server Instance is not hidden. Hide the instance','fail','\n-\n0',NULL,'2026-01-22 15:25:44'),(1213,202601,30,21,'AA_SqlServer_160_Hide SQL Server Instance','major','CONFIG','This test checks if SQL Server Instance is not advertised by the SQL Server Browser service. To maintain a higher level of protection for database instances, we recommend that SQL Server Instance be hidden when it is not required. Please note that this test does not include Clustered Instances as turning off this feature may cause issues with the Clustered environment.\r\n\r\n','','execute sp_executesql N\'\r\n\r\nDECLARE @getValue INT\r\n\r\nEXEC master.sys.xp_instance_regread\r\n@rootkey = N\'\'HKEY_LOCAL_MACHINE\'\',\r\n@key = N\'\'SOFTWARE\\Microsoft\\Microsoft SQL Server\\MSSQLServer\\SuperSocketNetLib\'\',\r\n@value_name = N\'\'HideInstance\'\',\r\n@value = @getValue OUTPUT\r\n\r\nSELECT isnull(@getvalue,0)\'','==1','','execute sp_executesql N\'\r\n\r\nDECLARE @getValue INT\r\n\r\nEXEC master.sys.xp_instance_regread\r\n@rootkey = N\'\'HKEY_LOCAL_MACHINE\'\',\r\n@key = N\'\'SOFTWARE\\Microsoft\\Microsoft SQL Server\\MSSQLServer\\SuperSocketNetLib\'\',\r\n@value_name = N\'\'HideInstance\'\',\r\n@value = @getValue OUTPUT\r\n\r\nSELECT isnull(@getvalue,0)\'','SQL Server Instance is  hidden.','SQL Server Instance is not hidden. Hide the instance','fail','\n-\n0',NULL,'2026-01-22 15:25:44'),(1214,202601,30,38,'AA_SqlServer_300_No Access To General Extended procedures','major','PRIV','This test checks for the existence of, and user permissions on, extended stored procedures.  Either these procedures should be completely dropped, or access to them should be strictly limited. xp_cmdshell, xp_enumgroups, xp_grantlogin ,xp_logevent, xp_logininfo,    xp_msver, xp_revokelogin, xp_sprintf, xp_sqlmaint, xp_sscanf\r\n','','SELECT \r\ncount(*) \r\nFROM \r\n  [master].sys.system_objects o \r\n  JOIN [master].sys.database_permissions p ON o.object_id = p.major_id \r\n  JOIN [master].sys.database_principals u ON p.grantee_principal_id = u.principal_id \r\nWHERE \r\n    o.name in ( \r\n	\'xp_cmdshell\', \r\n	\'xp_enumgroups\', \r\n    \'xp_grantlogin\' ,\r\n	\'xp_logevent\', \r\n	\'xp_logininfo\', \r\n    \'xp_msver\', \r\n	\'xp_revokelogin\', \r\n	\'xp_sprintf\', \r\n    \'xp_sqlmaint\', \r\n	\'xp_sscanf\' )\r\n  AND p.type = \'EX\' ','== 0','','SELECT \r\n  \'Principal : \'+u.name  COLLATE DATABASE_DEFAULT +\r\n  \' Extended Procedure Name : \'+o.name COLLATE DATABASE_DEFAULT +\r\n  \' Type : \'+ u.type_desc COLLATE DATABASE_DEFAULT \r\nFROM \r\n  [master].sys.system_objects o \r\n  JOIN [master].sys.database_permissions p ON o.object_id = p.major_id \r\n  JOIN [master].sys.database_principals u ON p.grantee_principal_id = u.principal_id \r\nWHERE \r\n    o.name in ( \r\n	\'xp_cmdshell\', \r\n	\'xp_enumgroups\', \r\n    \'xp_grantlogin\' ,\r\n	\'xp_logevent\', \r\n	\'xp_logininfo\', \r\n    \'xp_msver\', \r\n	\'xp_revokelogin\', \r\n	\'xp_sprintf\', \r\n    \'xp_sqlmaint\', \r\n	\'xp_sscanf\' )\r\n  AND p.type = \'EX\' ','There are no permissions on general extended stored procedures\r\n','There are some persmissions permissions on general extended stored procedures.\r\n','fail','\n----------------------------------------------------------------------------------\n\'Principal : public Extended Procedure Name : xp_msver Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_sscanf Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_revokelogin Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_grantlogin Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_sprintf Type : DATABASE_ROLE\'',NULL,'2026-01-22 15:25:44'),(1215,202601,30,39,'AA_SqlServer_310_No Access to OLE Automation procedures','major','CONFIG','This test checks for the existence of,and user permissions on OLE automation extended stored procedures.  Either these procedures should be completely dropped, or access to them should be strictly limited.      \r\n','','SELECT CAST(value as int) +\r\n       CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Ole Automation Procedures\'   \r\n','== 0','','SELECT CAST(value as int) +\r\n       CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Ole Automation Procedures\'\r\n  \r\n','OLE Automation procedures  option is disabled\r\n','OLE Automation procedures  option  is not disabled. Disable this option\r\n','pass',NULL,NULL,'2026-01-22 15:25:44'),(1216,202601,30,17,'AA_SqlServer_130_Disable Ole Automation Procedures option','minor','CONFIG','This test checks if Ole Automation Procedures option is disabled. Ole Automation Procedures option allows SQL Server users to execute functions external to SQL Server. Enabling this option will increase the attack surface of SQL Server and allow users to execute functions in the security context of SQL Server. We recommend that the Ole Automation Procedures option to be disabled when it is not document as a requirement.\r\n\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Ole Automation Procedures\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \'Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'Ole Automation Procedures\'',' Ole Automation Procedures option is disabled',' Ole Automation Procedures option  is not disabled. Disable this option','pass',NULL,NULL,'2026-01-22 15:25:44'),(1217,202601,30,18,'AA_SqlServer_140_Disable Scan for Startup Procedures option','minor','CONFIG','This test checks if scan for startup procedures is disabled. This feature causes SQL Server to scan for and automatically run all stored procedures that are set to execute upon service startup. If there are no user-defined stored procedures set to execute when SQL server starts, we recommend this feature to be disabled.\r\n\r\n','','SELECT CAST(value as int) +\r\n       CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'scan for startup procs\'','== 0','','SELECT name + \' value : \'+cast( value as varchar ) +\r\n\' value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'scan for startup procs\'','Scan for Startup Procedures  option is disabled','Scan for Startup Procedures  option  is not disabled. Disable this option','pass',NULL,NULL,'2026-01-22 15:25:44'),(1218,202601,30,9,'AA_SqlServer_040_Rename the sa Login Account','major','ACCOUNT','The \'sa\' account is a well-known account.  Well-known account names provide an easier target for attack.  Renaming the sa account helps reduce the risk of an attack to this built-in account.','','SELECT count(*)\r\nFROM sys.server_principals\r\nWHERE sid = 0x01 and name=\'sa\'','== 0','','SELECT name\r\nFROM sys.server_principals\r\nWHERE sid = 0x01','sa Login Account is renamed','sa Login Account is not renamed. Rename this account','fail','name\n----\n\'sa\'',NULL,'2026-01-22 15:25:44'),(1219,202601,31,24,'AA_SqlServer_190_Public server role permision','critical','PRIV','public is a special fixed server role containing all logins. Unlike other fixed server roles,\r\npermissions can be changed for the public role. In keeping with the principle of least\r\nprivileges, the public server role should not be used to grant permissions at the server\r\nscope as these would be inherited by all users.\r\n\r\nEvery SQL Server login belongs to the public role and cannot be removed from this role.\r\nTherefore, any permissions granted to this role will be available to all logins unless they\r\nhave been explicitly denied to specific logins or user-defined server roles.','','Select \r\n  count (permission_name) \r\nfrom \r\n  sys.server_permissions \r\nwhere \r\n  SUSER_NAME(grantee_principal_id) = \'public\' \r\n  and permission_name not in (\'VIEW ANY DATABASE\', \'CONNECT\')\r\n','== 0','','Select \r\n  permission_name \r\nfrom \r\n  sys.server_permissions \r\nwhere \r\n  SUSER_NAME(grantee_principal_id) = \'public\' \r\n  and permission_name not in (\'VIEW ANY DATABASE\', \'CONNECT\')\r\n\r\n','No server permissions are granted to public.','Some server permissions are granted to public.','pass',NULL,NULL,'2026-01-22 15:26:06'),(1220,202601,31,5,'AA_SqlServer_010_Supported SQL Server version','critical','PATCH','This test checks whether your current SQL Server version is a vendor-supported version.  Microsoft does not provide security fixes or software updates to unsupported software versions','','SELECT cast(ISNULL(SERVERPROPERTY(\'ProductMajorVersion\'),0) as int)   ','>=11','','SELECT \'Product Major version \' +  cast(ISNULL(SERVERPROPERTY(\'ProductMajorVersion\'),\'Null\' ) as  char ) ','The version of the database is acceptable.','The version of the database is not acceptable. The database version should SQL Sever 2012 or upper.','pass',NULL,NULL,'2026-01-22 15:26:06'),(1221,202601,31,6,'AA_SqlServer_020_Disable the sa Login Account','critical','ACCOUNT','This test checks if the \'sa\' Login Account is disabled. The sa account is a widely known and often widely used SQL Server account with sysadmin privileges. Enforcing this control reduces the probability of an attacker executing brute force attacks against a well-known principal.','','SELECT  count(*)\r\nFROM sys.server_principals\r\nWHERE sid = 0x01\r\nAND is_disabled = 0','== 0','','SELECT \'sa user name : \'+ name+\' is disabled : \' +  cast( is_disabled as char)\r\nFROM sys.server_principals\r\nWHERE sid = 0x01\r\n','sa Login Account is disabled','Disable sa login account','fail','\n----------------------------------------------------------------\n\'sa user name : sa is disabled : 0                             \'',NULL,'2026-01-22 15:26:06'),(1222,202601,31,7,'AA_SqlServer_025_sa Change password','critical','ACCOUNT','This test checks that sa password change . The sa password should be changed in every two days','','select datediff( day,  modify_date , getdate() ) FROM sys.server_principals\r\nWHERE sid = 0x01  ','< 3','','select datediff( day,  modify_date , getdate() ) FROM sys.server_principals\r\nWHERE sid = 0x01 ','sa password was changed in two days','','fail','\n-\n8',NULL,'2026-01-22 15:26:06'),(1223,202601,31,8,'AA_SqlServer_030_Ensure no Login exists with sa Login Account','critical','ACCOUNT','The \'sa\' account is a well-known account.  Well-known account names provide an easier target for attack. The lack of the sa account helps reduce the risk of an attack to this built-in account.','','SELECT count(*)\r\nFROM sys.server_principals\r\nWHERE name = \'sa\'','== 0','','SELECT name\r\nFROM sys.server_principals\r\nWHERE name = \'sa\'','There is no the sa account in the database.','There is the sa Login account in the database.Drop this user or rename et.','fail','name\n----\n\'sa\'',NULL,'2026-01-22 15:26:06'),(1224,202601,31,25,'AA_SqlServer_200_Fixed Server Role members for users','critical','PRIV','This test checks fixed server roles for analyst , developers and real persons. Fixed server roles could not be assigned to real person users ( Developer, Analyst users ) . Only Admin can use fixed server role.\r\n','','Select     count(*)   from      sys.server_role_members    where      (       suser_name(member_principal_id) like \'ODEABANK%.%\'    	AND       suser_name(member_principal_id) not like \'%admin%\'         AND       suser_name(member_principal_id) not like \'%t.coban%\'     )      OR (       suser_name(member_principal_id) like \'ODEABANK\\Cyberark_Intertech%\'     )      \r\n','== 0','','Select      suser_name(role_principal_id) + \'   \' + suser_name(member_principal_id)    from      sys.server_role_members    where      (       suser_name(member_principal_id) like \'ODEABANK%.%\'    	AND       suser_name(member_principal_id) not like \'%admin%\'         AND       suser_name(member_principal_id) not like \'%t.coban%\'     )      OR (       suser_name(member_principal_id) like \'ODEABANK\\Cyberark_Intertech%\'     )          \r\n','Fixed Server role usage is correct.\r\n','Fixed Server role usage is not correct.\r\n','pass',NULL,NULL,'2026-01-22 15:26:06'),(1225,202601,31,26,'AA_SqlServer_210_Database Role members for users','critical','PRIV','This test checks database role members for analyst and real person users. Database roles  except  db_datareader could not be assigned to real person users ( Developer, Analyst users ) .\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      EXEC sp_MSforeachdb \'\' USE [?]    INSERT INTO #TEMP   SELECT \'\'\'\'DB Name : \'\'\'\'+Cast (DB_NAME() as varchar)+\'\'\'\' Role Name : \'\'\'\'+USER_NAME(role_principal_id)  +\'\'\'\' User Name \'\'\'\'+  USER_NAME(member_principal_id)    from  sys.database_role_members   	Where   	(   	( USER_NAME(member_principal_id)  like \'\'\'\'%ODEABANK%.%\'\'\'\'  and   USER_NAME(member_principal_id)  not like \'\'\'\'%admin%\'\'\'\' )     	OR   	  (suser_name(member_principal_id) like \'\'\'\'%ODEABANK%Cyberark%\'\'\'\')       )    	AND   	DB_NAME() <> \'\'\'\'master\'\'\'\' and   	USER_NAME(role_principal_id) not in (\'\'\'\'db_datareader\'\'\'\',\'\'\'\'db_viewdefinition\'\'\'\',\'\'\'\'db_denydatareader\'\'\'\',\'\'\'\'db_deny_maas\'\'\'\');   \'\'      Select  count(*)  from #TEMP;   \'\r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      EXEC sp_MSforeachdb \'\' USE [?]    INSERT INTO #TEMP   SELECT \'\'\'\'DB Name : \'\'\'\'+Cast (DB_NAME() as varchar)+\'\'\'\' Role Name : \'\'\'\'+USER_NAME(role_principal_id)  +\'\'\'\' User Name \'\'\'\'+  USER_NAME(member_principal_id)    from  sys.database_role_members   	Where   (   	( USER_NAME(member_principal_id)  like \'\'\'\'%ODEABANK%.%\'\'\'\'  and   USER_NAME(member_principal_id)  not like \'\'\'\'%admin%\'\'\'\' )     	OR   	(suser_name(member_principal_id) like \'\'\'\'%ODEABANK%Cyberark%\'\'\'\')   )    	AND   	DB_NAME() <> \'\'\'\'master\'\'\'\' and   	USER_NAME(role_principal_id) not in  (\'\'\'\'db_datareader\'\'\'\',\'\'\'\'db_viewdefinition\'\'\'\',\'\'\'\'db_denydatareader\'\'\'\',\'\'\'\'db_deny_maas\'\'\'\');   \'\'      Select  * from #TEMP;   \'\r\n','Database role member usage for users  is correct\r\n','Database role member usage for users  is not correct\r\n','pass',NULL,NULL,'2026-01-22 15:26:06'),(1226,202601,31,27,'AA_SqlServer_220_2_Public Database Permissions','critical','PRIV','This test checks database permisions for public . Public is a special role and permissions should not be granted to public role.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP ( row varchar(500));          exec sp_MSforeachdb \'\'   USE [?]   iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'public\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND OBJECT_NAME(MAJOR_iD) NOT LiKE (\'\'\'\'%fn_cdc_get_net_changes_application_data%\'\'\'\')   AND NOT (OBJECT_SCHEMA_NAME(MAJOR_iD) = \'\'\'\'cdc\'\'\'\' and PERMiSSiON_NAME=\'\'\'\'SELECT\'\'\'\')   AND NOT (PERMiSSiON_NAME IN (\'\'\'\'REFERENCES\'\'\'\',\'\'\'\'SEND\'\'\'\',   \'\'\'\'VIEW ANY COLUMN ENCRYPTION KEY DEFINITION\'\'\'\',   \'\'\'\'VIEW ANY COLUMN MASTER KEY DEFINITION\'\'\'\' ) and OBJECT_SCHEMA_NAME(MAJOR_iD) IS NULL)   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select count(*) from #TEMP;   \'\r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP ( row varchar(500));          exec sp_MSforeachdb \'\'   USE [?]   iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'public\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND OBJECT_NAME(MAJOR_iD) NOT LiKE (\'\'\'\'%fn_cdc_get_net_changes_application_data%\'\'\'\')   AND NOT (OBJECT_SCHEMA_NAME(MAJOR_iD) = \'\'\'\'cdc\'\'\'\' and PERMiSSiON_NAME=\'\'\'\'SELECT\'\'\'\')   AND NOT (PERMiSSiON_NAME IN (\'\'\'\'REFERENCES\'\'\'\',\'\'\'\'SEND\'\'\'\',   \'\'\'\'VIEW ANY COLUMN ENCRYPTION KEY DEFINITION\'\'\'\',   \'\'\'\'VIEW ANY COLUMN MASTER KEY DEFINITION\'\'\'\' ) and OBJECT_SCHEMA_NAME(MAJOR_iD) IS NULL)   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select * from #TEMP;   \'','There are no permissions which are assigned to public.\r\n','There are some persmissions which are assigned to public\r\n','pass',NULL,NULL,'2026-01-22 15:26:06'),(1227,202601,31,28,'AA_SqlServer_220_Public Database Permissions','critical','PRIV','This test checks database permisions for public . Public is a special role and permissions should not be granted to public role.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      exec sp_msforeachdb \'\'   USE [?]     iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'public\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND OBJECT_NAME(MAJOR_iD) NOT LiKE (\'\'\'\'%fn_cdc_get_net_changes_application_data%\'\'\'\')   AND NOT (OBJECT_SCHEMA_NAME(MAJOR_iD) = \'\'\'\'cdc\'\'\'\' and PERMiSSiON_NAME=\'\'\'\'SELECT\'\'\'\')   AND NOT (PERMiSSiON_NAME IN (\'\'\'\'REFERENCES\'\'\'\',\'\'\'\'SEND\'\'\'\',   \'\'\'\'VIEW ANY COLUMN ENCRYPTION KEY DEFINITION\'\'\'\',   \'\'\'\'VIEW ANY COLUMN MASTER KEY DEFINITION\'\'\'\' ) and OBJECT_SCHEMA_NAME(MAJOR_iD) IS NULL)   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select count(*) from #TEMP;   \' \r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      exec sp_msforeachdb \'\'   USE [?]     iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'public\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND OBJECT_NAME(MAJOR_iD) NOT LiKE (\'\'\'\'%fn_cdc_get_net_changes_application_data%\'\'\'\')   AND NOT (OBJECT_SCHEMA_NAME(MAJOR_iD) = \'\'\'\'cdc\'\'\'\' and PERMiSSiON_NAME=\'\'\'\'SELECT\'\'\'\')   AND NOT (PERMiSSiON_NAME IN (\'\'\'\'REFERENCES\'\'\'\',\'\'\'\'SEND\'\'\'\',   \'\'\'\'VIEW ANY COLUMN ENCRYPTION KEY DEFINITION\'\'\'\',   \'\'\'\'VIEW ANY COLUMN MASTER KEY DEFINITION\'\'\'\' ) and OBJECT_SCHEMA_NAME(MAJOR_iD) IS NULL)   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select * from #TEMP;   \' \r\n','There are no permissions which are assigned to public.\r\n','There are some persmissions which are assigned to public\r\n','pass',NULL,NULL,'2026-01-22 15:26:06'),(1228,202601,31,29,'AA_SqlServer_230_Real person users','critical','ACCOUNT','All logins to the database should be made with AD groups, real person users should  not be connected database directly\r\n','','Select      count(*)   from      sys.server_principals    where      name like \'ODEABANK%.%\'      and is_disabled = 0   \r\n','== 0','','Select      name     from      sys.server_principals    where      name like \'ODEABANK%.%\'      and is_disabled = 0;\r\n','Real person users are not found in the logins\r\n','Some real person users are found in the logins\r\n','pass',NULL,NULL,'2026-01-22 15:26:06'),(1229,202601,31,30,'AA_SqlServer_240_2_guest Database Permissions','critical','ACCOUNT','This test checks database permisions for guest . guest is a special user and permissions should not be granted to guest user.\r\n','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP ( row varchar(500));\r\n\r\nexec sp_MSforeachdb \'\'\r\nUSE [?]\r\niNSERT iNTO #TEMP\r\nSELECT\r\n\'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +\r\n\'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +\r\n\'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +\r\n\'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )\r\nFROM\r\nsys.database_permissions\r\nWHERE\r\nUSER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'guest\'\'\'\' )\r\nAND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'\r\nAND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')\r\nAND STATE_DESC=\'\'\'\'GRANT\'\'\'\'\r\n;\r\n\'\'\r\nselect count(*) from #TEMP;\r\n\'','== 0','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP ( row varchar(500));\r\n\r\nexec sp_MSforeachdb \'\'\r\nUSE [?]\r\niNSERT iNTO #TEMP\r\nSELECT\r\n\'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +\r\n\'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +\r\n\'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +\r\n\'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )\r\nFROM\r\nsys.database_permissions\r\nWHERE\r\nUSER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'guest\'\'\'\' )\r\nAND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'\r\nAND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')\r\nAND STATE_DESC=\'\'\'\'GRANT\'\'\'\'\r\n;\r\n\'\'\r\nselect * from #TEMP;\r\n\'','There are no permissions which are assigned to guest.\r\n','There are some persmissions which are assigned to guest\r\n','pass',NULL,NULL,'2026-01-22 15:26:06'),(1230,202601,31,31,'AA_SqlServer_240_guest Database Permissions','critical','PRIV','This test checks database permisions for guest . guest is a special user and permissions should not be granted to guest user.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      exec sp_msforeachdb \'\'   USE [?]     iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'guest\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select count(*) from #TEMP;   \' \r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      exec sp_msforeachdb \'\'   USE [?]     iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'guest\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select  *  from #TEMP;   \' \r\n','There are no permissions which are assigned to guest.\r\n','There are some persmissions which are assigned to guest\r\n','pass',NULL,NULL,'2026-01-22 15:26:06'),(1231,202601,31,32,'AA_SqlServer_250_Database Role members for guest','critical','PRIV','This test checks database role members for guest  user. Database roles  could not be assigned to guest role.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      EXEC sp_MSforeachdb \'\' USE [?]    INSERT INTO #TEMP   SELECT \'\'\'\'DB Name : \'\'\'\'+Cast (DB_NAME() as varchar)+\'\'\'\' Role Name : \'\'\'\'+USER_NAME(role_principal_id)  +\'\'\'\' User Name \'\'\'\'+  USER_NAME(member_principal_id)    from  sys.database_role_members   	Where     USER_NAME(member_principal_id)  = \'\'\'\'guest\'\'\'\'     ;   \'\'      Select count(*)  from #TEMP;   \'\r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      EXEC sp_MSforeachdb \'\' USE [?]    INSERT INTO #TEMP   SELECT \'\'\'\'DB Name : \'\'\'\'+Cast (DB_NAME() as varchar)+\'\'\'\' Role Name : \'\'\'\'+USER_NAME(role_principal_id)  +\'\'\'\' User Name \'\'\'\'+  USER_NAME(member_principal_id)    from  sys.database_role_members   	Where     USER_NAME(member_principal_id)  = \'\'\'\'guest\'\'\'\'     ;   \'\'      Select  *  from #TEMP;   \'\r\n','Database role member usage for guest user  is correct\r\n','Database role member usage for guest user  is not correct\r\n','pass',NULL,NULL,'2026-01-22 15:26:06'),(1232,202601,31,33,'AA_SqlServer_260_SQL Logins with Null Password','critical','ACCOUNT','This test checks sql logins with null password. SQL Logins should not have null passwords.\r\n','','SELECT      count(name)   from      sys.sql_logins    WHERE      PWDCOMPARE(\'\', password_hash)= 1\r\n','== 0','','SELECT      name    from      sys.sql_logins    WHERE      PWDCOMPARE(\'\', password_hash)= 1   \r\n','There are no sql logins with null paswords\r\n','There are some sql logins with null passwords.\r\n','pass',NULL,NULL,'2026-01-22 15:26:06'),(1233,202601,31,34,'AA_SqlServer_270_SQL Logins with username and passwords are equal','critical','ACCOUNT','This test checks sql login password which are egual to username. Username and password must be different for SQL logins.\r\n','','SELECT      count(name)   from      sys.sql_logins    WHERE      PWDCOMPARE(name,password_hash)=1 \r\n','== 0','','SELECT      name    from      sys.sql_logins    WHERE      PWDCOMPARE(name,password_hash)=1    \r\n','There is no SQL login name which is equal to password.\r\n','There are some sql logins whose passwords are egual to usernames.\r\n','pass',NULL,NULL,'2026-01-22 15:26:06'),(1234,202601,31,35,'AA_SqlServer_280_No Sample Databases','critical','CONFIG','This test checks whether the sample databases created optionally on installation are present.  These sample databases contain many default permissions, and can be used as an entry point to your systems. \r\n','','select      count(name)    from      sys.databases    where      name in (       \'AdventureWorks\', \'AdventureWorksDW\',        \'Northwind\', \'Pubs\'     )   \r\n','== 0','','select      name    from      sys.databases    where      name in (       \'AdventureWorks\', \'AdventureWorksDW\',        \'Northwind\', \'Pubs\'     )   \r\n','There are no sample databases in the server\r\n','There are some sample databases in the server\r\n','pass',NULL,NULL,'2026-01-22 15:26:06'),(1235,202601,31,43,'AA_SqlServer_350_User Password Policy Is Checked','critical','ACCOUNT','This test checks that CHECK_POLICY is enabled for all users.  Enabling CHECK_POLICY ensures that Windows passwords policies are enforced.','','select count(*) from sys.sql_logins  \r\nwhere \r\nis_policy_checked=0 and\r\nname not like \'##%\'','== 0','','select name from sys.sql_logins  \r\nwhere \r\nis_policy_checked=0 and\r\nname not like \'##%\'','CHECK_POLICY is enabled for all users','CHECK_POLICY is not enabled for all users','pass',NULL,NULL,'2026-01-22 15:26:06'),(1236,202601,31,44,'AA_SqlServer_360_CHECK_EXPIRATION Is Checked','critical','ACCOUNT','This test checks that CHECK_EXPIRATION is enabled for all users.  Passwords that have been in use for long periods of time are likely to become known to unauthorized users.\r\n','','select count(*) from sys.sql_logins     where    is_expiration_checked=0 and   name not like \'##%\'\r\n','== 0','','select name from sys.sql_logins     where    is_expiration_checked=0 and   name not like \'##%\'\r\n','CHECK_EXPIRATION is enabled for all users\r\n','CHECK_EXPIRATION is not enabled for all users\r\n','fail','name\n----\n\'sa\'',NULL,'2026-01-22 15:26:06'),(1237,202601,31,22,'AA_SqlServer_170_Windows Authentication','major','AUTH','This test checks that the authentication mode is set to Windows authentication only.  Windows provides a more robust authentication mechanism than SQL Server authentication.','',' SELECT cast( SERVERPROPERTY(\'IsIntegratedSecurityOnly\') as int) ','==1','','SELECT cast( SERVERPROPERTY(\'IsIntegratedSecurityOnly\') as varchar)','The authentication mode is set to Windows authentication only. ','The authentication mode is not set to Windows authentication only.','fail','\n---\n\'0\'',NULL,'2026-01-22 15:26:06'),(1238,202601,31,23,'AA_SqlServer_180_No Guest User Accounts','major','ACCOUNT','This test checks for the existence of guest user accounts with CONNECT permission in database other than master, msdb and tempdb.  This test also exclude databases that are flagged as distributor. If the GUEST user exists and a specific login has not been granted to a database, a login will be mapped to GUEST. The presence of the GUEST user allows all logins to access the database.\r\n','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP  ( row int);\r\n\r\nEXEC sp_MSforeachdb \'\' USE [?]\r\n	INSERT INTO #TEMP\r\n	SELECT count(*) \r\n	FROM sys.database_permissions\r\n	WHERE [grantee_principal_id] = DATABASE_PRINCIPAL_ID(\'\'\'\'guest\'\'\'\')\r\n	AND [state_desc] LIKE \'\'\'\'GRANT%\'\'\'\'\r\n	AND [permission_name] = \'\'\'\'CONNECT\'\'\'\'\r\n	AND DB_NAME() NOT IN (\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'msdb\'\'\'\') ;\r\n\'\'\r\n\r\nSelect sum(row) from #TEMP;\r\ndrop table #TEMP;\r\n\'','== 0','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP  ( row varchar(500));\r\n\r\nEXEC sp_MSforeachdb \'\' USE  [?] \r\n	INSERT INTO #TEMP\r\n	SELECT \'\'\'\' DB NAME : \'\'\'\' + Cast (DB_NAME() as varchar) + \'\'\'\' guest user has CONNECT permission \'\'\'\'\r\n	FROM sys.database_permissions\r\n	WHERE [grantee_principal_id] = DATABASE_PRINCIPAL_ID(\'\'\'\'guest\'\'\'\')\r\n	AND [state_desc] LIKE \'\'\'\'GRANT%\'\'\'\'\r\n	AND [permission_name] = \'\'\'\'CONNECT\'\'\'\'\r\n	AND DB_NAME() NOT IN (\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'msdb\'\'\'\') ;\r\n\'\'\r\n\r\nSelect * from #TEMP;\r\ndrop table #TEMP;\r\n\'','There is no guest user with CONNECT permission. ','There are   guest users with CONNECT permission. Remove these users','pass',NULL,NULL,'2026-01-22 15:26:07'),(1239,202601,31,36,'AA_SqlServer_290_2_No Permissions with GRANT Option','major','PRIV','This test checks database permisions  with grant option. No permission with grant option should be defined in the database.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP ( row varchar(500));      exec sp_MSforeachdb \'\'   USE [?]   iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   STATE_DESC like \'\'\'\'%WITH_GRANT%\'\'\'\'   ;   \'\'   select count(*) from #TEMP;   \'\r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP ( row varchar(500));      exec sp_MSforeachdb \'\'   USE [?]   iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   STATE_DESC like \'\'\'\'%WITH_GRANT%\'\'\'\'   ;   \'\'   select * from #TEMP;   \'\r\n','There are no permissions with grant option.\r\n','There are some persmissions  with grant option.\r\n','pass',NULL,NULL,'2026-01-22 15:26:07'),(1240,202601,31,37,'AA_SqlServer_290_No Permissions with GRANT Option','major','PRIV','','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP  ( row varchar(500));\r\n\r\nexec sp_msforeachdb \'\'\r\nUSE [?]  \r\niNSERT iNTO #TEMP\r\nSELECT\r\n\'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +\r\n\'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +\r\n\'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +\r\n\'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )\r\nFROM\r\nsys.database_permissions\r\nWHERE\r\nSTATE_DESC like \'\'\'\'%WITH_GRANT%\'\'\'\'\r\n;\r\n\'\'\r\nselect  count(*)  from #TEMP;\r\n\' ','== 0','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP  ( row varchar(500));\r\n\r\nexec sp_msforeachdb \'\'\r\nUSE [?]  \r\niNSERT iNTO #TEMP\r\nSELECT\r\n\'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +\r\n\'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +\r\n\'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +\r\n\'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )\r\nFROM\r\nsys.database_permissions\r\nWHERE\r\nSTATE_DESC like \'\'\'\'%WITH_GRANT%\'\'\'\'\r\n;\r\n\'\'\r\nselect * from #TEMP;\r\n\' ','There are no permissions with grant option.\r\n','There are some persmissions  with grant option.\r\n','pass',NULL,NULL,'2026-01-22 15:26:07'),(1241,202601,31,40,'AA_SqlServer_320_No Access to Registry Access Extended procedures','major','PRIV','This test checks for the existence of, and user permissions on, registry access extended stored procedures.  Either these procedures should be completely dropped, or access to them should be strictly limited. xp_reg%,xp_instance_reg%\r\n','','SELECT \r\ncount(*) \r\nFROM \r\n  [master].sys.system_objects o \r\n  JOIN [master].sys.database_permissions p ON o.object_id = p.major_id \r\n  JOIN [master].sys.database_principals u ON p.grantee_principal_id = u.principal_id \r\nWHERE \r\n( o.name LIKE \'xp_reg%\' OR o.name LIKE \'xp_instance_reg%\')\r\n  AND p.type = \'EX\' ','== 0','','SELECT \r\n  \'Principal : \'+u.name  COLLATE DATABASE_DEFAULT +\r\n  \' Extended Procedure Name : \'+o.name COLLATE DATABASE_DEFAULT +\r\n  \' Type : \'+ u.type_desc COLLATE DATABASE_DEFAULT \r\nFROM \r\n  [master].sys.system_objects o \r\n  JOIN [master].sys.database_permissions p ON o.object_id = p.major_id \r\n  JOIN [master].sys.database_principals u ON p.grantee_principal_id = u.principal_id \r\nWHERE \r\n( o.name LIKE \'xp_reg%\' OR o.name LIKE \'xp_instance_reg%\')\r\n  AND p.type = \'EX\' ','There are no permissions on registry access extended stored procedures\r\n','There are some persmissions permissions on registry access extended stored procedures\r\n','fail','\n---------------------------------------------------------------------------------------\n\'Principal : public Extended Procedure Name : xp_instance_regread Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_regread Type : DATABASE_ROLE\'',NULL,'2026-01-22 15:26:07'),(1242,202601,31,41,'AA_SqlServer_330_Revoke public login from SQL Server agent proxy account','major','PRIV','The public database role contains every user in the msdb database. SQL Agent proxies   define a security context in which a job step can run.Granting access to SQL Agent proxies for the public role would allow all users to utilize the proxy which may have high privileges. This would likely break the principle of least   privileges.\r\n','','SELECT count(*)\r\nFROM msdb.dbo.sysproxylogin spl\r\nJOIN sys.database_principals dp\r\nON dp.sid = spl.sid\r\nJOIN msdb.dbo.sysproxies sp\r\nON sp.proxy_id = spl.proxy_id\r\nWHERE principal_id = USER_ID(\'public\')','== 0','','SELECT \'proxyname : \'+CAST(sp.name  as varchar)\r\nFROM msdb.dbo.sysproxylogin spl\r\nJOIN sys.database_principals dp\r\nON dp.sid = spl.sid\r\nJOIN msdb.dbo.sysproxies sp\r\nON sp.proxy_id = spl.proxy_id\r\nWHERE principal_id = USER_ID(\'public\')','There are no public permissions on SQL Server agent proxy account\r\n','There are some public permissions on SQL Server agent proxy account\r\n','pass',NULL,NULL,'2026-01-22 15:26:07'),(1243,202601,31,42,'AA_SqlServer_340_No Individual User Access To syscomment and sp_helptext','minor','PRIV','This test checks for grants on SYSCOMMENTS.TEXT.  Such grants allow any user to read the text comments associated with a database object, making the text publicly viewable.\r\n','','SELECT count(*)\r\nFROM msdb.dbo.sysproxylogin spl\r\nJOIN sys.database_principals dp\r\nON dp.sid = spl.sid\r\nJOIN msdb.dbo.sysproxies sp\r\nON sp.proxy_id = spl.proxy_id\r\nWHERE principal_id = USER_ID(\'public\')\r\n','== 0','','SELECT count(*)\r\nFROM msdb.dbo.sysproxylogin spl\r\nJOIN sys.database_principals dp\r\nON dp.sid = spl.sid\r\nJOIN msdb.dbo.sysproxies sp\r\nON sp.proxy_id = spl.proxy_id\r\nWHERE principal_id = USER_ID(\'public\')','There are no public permissions on SQL Server agent proxy account','There are some public permissions on SQL Server agent proxy account','pass',NULL,NULL,'2026-01-22 15:26:07'),(1244,202601,31,10,'AA_SqlServer_050_Disable Ad hoc distributed queries option','major','CONFIG','Adhoc queries allow undefined access to remote database sources.  Access to untrusted databases could result in execution of malicious applications and/or a compromise of local data confidentiality and integrity. The DBA will configure the database to disable access from the database to objects stored externally to the database on the local host unless mission and/or operationally required and documented.\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Ad Hoc Distributed Queries\'','== 0','','SELECT name + \' Value : \'+ cast( value as varchar ) + \' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'Ad Hoc Distributed Queries\'','Ad Hoc Distributed Queries is disabled','Ad Hoc Distributed Queries is not disabled. Disable this option','pass',NULL,NULL,'2026-01-22 15:26:07'),(1245,202601,31,11,'AA_SqlServer_060_Disable CLR option','major','CONFIG','The clr_enabled parameter configures SQL Server to allow or disallow use of Command Language Runtime objects.  CLR objects is managed code that integrates with the .NET Framework.  This is a more secure method than external stored procedures, although it still contains some risk.  Where no external application execution requirements are required, disallowing use of any improves the overall security posture of the database.\r\n\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'clr enabled\'','== 0','','SELECT name + \' Value : \'+ cast( value as varchar ) + \' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'clr enabled\'','CLR option is disabled','CLR option is not disabled. Disable this option','pass',NULL,NULL,'2026-01-22 15:26:07'),(1246,202601,31,12,'AA_SqlServer_070_Disable Cross db ownership chaining option','major','CONFIG','Cross database ownership chaining allows permissions to objects to be assigned by users other than the Information Owner.  This allows access to objects that are not authorized directly by the Information Owner based on job functions defined by the owner.  Unauthorized access may lead to a compromise of data integrity or confidentiality. The DBA will ensure database privileges are assigned via roles and not directly assigned to database accounts. Privileges may be assigned directly to application owner accounts where the DBMS does not otherwise support access via roles.\r\n\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'cross db ownership chaining\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'cross db ownership chaining\'','Cross db ownership chaining  option is disabled','Cross db ownership chaining option  is not disabled. Disable this option','pass',NULL,NULL,'2026-01-22 15:26:07'),(1247,202601,31,13,'AA_SqlServer_080_Disable Database Mail XPs option','major','CONFIG','SQL Mail accepts incoming database commands via email. This can introduce malicious codes or viruses into the SQL server environment.','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Database Mail XPs\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \'Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'Database Mail XPs\'','Database Mail XPs option is disabled','Database Mail XPs option  is not disabled. Disable this option','pass',NULL,NULL,'2026-01-22 15:26:07'),(1248,202601,31,14,'AA_SqlServer_100_Disable xp_cmdshell Server Configuration option','major','CONFIG','The xp_cmdshell extended stored procedures allows execution of host executables outside the controls of database access permissions.  This access may be exploited by malicious users who have compromised the integrity of the SQL Server database process to control the host operating system to perpetrate additional malicious activity. The DBA should disable the use of external procedures by the database unless it is mission critical or operationally required','','SELECT CAST(value as int) +\r\n       CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'xp_cmdshell\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) +\r\n\' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'xp_cmdshell\'','xp_cmdshell Server Configuration option is disabled','xp_cmdshell Server Configuration option is not disabled. This option must be disabled','pass',NULL,NULL,'2026-01-22 15:26:07'),(1249,202601,31,15,'AA_SqlServer_110_Disable Remote Access option','major','CONFIG','The remote access option controls the execution of local stored procedures on remote\r\nservers or remote stored procedures on local server.Functionality can be abused to launch a Denial-of-Service (DoS) attack on remote servers\r\nby off-loading query processing to a target.\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'remote access\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \' Value in use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'remote access\'','Remote Access option is disabled','Remote Access option  is not disabled. Disable this option','fail','\n------------------------------------------\n\'remote access Value : 1 Value in use : 1\'',NULL,'2026-01-22 15:26:07'),(1250,202601,31,16,'AA_SqlServer_120_Disable Remote Admin Connections option','major','CONFIG','The remote admin connections option controls whether a client application on a remote\r\ncomputer can use the Dedicated Administrator Connection (DAC).The Dedicated Administrator Connection (DAC) lets an administrator access a running\r\nserver to execute diagnostic functions or Transact-SQL statements, or to troubleshoot\r\nproblems on the server, even when the server is locked or running in an abnormal state\r\nand not responding to a SQL Server Database Engine connection. In a cluster scenario, the\r\nadministrator may not actually be logged on to the same node that is currently hosting the\r\nSQL Server instance and thus is considered \"remote\". Therefore, this setting should usually\r\nbe enabled (1) for SQL Server failover clusters; otherwise it should be disabled (0) which is\r\nthe default.\r\n','','execute sp_executesql N\'\r\n\r\nDECLARE @x int;\r\n\r\nSELECT @x=isnull(CAST(value as int) + CAST(value_in_use as int),100)\r\nFROM sys.configurations\r\nWHERE name = \'\'remote admin connections\'\'\r\n\r\nIF @x = 100\r\n       SELECT 0 ;\r\nELSE \r\n   SELECT CAST(value as int) + CAST(value_in_use as int) \r\n   FROM sys.configurations\r\n   WHERE name = \'\'remote admin connections\'\'\r\n\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'remote admin connections\'','Remote Admin Connections option is disabled','Remote Admin Connections option  is not disabled. Disable this option','pass',NULL,NULL,'2026-01-22 15:26:07'),(1251,202601,31,19,'AA_SqlServer_150_Disable database trustworthy status','major','CONFIG','The TRUSTWORTHY database setting restricts access to database resources by databases that contain assemblies with the EXTERNAL_ACCESS or UNSAFE permission settings and modules that use impersonation of accounts assigned elevated privileges.  Unless all assemblies and code for the database have been reviewed, especially in the case where databases have been detached and attached between server instances, leaving the TRUSTWORTHY status to off can help reduce threats from malicious assemblies or modules.','','SELECT count(name)\r\nFROM sys.databases\r\nWHERE is_trustworthy_on = 1\r\nAND name != \'msdb\';','== 0','','SELECT name\r\nFROM sys.databases\r\nWHERE is_trustworthy_on = 1\r\nAND name != \'msdb\';','database trustworthy status is disabled','database trustworthy status is not disabled. Disable this option','pass',NULL,NULL,'2026-01-22 15:26:07'),(1252,202601,31,20,'Checkpoint başarıyla oluşturuldu.','major','CONFIG','This test checks if SQL Server Instance is not advertised by the SQL Server Browser service. To maintain a higher level of protection for database instances, we recommend that SQL Server Instance be hidden when it is not required. Please note that this test does not include Clustered Instances as turning off this feature may cause issues with the Clustered environment.\r\n\r\n','','execute sp_executesql N\'\r\n\r\nDECLARE @getValue INT\r\n\r\nEXEC master.sys.xp_instance_regread\r\n@rootkey = N\'\'HKEY_LOCAL_MACHINE\'\',\r\n@key = N\'\'SOFTWARE\\Microsoft\\Microsoft SQL Server\\MSSQLServer\\SuperSocketNetLib\'\',\r\n@value_name = N\'\'HideInstance\'\',\r\n@value = @getValue OUTPUT\r\n\r\nSELECT isnull(@getvalue,0)\'','==1','','execute sp_executesql N\'\r\n\r\nDECLARE @getValue INT\r\n\r\nEXEC master.sys.xp_instance_regread\r\n@rootkey = N\'\'HKEY_LOCAL_MACHINE\'\',\r\n@key = N\'\'SOFTWARE\\Microsoft\\Microsoft SQL Server\\MSSQLServer\\SuperSocketNetLib\'\',\r\n@value_name = N\'\'HideInstance\'\',\r\n@value = @getValue OUTPUT\r\n\r\nSELECT isnull(@getvalue,0)\'','SQL Server Instance is  hidden.\r\n','SQL Server Instance is not hidden. Hide the instance','fail','\n-\n0',NULL,'2026-01-22 15:26:07'),(1253,202601,31,21,'AA_SqlServer_160_Hide SQL Server Instance','major','CONFIG','This test checks if SQL Server Instance is not advertised by the SQL Server Browser service. To maintain a higher level of protection for database instances, we recommend that SQL Server Instance be hidden when it is not required. Please note that this test does not include Clustered Instances as turning off this feature may cause issues with the Clustered environment.\r\n\r\n','','execute sp_executesql N\'\r\n\r\nDECLARE @getValue INT\r\n\r\nEXEC master.sys.xp_instance_regread\r\n@rootkey = N\'\'HKEY_LOCAL_MACHINE\'\',\r\n@key = N\'\'SOFTWARE\\Microsoft\\Microsoft SQL Server\\MSSQLServer\\SuperSocketNetLib\'\',\r\n@value_name = N\'\'HideInstance\'\',\r\n@value = @getValue OUTPUT\r\n\r\nSELECT isnull(@getvalue,0)\'','==1','','execute sp_executesql N\'\r\n\r\nDECLARE @getValue INT\r\n\r\nEXEC master.sys.xp_instance_regread\r\n@rootkey = N\'\'HKEY_LOCAL_MACHINE\'\',\r\n@key = N\'\'SOFTWARE\\Microsoft\\Microsoft SQL Server\\MSSQLServer\\SuperSocketNetLib\'\',\r\n@value_name = N\'\'HideInstance\'\',\r\n@value = @getValue OUTPUT\r\n\r\nSELECT isnull(@getvalue,0)\'','SQL Server Instance is  hidden.','SQL Server Instance is not hidden. Hide the instance','fail','\n-\n0',NULL,'2026-01-22 15:26:07'),(1254,202601,31,38,'AA_SqlServer_300_No Access To General Extended procedures','major','PRIV','This test checks for the existence of, and user permissions on, extended stored procedures.  Either these procedures should be completely dropped, or access to them should be strictly limited. xp_cmdshell, xp_enumgroups, xp_grantlogin ,xp_logevent, xp_logininfo,    xp_msver, xp_revokelogin, xp_sprintf, xp_sqlmaint, xp_sscanf\r\n','','SELECT \r\ncount(*) \r\nFROM \r\n  [master].sys.system_objects o \r\n  JOIN [master].sys.database_permissions p ON o.object_id = p.major_id \r\n  JOIN [master].sys.database_principals u ON p.grantee_principal_id = u.principal_id \r\nWHERE \r\n    o.name in ( \r\n	\'xp_cmdshell\', \r\n	\'xp_enumgroups\', \r\n    \'xp_grantlogin\' ,\r\n	\'xp_logevent\', \r\n	\'xp_logininfo\', \r\n    \'xp_msver\', \r\n	\'xp_revokelogin\', \r\n	\'xp_sprintf\', \r\n    \'xp_sqlmaint\', \r\n	\'xp_sscanf\' )\r\n  AND p.type = \'EX\' ','== 0','','SELECT \r\n  \'Principal : \'+u.name  COLLATE DATABASE_DEFAULT +\r\n  \' Extended Procedure Name : \'+o.name COLLATE DATABASE_DEFAULT +\r\n  \' Type : \'+ u.type_desc COLLATE DATABASE_DEFAULT \r\nFROM \r\n  [master].sys.system_objects o \r\n  JOIN [master].sys.database_permissions p ON o.object_id = p.major_id \r\n  JOIN [master].sys.database_principals u ON p.grantee_principal_id = u.principal_id \r\nWHERE \r\n    o.name in ( \r\n	\'xp_cmdshell\', \r\n	\'xp_enumgroups\', \r\n    \'xp_grantlogin\' ,\r\n	\'xp_logevent\', \r\n	\'xp_logininfo\', \r\n    \'xp_msver\', \r\n	\'xp_revokelogin\', \r\n	\'xp_sprintf\', \r\n    \'xp_sqlmaint\', \r\n	\'xp_sscanf\' )\r\n  AND p.type = \'EX\' ','There are no permissions on general extended stored procedures\r\n','There are some persmissions permissions on general extended stored procedures.\r\n','fail','\n----------------------------------------------------------------------------------\n\'Principal : public Extended Procedure Name : xp_msver Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_sscanf Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_revokelogin Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_grantlogin Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_sprintf Type : DATABASE_ROLE\'',NULL,'2026-01-22 15:26:07'),(1255,202601,31,39,'AA_SqlServer_310_No Access to OLE Automation procedures','major','CONFIG','This test checks for the existence of,and user permissions on OLE automation extended stored procedures.  Either these procedures should be completely dropped, or access to them should be strictly limited.      \r\n','','SELECT CAST(value as int) +\r\n       CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Ole Automation Procedures\'   \r\n','== 0','','SELECT CAST(value as int) +\r\n       CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Ole Automation Procedures\'\r\n  \r\n','OLE Automation procedures  option is disabled\r\n','OLE Automation procedures  option  is not disabled. Disable this option\r\n','pass',NULL,NULL,'2026-01-22 15:26:07'),(1256,202601,31,17,'AA_SqlServer_130_Disable Ole Automation Procedures option','minor','CONFIG','This test checks if Ole Automation Procedures option is disabled. Ole Automation Procedures option allows SQL Server users to execute functions external to SQL Server. Enabling this option will increase the attack surface of SQL Server and allow users to execute functions in the security context of SQL Server. We recommend that the Ole Automation Procedures option to be disabled when it is not document as a requirement.\r\n\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Ole Automation Procedures\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \'Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'Ole Automation Procedures\'',' Ole Automation Procedures option is disabled',' Ole Automation Procedures option  is not disabled. Disable this option','pass',NULL,NULL,'2026-01-22 15:26:07'),(1257,202601,31,18,'AA_SqlServer_140_Disable Scan for Startup Procedures option','minor','CONFIG','This test checks if scan for startup procedures is disabled. This feature causes SQL Server to scan for and automatically run all stored procedures that are set to execute upon service startup. If there are no user-defined stored procedures set to execute when SQL server starts, we recommend this feature to be disabled.\r\n\r\n','','SELECT CAST(value as int) +\r\n       CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'scan for startup procs\'','== 0','','SELECT name + \' value : \'+cast( value as varchar ) +\r\n\' value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'scan for startup procs\'','Scan for Startup Procedures  option is disabled','Scan for Startup Procedures  option  is not disabled. Disable this option','pass',NULL,NULL,'2026-01-22 15:26:07'),(1258,202601,31,9,'AA_SqlServer_040_Rename the sa Login Account','major','ACCOUNT','The \'sa\' account is a well-known account.  Well-known account names provide an easier target for attack.  Renaming the sa account helps reduce the risk of an attack to this built-in account.','','SELECT count(*)\r\nFROM sys.server_principals\r\nWHERE sid = 0x01 and name=\'sa\'','== 0','','SELECT name\r\nFROM sys.server_principals\r\nWHERE sid = 0x01','sa Login Account is renamed','sa Login Account is not renamed. Rename this account','fail','name\n----\n\'sa\'',NULL,'2026-01-22 15:26:07'),(1259,202601,32,24,'AA_SqlServer_190_Public server role permision','critical','PRIV','public is a special fixed server role containing all logins. Unlike other fixed server roles,\r\npermissions can be changed for the public role. In keeping with the principle of least\r\nprivileges, the public server role should not be used to grant permissions at the server\r\nscope as these would be inherited by all users.\r\n\r\nEvery SQL Server login belongs to the public role and cannot be removed from this role.\r\nTherefore, any permissions granted to this role will be available to all logins unless they\r\nhave been explicitly denied to specific logins or user-defined server roles.','','Select \r\n  count (permission_name) \r\nfrom \r\n  sys.server_permissions \r\nwhere \r\n  SUSER_NAME(grantee_principal_id) = \'public\' \r\n  and permission_name not in (\'VIEW ANY DATABASE\', \'CONNECT\')\r\n','== 0','','Select \r\n  permission_name \r\nfrom \r\n  sys.server_permissions \r\nwhere \r\n  SUSER_NAME(grantee_principal_id) = \'public\' \r\n  and permission_name not in (\'VIEW ANY DATABASE\', \'CONNECT\')\r\n\r\n','No server permissions are granted to public.','Some server permissions are granted to public.','pass',NULL,NULL,'2026-01-22 15:27:55'),(1260,202601,32,5,'AA_SqlServer_010_Supported SQL Server version','critical','PATCH','This test checks whether your current SQL Server version is a vendor-supported version.  Microsoft does not provide security fixes or software updates to unsupported software versions','','SELECT cast(ISNULL(SERVERPROPERTY(\'ProductMajorVersion\'),0) as int)   ','>=11','','SELECT \'Product Major version \' +  cast(ISNULL(SERVERPROPERTY(\'ProductMajorVersion\'),\'Null\' ) as  char ) ','The version of the database is acceptable.','The version of the database is not acceptable. The database version should SQL Sever 2012 or upper.','pass',NULL,NULL,'2026-01-22 15:27:55'),(1261,202601,32,6,'AA_SqlServer_020_Disable the sa Login Account','critical','ACCOUNT','This test checks if the \'sa\' Login Account is disabled. The sa account is a widely known and often widely used SQL Server account with sysadmin privileges. Enforcing this control reduces the probability of an attacker executing brute force attacks against a well-known principal.','','SELECT  count(*)\r\nFROM sys.server_principals\r\nWHERE sid = 0x01\r\nAND is_disabled = 0','== 0','','SELECT \'sa user name : \'+ name+\' is disabled : \' +  cast( is_disabled as char)\r\nFROM sys.server_principals\r\nWHERE sid = 0x01\r\n','sa Login Account is disabled','Disable sa login account','fail','\n----------------------------------------------------------------\n\'sa user name : sa is disabled : 0                             \'',NULL,'2026-01-22 15:27:55'),(1262,202601,32,7,'AA_SqlServer_025_sa Change password','critical','ACCOUNT','This test checks that sa password change . The sa password should be changed in every two days','','select datediff( day,  modify_date , getdate() ) FROM sys.server_principals\r\nWHERE sid = 0x01  ','< 3','','select datediff( day,  modify_date , getdate() ) FROM sys.server_principals\r\nWHERE sid = 0x01 ','sa password was changed in two days','','fail','\n-\n8',NULL,'2026-01-22 15:27:55'),(1263,202601,32,8,'AA_SqlServer_030_Ensure no Login exists with sa Login Account','critical','ACCOUNT','The \'sa\' account is a well-known account.  Well-known account names provide an easier target for attack. The lack of the sa account helps reduce the risk of an attack to this built-in account.','','SELECT count(*)\r\nFROM sys.server_principals\r\nWHERE name = \'sa\'','== 0','','SELECT name\r\nFROM sys.server_principals\r\nWHERE name = \'sa\'','There is no the sa account in the database.','There is the sa Login account in the database.Drop this user or rename et.','fail','name\n----\n\'sa\'',NULL,'2026-01-22 15:27:55'),(1264,202601,32,25,'AA_SqlServer_200_Fixed Server Role members for users','critical','PRIV','This test checks fixed server roles for analyst , developers and real persons. Fixed server roles could not be assigned to real person users ( Developer, Analyst users ) . Only Admin can use fixed server role.\r\n','','Select     count(*)   from      sys.server_role_members    where      (       suser_name(member_principal_id) like \'ODEABANK%.%\'    	AND       suser_name(member_principal_id) not like \'%admin%\'         AND       suser_name(member_principal_id) not like \'%t.coban%\'     )      OR (       suser_name(member_principal_id) like \'ODEABANK\\Cyberark_Intertech%\'     )      \r\n','== 0','','Select      suser_name(role_principal_id) + \'   \' + suser_name(member_principal_id)    from      sys.server_role_members    where      (       suser_name(member_principal_id) like \'ODEABANK%.%\'    	AND       suser_name(member_principal_id) not like \'%admin%\'         AND       suser_name(member_principal_id) not like \'%t.coban%\'     )      OR (       suser_name(member_principal_id) like \'ODEABANK\\Cyberark_Intertech%\'     )          \r\n','Fixed Server role usage is correct.\r\n','Fixed Server role usage is not correct.\r\n','pass',NULL,NULL,'2026-01-22 15:27:55'),(1265,202601,32,26,'AA_SqlServer_210_Database Role members for users','critical','PRIV','This test checks database role members for analyst and real person users. Database roles  except  db_datareader could not be assigned to real person users ( Developer, Analyst users ) .\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      EXEC sp_MSforeachdb \'\' USE [?]    INSERT INTO #TEMP   SELECT \'\'\'\'DB Name : \'\'\'\'+Cast (DB_NAME() as varchar)+\'\'\'\' Role Name : \'\'\'\'+USER_NAME(role_principal_id)  +\'\'\'\' User Name \'\'\'\'+  USER_NAME(member_principal_id)    from  sys.database_role_members   	Where   	(   	( USER_NAME(member_principal_id)  like \'\'\'\'%ODEABANK%.%\'\'\'\'  and   USER_NAME(member_principal_id)  not like \'\'\'\'%admin%\'\'\'\' )     	OR   	  (suser_name(member_principal_id) like \'\'\'\'%ODEABANK%Cyberark%\'\'\'\')       )    	AND   	DB_NAME() <> \'\'\'\'master\'\'\'\' and   	USER_NAME(role_principal_id) not in (\'\'\'\'db_datareader\'\'\'\',\'\'\'\'db_viewdefinition\'\'\'\',\'\'\'\'db_denydatareader\'\'\'\',\'\'\'\'db_deny_maas\'\'\'\');   \'\'      Select  count(*)  from #TEMP;   \'\r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      EXEC sp_MSforeachdb \'\' USE [?]    INSERT INTO #TEMP   SELECT \'\'\'\'DB Name : \'\'\'\'+Cast (DB_NAME() as varchar)+\'\'\'\' Role Name : \'\'\'\'+USER_NAME(role_principal_id)  +\'\'\'\' User Name \'\'\'\'+  USER_NAME(member_principal_id)    from  sys.database_role_members   	Where   (   	( USER_NAME(member_principal_id)  like \'\'\'\'%ODEABANK%.%\'\'\'\'  and   USER_NAME(member_principal_id)  not like \'\'\'\'%admin%\'\'\'\' )     	OR   	(suser_name(member_principal_id) like \'\'\'\'%ODEABANK%Cyberark%\'\'\'\')   )    	AND   	DB_NAME() <> \'\'\'\'master\'\'\'\' and   	USER_NAME(role_principal_id) not in  (\'\'\'\'db_datareader\'\'\'\',\'\'\'\'db_viewdefinition\'\'\'\',\'\'\'\'db_denydatareader\'\'\'\',\'\'\'\'db_deny_maas\'\'\'\');   \'\'      Select  * from #TEMP;   \'\r\n','Database role member usage for users  is correct\r\n','Database role member usage for users  is not correct\r\n','pass',NULL,NULL,'2026-01-22 15:27:55'),(1266,202601,32,27,'AA_SqlServer_220_2_Public Database Permissions','critical','PRIV','This test checks database permisions for public . Public is a special role and permissions should not be granted to public role.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP ( row varchar(500));          exec sp_MSforeachdb \'\'   USE [?]   iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'public\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND OBJECT_NAME(MAJOR_iD) NOT LiKE (\'\'\'\'%fn_cdc_get_net_changes_application_data%\'\'\'\')   AND NOT (OBJECT_SCHEMA_NAME(MAJOR_iD) = \'\'\'\'cdc\'\'\'\' and PERMiSSiON_NAME=\'\'\'\'SELECT\'\'\'\')   AND NOT (PERMiSSiON_NAME IN (\'\'\'\'REFERENCES\'\'\'\',\'\'\'\'SEND\'\'\'\',   \'\'\'\'VIEW ANY COLUMN ENCRYPTION KEY DEFINITION\'\'\'\',   \'\'\'\'VIEW ANY COLUMN MASTER KEY DEFINITION\'\'\'\' ) and OBJECT_SCHEMA_NAME(MAJOR_iD) IS NULL)   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select count(*) from #TEMP;   \'\r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP ( row varchar(500));          exec sp_MSforeachdb \'\'   USE [?]   iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'public\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND OBJECT_NAME(MAJOR_iD) NOT LiKE (\'\'\'\'%fn_cdc_get_net_changes_application_data%\'\'\'\')   AND NOT (OBJECT_SCHEMA_NAME(MAJOR_iD) = \'\'\'\'cdc\'\'\'\' and PERMiSSiON_NAME=\'\'\'\'SELECT\'\'\'\')   AND NOT (PERMiSSiON_NAME IN (\'\'\'\'REFERENCES\'\'\'\',\'\'\'\'SEND\'\'\'\',   \'\'\'\'VIEW ANY COLUMN ENCRYPTION KEY DEFINITION\'\'\'\',   \'\'\'\'VIEW ANY COLUMN MASTER KEY DEFINITION\'\'\'\' ) and OBJECT_SCHEMA_NAME(MAJOR_iD) IS NULL)   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select * from #TEMP;   \'','There are no permissions which are assigned to public.\r\n','There are some persmissions which are assigned to public\r\n','pass',NULL,NULL,'2026-01-22 15:27:55'),(1267,202601,32,28,'AA_SqlServer_220_Public Database Permissions','critical','PRIV','This test checks database permisions for public . Public is a special role and permissions should not be granted to public role.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      exec sp_msforeachdb \'\'   USE [?]     iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'public\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND OBJECT_NAME(MAJOR_iD) NOT LiKE (\'\'\'\'%fn_cdc_get_net_changes_application_data%\'\'\'\')   AND NOT (OBJECT_SCHEMA_NAME(MAJOR_iD) = \'\'\'\'cdc\'\'\'\' and PERMiSSiON_NAME=\'\'\'\'SELECT\'\'\'\')   AND NOT (PERMiSSiON_NAME IN (\'\'\'\'REFERENCES\'\'\'\',\'\'\'\'SEND\'\'\'\',   \'\'\'\'VIEW ANY COLUMN ENCRYPTION KEY DEFINITION\'\'\'\',   \'\'\'\'VIEW ANY COLUMN MASTER KEY DEFINITION\'\'\'\' ) and OBJECT_SCHEMA_NAME(MAJOR_iD) IS NULL)   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select count(*) from #TEMP;   \' \r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      exec sp_msforeachdb \'\'   USE [?]     iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'public\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND OBJECT_NAME(MAJOR_iD) NOT LiKE (\'\'\'\'%fn_cdc_get_net_changes_application_data%\'\'\'\')   AND NOT (OBJECT_SCHEMA_NAME(MAJOR_iD) = \'\'\'\'cdc\'\'\'\' and PERMiSSiON_NAME=\'\'\'\'SELECT\'\'\'\')   AND NOT (PERMiSSiON_NAME IN (\'\'\'\'REFERENCES\'\'\'\',\'\'\'\'SEND\'\'\'\',   \'\'\'\'VIEW ANY COLUMN ENCRYPTION KEY DEFINITION\'\'\'\',   \'\'\'\'VIEW ANY COLUMN MASTER KEY DEFINITION\'\'\'\' ) and OBJECT_SCHEMA_NAME(MAJOR_iD) IS NULL)   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select * from #TEMP;   \' \r\n','There are no permissions which are assigned to public.\r\n','There are some persmissions which are assigned to public\r\n','pass',NULL,NULL,'2026-01-22 15:27:55'),(1268,202601,32,29,'AA_SqlServer_230_Real person users','critical','ACCOUNT','All logins to the database should be made with AD groups, real person users should  not be connected database directly\r\n','','Select      count(*)   from      sys.server_principals    where      name like \'ODEABANK%.%\'      and is_disabled = 0   \r\n','== 0','','Select      name     from      sys.server_principals    where      name like \'ODEABANK%.%\'      and is_disabled = 0;\r\n','Real person users are not found in the logins\r\n','Some real person users are found in the logins\r\n','pass',NULL,NULL,'2026-01-22 15:27:55'),(1269,202601,32,30,'AA_SqlServer_240_2_guest Database Permissions','critical','ACCOUNT','This test checks database permisions for guest . guest is a special user and permissions should not be granted to guest user.\r\n','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP ( row varchar(500));\r\n\r\nexec sp_MSforeachdb \'\'\r\nUSE [?]\r\niNSERT iNTO #TEMP\r\nSELECT\r\n\'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +\r\n\'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +\r\n\'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +\r\n\'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )\r\nFROM\r\nsys.database_permissions\r\nWHERE\r\nUSER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'guest\'\'\'\' )\r\nAND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'\r\nAND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')\r\nAND STATE_DESC=\'\'\'\'GRANT\'\'\'\'\r\n;\r\n\'\'\r\nselect count(*) from #TEMP;\r\n\'','== 0','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP ( row varchar(500));\r\n\r\nexec sp_MSforeachdb \'\'\r\nUSE [?]\r\niNSERT iNTO #TEMP\r\nSELECT\r\n\'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +\r\n\'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +\r\n\'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +\r\n\'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )\r\nFROM\r\nsys.database_permissions\r\nWHERE\r\nUSER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'guest\'\'\'\' )\r\nAND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'\r\nAND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')\r\nAND STATE_DESC=\'\'\'\'GRANT\'\'\'\'\r\n;\r\n\'\'\r\nselect * from #TEMP;\r\n\'','There are no permissions which are assigned to guest.\r\n','There are some persmissions which are assigned to guest\r\n','pass',NULL,NULL,'2026-01-22 15:27:55'),(1270,202601,32,31,'AA_SqlServer_240_guest Database Permissions','critical','PRIV','This test checks database permisions for guest . guest is a special user and permissions should not be granted to guest user.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      exec sp_msforeachdb \'\'   USE [?]     iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'guest\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select count(*) from #TEMP;   \' \r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      exec sp_msforeachdb \'\'   USE [?]     iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'guest\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select  *  from #TEMP;   \' \r\n','There are no permissions which are assigned to guest.\r\n','There are some persmissions which are assigned to guest\r\n','pass',NULL,NULL,'2026-01-22 15:27:55'),(1271,202601,32,32,'AA_SqlServer_250_Database Role members for guest','critical','PRIV','This test checks database role members for guest  user. Database roles  could not be assigned to guest role.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      EXEC sp_MSforeachdb \'\' USE [?]    INSERT INTO #TEMP   SELECT \'\'\'\'DB Name : \'\'\'\'+Cast (DB_NAME() as varchar)+\'\'\'\' Role Name : \'\'\'\'+USER_NAME(role_principal_id)  +\'\'\'\' User Name \'\'\'\'+  USER_NAME(member_principal_id)    from  sys.database_role_members   	Where     USER_NAME(member_principal_id)  = \'\'\'\'guest\'\'\'\'     ;   \'\'      Select count(*)  from #TEMP;   \'\r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      EXEC sp_MSforeachdb \'\' USE [?]    INSERT INTO #TEMP   SELECT \'\'\'\'DB Name : \'\'\'\'+Cast (DB_NAME() as varchar)+\'\'\'\' Role Name : \'\'\'\'+USER_NAME(role_principal_id)  +\'\'\'\' User Name \'\'\'\'+  USER_NAME(member_principal_id)    from  sys.database_role_members   	Where     USER_NAME(member_principal_id)  = \'\'\'\'guest\'\'\'\'     ;   \'\'      Select  *  from #TEMP;   \'\r\n','Database role member usage for guest user  is correct\r\n','Database role member usage for guest user  is not correct\r\n','pass',NULL,NULL,'2026-01-22 15:27:55'),(1272,202601,32,33,'AA_SqlServer_260_SQL Logins with Null Password','critical','ACCOUNT','This test checks sql logins with null password. SQL Logins should not have null passwords.\r\n','','SELECT      count(name)   from      sys.sql_logins    WHERE      PWDCOMPARE(\'\', password_hash)= 1\r\n','== 0','','SELECT      name    from      sys.sql_logins    WHERE      PWDCOMPARE(\'\', password_hash)= 1   \r\n','There are no sql logins with null paswords\r\n','There are some sql logins with null passwords.\r\n','pass',NULL,NULL,'2026-01-22 15:27:55'),(1273,202601,32,34,'AA_SqlServer_270_SQL Logins with username and passwords are equal','critical','ACCOUNT','This test checks sql login password which are egual to username. Username and password must be different for SQL logins.\r\n','','SELECT      count(name)   from      sys.sql_logins    WHERE      PWDCOMPARE(name,password_hash)=1 \r\n','== 0','','SELECT      name    from      sys.sql_logins    WHERE      PWDCOMPARE(name,password_hash)=1    \r\n','There is no SQL login name which is equal to password.\r\n','There are some sql logins whose passwords are egual to usernames.\r\n','pass',NULL,NULL,'2026-01-22 15:27:55'),(1274,202601,32,35,'AA_SqlServer_280_No Sample Databases','critical','CONFIG','This test checks whether the sample databases created optionally on installation are present.  These sample databases contain many default permissions, and can be used as an entry point to your systems. \r\n','','select      count(name)    from      sys.databases    where      name in (       \'AdventureWorks\', \'AdventureWorksDW\',        \'Northwind\', \'Pubs\'     )   \r\n','== 0','','select      name    from      sys.databases    where      name in (       \'AdventureWorks\', \'AdventureWorksDW\',        \'Northwind\', \'Pubs\'     )   \r\n','There are no sample databases in the server\r\n','There are some sample databases in the server\r\n','pass',NULL,NULL,'2026-01-22 15:27:55'),(1275,202601,32,43,'AA_SqlServer_350_User Password Policy Is Checked','critical','ACCOUNT','This test checks that CHECK_POLICY is enabled for all users.  Enabling CHECK_POLICY ensures that Windows passwords policies are enforced.','','select count(*) from sys.sql_logins  \r\nwhere \r\nis_policy_checked=0 and\r\nname not like \'##%\'','== 0','','select name from sys.sql_logins  \r\nwhere \r\nis_policy_checked=0 and\r\nname not like \'##%\'','CHECK_POLICY is enabled for all users','CHECK_POLICY is not enabled for all users','pass',NULL,NULL,'2026-01-22 15:27:55'),(1276,202601,32,44,'AA_SqlServer_360_CHECK_EXPIRATION Is Checked','critical','ACCOUNT','This test checks that CHECK_EXPIRATION is enabled for all users.  Passwords that have been in use for long periods of time are likely to become known to unauthorized users.\r\n','','select count(*) from sys.sql_logins     where    is_expiration_checked=0 and   name not like \'##%\'\r\n','== 0','','select name from sys.sql_logins     where    is_expiration_checked=0 and   name not like \'##%\'\r\n','CHECK_EXPIRATION is enabled for all users\r\n','CHECK_EXPIRATION is not enabled for all users\r\n','fail','name\n----\n\'sa\'',NULL,'2026-01-22 15:27:55'),(1277,202601,32,22,'AA_SqlServer_170_Windows Authentication','major','AUTH','This test checks that the authentication mode is set to Windows authentication only.  Windows provides a more robust authentication mechanism than SQL Server authentication.','',' SELECT cast( SERVERPROPERTY(\'IsIntegratedSecurityOnly\') as int) ','==1','','SELECT cast( SERVERPROPERTY(\'IsIntegratedSecurityOnly\') as varchar)','The authentication mode is set to Windows authentication only. ','The authentication mode is not set to Windows authentication only.','fail','\n---\n\'0\'',NULL,'2026-01-22 15:27:55'),(1278,202601,32,23,'AA_SqlServer_180_No Guest User Accounts','major','ACCOUNT','This test checks for the existence of guest user accounts with CONNECT permission in database other than master, msdb and tempdb.  This test also exclude databases that are flagged as distributor. If the GUEST user exists and a specific login has not been granted to a database, a login will be mapped to GUEST. The presence of the GUEST user allows all logins to access the database.\r\n','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP  ( row int);\r\n\r\nEXEC sp_MSforeachdb \'\' USE [?]\r\n	INSERT INTO #TEMP\r\n	SELECT count(*) \r\n	FROM sys.database_permissions\r\n	WHERE [grantee_principal_id] = DATABASE_PRINCIPAL_ID(\'\'\'\'guest\'\'\'\')\r\n	AND [state_desc] LIKE \'\'\'\'GRANT%\'\'\'\'\r\n	AND [permission_name] = \'\'\'\'CONNECT\'\'\'\'\r\n	AND DB_NAME() NOT IN (\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'msdb\'\'\'\') ;\r\n\'\'\r\n\r\nSelect sum(row) from #TEMP;\r\ndrop table #TEMP;\r\n\'','== 0','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP  ( row varchar(500));\r\n\r\nEXEC sp_MSforeachdb \'\' USE  [?] \r\n	INSERT INTO #TEMP\r\n	SELECT \'\'\'\' DB NAME : \'\'\'\' + Cast (DB_NAME() as varchar) + \'\'\'\' guest user has CONNECT permission \'\'\'\'\r\n	FROM sys.database_permissions\r\n	WHERE [grantee_principal_id] = DATABASE_PRINCIPAL_ID(\'\'\'\'guest\'\'\'\')\r\n	AND [state_desc] LIKE \'\'\'\'GRANT%\'\'\'\'\r\n	AND [permission_name] = \'\'\'\'CONNECT\'\'\'\'\r\n	AND DB_NAME() NOT IN (\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'msdb\'\'\'\') ;\r\n\'\'\r\n\r\nSelect * from #TEMP;\r\ndrop table #TEMP;\r\n\'','There is no guest user with CONNECT permission. ','There are   guest users with CONNECT permission. Remove these users','pass',NULL,NULL,'2026-01-22 15:27:55'),(1279,202601,32,36,'AA_SqlServer_290_2_No Permissions with GRANT Option','major','PRIV','This test checks database permisions  with grant option. No permission with grant option should be defined in the database.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP ( row varchar(500));      exec sp_MSforeachdb \'\'   USE [?]   iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   STATE_DESC like \'\'\'\'%WITH_GRANT%\'\'\'\'   ;   \'\'   select count(*) from #TEMP;   \'\r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP ( row varchar(500));      exec sp_MSforeachdb \'\'   USE [?]   iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   STATE_DESC like \'\'\'\'%WITH_GRANT%\'\'\'\'   ;   \'\'   select * from #TEMP;   \'\r\n','There are no permissions with grant option.\r\n','There are some persmissions  with grant option.\r\n','pass',NULL,NULL,'2026-01-22 15:27:55'),(1280,202601,32,37,'AA_SqlServer_290_No Permissions with GRANT Option','major','PRIV','','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP  ( row varchar(500));\r\n\r\nexec sp_msforeachdb \'\'\r\nUSE [?]  \r\niNSERT iNTO #TEMP\r\nSELECT\r\n\'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +\r\n\'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +\r\n\'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +\r\n\'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )\r\nFROM\r\nsys.database_permissions\r\nWHERE\r\nSTATE_DESC like \'\'\'\'%WITH_GRANT%\'\'\'\'\r\n;\r\n\'\'\r\nselect  count(*)  from #TEMP;\r\n\' ','== 0','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP  ( row varchar(500));\r\n\r\nexec sp_msforeachdb \'\'\r\nUSE [?]  \r\niNSERT iNTO #TEMP\r\nSELECT\r\n\'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +\r\n\'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +\r\n\'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +\r\n\'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )\r\nFROM\r\nsys.database_permissions\r\nWHERE\r\nSTATE_DESC like \'\'\'\'%WITH_GRANT%\'\'\'\'\r\n;\r\n\'\'\r\nselect * from #TEMP;\r\n\' ','There are no permissions with grant option.\r\n','There are some persmissions  with grant option.\r\n','pass',NULL,NULL,'2026-01-22 15:27:55'),(1281,202601,32,40,'AA_SqlServer_320_No Access to Registry Access Extended procedures','major','PRIV','This test checks for the existence of, and user permissions on, registry access extended stored procedures.  Either these procedures should be completely dropped, or access to them should be strictly limited. xp_reg%,xp_instance_reg%\r\n','','SELECT \r\ncount(*) \r\nFROM \r\n  [master].sys.system_objects o \r\n  JOIN [master].sys.database_permissions p ON o.object_id = p.major_id \r\n  JOIN [master].sys.database_principals u ON p.grantee_principal_id = u.principal_id \r\nWHERE \r\n( o.name LIKE \'xp_reg%\' OR o.name LIKE \'xp_instance_reg%\')\r\n  AND p.type = \'EX\' ','== 0','','SELECT \r\n  \'Principal : \'+u.name  COLLATE DATABASE_DEFAULT +\r\n  \' Extended Procedure Name : \'+o.name COLLATE DATABASE_DEFAULT +\r\n  \' Type : \'+ u.type_desc COLLATE DATABASE_DEFAULT \r\nFROM \r\n  [master].sys.system_objects o \r\n  JOIN [master].sys.database_permissions p ON o.object_id = p.major_id \r\n  JOIN [master].sys.database_principals u ON p.grantee_principal_id = u.principal_id \r\nWHERE \r\n( o.name LIKE \'xp_reg%\' OR o.name LIKE \'xp_instance_reg%\')\r\n  AND p.type = \'EX\' ','There are no permissions on registry access extended stored procedures\r\n','There are some persmissions permissions on registry access extended stored procedures\r\n','fail','\n---------------------------------------------------------------------------------------\n\'Principal : public Extended Procedure Name : xp_instance_regread Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_regread Type : DATABASE_ROLE\'',NULL,'2026-01-22 15:27:55'),(1282,202601,32,41,'AA_SqlServer_330_Revoke public login from SQL Server agent proxy account','major','PRIV','The public database role contains every user in the msdb database. SQL Agent proxies   define a security context in which a job step can run.Granting access to SQL Agent proxies for the public role would allow all users to utilize the proxy which may have high privileges. This would likely break the principle of least   privileges.\r\n','','SELECT count(*)\r\nFROM msdb.dbo.sysproxylogin spl\r\nJOIN sys.database_principals dp\r\nON dp.sid = spl.sid\r\nJOIN msdb.dbo.sysproxies sp\r\nON sp.proxy_id = spl.proxy_id\r\nWHERE principal_id = USER_ID(\'public\')','== 0','','SELECT \'proxyname : \'+CAST(sp.name  as varchar)\r\nFROM msdb.dbo.sysproxylogin spl\r\nJOIN sys.database_principals dp\r\nON dp.sid = spl.sid\r\nJOIN msdb.dbo.sysproxies sp\r\nON sp.proxy_id = spl.proxy_id\r\nWHERE principal_id = USER_ID(\'public\')','There are no public permissions on SQL Server agent proxy account\r\n','There are some public permissions on SQL Server agent proxy account\r\n','pass',NULL,NULL,'2026-01-22 15:27:55'),(1283,202601,32,42,'AA_SqlServer_340_No Individual User Access To syscomment and sp_helptext','minor','PRIV','This test checks for grants on SYSCOMMENTS.TEXT.  Such grants allow any user to read the text comments associated with a database object, making the text publicly viewable.\r\n','','SELECT count(*)\r\nFROM msdb.dbo.sysproxylogin spl\r\nJOIN sys.database_principals dp\r\nON dp.sid = spl.sid\r\nJOIN msdb.dbo.sysproxies sp\r\nON sp.proxy_id = spl.proxy_id\r\nWHERE principal_id = USER_ID(\'public\')\r\n','== 0','','SELECT count(*)\r\nFROM msdb.dbo.sysproxylogin spl\r\nJOIN sys.database_principals dp\r\nON dp.sid = spl.sid\r\nJOIN msdb.dbo.sysproxies sp\r\nON sp.proxy_id = spl.proxy_id\r\nWHERE principal_id = USER_ID(\'public\')','There are no public permissions on SQL Server agent proxy account','There are some public permissions on SQL Server agent proxy account','pass',NULL,NULL,'2026-01-22 15:27:55'),(1284,202601,32,10,'AA_SqlServer_050_Disable Ad hoc distributed queries option','major','CONFIG','Adhoc queries allow undefined access to remote database sources.  Access to untrusted databases could result in execution of malicious applications and/or a compromise of local data confidentiality and integrity. The DBA will configure the database to disable access from the database to objects stored externally to the database on the local host unless mission and/or operationally required and documented.\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Ad Hoc Distributed Queries\'','== 0','','SELECT name + \' Value : \'+ cast( value as varchar ) + \' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'Ad Hoc Distributed Queries\'','Ad Hoc Distributed Queries is disabled','Ad Hoc Distributed Queries is not disabled. Disable this option','pass',NULL,NULL,'2026-01-22 15:27:55'),(1285,202601,32,11,'AA_SqlServer_060_Disable CLR option','major','CONFIG','The clr_enabled parameter configures SQL Server to allow or disallow use of Command Language Runtime objects.  CLR objects is managed code that integrates with the .NET Framework.  This is a more secure method than external stored procedures, although it still contains some risk.  Where no external application execution requirements are required, disallowing use of any improves the overall security posture of the database.\r\n\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'clr enabled\'','== 0','','SELECT name + \' Value : \'+ cast( value as varchar ) + \' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'clr enabled\'','CLR option is disabled','CLR option is not disabled. Disable this option','pass',NULL,NULL,'2026-01-22 15:27:55'),(1286,202601,32,12,'AA_SqlServer_070_Disable Cross db ownership chaining option','major','CONFIG','Cross database ownership chaining allows permissions to objects to be assigned by users other than the Information Owner.  This allows access to objects that are not authorized directly by the Information Owner based on job functions defined by the owner.  Unauthorized access may lead to a compromise of data integrity or confidentiality. The DBA will ensure database privileges are assigned via roles and not directly assigned to database accounts. Privileges may be assigned directly to application owner accounts where the DBMS does not otherwise support access via roles.\r\n\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'cross db ownership chaining\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'cross db ownership chaining\'','Cross db ownership chaining  option is disabled','Cross db ownership chaining option  is not disabled. Disable this option','pass',NULL,NULL,'2026-01-22 15:27:55'),(1287,202601,32,13,'AA_SqlServer_080_Disable Database Mail XPs option','major','CONFIG','SQL Mail accepts incoming database commands via email. This can introduce malicious codes or viruses into the SQL server environment.','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Database Mail XPs\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \'Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'Database Mail XPs\'','Database Mail XPs option is disabled','Database Mail XPs option  is not disabled. Disable this option','pass',NULL,NULL,'2026-01-22 15:27:55'),(1288,202601,32,14,'AA_SqlServer_100_Disable xp_cmdshell Server Configuration option','major','CONFIG','The xp_cmdshell extended stored procedures allows execution of host executables outside the controls of database access permissions.  This access may be exploited by malicious users who have compromised the integrity of the SQL Server database process to control the host operating system to perpetrate additional malicious activity. The DBA should disable the use of external procedures by the database unless it is mission critical or operationally required','','SELECT CAST(value as int) +\r\n       CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'xp_cmdshell\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) +\r\n\' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'xp_cmdshell\'','xp_cmdshell Server Configuration option is disabled','xp_cmdshell Server Configuration option is not disabled. This option must be disabled','pass',NULL,NULL,'2026-01-22 15:27:55'),(1289,202601,32,15,'AA_SqlServer_110_Disable Remote Access option','major','CONFIG','The remote access option controls the execution of local stored procedures on remote\r\nservers or remote stored procedures on local server.Functionality can be abused to launch a Denial-of-Service (DoS) attack on remote servers\r\nby off-loading query processing to a target.\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'remote access\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \' Value in use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'remote access\'','Remote Access option is disabled','Remote Access option  is not disabled. Disable this option','fail','\n------------------------------------------\n\'remote access Value : 1 Value in use : 1\'',NULL,'2026-01-22 15:27:55'),(1290,202601,32,16,'AA_SqlServer_120_Disable Remote Admin Connections option','major','CONFIG','The remote admin connections option controls whether a client application on a remote\r\ncomputer can use the Dedicated Administrator Connection (DAC).The Dedicated Administrator Connection (DAC) lets an administrator access a running\r\nserver to execute diagnostic functions or Transact-SQL statements, or to troubleshoot\r\nproblems on the server, even when the server is locked or running in an abnormal state\r\nand not responding to a SQL Server Database Engine connection. In a cluster scenario, the\r\nadministrator may not actually be logged on to the same node that is currently hosting the\r\nSQL Server instance and thus is considered \"remote\". Therefore, this setting should usually\r\nbe enabled (1) for SQL Server failover clusters; otherwise it should be disabled (0) which is\r\nthe default.\r\n','','execute sp_executesql N\'\r\n\r\nDECLARE @x int;\r\n\r\nSELECT @x=isnull(CAST(value as int) + CAST(value_in_use as int),100)\r\nFROM sys.configurations\r\nWHERE name = \'\'remote admin connections\'\'\r\n\r\nIF @x = 100\r\n       SELECT 0 ;\r\nELSE \r\n   SELECT CAST(value as int) + CAST(value_in_use as int) \r\n   FROM sys.configurations\r\n   WHERE name = \'\'remote admin connections\'\'\r\n\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'remote admin connections\'','Remote Admin Connections option is disabled','Remote Admin Connections option  is not disabled. Disable this option','pass',NULL,NULL,'2026-01-22 15:27:55'),(1291,202601,32,19,'AA_SqlServer_150_Disable database trustworthy status','major','CONFIG','The TRUSTWORTHY database setting restricts access to database resources by databases that contain assemblies with the EXTERNAL_ACCESS or UNSAFE permission settings and modules that use impersonation of accounts assigned elevated privileges.  Unless all assemblies and code for the database have been reviewed, especially in the case where databases have been detached and attached between server instances, leaving the TRUSTWORTHY status to off can help reduce threats from malicious assemblies or modules.','','SELECT count(name)\r\nFROM sys.databases\r\nWHERE is_trustworthy_on = 1\r\nAND name != \'msdb\';','== 0','','SELECT name\r\nFROM sys.databases\r\nWHERE is_trustworthy_on = 1\r\nAND name != \'msdb\';','database trustworthy status is disabled','database trustworthy status is not disabled. Disable this option','pass',NULL,NULL,'2026-01-22 15:27:55'),(1292,202601,32,20,'Checkpoint başarıyla oluşturuldu.','major','CONFIG','This test checks if SQL Server Instance is not advertised by the SQL Server Browser service. To maintain a higher level of protection for database instances, we recommend that SQL Server Instance be hidden when it is not required. Please note that this test does not include Clustered Instances as turning off this feature may cause issues with the Clustered environment.\r\n\r\n','','execute sp_executesql N\'\r\n\r\nDECLARE @getValue INT\r\n\r\nEXEC master.sys.xp_instance_regread\r\n@rootkey = N\'\'HKEY_LOCAL_MACHINE\'\',\r\n@key = N\'\'SOFTWARE\\Microsoft\\Microsoft SQL Server\\MSSQLServer\\SuperSocketNetLib\'\',\r\n@value_name = N\'\'HideInstance\'\',\r\n@value = @getValue OUTPUT\r\n\r\nSELECT isnull(@getvalue,0)\'','==1','','execute sp_executesql N\'\r\n\r\nDECLARE @getValue INT\r\n\r\nEXEC master.sys.xp_instance_regread\r\n@rootkey = N\'\'HKEY_LOCAL_MACHINE\'\',\r\n@key = N\'\'SOFTWARE\\Microsoft\\Microsoft SQL Server\\MSSQLServer\\SuperSocketNetLib\'\',\r\n@value_name = N\'\'HideInstance\'\',\r\n@value = @getValue OUTPUT\r\n\r\nSELECT isnull(@getvalue,0)\'','SQL Server Instance is  hidden.\r\n','SQL Server Instance is not hidden. Hide the instance','fail','\n-\n0',NULL,'2026-01-22 15:27:55'),(1293,202601,32,21,'AA_SqlServer_160_Hide SQL Server Instance','major','CONFIG','This test checks if SQL Server Instance is not advertised by the SQL Server Browser service. To maintain a higher level of protection for database instances, we recommend that SQL Server Instance be hidden when it is not required. Please note that this test does not include Clustered Instances as turning off this feature may cause issues with the Clustered environment.\r\n\r\n','','execute sp_executesql N\'\r\n\r\nDECLARE @getValue INT\r\n\r\nEXEC master.sys.xp_instance_regread\r\n@rootkey = N\'\'HKEY_LOCAL_MACHINE\'\',\r\n@key = N\'\'SOFTWARE\\Microsoft\\Microsoft SQL Server\\MSSQLServer\\SuperSocketNetLib\'\',\r\n@value_name = N\'\'HideInstance\'\',\r\n@value = @getValue OUTPUT\r\n\r\nSELECT isnull(@getvalue,0)\'','==1','','execute sp_executesql N\'\r\n\r\nDECLARE @getValue INT\r\n\r\nEXEC master.sys.xp_instance_regread\r\n@rootkey = N\'\'HKEY_LOCAL_MACHINE\'\',\r\n@key = N\'\'SOFTWARE\\Microsoft\\Microsoft SQL Server\\MSSQLServer\\SuperSocketNetLib\'\',\r\n@value_name = N\'\'HideInstance\'\',\r\n@value = @getValue OUTPUT\r\n\r\nSELECT isnull(@getvalue,0)\'','SQL Server Instance is  hidden.','SQL Server Instance is not hidden. Hide the instance','fail','\n-\n0',NULL,'2026-01-22 15:27:55'),(1294,202601,32,38,'AA_SqlServer_300_No Access To General Extended procedures','major','PRIV','This test checks for the existence of, and user permissions on, extended stored procedures.  Either these procedures should be completely dropped, or access to them should be strictly limited. xp_cmdshell, xp_enumgroups, xp_grantlogin ,xp_logevent, xp_logininfo,    xp_msver, xp_revokelogin, xp_sprintf, xp_sqlmaint, xp_sscanf\r\n','','SELECT \r\ncount(*) \r\nFROM \r\n  [master].sys.system_objects o \r\n  JOIN [master].sys.database_permissions p ON o.object_id = p.major_id \r\n  JOIN [master].sys.database_principals u ON p.grantee_principal_id = u.principal_id \r\nWHERE \r\n    o.name in ( \r\n	\'xp_cmdshell\', \r\n	\'xp_enumgroups\', \r\n    \'xp_grantlogin\' ,\r\n	\'xp_logevent\', \r\n	\'xp_logininfo\', \r\n    \'xp_msver\', \r\n	\'xp_revokelogin\', \r\n	\'xp_sprintf\', \r\n    \'xp_sqlmaint\', \r\n	\'xp_sscanf\' )\r\n  AND p.type = \'EX\' ','== 0','','SELECT \r\n  \'Principal : \'+u.name  COLLATE DATABASE_DEFAULT +\r\n  \' Extended Procedure Name : \'+o.name COLLATE DATABASE_DEFAULT +\r\n  \' Type : \'+ u.type_desc COLLATE DATABASE_DEFAULT \r\nFROM \r\n  [master].sys.system_objects o \r\n  JOIN [master].sys.database_permissions p ON o.object_id = p.major_id \r\n  JOIN [master].sys.database_principals u ON p.grantee_principal_id = u.principal_id \r\nWHERE \r\n    o.name in ( \r\n	\'xp_cmdshell\', \r\n	\'xp_enumgroups\', \r\n    \'xp_grantlogin\' ,\r\n	\'xp_logevent\', \r\n	\'xp_logininfo\', \r\n    \'xp_msver\', \r\n	\'xp_revokelogin\', \r\n	\'xp_sprintf\', \r\n    \'xp_sqlmaint\', \r\n	\'xp_sscanf\' )\r\n  AND p.type = \'EX\' ','There are no permissions on general extended stored procedures\r\n','There are some persmissions permissions on general extended stored procedures.\r\n','fail','\n----------------------------------------------------------------------------------\n\'Principal : public Extended Procedure Name : xp_msver Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_sscanf Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_revokelogin Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_grantlogin Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_sprintf Type : DATABASE_ROLE\'',NULL,'2026-01-22 15:27:55'),(1295,202601,32,39,'AA_SqlServer_310_No Access to OLE Automation procedures','major','CONFIG','This test checks for the existence of,and user permissions on OLE automation extended stored procedures.  Either these procedures should be completely dropped, or access to them should be strictly limited.      \r\n','','SELECT CAST(value as int) +\r\n       CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Ole Automation Procedures\'   \r\n','== 0','','SELECT CAST(value as int) +\r\n       CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Ole Automation Procedures\'\r\n  \r\n','OLE Automation procedures  option is disabled\r\n','OLE Automation procedures  option  is not disabled. Disable this option\r\n','pass',NULL,NULL,'2026-01-22 15:27:55'),(1296,202601,32,17,'AA_SqlServer_130_Disable Ole Automation Procedures option','minor','CONFIG','This test checks if Ole Automation Procedures option is disabled. Ole Automation Procedures option allows SQL Server users to execute functions external to SQL Server. Enabling this option will increase the attack surface of SQL Server and allow users to execute functions in the security context of SQL Server. We recommend that the Ole Automation Procedures option to be disabled when it is not document as a requirement.\r\n\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Ole Automation Procedures\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \'Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'Ole Automation Procedures\'',' Ole Automation Procedures option is disabled',' Ole Automation Procedures option  is not disabled. Disable this option','pass',NULL,NULL,'2026-01-22 15:27:55'),(1297,202601,32,18,'AA_SqlServer_140_Disable Scan for Startup Procedures option','minor','CONFIG','This test checks if scan for startup procedures is disabled. This feature causes SQL Server to scan for and automatically run all stored procedures that are set to execute upon service startup. If there are no user-defined stored procedures set to execute when SQL server starts, we recommend this feature to be disabled.\r\n\r\n','','SELECT CAST(value as int) +\r\n       CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'scan for startup procs\'','== 0','','SELECT name + \' value : \'+cast( value as varchar ) +\r\n\' value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'scan for startup procs\'','Scan for Startup Procedures  option is disabled','Scan for Startup Procedures  option  is not disabled. Disable this option','pass',NULL,NULL,'2026-01-22 15:27:55'),(1298,202601,32,9,'AA_SqlServer_040_Rename the sa Login Account','major','ACCOUNT','The \'sa\' account is a well-known account.  Well-known account names provide an easier target for attack.  Renaming the sa account helps reduce the risk of an attack to this built-in account.','','SELECT count(*)\r\nFROM sys.server_principals\r\nWHERE sid = 0x01 and name=\'sa\'','== 0','','SELECT name\r\nFROM sys.server_principals\r\nWHERE sid = 0x01','sa Login Account is renamed','sa Login Account is not renamed. Rename this account','fail','name\n----\n\'sa\'',NULL,'2026-01-22 15:27:55'),(1299,202601,33,24,'AA_SqlServer_190_Public server role permision','critical','PRIV','public is a special fixed server role containing all logins. Unlike other fixed server roles,\r\npermissions can be changed for the public role. In keeping with the principle of least\r\nprivileges, the public server role should not be used to grant permissions at the server\r\nscope as these would be inherited by all users.\r\n\r\nEvery SQL Server login belongs to the public role and cannot be removed from this role.\r\nTherefore, any permissions granted to this role will be available to all logins unless they\r\nhave been explicitly denied to specific logins or user-defined server roles.','','Select \r\n  count (permission_name) \r\nfrom \r\n  sys.server_permissions \r\nwhere \r\n  SUSER_NAME(grantee_principal_id) = \'public\' \r\n  and permission_name not in (\'VIEW ANY DATABASE\', \'CONNECT\')\r\n','== 0','','Select \r\n  permission_name \r\nfrom \r\n  sys.server_permissions \r\nwhere \r\n  SUSER_NAME(grantee_principal_id) = \'public\' \r\n  and permission_name not in (\'VIEW ANY DATABASE\', \'CONNECT\')\r\n\r\n','No server permissions are granted to public.','Some server permissions are granted to public.','pass',NULL,NULL,'2026-01-22 15:29:05'),(1300,202601,33,5,'AA_SqlServer_010_Supported SQL Server version','critical','PATCH','This test checks whether your current SQL Server version is a vendor-supported version.  Microsoft does not provide security fixes or software updates to unsupported software versions','','SELECT cast(ISNULL(SERVERPROPERTY(\'ProductMajorVersion\'),0) as int)   ','>=11','','SELECT \'Product Major version \' +  cast(ISNULL(SERVERPROPERTY(\'ProductMajorVersion\'),\'Null\' ) as  char ) ','The version of the database is acceptable.','The version of the database is not acceptable. The database version should SQL Sever 2012 or upper.','pass',NULL,NULL,'2026-01-22 15:29:05'),(1301,202601,33,6,'AA_SqlServer_020_Disable the sa Login Account','critical','ACCOUNT','This test checks if the \'sa\' Login Account is disabled. The sa account is a widely known and often widely used SQL Server account with sysadmin privileges. Enforcing this control reduces the probability of an attacker executing brute force attacks against a well-known principal.','','SELECT  count(*)\r\nFROM sys.server_principals\r\nWHERE sid = 0x01\r\nAND is_disabled = 0','== 0','','SELECT \'sa user name : \'+ name+\' is disabled : \' +  cast( is_disabled as char)\r\nFROM sys.server_principals\r\nWHERE sid = 0x01\r\n','sa Login Account is disabled','Disable sa login account','fail','\n----------------------------------------------------------------\n\'sa user name : sa is disabled : 0                             \'',NULL,'2026-01-22 15:29:05'),(1302,202601,33,7,'AA_SqlServer_025_sa Change password','critical','ACCOUNT','This test checks that sa password change . The sa password should be changed in every two days','','select datediff( day,  modify_date , getdate() ) FROM sys.server_principals\r\nWHERE sid = 0x01  ','< 3','','select datediff( day,  modify_date , getdate() ) FROM sys.server_principals\r\nWHERE sid = 0x01 ','sa password was changed in two days','','fail','\n-\n8',NULL,'2026-01-22 15:29:05'),(1303,202601,33,8,'AA_SqlServer_030_Ensure no Login exists with sa Login Account','critical','ACCOUNT','The \'sa\' account is a well-known account.  Well-known account names provide an easier target for attack. The lack of the sa account helps reduce the risk of an attack to this built-in account.','','SELECT count(*)\r\nFROM sys.server_principals\r\nWHERE name = \'sa\'','== 0','','SELECT name\r\nFROM sys.server_principals\r\nWHERE name = \'sa\'','There is no the sa account in the database.','There is the sa Login account in the database.Drop this user or rename et.','fail','name\n----\n\'sa\'',NULL,'2026-01-22 15:29:05'),(1304,202601,33,25,'AA_SqlServer_200_Fixed Server Role members for users','critical','PRIV','This test checks fixed server roles for analyst , developers and real persons. Fixed server roles could not be assigned to real person users ( Developer, Analyst users ) . Only Admin can use fixed server role.\r\n','','Select     count(*)   from      sys.server_role_members    where      (       suser_name(member_principal_id) like \'ODEABANK%.%\'    	AND       suser_name(member_principal_id) not like \'%admin%\'         AND       suser_name(member_principal_id) not like \'%t.coban%\'     )      OR (       suser_name(member_principal_id) like \'ODEABANK\\Cyberark_Intertech%\'     )      \r\n','== 0','','Select      suser_name(role_principal_id) + \'   \' + suser_name(member_principal_id)    from      sys.server_role_members    where      (       suser_name(member_principal_id) like \'ODEABANK%.%\'    	AND       suser_name(member_principal_id) not like \'%admin%\'         AND       suser_name(member_principal_id) not like \'%t.coban%\'     )      OR (       suser_name(member_principal_id) like \'ODEABANK\\Cyberark_Intertech%\'     )          \r\n','Fixed Server role usage is correct.\r\n','Fixed Server role usage is not correct.\r\n','pass',NULL,NULL,'2026-01-22 15:29:05'),(1305,202601,33,26,'AA_SqlServer_210_Database Role members for users','critical','PRIV','This test checks database role members for analyst and real person users. Database roles  except  db_datareader could not be assigned to real person users ( Developer, Analyst users ) .\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      EXEC sp_MSforeachdb \'\' USE [?]    INSERT INTO #TEMP   SELECT \'\'\'\'DB Name : \'\'\'\'+Cast (DB_NAME() as varchar)+\'\'\'\' Role Name : \'\'\'\'+USER_NAME(role_principal_id)  +\'\'\'\' User Name \'\'\'\'+  USER_NAME(member_principal_id)    from  sys.database_role_members   	Where   	(   	( USER_NAME(member_principal_id)  like \'\'\'\'%ODEABANK%.%\'\'\'\'  and   USER_NAME(member_principal_id)  not like \'\'\'\'%admin%\'\'\'\' )     	OR   	  (suser_name(member_principal_id) like \'\'\'\'%ODEABANK%Cyberark%\'\'\'\')       )    	AND   	DB_NAME() <> \'\'\'\'master\'\'\'\' and   	USER_NAME(role_principal_id) not in (\'\'\'\'db_datareader\'\'\'\',\'\'\'\'db_viewdefinition\'\'\'\',\'\'\'\'db_denydatareader\'\'\'\',\'\'\'\'db_deny_maas\'\'\'\');   \'\'      Select  count(*)  from #TEMP;   \'\r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      EXEC sp_MSforeachdb \'\' USE [?]    INSERT INTO #TEMP   SELECT \'\'\'\'DB Name : \'\'\'\'+Cast (DB_NAME() as varchar)+\'\'\'\' Role Name : \'\'\'\'+USER_NAME(role_principal_id)  +\'\'\'\' User Name \'\'\'\'+  USER_NAME(member_principal_id)    from  sys.database_role_members   	Where   (   	( USER_NAME(member_principal_id)  like \'\'\'\'%ODEABANK%.%\'\'\'\'  and   USER_NAME(member_principal_id)  not like \'\'\'\'%admin%\'\'\'\' )     	OR   	(suser_name(member_principal_id) like \'\'\'\'%ODEABANK%Cyberark%\'\'\'\')   )    	AND   	DB_NAME() <> \'\'\'\'master\'\'\'\' and   	USER_NAME(role_principal_id) not in  (\'\'\'\'db_datareader\'\'\'\',\'\'\'\'db_viewdefinition\'\'\'\',\'\'\'\'db_denydatareader\'\'\'\',\'\'\'\'db_deny_maas\'\'\'\');   \'\'      Select  * from #TEMP;   \'\r\n','Database role member usage for users  is correct\r\n','Database role member usage for users  is not correct\r\n','pass',NULL,NULL,'2026-01-22 15:29:05'),(1306,202601,33,27,'AA_SqlServer_220_2_Public Database Permissions','critical','PRIV','This test checks database permisions for public . Public is a special role and permissions should not be granted to public role.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP ( row varchar(500));          exec sp_MSforeachdb \'\'   USE [?]   iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'public\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND OBJECT_NAME(MAJOR_iD) NOT LiKE (\'\'\'\'%fn_cdc_get_net_changes_application_data%\'\'\'\')   AND NOT (OBJECT_SCHEMA_NAME(MAJOR_iD) = \'\'\'\'cdc\'\'\'\' and PERMiSSiON_NAME=\'\'\'\'SELECT\'\'\'\')   AND NOT (PERMiSSiON_NAME IN (\'\'\'\'REFERENCES\'\'\'\',\'\'\'\'SEND\'\'\'\',   \'\'\'\'VIEW ANY COLUMN ENCRYPTION KEY DEFINITION\'\'\'\',   \'\'\'\'VIEW ANY COLUMN MASTER KEY DEFINITION\'\'\'\' ) and OBJECT_SCHEMA_NAME(MAJOR_iD) IS NULL)   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select count(*) from #TEMP;   \'\r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP ( row varchar(500));          exec sp_MSforeachdb \'\'   USE [?]   iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'public\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND OBJECT_NAME(MAJOR_iD) NOT LiKE (\'\'\'\'%fn_cdc_get_net_changes_application_data%\'\'\'\')   AND NOT (OBJECT_SCHEMA_NAME(MAJOR_iD) = \'\'\'\'cdc\'\'\'\' and PERMiSSiON_NAME=\'\'\'\'SELECT\'\'\'\')   AND NOT (PERMiSSiON_NAME IN (\'\'\'\'REFERENCES\'\'\'\',\'\'\'\'SEND\'\'\'\',   \'\'\'\'VIEW ANY COLUMN ENCRYPTION KEY DEFINITION\'\'\'\',   \'\'\'\'VIEW ANY COLUMN MASTER KEY DEFINITION\'\'\'\' ) and OBJECT_SCHEMA_NAME(MAJOR_iD) IS NULL)   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select * from #TEMP;   \'','There are no permissions which are assigned to public.\r\n','There are some persmissions which are assigned to public\r\n','pass',NULL,NULL,'2026-01-22 15:29:05'),(1307,202601,33,28,'AA_SqlServer_220_Public Database Permissions','critical','PRIV','This test checks database permisions for public . Public is a special role and permissions should not be granted to public role.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      exec sp_msforeachdb \'\'   USE [?]     iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'public\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND OBJECT_NAME(MAJOR_iD) NOT LiKE (\'\'\'\'%fn_cdc_get_net_changes_application_data%\'\'\'\')   AND NOT (OBJECT_SCHEMA_NAME(MAJOR_iD) = \'\'\'\'cdc\'\'\'\' and PERMiSSiON_NAME=\'\'\'\'SELECT\'\'\'\')   AND NOT (PERMiSSiON_NAME IN (\'\'\'\'REFERENCES\'\'\'\',\'\'\'\'SEND\'\'\'\',   \'\'\'\'VIEW ANY COLUMN ENCRYPTION KEY DEFINITION\'\'\'\',   \'\'\'\'VIEW ANY COLUMN MASTER KEY DEFINITION\'\'\'\' ) and OBJECT_SCHEMA_NAME(MAJOR_iD) IS NULL)   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select count(*) from #TEMP;   \' \r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      exec sp_msforeachdb \'\'   USE [?]     iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'public\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND OBJECT_NAME(MAJOR_iD) NOT LiKE (\'\'\'\'%fn_cdc_get_net_changes_application_data%\'\'\'\')   AND NOT (OBJECT_SCHEMA_NAME(MAJOR_iD) = \'\'\'\'cdc\'\'\'\' and PERMiSSiON_NAME=\'\'\'\'SELECT\'\'\'\')   AND NOT (PERMiSSiON_NAME IN (\'\'\'\'REFERENCES\'\'\'\',\'\'\'\'SEND\'\'\'\',   \'\'\'\'VIEW ANY COLUMN ENCRYPTION KEY DEFINITION\'\'\'\',   \'\'\'\'VIEW ANY COLUMN MASTER KEY DEFINITION\'\'\'\' ) and OBJECT_SCHEMA_NAME(MAJOR_iD) IS NULL)   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select * from #TEMP;   \' \r\n','There are no permissions which are assigned to public.\r\n','There are some persmissions which are assigned to public\r\n','pass',NULL,NULL,'2026-01-22 15:29:05'),(1308,202601,33,29,'AA_SqlServer_230_Real person users','critical','ACCOUNT','All logins to the database should be made with AD groups, real person users should  not be connected database directly\r\n','','Select      count(*)   from      sys.server_principals    where      name like \'ODEABANK%.%\'      and is_disabled = 0   \r\n','== 0','','Select      name     from      sys.server_principals    where      name like \'ODEABANK%.%\'      and is_disabled = 0;\r\n','Real person users are not found in the logins\r\n','Some real person users are found in the logins\r\n','pass',NULL,NULL,'2026-01-22 15:29:05'),(1309,202601,33,30,'AA_SqlServer_240_2_guest Database Permissions','critical','ACCOUNT','This test checks database permisions for guest . guest is a special user and permissions should not be granted to guest user.\r\n','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP ( row varchar(500));\r\n\r\nexec sp_MSforeachdb \'\'\r\nUSE [?]\r\niNSERT iNTO #TEMP\r\nSELECT\r\n\'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +\r\n\'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +\r\n\'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +\r\n\'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )\r\nFROM\r\nsys.database_permissions\r\nWHERE\r\nUSER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'guest\'\'\'\' )\r\nAND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'\r\nAND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')\r\nAND STATE_DESC=\'\'\'\'GRANT\'\'\'\'\r\n;\r\n\'\'\r\nselect count(*) from #TEMP;\r\n\'','== 0','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP ( row varchar(500));\r\n\r\nexec sp_MSforeachdb \'\'\r\nUSE [?]\r\niNSERT iNTO #TEMP\r\nSELECT\r\n\'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +\r\n\'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +\r\n\'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +\r\n\'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )\r\nFROM\r\nsys.database_permissions\r\nWHERE\r\nUSER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'guest\'\'\'\' )\r\nAND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'\r\nAND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')\r\nAND STATE_DESC=\'\'\'\'GRANT\'\'\'\'\r\n;\r\n\'\'\r\nselect * from #TEMP;\r\n\'','There are no permissions which are assigned to guest.\r\n','There are some persmissions which are assigned to guest\r\n','pass',NULL,NULL,'2026-01-22 15:29:05'),(1310,202601,33,31,'AA_SqlServer_240_guest Database Permissions','critical','PRIV','This test checks database permisions for guest . guest is a special user and permissions should not be granted to guest user.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      exec sp_msforeachdb \'\'   USE [?]     iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'guest\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select count(*) from #TEMP;   \' \r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      exec sp_msforeachdb \'\'   USE [?]     iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'guest\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select  *  from #TEMP;   \' \r\n','There are no permissions which are assigned to guest.\r\n','There are some persmissions which are assigned to guest\r\n','pass',NULL,NULL,'2026-01-22 15:29:05'),(1311,202601,33,32,'AA_SqlServer_250_Database Role members for guest','critical','PRIV','This test checks database role members for guest  user. Database roles  could not be assigned to guest role.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      EXEC sp_MSforeachdb \'\' USE [?]    INSERT INTO #TEMP   SELECT \'\'\'\'DB Name : \'\'\'\'+Cast (DB_NAME() as varchar)+\'\'\'\' Role Name : \'\'\'\'+USER_NAME(role_principal_id)  +\'\'\'\' User Name \'\'\'\'+  USER_NAME(member_principal_id)    from  sys.database_role_members   	Where     USER_NAME(member_principal_id)  = \'\'\'\'guest\'\'\'\'     ;   \'\'      Select count(*)  from #TEMP;   \'\r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      EXEC sp_MSforeachdb \'\' USE [?]    INSERT INTO #TEMP   SELECT \'\'\'\'DB Name : \'\'\'\'+Cast (DB_NAME() as varchar)+\'\'\'\' Role Name : \'\'\'\'+USER_NAME(role_principal_id)  +\'\'\'\' User Name \'\'\'\'+  USER_NAME(member_principal_id)    from  sys.database_role_members   	Where     USER_NAME(member_principal_id)  = \'\'\'\'guest\'\'\'\'     ;   \'\'      Select  *  from #TEMP;   \'\r\n','Database role member usage for guest user  is correct\r\n','Database role member usage for guest user  is not correct\r\n','pass',NULL,NULL,'2026-01-22 15:29:05'),(1312,202601,33,33,'AA_SqlServer_260_SQL Logins with Null Password','critical','ACCOUNT','This test checks sql logins with null password. SQL Logins should not have null passwords.\r\n','','SELECT      count(name)   from      sys.sql_logins    WHERE      PWDCOMPARE(\'\', password_hash)= 1\r\n','== 0','','SELECT      name    from      sys.sql_logins    WHERE      PWDCOMPARE(\'\', password_hash)= 1   \r\n','There are no sql logins with null paswords\r\n','There are some sql logins with null passwords.\r\n','pass',NULL,NULL,'2026-01-22 15:29:05'),(1313,202601,33,34,'AA_SqlServer_270_SQL Logins with username and passwords are equal','critical','ACCOUNT','This test checks sql login password which are egual to username. Username and password must be different for SQL logins.\r\n','','SELECT      count(name)   from      sys.sql_logins    WHERE      PWDCOMPARE(name,password_hash)=1 \r\n','== 0','','SELECT      name    from      sys.sql_logins    WHERE      PWDCOMPARE(name,password_hash)=1    \r\n','There is no SQL login name which is equal to password.\r\n','There are some sql logins whose passwords are egual to usernames.\r\n','pass',NULL,NULL,'2026-01-22 15:29:05'),(1314,202601,33,35,'AA_SqlServer_280_No Sample Databases','critical','CONFIG','This test checks whether the sample databases created optionally on installation are present.  These sample databases contain many default permissions, and can be used as an entry point to your systems. \r\n','','select      count(name)    from      sys.databases    where      name in (       \'AdventureWorks\', \'AdventureWorksDW\',        \'Northwind\', \'Pubs\'     )   \r\n','== 0','','select      name    from      sys.databases    where      name in (       \'AdventureWorks\', \'AdventureWorksDW\',        \'Northwind\', \'Pubs\'     )   \r\n','There are no sample databases in the server\r\n','There are some sample databases in the server\r\n','pass',NULL,NULL,'2026-01-22 15:29:05'),(1315,202601,33,43,'AA_SqlServer_350_User Password Policy Is Checked','critical','ACCOUNT','This test checks that CHECK_POLICY is enabled for all users.  Enabling CHECK_POLICY ensures that Windows passwords policies are enforced.','','select count(*) from sys.sql_logins  \r\nwhere \r\nis_policy_checked=0 and\r\nname not like \'##%\'','== 0','','select name from sys.sql_logins  \r\nwhere \r\nis_policy_checked=0 and\r\nname not like \'##%\'','CHECK_POLICY is enabled for all users','CHECK_POLICY is not enabled for all users','pass',NULL,NULL,'2026-01-22 15:29:05'),(1316,202601,33,44,'AA_SqlServer_360_CHECK_EXPIRATION Is Checked','critical','ACCOUNT','This test checks that CHECK_EXPIRATION is enabled for all users.  Passwords that have been in use for long periods of time are likely to become known to unauthorized users.\r\n','','select count(*) from sys.sql_logins     where    is_expiration_checked=0 and   name not like \'##%\'\r\n','== 0','','select name from sys.sql_logins     where    is_expiration_checked=0 and   name not like \'##%\'\r\n','CHECK_EXPIRATION is enabled for all users\r\n','CHECK_EXPIRATION is not enabled for all users\r\n','fail','name\n----\n\'sa\'',NULL,'2026-01-22 15:29:05'),(1317,202601,33,22,'AA_SqlServer_170_Windows Authentication','major','AUTH','This test checks that the authentication mode is set to Windows authentication only.  Windows provides a more robust authentication mechanism than SQL Server authentication.','',' SELECT cast( SERVERPROPERTY(\'IsIntegratedSecurityOnly\') as int) ','==1','','SELECT cast( SERVERPROPERTY(\'IsIntegratedSecurityOnly\') as varchar)','The authentication mode is set to Windows authentication only. ','The authentication mode is not set to Windows authentication only.','fail','\n---\n\'0\'',NULL,'2026-01-22 15:29:05'),(1318,202601,33,23,'AA_SqlServer_180_No Guest User Accounts','major','ACCOUNT','This test checks for the existence of guest user accounts with CONNECT permission in database other than master, msdb and tempdb.  This test also exclude databases that are flagged as distributor. If the GUEST user exists and a specific login has not been granted to a database, a login will be mapped to GUEST. The presence of the GUEST user allows all logins to access the database.\r\n','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP  ( row int);\r\n\r\nEXEC sp_MSforeachdb \'\' USE [?]\r\n	INSERT INTO #TEMP\r\n	SELECT count(*) \r\n	FROM sys.database_permissions\r\n	WHERE [grantee_principal_id] = DATABASE_PRINCIPAL_ID(\'\'\'\'guest\'\'\'\')\r\n	AND [state_desc] LIKE \'\'\'\'GRANT%\'\'\'\'\r\n	AND [permission_name] = \'\'\'\'CONNECT\'\'\'\'\r\n	AND DB_NAME() NOT IN (\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'msdb\'\'\'\') ;\r\n\'\'\r\n\r\nSelect sum(row) from #TEMP;\r\ndrop table #TEMP;\r\n\'','== 0','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP  ( row varchar(500));\r\n\r\nEXEC sp_MSforeachdb \'\' USE  [?] \r\n	INSERT INTO #TEMP\r\n	SELECT \'\'\'\' DB NAME : \'\'\'\' + Cast (DB_NAME() as varchar) + \'\'\'\' guest user has CONNECT permission \'\'\'\'\r\n	FROM sys.database_permissions\r\n	WHERE [grantee_principal_id] = DATABASE_PRINCIPAL_ID(\'\'\'\'guest\'\'\'\')\r\n	AND [state_desc] LIKE \'\'\'\'GRANT%\'\'\'\'\r\n	AND [permission_name] = \'\'\'\'CONNECT\'\'\'\'\r\n	AND DB_NAME() NOT IN (\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'msdb\'\'\'\') ;\r\n\'\'\r\n\r\nSelect * from #TEMP;\r\ndrop table #TEMP;\r\n\'','There is no guest user with CONNECT permission. ','There are   guest users with CONNECT permission. Remove these users','pass',NULL,NULL,'2026-01-22 15:29:05'),(1319,202601,33,36,'AA_SqlServer_290_2_No Permissions with GRANT Option','major','PRIV','This test checks database permisions  with grant option. No permission with grant option should be defined in the database.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP ( row varchar(500));      exec sp_MSforeachdb \'\'   USE [?]   iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   STATE_DESC like \'\'\'\'%WITH_GRANT%\'\'\'\'   ;   \'\'   select count(*) from #TEMP;   \'\r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP ( row varchar(500));      exec sp_MSforeachdb \'\'   USE [?]   iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   STATE_DESC like \'\'\'\'%WITH_GRANT%\'\'\'\'   ;   \'\'   select * from #TEMP;   \'\r\n','There are no permissions with grant option.\r\n','There are some persmissions  with grant option.\r\n','pass',NULL,NULL,'2026-01-22 15:29:05'),(1320,202601,33,37,'AA_SqlServer_290_No Permissions with GRANT Option','major','PRIV','','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP  ( row varchar(500));\r\n\r\nexec sp_msforeachdb \'\'\r\nUSE [?]  \r\niNSERT iNTO #TEMP\r\nSELECT\r\n\'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +\r\n\'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +\r\n\'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +\r\n\'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )\r\nFROM\r\nsys.database_permissions\r\nWHERE\r\nSTATE_DESC like \'\'\'\'%WITH_GRANT%\'\'\'\'\r\n;\r\n\'\'\r\nselect  count(*)  from #TEMP;\r\n\' ','== 0','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP  ( row varchar(500));\r\n\r\nexec sp_msforeachdb \'\'\r\nUSE [?]  \r\niNSERT iNTO #TEMP\r\nSELECT\r\n\'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +\r\n\'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +\r\n\'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +\r\n\'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )\r\nFROM\r\nsys.database_permissions\r\nWHERE\r\nSTATE_DESC like \'\'\'\'%WITH_GRANT%\'\'\'\'\r\n;\r\n\'\'\r\nselect * from #TEMP;\r\n\' ','There are no permissions with grant option.\r\n','There are some persmissions  with grant option.\r\n','pass',NULL,NULL,'2026-01-22 15:29:05'),(1321,202601,33,40,'AA_SqlServer_320_No Access to Registry Access Extended procedures','major','PRIV','This test checks for the existence of, and user permissions on, registry access extended stored procedures.  Either these procedures should be completely dropped, or access to them should be strictly limited. xp_reg%,xp_instance_reg%\r\n','','SELECT \r\ncount(*) \r\nFROM \r\n  [master].sys.system_objects o \r\n  JOIN [master].sys.database_permissions p ON o.object_id = p.major_id \r\n  JOIN [master].sys.database_principals u ON p.grantee_principal_id = u.principal_id \r\nWHERE \r\n( o.name LIKE \'xp_reg%\' OR o.name LIKE \'xp_instance_reg%\')\r\n  AND p.type = \'EX\' ','== 0','','SELECT \r\n  \'Principal : \'+u.name  COLLATE DATABASE_DEFAULT +\r\n  \' Extended Procedure Name : \'+o.name COLLATE DATABASE_DEFAULT +\r\n  \' Type : \'+ u.type_desc COLLATE DATABASE_DEFAULT \r\nFROM \r\n  [master].sys.system_objects o \r\n  JOIN [master].sys.database_permissions p ON o.object_id = p.major_id \r\n  JOIN [master].sys.database_principals u ON p.grantee_principal_id = u.principal_id \r\nWHERE \r\n( o.name LIKE \'xp_reg%\' OR o.name LIKE \'xp_instance_reg%\')\r\n  AND p.type = \'EX\' ','There are no permissions on registry access extended stored procedures\r\n','There are some persmissions permissions on registry access extended stored procedures\r\n','fail','\n---------------------------------------------------------------------------------------\n\'Principal : public Extended Procedure Name : xp_instance_regread Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_regread Type : DATABASE_ROLE\'',NULL,'2026-01-22 15:29:05'),(1322,202601,33,41,'AA_SqlServer_330_Revoke public login from SQL Server agent proxy account','major','PRIV','The public database role contains every user in the msdb database. SQL Agent proxies   define a security context in which a job step can run.Granting access to SQL Agent proxies for the public role would allow all users to utilize the proxy which may have high privileges. This would likely break the principle of least   privileges.\r\n','','SELECT count(*)\r\nFROM msdb.dbo.sysproxylogin spl\r\nJOIN sys.database_principals dp\r\nON dp.sid = spl.sid\r\nJOIN msdb.dbo.sysproxies sp\r\nON sp.proxy_id = spl.proxy_id\r\nWHERE principal_id = USER_ID(\'public\')','== 0','','SELECT \'proxyname : \'+CAST(sp.name  as varchar)\r\nFROM msdb.dbo.sysproxylogin spl\r\nJOIN sys.database_principals dp\r\nON dp.sid = spl.sid\r\nJOIN msdb.dbo.sysproxies sp\r\nON sp.proxy_id = spl.proxy_id\r\nWHERE principal_id = USER_ID(\'public\')','There are no public permissions on SQL Server agent proxy account\r\n','There are some public permissions on SQL Server agent proxy account\r\n','pass',NULL,NULL,'2026-01-22 15:29:05'),(1323,202601,33,42,'AA_SqlServer_340_No Individual User Access To syscomment and sp_helptext','minor','PRIV','This test checks for grants on SYSCOMMENTS.TEXT.  Such grants allow any user to read the text comments associated with a database object, making the text publicly viewable.\r\n','','SELECT count(*)\r\nFROM msdb.dbo.sysproxylogin spl\r\nJOIN sys.database_principals dp\r\nON dp.sid = spl.sid\r\nJOIN msdb.dbo.sysproxies sp\r\nON sp.proxy_id = spl.proxy_id\r\nWHERE principal_id = USER_ID(\'public\')\r\n','== 0','','SELECT count(*)\r\nFROM msdb.dbo.sysproxylogin spl\r\nJOIN sys.database_principals dp\r\nON dp.sid = spl.sid\r\nJOIN msdb.dbo.sysproxies sp\r\nON sp.proxy_id = spl.proxy_id\r\nWHERE principal_id = USER_ID(\'public\')','There are no public permissions on SQL Server agent proxy account','There are some public permissions on SQL Server agent proxy account','pass',NULL,NULL,'2026-01-22 15:29:05'),(1324,202601,33,10,'AA_SqlServer_050_Disable Ad hoc distributed queries option','major','CONFIG','Adhoc queries allow undefined access to remote database sources.  Access to untrusted databases could result in execution of malicious applications and/or a compromise of local data confidentiality and integrity. The DBA will configure the database to disable access from the database to objects stored externally to the database on the local host unless mission and/or operationally required and documented.\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Ad Hoc Distributed Queries\'','== 0','','SELECT name + \' Value : \'+ cast( value as varchar ) + \' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'Ad Hoc Distributed Queries\'','Ad Hoc Distributed Queries is disabled','Ad Hoc Distributed Queries is not disabled. Disable this option','pass',NULL,NULL,'2026-01-22 15:29:05'),(1325,202601,33,11,'AA_SqlServer_060_Disable CLR option','major','CONFIG','The clr_enabled parameter configures SQL Server to allow or disallow use of Command Language Runtime objects.  CLR objects is managed code that integrates with the .NET Framework.  This is a more secure method than external stored procedures, although it still contains some risk.  Where no external application execution requirements are required, disallowing use of any improves the overall security posture of the database.\r\n\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'clr enabled\'','== 0','','SELECT name + \' Value : \'+ cast( value as varchar ) + \' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'clr enabled\'','CLR option is disabled','CLR option is not disabled. Disable this option','pass',NULL,NULL,'2026-01-22 15:29:05'),(1326,202601,33,12,'AA_SqlServer_070_Disable Cross db ownership chaining option','major','CONFIG','Cross database ownership chaining allows permissions to objects to be assigned by users other than the Information Owner.  This allows access to objects that are not authorized directly by the Information Owner based on job functions defined by the owner.  Unauthorized access may lead to a compromise of data integrity or confidentiality. The DBA will ensure database privileges are assigned via roles and not directly assigned to database accounts. Privileges may be assigned directly to application owner accounts where the DBMS does not otherwise support access via roles.\r\n\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'cross db ownership chaining\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'cross db ownership chaining\'','Cross db ownership chaining  option is disabled','Cross db ownership chaining option  is not disabled. Disable this option','pass',NULL,NULL,'2026-01-22 15:29:05'),(1327,202601,33,13,'AA_SqlServer_080_Disable Database Mail XPs option','major','CONFIG','SQL Mail accepts incoming database commands via email. This can introduce malicious codes or viruses into the SQL server environment.','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Database Mail XPs\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \'Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'Database Mail XPs\'','Database Mail XPs option is disabled','Database Mail XPs option  is not disabled. Disable this option','pass',NULL,NULL,'2026-01-22 15:29:05'),(1328,202601,33,14,'AA_SqlServer_100_Disable xp_cmdshell Server Configuration option','major','CONFIG','The xp_cmdshell extended stored procedures allows execution of host executables outside the controls of database access permissions.  This access may be exploited by malicious users who have compromised the integrity of the SQL Server database process to control the host operating system to perpetrate additional malicious activity. The DBA should disable the use of external procedures by the database unless it is mission critical or operationally required','','SELECT CAST(value as int) +\r\n       CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'xp_cmdshell\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) +\r\n\' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'xp_cmdshell\'','xp_cmdshell Server Configuration option is disabled','xp_cmdshell Server Configuration option is not disabled. This option must be disabled','pass',NULL,NULL,'2026-01-22 15:29:05'),(1329,202601,33,15,'AA_SqlServer_110_Disable Remote Access option','major','CONFIG','The remote access option controls the execution of local stored procedures on remote\r\nservers or remote stored procedures on local server.Functionality can be abused to launch a Denial-of-Service (DoS) attack on remote servers\r\nby off-loading query processing to a target.\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'remote access\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \' Value in use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'remote access\'','Remote Access option is disabled','Remote Access option  is not disabled. Disable this option','fail','\n------------------------------------------\n\'remote access Value : 1 Value in use : 1\'',NULL,'2026-01-22 15:29:05'),(1330,202601,33,16,'AA_SqlServer_120_Disable Remote Admin Connections option','major','CONFIG','The remote admin connections option controls whether a client application on a remote\r\ncomputer can use the Dedicated Administrator Connection (DAC).The Dedicated Administrator Connection (DAC) lets an administrator access a running\r\nserver to execute diagnostic functions or Transact-SQL statements, or to troubleshoot\r\nproblems on the server, even when the server is locked or running in an abnormal state\r\nand not responding to a SQL Server Database Engine connection. In a cluster scenario, the\r\nadministrator may not actually be logged on to the same node that is currently hosting the\r\nSQL Server instance and thus is considered \"remote\". Therefore, this setting should usually\r\nbe enabled (1) for SQL Server failover clusters; otherwise it should be disabled (0) which is\r\nthe default.\r\n','','execute sp_executesql N\'\r\n\r\nDECLARE @x int;\r\n\r\nSELECT @x=isnull(CAST(value as int) + CAST(value_in_use as int),100)\r\nFROM sys.configurations\r\nWHERE name = \'\'remote admin connections\'\'\r\n\r\nIF @x = 100\r\n       SELECT 0 ;\r\nELSE \r\n   SELECT CAST(value as int) + CAST(value_in_use as int) \r\n   FROM sys.configurations\r\n   WHERE name = \'\'remote admin connections\'\'\r\n\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'remote admin connections\'','Remote Admin Connections option is disabled','Remote Admin Connections option  is not disabled. Disable this option','pass',NULL,NULL,'2026-01-22 15:29:05'),(1331,202601,33,19,'AA_SqlServer_150_Disable database trustworthy status','major','CONFIG','The TRUSTWORTHY database setting restricts access to database resources by databases that contain assemblies with the EXTERNAL_ACCESS or UNSAFE permission settings and modules that use impersonation of accounts assigned elevated privileges.  Unless all assemblies and code for the database have been reviewed, especially in the case where databases have been detached and attached between server instances, leaving the TRUSTWORTHY status to off can help reduce threats from malicious assemblies or modules.','','SELECT count(name)\r\nFROM sys.databases\r\nWHERE is_trustworthy_on = 1\r\nAND name != \'msdb\';','== 0','','SELECT name\r\nFROM sys.databases\r\nWHERE is_trustworthy_on = 1\r\nAND name != \'msdb\';','database trustworthy status is disabled','database trustworthy status is not disabled. Disable this option','pass',NULL,NULL,'2026-01-22 15:29:05'),(1332,202601,33,20,'Checkpoint başarıyla oluşturuldu.','major','CONFIG','This test checks if SQL Server Instance is not advertised by the SQL Server Browser service. To maintain a higher level of protection for database instances, we recommend that SQL Server Instance be hidden when it is not required. Please note that this test does not include Clustered Instances as turning off this feature may cause issues with the Clustered environment.\r\n\r\n','','execute sp_executesql N\'\r\n\r\nDECLARE @getValue INT\r\n\r\nEXEC master.sys.xp_instance_regread\r\n@rootkey = N\'\'HKEY_LOCAL_MACHINE\'\',\r\n@key = N\'\'SOFTWARE\\Microsoft\\Microsoft SQL Server\\MSSQLServer\\SuperSocketNetLib\'\',\r\n@value_name = N\'\'HideInstance\'\',\r\n@value = @getValue OUTPUT\r\n\r\nSELECT isnull(@getvalue,0)\'','==1','','execute sp_executesql N\'\r\n\r\nDECLARE @getValue INT\r\n\r\nEXEC master.sys.xp_instance_regread\r\n@rootkey = N\'\'HKEY_LOCAL_MACHINE\'\',\r\n@key = N\'\'SOFTWARE\\Microsoft\\Microsoft SQL Server\\MSSQLServer\\SuperSocketNetLib\'\',\r\n@value_name = N\'\'HideInstance\'\',\r\n@value = @getValue OUTPUT\r\n\r\nSELECT isnull(@getvalue,0)\'','SQL Server Instance is  hidden.\r\n','SQL Server Instance is not hidden. Hide the instance','fail','\n-\n0',NULL,'2026-01-22 15:29:05'),(1333,202601,33,21,'AA_SqlServer_160_Hide SQL Server Instance','major','CONFIG','This test checks if SQL Server Instance is not advertised by the SQL Server Browser service. To maintain a higher level of protection for database instances, we recommend that SQL Server Instance be hidden when it is not required. Please note that this test does not include Clustered Instances as turning off this feature may cause issues with the Clustered environment.\r\n\r\n','','execute sp_executesql N\'\r\n\r\nDECLARE @getValue INT\r\n\r\nEXEC master.sys.xp_instance_regread\r\n@rootkey = N\'\'HKEY_LOCAL_MACHINE\'\',\r\n@key = N\'\'SOFTWARE\\Microsoft\\Microsoft SQL Server\\MSSQLServer\\SuperSocketNetLib\'\',\r\n@value_name = N\'\'HideInstance\'\',\r\n@value = @getValue OUTPUT\r\n\r\nSELECT isnull(@getvalue,0)\'','==1','','execute sp_executesql N\'\r\n\r\nDECLARE @getValue INT\r\n\r\nEXEC master.sys.xp_instance_regread\r\n@rootkey = N\'\'HKEY_LOCAL_MACHINE\'\',\r\n@key = N\'\'SOFTWARE\\Microsoft\\Microsoft SQL Server\\MSSQLServer\\SuperSocketNetLib\'\',\r\n@value_name = N\'\'HideInstance\'\',\r\n@value = @getValue OUTPUT\r\n\r\nSELECT isnull(@getvalue,0)\'','SQL Server Instance is  hidden.','SQL Server Instance is not hidden. Hide the instance','fail','\n-\n0',NULL,'2026-01-22 15:29:05'),(1334,202601,33,38,'AA_SqlServer_300_No Access To General Extended procedures','major','PRIV','This test checks for the existence of, and user permissions on, extended stored procedures.  Either these procedures should be completely dropped, or access to them should be strictly limited. xp_cmdshell, xp_enumgroups, xp_grantlogin ,xp_logevent, xp_logininfo,    xp_msver, xp_revokelogin, xp_sprintf, xp_sqlmaint, xp_sscanf\r\n','','SELECT \r\ncount(*) \r\nFROM \r\n  [master].sys.system_objects o \r\n  JOIN [master].sys.database_permissions p ON o.object_id = p.major_id \r\n  JOIN [master].sys.database_principals u ON p.grantee_principal_id = u.principal_id \r\nWHERE \r\n    o.name in ( \r\n	\'xp_cmdshell\', \r\n	\'xp_enumgroups\', \r\n    \'xp_grantlogin\' ,\r\n	\'xp_logevent\', \r\n	\'xp_logininfo\', \r\n    \'xp_msver\', \r\n	\'xp_revokelogin\', \r\n	\'xp_sprintf\', \r\n    \'xp_sqlmaint\', \r\n	\'xp_sscanf\' )\r\n  AND p.type = \'EX\' ','== 0','','SELECT \r\n  \'Principal : \'+u.name  COLLATE DATABASE_DEFAULT +\r\n  \' Extended Procedure Name : \'+o.name COLLATE DATABASE_DEFAULT +\r\n  \' Type : \'+ u.type_desc COLLATE DATABASE_DEFAULT \r\nFROM \r\n  [master].sys.system_objects o \r\n  JOIN [master].sys.database_permissions p ON o.object_id = p.major_id \r\n  JOIN [master].sys.database_principals u ON p.grantee_principal_id = u.principal_id \r\nWHERE \r\n    o.name in ( \r\n	\'xp_cmdshell\', \r\n	\'xp_enumgroups\', \r\n    \'xp_grantlogin\' ,\r\n	\'xp_logevent\', \r\n	\'xp_logininfo\', \r\n    \'xp_msver\', \r\n	\'xp_revokelogin\', \r\n	\'xp_sprintf\', \r\n    \'xp_sqlmaint\', \r\n	\'xp_sscanf\' )\r\n  AND p.type = \'EX\' ','There are no permissions on general extended stored procedures\r\n','There are some persmissions permissions on general extended stored procedures.\r\n','fail','\n----------------------------------------------------------------------------------\n\'Principal : public Extended Procedure Name : xp_msver Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_sscanf Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_revokelogin Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_grantlogin Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_sprintf Type : DATABASE_ROLE\'',NULL,'2026-01-22 15:29:05'),(1335,202601,33,39,'AA_SqlServer_310_No Access to OLE Automation procedures','major','CONFIG','This test checks for the existence of,and user permissions on OLE automation extended stored procedures.  Either these procedures should be completely dropped, or access to them should be strictly limited.      \r\n','','SELECT CAST(value as int) +\r\n       CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Ole Automation Procedures\'   \r\n','== 0','','SELECT CAST(value as int) +\r\n       CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Ole Automation Procedures\'\r\n  \r\n','OLE Automation procedures  option is disabled\r\n','OLE Automation procedures  option  is not disabled. Disable this option\r\n','pass',NULL,NULL,'2026-01-22 15:29:05'),(1336,202601,33,17,'AA_SqlServer_130_Disable Ole Automation Procedures option','minor','CONFIG','This test checks if Ole Automation Procedures option is disabled. Ole Automation Procedures option allows SQL Server users to execute functions external to SQL Server. Enabling this option will increase the attack surface of SQL Server and allow users to execute functions in the security context of SQL Server. We recommend that the Ole Automation Procedures option to be disabled when it is not document as a requirement.\r\n\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Ole Automation Procedures\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \'Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'Ole Automation Procedures\'',' Ole Automation Procedures option is disabled',' Ole Automation Procedures option  is not disabled. Disable this option','pass',NULL,NULL,'2026-01-22 15:29:05'),(1337,202601,33,18,'AA_SqlServer_140_Disable Scan for Startup Procedures option','minor','CONFIG','This test checks if scan for startup procedures is disabled. This feature causes SQL Server to scan for and automatically run all stored procedures that are set to execute upon service startup. If there are no user-defined stored procedures set to execute when SQL server starts, we recommend this feature to be disabled.\r\n\r\n','','SELECT CAST(value as int) +\r\n       CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'scan for startup procs\'','== 0','','SELECT name + \' value : \'+cast( value as varchar ) +\r\n\' value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'scan for startup procs\'','Scan for Startup Procedures  option is disabled','Scan for Startup Procedures  option  is not disabled. Disable this option','pass',NULL,NULL,'2026-01-22 15:29:05'),(1338,202601,33,9,'AA_SqlServer_040_Rename the sa Login Account','major','ACCOUNT','The \'sa\' account is a well-known account.  Well-known account names provide an easier target for attack.  Renaming the sa account helps reduce the risk of an attack to this built-in account.','','SELECT count(*)\r\nFROM sys.server_principals\r\nWHERE sid = 0x01 and name=\'sa\'','== 0','','SELECT name\r\nFROM sys.server_principals\r\nWHERE sid = 0x01','sa Login Account is renamed','sa Login Account is not renamed. Rename this account','fail','name\n----\n\'sa\'',NULL,'2026-01-22 15:29:05'),(1339,202601,34,24,'AA_SqlServer_190_Public server role permision','critical','PRIV','public is a special fixed server role containing all logins. Unlike other fixed server roles,\r\npermissions can be changed for the public role. In keeping with the principle of least\r\nprivileges, the public server role should not be used to grant permissions at the server\r\nscope as these would be inherited by all users.\r\n\r\nEvery SQL Server login belongs to the public role and cannot be removed from this role.\r\nTherefore, any permissions granted to this role will be available to all logins unless they\r\nhave been explicitly denied to specific logins or user-defined server roles.','','Select \r\n  count (permission_name) \r\nfrom \r\n  sys.server_permissions \r\nwhere \r\n  SUSER_NAME(grantee_principal_id) = \'public\' \r\n  and permission_name not in (\'VIEW ANY DATABASE\', \'CONNECT\')\r\n','== 0','','Select \r\n  permission_name \r\nfrom \r\n  sys.server_permissions \r\nwhere \r\n  SUSER_NAME(grantee_principal_id) = \'public\' \r\n  and permission_name not in (\'VIEW ANY DATABASE\', \'CONNECT\')\r\n\r\n','No server permissions are granted to public.','Some server permissions are granted to public.','pass',NULL,NULL,'2026-01-22 15:29:06'),(1340,202601,34,5,'AA_SqlServer_010_Supported SQL Server version','critical','PATCH','This test checks whether your current SQL Server version is a vendor-supported version.  Microsoft does not provide security fixes or software updates to unsupported software versions','','SELECT cast(ISNULL(SERVERPROPERTY(\'ProductMajorVersion\'),0) as int)   ','>=11','','SELECT \'Product Major version \' +  cast(ISNULL(SERVERPROPERTY(\'ProductMajorVersion\'),\'Null\' ) as  char ) ','The version of the database is acceptable.','The version of the database is not acceptable. The database version should SQL Sever 2012 or upper.','pass',NULL,NULL,'2026-01-22 15:29:06'),(1341,202601,34,6,'AA_SqlServer_020_Disable the sa Login Account','critical','ACCOUNT','This test checks if the \'sa\' Login Account is disabled. The sa account is a widely known and often widely used SQL Server account with sysadmin privileges. Enforcing this control reduces the probability of an attacker executing brute force attacks against a well-known principal.','','SELECT  count(*)\r\nFROM sys.server_principals\r\nWHERE sid = 0x01\r\nAND is_disabled = 0','== 0','','SELECT \'sa user name : \'+ name+\' is disabled : \' +  cast( is_disabled as char)\r\nFROM sys.server_principals\r\nWHERE sid = 0x01\r\n','sa Login Account is disabled','Disable sa login account','fail','\n----------------------------------------------------------------\n\'sa user name : sa is disabled : 0                             \'',NULL,'2026-01-22 15:29:06'),(1342,202601,34,7,'AA_SqlServer_025_sa Change password','critical','ACCOUNT','This test checks that sa password change . The sa password should be changed in every two days','','select datediff( day,  modify_date , getdate() ) FROM sys.server_principals\r\nWHERE sid = 0x01  ','< 3','','select datediff( day,  modify_date , getdate() ) FROM sys.server_principals\r\nWHERE sid = 0x01 ','sa password was changed in two days','','fail','\n-\n8',NULL,'2026-01-22 15:29:06'),(1343,202601,34,8,'AA_SqlServer_030_Ensure no Login exists with sa Login Account','critical','ACCOUNT','The \'sa\' account is a well-known account.  Well-known account names provide an easier target for attack. The lack of the sa account helps reduce the risk of an attack to this built-in account.','','SELECT count(*)\r\nFROM sys.server_principals\r\nWHERE name = \'sa\'','== 0','','SELECT name\r\nFROM sys.server_principals\r\nWHERE name = \'sa\'','There is no the sa account in the database.','There is the sa Login account in the database.Drop this user or rename et.','fail','name\n----\n\'sa\'',NULL,'2026-01-22 15:29:06'),(1344,202601,34,25,'AA_SqlServer_200_Fixed Server Role members for users','critical','PRIV','This test checks fixed server roles for analyst , developers and real persons. Fixed server roles could not be assigned to real person users ( Developer, Analyst users ) . Only Admin can use fixed server role.\r\n','','Select     count(*)   from      sys.server_role_members    where      (       suser_name(member_principal_id) like \'ODEABANK%.%\'    	AND       suser_name(member_principal_id) not like \'%admin%\'         AND       suser_name(member_principal_id) not like \'%t.coban%\'     )      OR (       suser_name(member_principal_id) like \'ODEABANK\\Cyberark_Intertech%\'     )      \r\n','== 0','','Select      suser_name(role_principal_id) + \'   \' + suser_name(member_principal_id)    from      sys.server_role_members    where      (       suser_name(member_principal_id) like \'ODEABANK%.%\'    	AND       suser_name(member_principal_id) not like \'%admin%\'         AND       suser_name(member_principal_id) not like \'%t.coban%\'     )      OR (       suser_name(member_principal_id) like \'ODEABANK\\Cyberark_Intertech%\'     )          \r\n','Fixed Server role usage is correct.\r\n','Fixed Server role usage is not correct.\r\n','pass',NULL,NULL,'2026-01-22 15:29:06'),(1345,202601,34,26,'AA_SqlServer_210_Database Role members for users','critical','PRIV','This test checks database role members for analyst and real person users. Database roles  except  db_datareader could not be assigned to real person users ( Developer, Analyst users ) .\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      EXEC sp_MSforeachdb \'\' USE [?]    INSERT INTO #TEMP   SELECT \'\'\'\'DB Name : \'\'\'\'+Cast (DB_NAME() as varchar)+\'\'\'\' Role Name : \'\'\'\'+USER_NAME(role_principal_id)  +\'\'\'\' User Name \'\'\'\'+  USER_NAME(member_principal_id)    from  sys.database_role_members   	Where   	(   	( USER_NAME(member_principal_id)  like \'\'\'\'%ODEABANK%.%\'\'\'\'  and   USER_NAME(member_principal_id)  not like \'\'\'\'%admin%\'\'\'\' )     	OR   	  (suser_name(member_principal_id) like \'\'\'\'%ODEABANK%Cyberark%\'\'\'\')       )    	AND   	DB_NAME() <> \'\'\'\'master\'\'\'\' and   	USER_NAME(role_principal_id) not in (\'\'\'\'db_datareader\'\'\'\',\'\'\'\'db_viewdefinition\'\'\'\',\'\'\'\'db_denydatareader\'\'\'\',\'\'\'\'db_deny_maas\'\'\'\');   \'\'      Select  count(*)  from #TEMP;   \'\r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      EXEC sp_MSforeachdb \'\' USE [?]    INSERT INTO #TEMP   SELECT \'\'\'\'DB Name : \'\'\'\'+Cast (DB_NAME() as varchar)+\'\'\'\' Role Name : \'\'\'\'+USER_NAME(role_principal_id)  +\'\'\'\' User Name \'\'\'\'+  USER_NAME(member_principal_id)    from  sys.database_role_members   	Where   (   	( USER_NAME(member_principal_id)  like \'\'\'\'%ODEABANK%.%\'\'\'\'  and   USER_NAME(member_principal_id)  not like \'\'\'\'%admin%\'\'\'\' )     	OR   	(suser_name(member_principal_id) like \'\'\'\'%ODEABANK%Cyberark%\'\'\'\')   )    	AND   	DB_NAME() <> \'\'\'\'master\'\'\'\' and   	USER_NAME(role_principal_id) not in  (\'\'\'\'db_datareader\'\'\'\',\'\'\'\'db_viewdefinition\'\'\'\',\'\'\'\'db_denydatareader\'\'\'\',\'\'\'\'db_deny_maas\'\'\'\');   \'\'      Select  * from #TEMP;   \'\r\n','Database role member usage for users  is correct\r\n','Database role member usage for users  is not correct\r\n','pass',NULL,NULL,'2026-01-22 15:29:06');
INSERT INTO `assessment_run_checkpoints` VALUES (1346,202601,34,27,'AA_SqlServer_220_2_Public Database Permissions','critical','PRIV','This test checks database permisions for public . Public is a special role and permissions should not be granted to public role.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP ( row varchar(500));          exec sp_MSforeachdb \'\'   USE [?]   iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'public\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND OBJECT_NAME(MAJOR_iD) NOT LiKE (\'\'\'\'%fn_cdc_get_net_changes_application_data%\'\'\'\')   AND NOT (OBJECT_SCHEMA_NAME(MAJOR_iD) = \'\'\'\'cdc\'\'\'\' and PERMiSSiON_NAME=\'\'\'\'SELECT\'\'\'\')   AND NOT (PERMiSSiON_NAME IN (\'\'\'\'REFERENCES\'\'\'\',\'\'\'\'SEND\'\'\'\',   \'\'\'\'VIEW ANY COLUMN ENCRYPTION KEY DEFINITION\'\'\'\',   \'\'\'\'VIEW ANY COLUMN MASTER KEY DEFINITION\'\'\'\' ) and OBJECT_SCHEMA_NAME(MAJOR_iD) IS NULL)   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select count(*) from #TEMP;   \'\r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP ( row varchar(500));          exec sp_MSforeachdb \'\'   USE [?]   iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'public\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND OBJECT_NAME(MAJOR_iD) NOT LiKE (\'\'\'\'%fn_cdc_get_net_changes_application_data%\'\'\'\')   AND NOT (OBJECT_SCHEMA_NAME(MAJOR_iD) = \'\'\'\'cdc\'\'\'\' and PERMiSSiON_NAME=\'\'\'\'SELECT\'\'\'\')   AND NOT (PERMiSSiON_NAME IN (\'\'\'\'REFERENCES\'\'\'\',\'\'\'\'SEND\'\'\'\',   \'\'\'\'VIEW ANY COLUMN ENCRYPTION KEY DEFINITION\'\'\'\',   \'\'\'\'VIEW ANY COLUMN MASTER KEY DEFINITION\'\'\'\' ) and OBJECT_SCHEMA_NAME(MAJOR_iD) IS NULL)   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select * from #TEMP;   \'','There are no permissions which are assigned to public.\r\n','There are some persmissions which are assigned to public\r\n','pass',NULL,NULL,'2026-01-22 15:29:06'),(1347,202601,34,28,'AA_SqlServer_220_Public Database Permissions','critical','PRIV','This test checks database permisions for public . Public is a special role and permissions should not be granted to public role.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      exec sp_msforeachdb \'\'   USE [?]     iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'public\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND OBJECT_NAME(MAJOR_iD) NOT LiKE (\'\'\'\'%fn_cdc_get_net_changes_application_data%\'\'\'\')   AND NOT (OBJECT_SCHEMA_NAME(MAJOR_iD) = \'\'\'\'cdc\'\'\'\' and PERMiSSiON_NAME=\'\'\'\'SELECT\'\'\'\')   AND NOT (PERMiSSiON_NAME IN (\'\'\'\'REFERENCES\'\'\'\',\'\'\'\'SEND\'\'\'\',   \'\'\'\'VIEW ANY COLUMN ENCRYPTION KEY DEFINITION\'\'\'\',   \'\'\'\'VIEW ANY COLUMN MASTER KEY DEFINITION\'\'\'\' ) and OBJECT_SCHEMA_NAME(MAJOR_iD) IS NULL)   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select count(*) from #TEMP;   \' \r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      exec sp_msforeachdb \'\'   USE [?]     iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'public\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND OBJECT_NAME(MAJOR_iD) NOT LiKE (\'\'\'\'%fn_cdc_get_net_changes_application_data%\'\'\'\')   AND NOT (OBJECT_SCHEMA_NAME(MAJOR_iD) = \'\'\'\'cdc\'\'\'\' and PERMiSSiON_NAME=\'\'\'\'SELECT\'\'\'\')   AND NOT (PERMiSSiON_NAME IN (\'\'\'\'REFERENCES\'\'\'\',\'\'\'\'SEND\'\'\'\',   \'\'\'\'VIEW ANY COLUMN ENCRYPTION KEY DEFINITION\'\'\'\',   \'\'\'\'VIEW ANY COLUMN MASTER KEY DEFINITION\'\'\'\' ) and OBJECT_SCHEMA_NAME(MAJOR_iD) IS NULL)   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select * from #TEMP;   \' \r\n','There are no permissions which are assigned to public.\r\n','There are some persmissions which are assigned to public\r\n','pass',NULL,NULL,'2026-01-22 15:29:06'),(1348,202601,34,29,'AA_SqlServer_230_Real person users','critical','ACCOUNT','All logins to the database should be made with AD groups, real person users should  not be connected database directly\r\n','','Select      count(*)   from      sys.server_principals    where      name like \'ODEABANK%.%\'      and is_disabled = 0   \r\n','== 0','','Select      name     from      sys.server_principals    where      name like \'ODEABANK%.%\'      and is_disabled = 0;\r\n','Real person users are not found in the logins\r\n','Some real person users are found in the logins\r\n','pass',NULL,NULL,'2026-01-22 15:29:06'),(1349,202601,34,30,'AA_SqlServer_240_2_guest Database Permissions','critical','ACCOUNT','This test checks database permisions for guest . guest is a special user and permissions should not be granted to guest user.\r\n','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP ( row varchar(500));\r\n\r\nexec sp_MSforeachdb \'\'\r\nUSE [?]\r\niNSERT iNTO #TEMP\r\nSELECT\r\n\'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +\r\n\'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +\r\n\'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +\r\n\'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )\r\nFROM\r\nsys.database_permissions\r\nWHERE\r\nUSER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'guest\'\'\'\' )\r\nAND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'\r\nAND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')\r\nAND STATE_DESC=\'\'\'\'GRANT\'\'\'\'\r\n;\r\n\'\'\r\nselect count(*) from #TEMP;\r\n\'','== 0','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP ( row varchar(500));\r\n\r\nexec sp_MSforeachdb \'\'\r\nUSE [?]\r\niNSERT iNTO #TEMP\r\nSELECT\r\n\'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +\r\n\'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +\r\n\'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +\r\n\'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )\r\nFROM\r\nsys.database_permissions\r\nWHERE\r\nUSER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'guest\'\'\'\' )\r\nAND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'\r\nAND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')\r\nAND STATE_DESC=\'\'\'\'GRANT\'\'\'\'\r\n;\r\n\'\'\r\nselect * from #TEMP;\r\n\'','There are no permissions which are assigned to guest.\r\n','There are some persmissions which are assigned to guest\r\n','pass',NULL,NULL,'2026-01-22 15:29:06'),(1350,202601,34,31,'AA_SqlServer_240_guest Database Permissions','critical','PRIV','This test checks database permisions for guest . guest is a special user and permissions should not be granted to guest user.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      exec sp_msforeachdb \'\'   USE [?]     iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'guest\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select count(*) from #TEMP;   \' \r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      exec sp_msforeachdb \'\'   USE [?]     iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'guest\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select  *  from #TEMP;   \' \r\n','There are no permissions which are assigned to guest.\r\n','There are some persmissions which are assigned to guest\r\n','pass',NULL,NULL,'2026-01-22 15:29:06'),(1351,202601,34,32,'AA_SqlServer_250_Database Role members for guest','critical','PRIV','This test checks database role members for guest  user. Database roles  could not be assigned to guest role.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      EXEC sp_MSforeachdb \'\' USE [?]    INSERT INTO #TEMP   SELECT \'\'\'\'DB Name : \'\'\'\'+Cast (DB_NAME() as varchar)+\'\'\'\' Role Name : \'\'\'\'+USER_NAME(role_principal_id)  +\'\'\'\' User Name \'\'\'\'+  USER_NAME(member_principal_id)    from  sys.database_role_members   	Where     USER_NAME(member_principal_id)  = \'\'\'\'guest\'\'\'\'     ;   \'\'      Select count(*)  from #TEMP;   \'\r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      EXEC sp_MSforeachdb \'\' USE [?]    INSERT INTO #TEMP   SELECT \'\'\'\'DB Name : \'\'\'\'+Cast (DB_NAME() as varchar)+\'\'\'\' Role Name : \'\'\'\'+USER_NAME(role_principal_id)  +\'\'\'\' User Name \'\'\'\'+  USER_NAME(member_principal_id)    from  sys.database_role_members   	Where     USER_NAME(member_principal_id)  = \'\'\'\'guest\'\'\'\'     ;   \'\'      Select  *  from #TEMP;   \'\r\n','Database role member usage for guest user  is correct\r\n','Database role member usage for guest user  is not correct\r\n','pass',NULL,NULL,'2026-01-22 15:29:06'),(1352,202601,34,33,'AA_SqlServer_260_SQL Logins with Null Password','critical','ACCOUNT','This test checks sql logins with null password. SQL Logins should not have null passwords.\r\n','','SELECT      count(name)   from      sys.sql_logins    WHERE      PWDCOMPARE(\'\', password_hash)= 1\r\n','== 0','','SELECT      name    from      sys.sql_logins    WHERE      PWDCOMPARE(\'\', password_hash)= 1   \r\n','There are no sql logins with null paswords\r\n','There are some sql logins with null passwords.\r\n','pass',NULL,NULL,'2026-01-22 15:29:06'),(1353,202601,34,34,'AA_SqlServer_270_SQL Logins with username and passwords are equal','critical','ACCOUNT','This test checks sql login password which are egual to username. Username and password must be different for SQL logins.\r\n','','SELECT      count(name)   from      sys.sql_logins    WHERE      PWDCOMPARE(name,password_hash)=1 \r\n','== 0','','SELECT      name    from      sys.sql_logins    WHERE      PWDCOMPARE(name,password_hash)=1    \r\n','There is no SQL login name which is equal to password.\r\n','There are some sql logins whose passwords are egual to usernames.\r\n','pass',NULL,NULL,'2026-01-22 15:29:06'),(1354,202601,34,35,'AA_SqlServer_280_No Sample Databases','critical','CONFIG','This test checks whether the sample databases created optionally on installation are present.  These sample databases contain many default permissions, and can be used as an entry point to your systems. \r\n','','select      count(name)    from      sys.databases    where      name in (       \'AdventureWorks\', \'AdventureWorksDW\',        \'Northwind\', \'Pubs\'     )   \r\n','== 0','','select      name    from      sys.databases    where      name in (       \'AdventureWorks\', \'AdventureWorksDW\',        \'Northwind\', \'Pubs\'     )   \r\n','There are no sample databases in the server\r\n','There are some sample databases in the server\r\n','pass',NULL,NULL,'2026-01-22 15:29:06'),(1355,202601,34,43,'AA_SqlServer_350_User Password Policy Is Checked','critical','ACCOUNT','This test checks that CHECK_POLICY is enabled for all users.  Enabling CHECK_POLICY ensures that Windows passwords policies are enforced.','','select count(*) from sys.sql_logins  \r\nwhere \r\nis_policy_checked=0 and\r\nname not like \'##%\'','== 0','','select name from sys.sql_logins  \r\nwhere \r\nis_policy_checked=0 and\r\nname not like \'##%\'','CHECK_POLICY is enabled for all users','CHECK_POLICY is not enabled for all users','pass',NULL,NULL,'2026-01-22 15:29:06'),(1356,202601,34,44,'AA_SqlServer_360_CHECK_EXPIRATION Is Checked','critical','ACCOUNT','This test checks that CHECK_EXPIRATION is enabled for all users.  Passwords that have been in use for long periods of time are likely to become known to unauthorized users.\r\n','','select count(*) from sys.sql_logins     where    is_expiration_checked=0 and   name not like \'##%\'\r\n','== 0','','select name from sys.sql_logins     where    is_expiration_checked=0 and   name not like \'##%\'\r\n','CHECK_EXPIRATION is enabled for all users\r\n','CHECK_EXPIRATION is not enabled for all users\r\n','fail','name\n----\n\'sa\'',NULL,'2026-01-22 15:29:06'),(1357,202601,34,22,'AA_SqlServer_170_Windows Authentication','major','AUTH','This test checks that the authentication mode is set to Windows authentication only.  Windows provides a more robust authentication mechanism than SQL Server authentication.','',' SELECT cast( SERVERPROPERTY(\'IsIntegratedSecurityOnly\') as int) ','==1','','SELECT cast( SERVERPROPERTY(\'IsIntegratedSecurityOnly\') as varchar)','The authentication mode is set to Windows authentication only. ','The authentication mode is not set to Windows authentication only.','fail','\n---\n\'0\'',NULL,'2026-01-22 15:29:06'),(1358,202601,34,23,'AA_SqlServer_180_No Guest User Accounts','major','ACCOUNT','This test checks for the existence of guest user accounts with CONNECT permission in database other than master, msdb and tempdb.  This test also exclude databases that are flagged as distributor. If the GUEST user exists and a specific login has not been granted to a database, a login will be mapped to GUEST. The presence of the GUEST user allows all logins to access the database.\r\n','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP  ( row int);\r\n\r\nEXEC sp_MSforeachdb \'\' USE [?]\r\n	INSERT INTO #TEMP\r\n	SELECT count(*) \r\n	FROM sys.database_permissions\r\n	WHERE [grantee_principal_id] = DATABASE_PRINCIPAL_ID(\'\'\'\'guest\'\'\'\')\r\n	AND [state_desc] LIKE \'\'\'\'GRANT%\'\'\'\'\r\n	AND [permission_name] = \'\'\'\'CONNECT\'\'\'\'\r\n	AND DB_NAME() NOT IN (\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'msdb\'\'\'\') ;\r\n\'\'\r\n\r\nSelect sum(row) from #TEMP;\r\ndrop table #TEMP;\r\n\'','== 0','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP  ( row varchar(500));\r\n\r\nEXEC sp_MSforeachdb \'\' USE  [?] \r\n	INSERT INTO #TEMP\r\n	SELECT \'\'\'\' DB NAME : \'\'\'\' + Cast (DB_NAME() as varchar) + \'\'\'\' guest user has CONNECT permission \'\'\'\'\r\n	FROM sys.database_permissions\r\n	WHERE [grantee_principal_id] = DATABASE_PRINCIPAL_ID(\'\'\'\'guest\'\'\'\')\r\n	AND [state_desc] LIKE \'\'\'\'GRANT%\'\'\'\'\r\n	AND [permission_name] = \'\'\'\'CONNECT\'\'\'\'\r\n	AND DB_NAME() NOT IN (\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'msdb\'\'\'\') ;\r\n\'\'\r\n\r\nSelect * from #TEMP;\r\ndrop table #TEMP;\r\n\'','There is no guest user with CONNECT permission. ','There are   guest users with CONNECT permission. Remove these users','pass',NULL,NULL,'2026-01-22 15:29:06'),(1359,202601,34,36,'AA_SqlServer_290_2_No Permissions with GRANT Option','major','PRIV','This test checks database permisions  with grant option. No permission with grant option should be defined in the database.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP ( row varchar(500));      exec sp_MSforeachdb \'\'   USE [?]   iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   STATE_DESC like \'\'\'\'%WITH_GRANT%\'\'\'\'   ;   \'\'   select count(*) from #TEMP;   \'\r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP ( row varchar(500));      exec sp_MSforeachdb \'\'   USE [?]   iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   STATE_DESC like \'\'\'\'%WITH_GRANT%\'\'\'\'   ;   \'\'   select * from #TEMP;   \'\r\n','There are no permissions with grant option.\r\n','There are some persmissions  with grant option.\r\n','pass',NULL,NULL,'2026-01-22 15:29:06'),(1360,202601,34,37,'AA_SqlServer_290_No Permissions with GRANT Option','major','PRIV','','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP  ( row varchar(500));\r\n\r\nexec sp_msforeachdb \'\'\r\nUSE [?]  \r\niNSERT iNTO #TEMP\r\nSELECT\r\n\'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +\r\n\'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +\r\n\'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +\r\n\'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )\r\nFROM\r\nsys.database_permissions\r\nWHERE\r\nSTATE_DESC like \'\'\'\'%WITH_GRANT%\'\'\'\'\r\n;\r\n\'\'\r\nselect  count(*)  from #TEMP;\r\n\' ','== 0','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP  ( row varchar(500));\r\n\r\nexec sp_msforeachdb \'\'\r\nUSE [?]  \r\niNSERT iNTO #TEMP\r\nSELECT\r\n\'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +\r\n\'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +\r\n\'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +\r\n\'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )\r\nFROM\r\nsys.database_permissions\r\nWHERE\r\nSTATE_DESC like \'\'\'\'%WITH_GRANT%\'\'\'\'\r\n;\r\n\'\'\r\nselect * from #TEMP;\r\n\' ','There are no permissions with grant option.\r\n','There are some persmissions  with grant option.\r\n','pass',NULL,NULL,'2026-01-22 15:29:06'),(1361,202601,34,40,'AA_SqlServer_320_No Access to Registry Access Extended procedures','major','PRIV','This test checks for the existence of, and user permissions on, registry access extended stored procedures.  Either these procedures should be completely dropped, or access to them should be strictly limited. xp_reg%,xp_instance_reg%\r\n','','SELECT \r\ncount(*) \r\nFROM \r\n  [master].sys.system_objects o \r\n  JOIN [master].sys.database_permissions p ON o.object_id = p.major_id \r\n  JOIN [master].sys.database_principals u ON p.grantee_principal_id = u.principal_id \r\nWHERE \r\n( o.name LIKE \'xp_reg%\' OR o.name LIKE \'xp_instance_reg%\')\r\n  AND p.type = \'EX\' ','== 0','','SELECT \r\n  \'Principal : \'+u.name  COLLATE DATABASE_DEFAULT +\r\n  \' Extended Procedure Name : \'+o.name COLLATE DATABASE_DEFAULT +\r\n  \' Type : \'+ u.type_desc COLLATE DATABASE_DEFAULT \r\nFROM \r\n  [master].sys.system_objects o \r\n  JOIN [master].sys.database_permissions p ON o.object_id = p.major_id \r\n  JOIN [master].sys.database_principals u ON p.grantee_principal_id = u.principal_id \r\nWHERE \r\n( o.name LIKE \'xp_reg%\' OR o.name LIKE \'xp_instance_reg%\')\r\n  AND p.type = \'EX\' ','There are no permissions on registry access extended stored procedures\r\n','There are some persmissions permissions on registry access extended stored procedures\r\n','fail','\n---------------------------------------------------------------------------------------\n\'Principal : public Extended Procedure Name : xp_instance_regread Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_regread Type : DATABASE_ROLE\'',NULL,'2026-01-22 15:29:06'),(1362,202601,34,41,'AA_SqlServer_330_Revoke public login from SQL Server agent proxy account','major','PRIV','The public database role contains every user in the msdb database. SQL Agent proxies   define a security context in which a job step can run.Granting access to SQL Agent proxies for the public role would allow all users to utilize the proxy which may have high privileges. This would likely break the principle of least   privileges.\r\n','','SELECT count(*)\r\nFROM msdb.dbo.sysproxylogin spl\r\nJOIN sys.database_principals dp\r\nON dp.sid = spl.sid\r\nJOIN msdb.dbo.sysproxies sp\r\nON sp.proxy_id = spl.proxy_id\r\nWHERE principal_id = USER_ID(\'public\')','== 0','','SELECT \'proxyname : \'+CAST(sp.name  as varchar)\r\nFROM msdb.dbo.sysproxylogin spl\r\nJOIN sys.database_principals dp\r\nON dp.sid = spl.sid\r\nJOIN msdb.dbo.sysproxies sp\r\nON sp.proxy_id = spl.proxy_id\r\nWHERE principal_id = USER_ID(\'public\')','There are no public permissions on SQL Server agent proxy account\r\n','There are some public permissions on SQL Server agent proxy account\r\n','pass',NULL,NULL,'2026-01-22 15:29:06'),(1363,202601,34,42,'AA_SqlServer_340_No Individual User Access To syscomment and sp_helptext','minor','PRIV','This test checks for grants on SYSCOMMENTS.TEXT.  Such grants allow any user to read the text comments associated with a database object, making the text publicly viewable.\r\n','','SELECT count(*)\r\nFROM msdb.dbo.sysproxylogin spl\r\nJOIN sys.database_principals dp\r\nON dp.sid = spl.sid\r\nJOIN msdb.dbo.sysproxies sp\r\nON sp.proxy_id = spl.proxy_id\r\nWHERE principal_id = USER_ID(\'public\')\r\n','== 0','','SELECT count(*)\r\nFROM msdb.dbo.sysproxylogin spl\r\nJOIN sys.database_principals dp\r\nON dp.sid = spl.sid\r\nJOIN msdb.dbo.sysproxies sp\r\nON sp.proxy_id = spl.proxy_id\r\nWHERE principal_id = USER_ID(\'public\')','There are no public permissions on SQL Server agent proxy account','There are some public permissions on SQL Server agent proxy account','pass',NULL,NULL,'2026-01-22 15:29:06'),(1364,202601,34,10,'AA_SqlServer_050_Disable Ad hoc distributed queries option','major','CONFIG','Adhoc queries allow undefined access to remote database sources.  Access to untrusted databases could result in execution of malicious applications and/or a compromise of local data confidentiality and integrity. The DBA will configure the database to disable access from the database to objects stored externally to the database on the local host unless mission and/or operationally required and documented.\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Ad Hoc Distributed Queries\'','== 0','','SELECT name + \' Value : \'+ cast( value as varchar ) + \' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'Ad Hoc Distributed Queries\'','Ad Hoc Distributed Queries is disabled','Ad Hoc Distributed Queries is not disabled. Disable this option','pass',NULL,NULL,'2026-01-22 15:29:06'),(1365,202601,34,11,'AA_SqlServer_060_Disable CLR option','major','CONFIG','The clr_enabled parameter configures SQL Server to allow or disallow use of Command Language Runtime objects.  CLR objects is managed code that integrates with the .NET Framework.  This is a more secure method than external stored procedures, although it still contains some risk.  Where no external application execution requirements are required, disallowing use of any improves the overall security posture of the database.\r\n\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'clr enabled\'','== 0','','SELECT name + \' Value : \'+ cast( value as varchar ) + \' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'clr enabled\'','CLR option is disabled','CLR option is not disabled. Disable this option','pass',NULL,NULL,'2026-01-22 15:29:06'),(1366,202601,34,12,'AA_SqlServer_070_Disable Cross db ownership chaining option','major','CONFIG','Cross database ownership chaining allows permissions to objects to be assigned by users other than the Information Owner.  This allows access to objects that are not authorized directly by the Information Owner based on job functions defined by the owner.  Unauthorized access may lead to a compromise of data integrity or confidentiality. The DBA will ensure database privileges are assigned via roles and not directly assigned to database accounts. Privileges may be assigned directly to application owner accounts where the DBMS does not otherwise support access via roles.\r\n\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'cross db ownership chaining\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'cross db ownership chaining\'','Cross db ownership chaining  option is disabled','Cross db ownership chaining option  is not disabled. Disable this option','pass',NULL,NULL,'2026-01-22 15:29:06'),(1367,202601,34,13,'AA_SqlServer_080_Disable Database Mail XPs option','major','CONFIG','SQL Mail accepts incoming database commands via email. This can introduce malicious codes or viruses into the SQL server environment.','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Database Mail XPs\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \'Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'Database Mail XPs\'','Database Mail XPs option is disabled','Database Mail XPs option  is not disabled. Disable this option','pass',NULL,NULL,'2026-01-22 15:29:06'),(1368,202601,34,14,'AA_SqlServer_100_Disable xp_cmdshell Server Configuration option','major','CONFIG','The xp_cmdshell extended stored procedures allows execution of host executables outside the controls of database access permissions.  This access may be exploited by malicious users who have compromised the integrity of the SQL Server database process to control the host operating system to perpetrate additional malicious activity. The DBA should disable the use of external procedures by the database unless it is mission critical or operationally required','','SELECT CAST(value as int) +\r\n       CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'xp_cmdshell\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) +\r\n\' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'xp_cmdshell\'','xp_cmdshell Server Configuration option is disabled','xp_cmdshell Server Configuration option is not disabled. This option must be disabled','pass',NULL,NULL,'2026-01-22 15:29:06'),(1369,202601,34,15,'AA_SqlServer_110_Disable Remote Access option','major','CONFIG','The remote access option controls the execution of local stored procedures on remote\r\nservers or remote stored procedures on local server.Functionality can be abused to launch a Denial-of-Service (DoS) attack on remote servers\r\nby off-loading query processing to a target.\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'remote access\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \' Value in use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'remote access\'','Remote Access option is disabled','Remote Access option  is not disabled. Disable this option','fail','\n------------------------------------------\n\'remote access Value : 1 Value in use : 1\'',NULL,'2026-01-22 15:29:06'),(1370,202601,34,16,'AA_SqlServer_120_Disable Remote Admin Connections option','major','CONFIG','The remote admin connections option controls whether a client application on a remote\r\ncomputer can use the Dedicated Administrator Connection (DAC).The Dedicated Administrator Connection (DAC) lets an administrator access a running\r\nserver to execute diagnostic functions or Transact-SQL statements, or to troubleshoot\r\nproblems on the server, even when the server is locked or running in an abnormal state\r\nand not responding to a SQL Server Database Engine connection. In a cluster scenario, the\r\nadministrator may not actually be logged on to the same node that is currently hosting the\r\nSQL Server instance and thus is considered \"remote\". Therefore, this setting should usually\r\nbe enabled (1) for SQL Server failover clusters; otherwise it should be disabled (0) which is\r\nthe default.\r\n','','execute sp_executesql N\'\r\n\r\nDECLARE @x int;\r\n\r\nSELECT @x=isnull(CAST(value as int) + CAST(value_in_use as int),100)\r\nFROM sys.configurations\r\nWHERE name = \'\'remote admin connections\'\'\r\n\r\nIF @x = 100\r\n       SELECT 0 ;\r\nELSE \r\n   SELECT CAST(value as int) + CAST(value_in_use as int) \r\n   FROM sys.configurations\r\n   WHERE name = \'\'remote admin connections\'\'\r\n\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'remote admin connections\'','Remote Admin Connections option is disabled','Remote Admin Connections option  is not disabled. Disable this option','pass',NULL,NULL,'2026-01-22 15:29:06'),(1371,202601,34,19,'AA_SqlServer_150_Disable database trustworthy status','major','CONFIG','The TRUSTWORTHY database setting restricts access to database resources by databases that contain assemblies with the EXTERNAL_ACCESS or UNSAFE permission settings and modules that use impersonation of accounts assigned elevated privileges.  Unless all assemblies and code for the database have been reviewed, especially in the case where databases have been detached and attached between server instances, leaving the TRUSTWORTHY status to off can help reduce threats from malicious assemblies or modules.','','SELECT count(name)\r\nFROM sys.databases\r\nWHERE is_trustworthy_on = 1\r\nAND name != \'msdb\';','== 0','','SELECT name\r\nFROM sys.databases\r\nWHERE is_trustworthy_on = 1\r\nAND name != \'msdb\';','database trustworthy status is disabled','database trustworthy status is not disabled. Disable this option','pass',NULL,NULL,'2026-01-22 15:29:06'),(1372,202601,34,20,'Checkpoint başarıyla oluşturuldu.','major','CONFIG','This test checks if SQL Server Instance is not advertised by the SQL Server Browser service. To maintain a higher level of protection for database instances, we recommend that SQL Server Instance be hidden when it is not required. Please note that this test does not include Clustered Instances as turning off this feature may cause issues with the Clustered environment.\r\n\r\n','','execute sp_executesql N\'\r\n\r\nDECLARE @getValue INT\r\n\r\nEXEC master.sys.xp_instance_regread\r\n@rootkey = N\'\'HKEY_LOCAL_MACHINE\'\',\r\n@key = N\'\'SOFTWARE\\Microsoft\\Microsoft SQL Server\\MSSQLServer\\SuperSocketNetLib\'\',\r\n@value_name = N\'\'HideInstance\'\',\r\n@value = @getValue OUTPUT\r\n\r\nSELECT isnull(@getvalue,0)\'','==1','','execute sp_executesql N\'\r\n\r\nDECLARE @getValue INT\r\n\r\nEXEC master.sys.xp_instance_regread\r\n@rootkey = N\'\'HKEY_LOCAL_MACHINE\'\',\r\n@key = N\'\'SOFTWARE\\Microsoft\\Microsoft SQL Server\\MSSQLServer\\SuperSocketNetLib\'\',\r\n@value_name = N\'\'HideInstance\'\',\r\n@value = @getValue OUTPUT\r\n\r\nSELECT isnull(@getvalue,0)\'','SQL Server Instance is  hidden.\r\n','SQL Server Instance is not hidden. Hide the instance','fail','\n-\n0',NULL,'2026-01-22 15:29:06'),(1373,202601,34,21,'AA_SqlServer_160_Hide SQL Server Instance','major','CONFIG','This test checks if SQL Server Instance is not advertised by the SQL Server Browser service. To maintain a higher level of protection for database instances, we recommend that SQL Server Instance be hidden when it is not required. Please note that this test does not include Clustered Instances as turning off this feature may cause issues with the Clustered environment.\r\n\r\n','','execute sp_executesql N\'\r\n\r\nDECLARE @getValue INT\r\n\r\nEXEC master.sys.xp_instance_regread\r\n@rootkey = N\'\'HKEY_LOCAL_MACHINE\'\',\r\n@key = N\'\'SOFTWARE\\Microsoft\\Microsoft SQL Server\\MSSQLServer\\SuperSocketNetLib\'\',\r\n@value_name = N\'\'HideInstance\'\',\r\n@value = @getValue OUTPUT\r\n\r\nSELECT isnull(@getvalue,0)\'','==1','','execute sp_executesql N\'\r\n\r\nDECLARE @getValue INT\r\n\r\nEXEC master.sys.xp_instance_regread\r\n@rootkey = N\'\'HKEY_LOCAL_MACHINE\'\',\r\n@key = N\'\'SOFTWARE\\Microsoft\\Microsoft SQL Server\\MSSQLServer\\SuperSocketNetLib\'\',\r\n@value_name = N\'\'HideInstance\'\',\r\n@value = @getValue OUTPUT\r\n\r\nSELECT isnull(@getvalue,0)\'','SQL Server Instance is  hidden.','SQL Server Instance is not hidden. Hide the instance','fail','\n-\n0',NULL,'2026-01-22 15:29:06'),(1374,202601,34,38,'AA_SqlServer_300_No Access To General Extended procedures','major','PRIV','This test checks for the existence of, and user permissions on, extended stored procedures.  Either these procedures should be completely dropped, or access to them should be strictly limited. xp_cmdshell, xp_enumgroups, xp_grantlogin ,xp_logevent, xp_logininfo,    xp_msver, xp_revokelogin, xp_sprintf, xp_sqlmaint, xp_sscanf\r\n','','SELECT \r\ncount(*) \r\nFROM \r\n  [master].sys.system_objects o \r\n  JOIN [master].sys.database_permissions p ON o.object_id = p.major_id \r\n  JOIN [master].sys.database_principals u ON p.grantee_principal_id = u.principal_id \r\nWHERE \r\n    o.name in ( \r\n	\'xp_cmdshell\', \r\n	\'xp_enumgroups\', \r\n    \'xp_grantlogin\' ,\r\n	\'xp_logevent\', \r\n	\'xp_logininfo\', \r\n    \'xp_msver\', \r\n	\'xp_revokelogin\', \r\n	\'xp_sprintf\', \r\n    \'xp_sqlmaint\', \r\n	\'xp_sscanf\' )\r\n  AND p.type = \'EX\' ','== 0','','SELECT \r\n  \'Principal : \'+u.name  COLLATE DATABASE_DEFAULT +\r\n  \' Extended Procedure Name : \'+o.name COLLATE DATABASE_DEFAULT +\r\n  \' Type : \'+ u.type_desc COLLATE DATABASE_DEFAULT \r\nFROM \r\n  [master].sys.system_objects o \r\n  JOIN [master].sys.database_permissions p ON o.object_id = p.major_id \r\n  JOIN [master].sys.database_principals u ON p.grantee_principal_id = u.principal_id \r\nWHERE \r\n    o.name in ( \r\n	\'xp_cmdshell\', \r\n	\'xp_enumgroups\', \r\n    \'xp_grantlogin\' ,\r\n	\'xp_logevent\', \r\n	\'xp_logininfo\', \r\n    \'xp_msver\', \r\n	\'xp_revokelogin\', \r\n	\'xp_sprintf\', \r\n    \'xp_sqlmaint\', \r\n	\'xp_sscanf\' )\r\n  AND p.type = \'EX\' ','There are no permissions on general extended stored procedures\r\n','There are some persmissions permissions on general extended stored procedures.\r\n','fail','\n----------------------------------------------------------------------------------\n\'Principal : public Extended Procedure Name : xp_msver Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_sscanf Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_revokelogin Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_grantlogin Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_sprintf Type : DATABASE_ROLE\'',NULL,'2026-01-22 15:29:06'),(1375,202601,34,39,'AA_SqlServer_310_No Access to OLE Automation procedures','major','CONFIG','This test checks for the existence of,and user permissions on OLE automation extended stored procedures.  Either these procedures should be completely dropped, or access to them should be strictly limited.      \r\n','','SELECT CAST(value as int) +\r\n       CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Ole Automation Procedures\'   \r\n','== 0','','SELECT CAST(value as int) +\r\n       CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Ole Automation Procedures\'\r\n  \r\n','OLE Automation procedures  option is disabled\r\n','OLE Automation procedures  option  is not disabled. Disable this option\r\n','pass',NULL,NULL,'2026-01-22 15:29:06'),(1376,202601,34,17,'AA_SqlServer_130_Disable Ole Automation Procedures option','minor','CONFIG','This test checks if Ole Automation Procedures option is disabled. Ole Automation Procedures option allows SQL Server users to execute functions external to SQL Server. Enabling this option will increase the attack surface of SQL Server and allow users to execute functions in the security context of SQL Server. We recommend that the Ole Automation Procedures option to be disabled when it is not document as a requirement.\r\n\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Ole Automation Procedures\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \'Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'Ole Automation Procedures\'',' Ole Automation Procedures option is disabled',' Ole Automation Procedures option  is not disabled. Disable this option','pass',NULL,NULL,'2026-01-22 15:29:06'),(1377,202601,34,18,'AA_SqlServer_140_Disable Scan for Startup Procedures option','minor','CONFIG','This test checks if scan for startup procedures is disabled. This feature causes SQL Server to scan for and automatically run all stored procedures that are set to execute upon service startup. If there are no user-defined stored procedures set to execute when SQL server starts, we recommend this feature to be disabled.\r\n\r\n','','SELECT CAST(value as int) +\r\n       CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'scan for startup procs\'','== 0','','SELECT name + \' value : \'+cast( value as varchar ) +\r\n\' value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'scan for startup procs\'','Scan for Startup Procedures  option is disabled','Scan for Startup Procedures  option  is not disabled. Disable this option','pass',NULL,NULL,'2026-01-22 15:29:06'),(1378,202601,34,9,'AA_SqlServer_040_Rename the sa Login Account','major','ACCOUNT','The \'sa\' account is a well-known account.  Well-known account names provide an easier target for attack.  Renaming the sa account helps reduce the risk of an attack to this built-in account.','','SELECT count(*)\r\nFROM sys.server_principals\r\nWHERE sid = 0x01 and name=\'sa\'','== 0','','SELECT name\r\nFROM sys.server_principals\r\nWHERE sid = 0x01','sa Login Account is renamed','sa Login Account is not renamed. Rename this account','fail','name\n----\n\'sa\'',NULL,'2026-01-22 15:29:06'),(1379,202601,46,24,'AA_SqlServer_190_Public server role permision','critical','PRIV','public is a special fixed server role containing all logins. Unlike other fixed server roles,\r\npermissions can be changed for the public role. In keeping with the principle of least\r\nprivileges, the public server role should not be used to grant permissions at the server\r\nscope as these would be inherited by all users.\r\n\r\nEvery SQL Server login belongs to the public role and cannot be removed from this role.\r\nTherefore, any permissions granted to this role will be available to all logins unless they\r\nhave been explicitly denied to specific logins or user-defined server roles.','','Select \r\n  count (permission_name) \r\nfrom \r\n  sys.server_permissions \r\nwhere \r\n  SUSER_NAME(grantee_principal_id) = \'public\' \r\n  and permission_name not in (\'VIEW ANY DATABASE\', \'CONNECT\')\r\n','== 0','','Select \r\n  permission_name \r\nfrom \r\n  sys.server_permissions \r\nwhere \r\n  SUSER_NAME(grantee_principal_id) = \'public\' \r\n  and permission_name not in (\'VIEW ANY DATABASE\', \'CONNECT\')\r\n\r\n','No server permissions are granted to public.','Some server permissions are granted to public.','pass',NULL,NULL,'2026-01-25 11:34:22'),(1380,202601,46,5,'AA_SqlServer_010_Supported SQL Server version','critical','PATCH','This test checks whether your current SQL Server version is a vendor-supported version.  Microsoft does not provide security fixes or software updates to unsupported software versions','','SELECT cast(ISNULL(SERVERPROPERTY(\'ProductMajorVersion\'),0) as int)   ','>=11','','SELECT \'Product Major version \' +  cast(ISNULL(SERVERPROPERTY(\'ProductMajorVersion\'),\'Null\' ) as  char ) ','The version of the database is acceptable.','The version of the database is not acceptable. The database version should SQL Sever 2012 or upper.','pass',NULL,NULL,'2026-01-25 11:34:22'),(1381,202601,46,6,'AA_SqlServer_020_Disable the sa Login Account','critical','ACCOUNT','This test checks if the \'sa\' Login Account is disabled. The sa account is a widely known and often widely used SQL Server account with sysadmin privileges. Enforcing this control reduces the probability of an attacker executing brute force attacks against a well-known principal.','','SELECT  count(*)\r\nFROM sys.server_principals\r\nWHERE sid = 0x01\r\nAND is_disabled = 0','== 0','','SELECT \'sa user name : \'+ name+\' is disabled : \' +  cast( is_disabled as char)\r\nFROM sys.server_principals\r\nWHERE sid = 0x01\r\n','sa Login Account is disabled','Disable sa login account','fail','\n----------------------------------------------------------------\n\'sa user name : sa is disabled : 0                             \'',NULL,'2026-01-25 11:34:22'),(1382,202601,46,7,'AA_SqlServer_025_sa Change password','critical','ACCOUNT','This test checks that sa password change . The sa password should be changed in every two days','','select datediff( day,  modify_date , getdate() ) FROM sys.server_principals\r\nWHERE sid = 0x01  ','< 3','','select datediff( day,  modify_date , getdate() ) FROM sys.server_principals\r\nWHERE sid = 0x01 ','sa password was changed in two days','','fail','\n--\n11',NULL,'2026-01-25 11:34:22'),(1383,202601,46,8,'AA_SqlServer_030_Ensure no Login exists with sa Login Account','critical','ACCOUNT','The \'sa\' account is a well-known account.  Well-known account names provide an easier target for attack. The lack of the sa account helps reduce the risk of an attack to this built-in account.','','SELECT count(*)\r\nFROM sys.server_principals\r\nWHERE name = \'sa\'','== 0','','SELECT name\r\nFROM sys.server_principals\r\nWHERE name = \'sa\'','There is no the sa account in the database.','There is the sa Login account in the database.Drop this user or rename et.','fail','name\n----\n\'sa\'',NULL,'2026-01-25 11:34:22'),(1384,202601,46,25,'AA_SqlServer_200_Fixed Server Role members for users','critical','PRIV','This test checks fixed server roles for analyst , developers and real persons. Fixed server roles could not be assigned to real person users ( Developer, Analyst users ) . Only Admin can use fixed server role.\r\n','','Select     count(*)   from      sys.server_role_members    where      (       suser_name(member_principal_id) like \'ODEABANK%.%\'    	AND       suser_name(member_principal_id) not like \'%admin%\'         AND       suser_name(member_principal_id) not like \'%t.coban%\'     )      OR (       suser_name(member_principal_id) like \'ODEABANK\\Cyberark_Intertech%\'     )      \r\n','== 0','','Select      suser_name(role_principal_id) + \'   \' + suser_name(member_principal_id)    from      sys.server_role_members    where      (       suser_name(member_principal_id) like \'ODEABANK%.%\'    	AND       suser_name(member_principal_id) not like \'%admin%\'         AND       suser_name(member_principal_id) not like \'%t.coban%\'     )      OR (       suser_name(member_principal_id) like \'ODEABANK\\Cyberark_Intertech%\'     )          \r\n','Fixed Server role usage is correct.\r\n','Fixed Server role usage is not correct.\r\n','pass',NULL,NULL,'2026-01-25 11:34:22'),(1385,202601,46,26,'AA_SqlServer_210_Database Role members for users','critical','PRIV','This test checks database role members for analyst and real person users. Database roles  except  db_datareader could not be assigned to real person users ( Developer, Analyst users ) .\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      EXEC sp_MSforeachdb \'\' USE [?]    INSERT INTO #TEMP   SELECT \'\'\'\'DB Name : \'\'\'\'+Cast (DB_NAME() as varchar)+\'\'\'\' Role Name : \'\'\'\'+USER_NAME(role_principal_id)  +\'\'\'\' User Name \'\'\'\'+  USER_NAME(member_principal_id)    from  sys.database_role_members   	Where   	(   	( USER_NAME(member_principal_id)  like \'\'\'\'%ODEABANK%.%\'\'\'\'  and   USER_NAME(member_principal_id)  not like \'\'\'\'%admin%\'\'\'\' )     	OR   	  (suser_name(member_principal_id) like \'\'\'\'%ODEABANK%Cyberark%\'\'\'\')       )    	AND   	DB_NAME() <> \'\'\'\'master\'\'\'\' and   	USER_NAME(role_principal_id) not in (\'\'\'\'db_datareader\'\'\'\',\'\'\'\'db_viewdefinition\'\'\'\',\'\'\'\'db_denydatareader\'\'\'\',\'\'\'\'db_deny_maas\'\'\'\');   \'\'      Select  count(*)  from #TEMP;   \'\r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      EXEC sp_MSforeachdb \'\' USE [?]    INSERT INTO #TEMP   SELECT \'\'\'\'DB Name : \'\'\'\'+Cast (DB_NAME() as varchar)+\'\'\'\' Role Name : \'\'\'\'+USER_NAME(role_principal_id)  +\'\'\'\' User Name \'\'\'\'+  USER_NAME(member_principal_id)    from  sys.database_role_members   	Where   (   	( USER_NAME(member_principal_id)  like \'\'\'\'%ODEABANK%.%\'\'\'\'  and   USER_NAME(member_principal_id)  not like \'\'\'\'%admin%\'\'\'\' )     	OR   	(suser_name(member_principal_id) like \'\'\'\'%ODEABANK%Cyberark%\'\'\'\')   )    	AND   	DB_NAME() <> \'\'\'\'master\'\'\'\' and   	USER_NAME(role_principal_id) not in  (\'\'\'\'db_datareader\'\'\'\',\'\'\'\'db_viewdefinition\'\'\'\',\'\'\'\'db_denydatareader\'\'\'\',\'\'\'\'db_deny_maas\'\'\'\');   \'\'      Select  * from #TEMP;   \'\r\n','Database role member usage for users  is correct\r\n','Database role member usage for users  is not correct\r\n','pass',NULL,NULL,'2026-01-25 11:34:23'),(1386,202601,46,27,'AA_SqlServer_220_2_Public Database Permissions','critical','PRIV','This test checks database permisions for public . Public is a special role and permissions should not be granted to public role.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP ( row varchar(500));          exec sp_MSforeachdb \'\'   USE [?]   iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'public\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND OBJECT_NAME(MAJOR_iD) NOT LiKE (\'\'\'\'%fn_cdc_get_net_changes_application_data%\'\'\'\')   AND NOT (OBJECT_SCHEMA_NAME(MAJOR_iD) = \'\'\'\'cdc\'\'\'\' and PERMiSSiON_NAME=\'\'\'\'SELECT\'\'\'\')   AND NOT (PERMiSSiON_NAME IN (\'\'\'\'REFERENCES\'\'\'\',\'\'\'\'SEND\'\'\'\',   \'\'\'\'VIEW ANY COLUMN ENCRYPTION KEY DEFINITION\'\'\'\',   \'\'\'\'VIEW ANY COLUMN MASTER KEY DEFINITION\'\'\'\' ) and OBJECT_SCHEMA_NAME(MAJOR_iD) IS NULL)   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select count(*) from #TEMP;   \'\r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP ( row varchar(500));          exec sp_MSforeachdb \'\'   USE [?]   iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'public\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND OBJECT_NAME(MAJOR_iD) NOT LiKE (\'\'\'\'%fn_cdc_get_net_changes_application_data%\'\'\'\')   AND NOT (OBJECT_SCHEMA_NAME(MAJOR_iD) = \'\'\'\'cdc\'\'\'\' and PERMiSSiON_NAME=\'\'\'\'SELECT\'\'\'\')   AND NOT (PERMiSSiON_NAME IN (\'\'\'\'REFERENCES\'\'\'\',\'\'\'\'SEND\'\'\'\',   \'\'\'\'VIEW ANY COLUMN ENCRYPTION KEY DEFINITION\'\'\'\',   \'\'\'\'VIEW ANY COLUMN MASTER KEY DEFINITION\'\'\'\' ) and OBJECT_SCHEMA_NAME(MAJOR_iD) IS NULL)   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select * from #TEMP;   \'','There are no permissions which are assigned to public.\r\n','There are some persmissions which are assigned to public\r\n','pass',NULL,NULL,'2026-01-25 11:34:23'),(1387,202601,46,28,'AA_SqlServer_220_Public Database Permissions','critical','PRIV','This test checks database permisions for public . Public is a special role and permissions should not be granted to public role.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      exec sp_msforeachdb \'\'   USE [?]     iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'public\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND OBJECT_NAME(MAJOR_iD) NOT LiKE (\'\'\'\'%fn_cdc_get_net_changes_application_data%\'\'\'\')   AND NOT (OBJECT_SCHEMA_NAME(MAJOR_iD) = \'\'\'\'cdc\'\'\'\' and PERMiSSiON_NAME=\'\'\'\'SELECT\'\'\'\')   AND NOT (PERMiSSiON_NAME IN (\'\'\'\'REFERENCES\'\'\'\',\'\'\'\'SEND\'\'\'\',   \'\'\'\'VIEW ANY COLUMN ENCRYPTION KEY DEFINITION\'\'\'\',   \'\'\'\'VIEW ANY COLUMN MASTER KEY DEFINITION\'\'\'\' ) and OBJECT_SCHEMA_NAME(MAJOR_iD) IS NULL)   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select count(*) from #TEMP;   \' \r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      exec sp_msforeachdb \'\'   USE [?]     iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'public\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND OBJECT_NAME(MAJOR_iD) NOT LiKE (\'\'\'\'%fn_cdc_get_net_changes_application_data%\'\'\'\')   AND NOT (OBJECT_SCHEMA_NAME(MAJOR_iD) = \'\'\'\'cdc\'\'\'\' and PERMiSSiON_NAME=\'\'\'\'SELECT\'\'\'\')   AND NOT (PERMiSSiON_NAME IN (\'\'\'\'REFERENCES\'\'\'\',\'\'\'\'SEND\'\'\'\',   \'\'\'\'VIEW ANY COLUMN ENCRYPTION KEY DEFINITION\'\'\'\',   \'\'\'\'VIEW ANY COLUMN MASTER KEY DEFINITION\'\'\'\' ) and OBJECT_SCHEMA_NAME(MAJOR_iD) IS NULL)   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select * from #TEMP;   \' \r\n','There are no permissions which are assigned to public.\r\n','There are some persmissions which are assigned to public\r\n','pass',NULL,NULL,'2026-01-25 11:34:23'),(1388,202601,46,29,'AA_SqlServer_230_Real person users','critical','ACCOUNT','All logins to the database should be made with AD groups, real person users should  not be connected database directly\r\n','','Select      count(*)   from      sys.server_principals    where      name like \'ODEABANK%.%\'      and is_disabled = 0   \r\n','== 0','','Select      name     from      sys.server_principals    where      name like \'ODEABANK%.%\'      and is_disabled = 0;\r\n','Real person users are not found in the logins\r\n','Some real person users are found in the logins\r\n','pass',NULL,NULL,'2026-01-25 11:34:23'),(1389,202601,46,30,'AA_SqlServer_240_2_guest Database Permissions','critical','ACCOUNT','This test checks database permisions for guest . guest is a special user and permissions should not be granted to guest user.\r\n','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP ( row varchar(500));\r\n\r\nexec sp_MSforeachdb \'\'\r\nUSE [?]\r\niNSERT iNTO #TEMP\r\nSELECT\r\n\'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +\r\n\'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +\r\n\'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +\r\n\'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )\r\nFROM\r\nsys.database_permissions\r\nWHERE\r\nUSER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'guest\'\'\'\' )\r\nAND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'\r\nAND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')\r\nAND STATE_DESC=\'\'\'\'GRANT\'\'\'\'\r\n;\r\n\'\'\r\nselect count(*) from #TEMP;\r\n\'','== 0','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP ( row varchar(500));\r\n\r\nexec sp_MSforeachdb \'\'\r\nUSE [?]\r\niNSERT iNTO #TEMP\r\nSELECT\r\n\'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +\r\n\'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +\r\n\'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +\r\n\'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )\r\nFROM\r\nsys.database_permissions\r\nWHERE\r\nUSER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'guest\'\'\'\' )\r\nAND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'\r\nAND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')\r\nAND STATE_DESC=\'\'\'\'GRANT\'\'\'\'\r\n;\r\n\'\'\r\nselect * from #TEMP;\r\n\'','There are no permissions which are assigned to guest.\r\n','There are some persmissions which are assigned to guest\r\n','pass',NULL,NULL,'2026-01-25 11:34:23'),(1390,202601,46,31,'AA_SqlServer_240_guest Database Permissions','critical','PRIV','This test checks database permisions for guest . guest is a special user and permissions should not be granted to guest user.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      exec sp_msforeachdb \'\'   USE [?]     iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'guest\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select count(*) from #TEMP;   \' \r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      exec sp_msforeachdb \'\'   USE [?]     iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'guest\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select  *  from #TEMP;   \' \r\n','There are no permissions which are assigned to guest.\r\n','There are some persmissions which are assigned to guest\r\n','pass',NULL,NULL,'2026-01-25 11:34:23'),(1391,202601,46,32,'AA_SqlServer_250_Database Role members for guest','critical','PRIV','This test checks database role members for guest  user. Database roles  could not be assigned to guest role.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      EXEC sp_MSforeachdb \'\' USE [?]    INSERT INTO #TEMP   SELECT \'\'\'\'DB Name : \'\'\'\'+Cast (DB_NAME() as varchar)+\'\'\'\' Role Name : \'\'\'\'+USER_NAME(role_principal_id)  +\'\'\'\' User Name \'\'\'\'+  USER_NAME(member_principal_id)    from  sys.database_role_members   	Where     USER_NAME(member_principal_id)  = \'\'\'\'guest\'\'\'\'     ;   \'\'      Select count(*)  from #TEMP;   \'\r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      EXEC sp_MSforeachdb \'\' USE [?]    INSERT INTO #TEMP   SELECT \'\'\'\'DB Name : \'\'\'\'+Cast (DB_NAME() as varchar)+\'\'\'\' Role Name : \'\'\'\'+USER_NAME(role_principal_id)  +\'\'\'\' User Name \'\'\'\'+  USER_NAME(member_principal_id)    from  sys.database_role_members   	Where     USER_NAME(member_principal_id)  = \'\'\'\'guest\'\'\'\'     ;   \'\'      Select  *  from #TEMP;   \'\r\n','Database role member usage for guest user  is correct\r\n','Database role member usage for guest user  is not correct\r\n','pass',NULL,NULL,'2026-01-25 11:34:23'),(1392,202601,46,33,'AA_SqlServer_260_SQL Logins with Null Password','critical','ACCOUNT','This test checks sql logins with null password. SQL Logins should not have null passwords.\r\n','','SELECT      count(name)   from      sys.sql_logins    WHERE      PWDCOMPARE(\'\', password_hash)= 1\r\n','== 0','','SELECT      name    from      sys.sql_logins    WHERE      PWDCOMPARE(\'\', password_hash)= 1   \r\n','There are no sql logins with null paswords\r\n','There are some sql logins with null passwords.\r\n','pass',NULL,NULL,'2026-01-25 11:34:23'),(1393,202601,46,34,'AA_SqlServer_270_SQL Logins with username and passwords are equal','critical','ACCOUNT','This test checks sql login password which are egual to username. Username and password must be different for SQL logins.\r\n','','SELECT      count(name)   from      sys.sql_logins    WHERE      PWDCOMPARE(name,password_hash)=1 \r\n','== 0','','SELECT      name    from      sys.sql_logins    WHERE      PWDCOMPARE(name,password_hash)=1    \r\n','There is no SQL login name which is equal to password.\r\n','There are some sql logins whose passwords are egual to usernames.\r\n','pass',NULL,NULL,'2026-01-25 11:34:23'),(1394,202601,46,35,'AA_SqlServer_280_No Sample Databases','critical','CONFIG','This test checks whether the sample databases created optionally on installation are present.  These sample databases contain many default permissions, and can be used as an entry point to your systems. \r\n','','select      count(name)    from      sys.databases    where      name in (       \'AdventureWorks\', \'AdventureWorksDW\',        \'Northwind\', \'Pubs\'     )   \r\n','== 0','','select      name    from      sys.databases    where      name in (       \'AdventureWorks\', \'AdventureWorksDW\',        \'Northwind\', \'Pubs\'     )   \r\n','There are no sample databases in the server\r\n','There are some sample databases in the server\r\n','pass',NULL,NULL,'2026-01-25 11:34:24'),(1395,202601,46,43,'AA_SqlServer_350_User Password Policy Is Checked','critical','ACCOUNT','This test checks that CHECK_POLICY is enabled for all users.  Enabling CHECK_POLICY ensures that Windows passwords policies are enforced.','','select count(*) from sys.sql_logins  \r\nwhere \r\nis_policy_checked=0 and\r\nname not like \'##%\'','== 0','','select name from sys.sql_logins  \r\nwhere \r\nis_policy_checked=0 and\r\nname not like \'##%\'','CHECK_POLICY is enabled for all users','CHECK_POLICY is not enabled for all users','pass',NULL,NULL,'2026-01-25 11:34:24'),(1396,202601,46,44,'AA_SqlServer_360_CHECK_EXPIRATION Is Checked','critical','ACCOUNT','This test checks that CHECK_EXPIRATION is enabled for all users.  Passwords that have been in use for long periods of time are likely to become known to unauthorized users.\r\n','','select count(*) from sys.sql_logins     where    is_expiration_checked=0 and   name not like \'##%\'\r\n','== 0','','select name from sys.sql_logins     where    is_expiration_checked=0 and   name not like \'##%\'\r\n','CHECK_EXPIRATION is enabled for all users\r\n','CHECK_EXPIRATION is not enabled for all users\r\n','fail','name\n----\n\'sa\'',NULL,'2026-01-25 11:34:24'),(1397,202601,46,22,'AA_SqlServer_170_Windows Authentication','major','AUTH','This test checks that the authentication mode is set to Windows authentication only.  Windows provides a more robust authentication mechanism than SQL Server authentication.','',' SELECT cast( SERVERPROPERTY(\'IsIntegratedSecurityOnly\') as int) ','==1','','SELECT cast( SERVERPROPERTY(\'IsIntegratedSecurityOnly\') as varchar)','The authentication mode is set to Windows authentication only. ','The authentication mode is not set to Windows authentication only.','fail','\n---\n\'0\'',NULL,'2026-01-25 11:34:24'),(1398,202601,46,23,'AA_SqlServer_180_No Guest User Accounts','major','ACCOUNT','This test checks for the existence of guest user accounts with CONNECT permission in database other than master, msdb and tempdb.  This test also exclude databases that are flagged as distributor. If the GUEST user exists and a specific login has not been granted to a database, a login will be mapped to GUEST. The presence of the GUEST user allows all logins to access the database.\r\n','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP  ( row int);\r\n\r\nEXEC sp_MSforeachdb \'\' USE [?]\r\n	INSERT INTO #TEMP\r\n	SELECT count(*) \r\n	FROM sys.database_permissions\r\n	WHERE [grantee_principal_id] = DATABASE_PRINCIPAL_ID(\'\'\'\'guest\'\'\'\')\r\n	AND [state_desc] LIKE \'\'\'\'GRANT%\'\'\'\'\r\n	AND [permission_name] = \'\'\'\'CONNECT\'\'\'\'\r\n	AND DB_NAME() NOT IN (\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'msdb\'\'\'\') ;\r\n\'\'\r\n\r\nSelect sum(row) from #TEMP;\r\ndrop table #TEMP;\r\n\'','== 0','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP  ( row varchar(500));\r\n\r\nEXEC sp_MSforeachdb \'\' USE  [?] \r\n	INSERT INTO #TEMP\r\n	SELECT \'\'\'\' DB NAME : \'\'\'\' + Cast (DB_NAME() as varchar) + \'\'\'\' guest user has CONNECT permission \'\'\'\'\r\n	FROM sys.database_permissions\r\n	WHERE [grantee_principal_id] = DATABASE_PRINCIPAL_ID(\'\'\'\'guest\'\'\'\')\r\n	AND [state_desc] LIKE \'\'\'\'GRANT%\'\'\'\'\r\n	AND [permission_name] = \'\'\'\'CONNECT\'\'\'\'\r\n	AND DB_NAME() NOT IN (\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'msdb\'\'\'\') ;\r\n\'\'\r\n\r\nSelect * from #TEMP;\r\ndrop table #TEMP;\r\n\'','There is no guest user with CONNECT permission. ','There are   guest users with CONNECT permission. Remove these users','pass',NULL,NULL,'2026-01-25 11:34:24'),(1399,202601,46,36,'AA_SqlServer_290_2_No Permissions with GRANT Option','major','PRIV','This test checks database permisions  with grant option. No permission with grant option should be defined in the database.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP ( row varchar(500));      exec sp_MSforeachdb \'\'   USE [?]   iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   STATE_DESC like \'\'\'\'%WITH_GRANT%\'\'\'\'   ;   \'\'   select count(*) from #TEMP;   \'\r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP ( row varchar(500));      exec sp_MSforeachdb \'\'   USE [?]   iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   STATE_DESC like \'\'\'\'%WITH_GRANT%\'\'\'\'   ;   \'\'   select * from #TEMP;   \'\r\n','There are no permissions with grant option.\r\n','There are some persmissions  with grant option.\r\n','pass',NULL,NULL,'2026-01-25 11:34:24'),(1400,202601,46,37,'AA_SqlServer_290_No Permissions with GRANT Option','major','PRIV','','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP  ( row varchar(500));\r\n\r\nexec sp_msforeachdb \'\'\r\nUSE [?]  \r\niNSERT iNTO #TEMP\r\nSELECT\r\n\'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +\r\n\'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +\r\n\'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +\r\n\'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )\r\nFROM\r\nsys.database_permissions\r\nWHERE\r\nSTATE_DESC like \'\'\'\'%WITH_GRANT%\'\'\'\'\r\n;\r\n\'\'\r\nselect  count(*)  from #TEMP;\r\n\' ','== 0','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP  ( row varchar(500));\r\n\r\nexec sp_msforeachdb \'\'\r\nUSE [?]  \r\niNSERT iNTO #TEMP\r\nSELECT\r\n\'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +\r\n\'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +\r\n\'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +\r\n\'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )\r\nFROM\r\nsys.database_permissions\r\nWHERE\r\nSTATE_DESC like \'\'\'\'%WITH_GRANT%\'\'\'\'\r\n;\r\n\'\'\r\nselect * from #TEMP;\r\n\' ','There are no permissions with grant option.\r\n','There are some persmissions  with grant option.\r\n','pass',NULL,NULL,'2026-01-25 11:34:24'),(1401,202601,46,40,'AA_SqlServer_320_No Access to Registry Access Extended procedures','major','PRIV','This test checks for the existence of, and user permissions on, registry access extended stored procedures.  Either these procedures should be completely dropped, or access to them should be strictly limited. xp_reg%,xp_instance_reg%\r\n','','SELECT \r\ncount(*) \r\nFROM \r\n  [master].sys.system_objects o \r\n  JOIN [master].sys.database_permissions p ON o.object_id = p.major_id \r\n  JOIN [master].sys.database_principals u ON p.grantee_principal_id = u.principal_id \r\nWHERE \r\n( o.name LIKE \'xp_reg%\' OR o.name LIKE \'xp_instance_reg%\')\r\n  AND p.type = \'EX\' ','== 0','','SELECT \r\n  \'Principal : \'+u.name  COLLATE DATABASE_DEFAULT +\r\n  \' Extended Procedure Name : \'+o.name COLLATE DATABASE_DEFAULT +\r\n  \' Type : \'+ u.type_desc COLLATE DATABASE_DEFAULT \r\nFROM \r\n  [master].sys.system_objects o \r\n  JOIN [master].sys.database_permissions p ON o.object_id = p.major_id \r\n  JOIN [master].sys.database_principals u ON p.grantee_principal_id = u.principal_id \r\nWHERE \r\n( o.name LIKE \'xp_reg%\' OR o.name LIKE \'xp_instance_reg%\')\r\n  AND p.type = \'EX\' ','There are no permissions on registry access extended stored procedures\r\n','There are some persmissions permissions on registry access extended stored procedures\r\n','fail','\n---------------------------------------------------------------------------------------\n\'Principal : public Extended Procedure Name : xp_instance_regread Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_regread Type : DATABASE_ROLE\'',NULL,'2026-01-25 11:34:24'),(1402,202601,46,41,'AA_SqlServer_330_Revoke public login from SQL Server agent proxy account','major','PRIV','The public database role contains every user in the msdb database. SQL Agent proxies   define a security context in which a job step can run.Granting access to SQL Agent proxies for the public role would allow all users to utilize the proxy which may have high privileges. This would likely break the principle of least   privileges.\r\n','','SELECT count(*)\r\nFROM msdb.dbo.sysproxylogin spl\r\nJOIN sys.database_principals dp\r\nON dp.sid = spl.sid\r\nJOIN msdb.dbo.sysproxies sp\r\nON sp.proxy_id = spl.proxy_id\r\nWHERE principal_id = USER_ID(\'public\')','== 0','','SELECT \'proxyname : \'+CAST(sp.name  as varchar)\r\nFROM msdb.dbo.sysproxylogin spl\r\nJOIN sys.database_principals dp\r\nON dp.sid = spl.sid\r\nJOIN msdb.dbo.sysproxies sp\r\nON sp.proxy_id = spl.proxy_id\r\nWHERE principal_id = USER_ID(\'public\')','There are no public permissions on SQL Server agent proxy account\r\n','There are some public permissions on SQL Server agent proxy account\r\n','pass',NULL,NULL,'2026-01-25 11:34:24'),(1403,202601,46,42,'AA_SqlServer_340_No Individual User Access To syscomment and sp_helptext','minor','PRIV','This test checks for grants on SYSCOMMENTS.TEXT.  Such grants allow any user to read the text comments associated with a database object, making the text publicly viewable.\r\n','','SELECT count(*)\r\nFROM msdb.dbo.sysproxylogin spl\r\nJOIN sys.database_principals dp\r\nON dp.sid = spl.sid\r\nJOIN msdb.dbo.sysproxies sp\r\nON sp.proxy_id = spl.proxy_id\r\nWHERE principal_id = USER_ID(\'public\')\r\n','== 0','','SELECT count(*)\r\nFROM msdb.dbo.sysproxylogin spl\r\nJOIN sys.database_principals dp\r\nON dp.sid = spl.sid\r\nJOIN msdb.dbo.sysproxies sp\r\nON sp.proxy_id = spl.proxy_id\r\nWHERE principal_id = USER_ID(\'public\')','There are no public permissions on SQL Server agent proxy account','There are some public permissions on SQL Server agent proxy account','pass',NULL,NULL,'2026-01-25 11:34:24'),(1404,202601,46,10,'AA_SqlServer_050_Disable Ad hoc distributed queries option','major','CONFIG','Adhoc queries allow undefined access to remote database sources.  Access to untrusted databases could result in execution of malicious applications and/or a compromise of local data confidentiality and integrity. The DBA will configure the database to disable access from the database to objects stored externally to the database on the local host unless mission and/or operationally required and documented.\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Ad Hoc Distributed Queries\'','== 0','','SELECT name + \' Value : \'+ cast( value as varchar ) + \' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'Ad Hoc Distributed Queries\'','Ad Hoc Distributed Queries is disabled','Ad Hoc Distributed Queries is not disabled. Disable this option','pass',NULL,NULL,'2026-01-25 11:34:24'),(1405,202601,46,11,'AA_SqlServer_060_Disable CLR option','major','CONFIG','The clr_enabled parameter configures SQL Server to allow or disallow use of Command Language Runtime objects.  CLR objects is managed code that integrates with the .NET Framework.  This is a more secure method than external stored procedures, although it still contains some risk.  Where no external application execution requirements are required, disallowing use of any improves the overall security posture of the database.\r\n\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'clr enabled\'','== 0','','SELECT name + \' Value : \'+ cast( value as varchar ) + \' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'clr enabled\'','CLR option is disabled','CLR option is not disabled. Disable this option','pass',NULL,NULL,'2026-01-25 11:34:24'),(1406,202601,46,12,'AA_SqlServer_070_Disable Cross db ownership chaining option','major','CONFIG','Cross database ownership chaining allows permissions to objects to be assigned by users other than the Information Owner.  This allows access to objects that are not authorized directly by the Information Owner based on job functions defined by the owner.  Unauthorized access may lead to a compromise of data integrity or confidentiality. The DBA will ensure database privileges are assigned via roles and not directly assigned to database accounts. Privileges may be assigned directly to application owner accounts where the DBMS does not otherwise support access via roles.\r\n\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'cross db ownership chaining\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'cross db ownership chaining\'','Cross db ownership chaining  option is disabled','Cross db ownership chaining option  is not disabled. Disable this option','pass',NULL,NULL,'2026-01-25 11:34:24'),(1407,202601,46,13,'AA_SqlServer_080_Disable Database Mail XPs option','major','CONFIG','SQL Mail accepts incoming database commands via email. This can introduce malicious codes or viruses into the SQL server environment.','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Database Mail XPs\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \'Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'Database Mail XPs\'','Database Mail XPs option is disabled','Database Mail XPs option  is not disabled. Disable this option','pass',NULL,NULL,'2026-01-25 11:34:24'),(1408,202601,46,14,'AA_SqlServer_100_Disable xp_cmdshell Server Configuration option','major','CONFIG','The xp_cmdshell extended stored procedures allows execution of host executables outside the controls of database access permissions.  This access may be exploited by malicious users who have compromised the integrity of the SQL Server database process to control the host operating system to perpetrate additional malicious activity. The DBA should disable the use of external procedures by the database unless it is mission critical or operationally required','','SELECT CAST(value as int) +\r\n       CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'xp_cmdshell\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) +\r\n\' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'xp_cmdshell\'','xp_cmdshell Server Configuration option is disabled','xp_cmdshell Server Configuration option is not disabled. This option must be disabled','pass',NULL,NULL,'2026-01-25 11:34:24'),(1409,202601,46,15,'AA_SqlServer_110_Disable Remote Access option','major','CONFIG','The remote access option controls the execution of local stored procedures on remote\r\nservers or remote stored procedures on local server.Functionality can be abused to launch a Denial-of-Service (DoS) attack on remote servers\r\nby off-loading query processing to a target.\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'remote access\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \' Value in use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'remote access\'','Remote Access option is disabled','Remote Access option  is not disabled. Disable this option','fail','\n------------------------------------------\n\'remote access Value : 1 Value in use : 1\'',NULL,'2026-01-25 11:34:24'),(1410,202601,46,16,'AA_SqlServer_120_Disable Remote Admin Connections option','major','CONFIG','The remote admin connections option controls whether a client application on a remote\r\ncomputer can use the Dedicated Administrator Connection (DAC).The Dedicated Administrator Connection (DAC) lets an administrator access a running\r\nserver to execute diagnostic functions or Transact-SQL statements, or to troubleshoot\r\nproblems on the server, even when the server is locked or running in an abnormal state\r\nand not responding to a SQL Server Database Engine connection. In a cluster scenario, the\r\nadministrator may not actually be logged on to the same node that is currently hosting the\r\nSQL Server instance and thus is considered \"remote\". Therefore, this setting should usually\r\nbe enabled (1) for SQL Server failover clusters; otherwise it should be disabled (0) which is\r\nthe default.\r\n','','execute sp_executesql N\'\r\n\r\nDECLARE @x int;\r\n\r\nSELECT @x=isnull(CAST(value as int) + CAST(value_in_use as int),100)\r\nFROM sys.configurations\r\nWHERE name = \'\'remote admin connections\'\'\r\n\r\nIF @x = 100\r\n       SELECT 0 ;\r\nELSE \r\n   SELECT CAST(value as int) + CAST(value_in_use as int) \r\n   FROM sys.configurations\r\n   WHERE name = \'\'remote admin connections\'\'\r\n\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'remote admin connections\'','Remote Admin Connections option is disabled','Remote Admin Connections option  is not disabled. Disable this option','pass',NULL,NULL,'2026-01-25 11:34:24'),(1411,202601,46,19,'AA_SqlServer_150_Disable database trustworthy status','major','CONFIG','The TRUSTWORTHY database setting restricts access to database resources by databases that contain assemblies with the EXTERNAL_ACCESS or UNSAFE permission settings and modules that use impersonation of accounts assigned elevated privileges.  Unless all assemblies and code for the database have been reviewed, especially in the case where databases have been detached and attached between server instances, leaving the TRUSTWORTHY status to off can help reduce threats from malicious assemblies or modules.','','SELECT count(name)\r\nFROM sys.databases\r\nWHERE is_trustworthy_on = 1\r\nAND name != \'msdb\';','== 0','','SELECT name\r\nFROM sys.databases\r\nWHERE is_trustworthy_on = 1\r\nAND name != \'msdb\';','database trustworthy status is disabled','database trustworthy status is not disabled. Disable this option','pass',NULL,NULL,'2026-01-25 11:34:24'),(1412,202601,46,20,'Checkpoint başarıyla oluşturuldu.','major','CONFIG','This test checks if SQL Server Instance is not advertised by the SQL Server Browser service. To maintain a higher level of protection for database instances, we recommend that SQL Server Instance be hidden when it is not required. Please note that this test does not include Clustered Instances as turning off this feature may cause issues with the Clustered environment.\r\n\r\n','','execute sp_executesql N\'\r\n\r\nDECLARE @getValue INT\r\n\r\nEXEC master.sys.xp_instance_regread\r\n@rootkey = N\'\'HKEY_LOCAL_MACHINE\'\',\r\n@key = N\'\'SOFTWARE\\Microsoft\\Microsoft SQL Server\\MSSQLServer\\SuperSocketNetLib\'\',\r\n@value_name = N\'\'HideInstance\'\',\r\n@value = @getValue OUTPUT\r\n\r\nSELECT isnull(@getvalue,0)\'','==1','','execute sp_executesql N\'\r\n\r\nDECLARE @getValue INT\r\n\r\nEXEC master.sys.xp_instance_regread\r\n@rootkey = N\'\'HKEY_LOCAL_MACHINE\'\',\r\n@key = N\'\'SOFTWARE\\Microsoft\\Microsoft SQL Server\\MSSQLServer\\SuperSocketNetLib\'\',\r\n@value_name = N\'\'HideInstance\'\',\r\n@value = @getValue OUTPUT\r\n\r\nSELECT isnull(@getvalue,0)\'','SQL Server Instance is  hidden.\r\n','SQL Server Instance is not hidden. Hide the instance','fail','\n-\n0',NULL,'2026-01-25 11:34:25'),(1413,202601,46,21,'AA_SqlServer_160_Hide SQL Server Instance','major','CONFIG','This test checks if SQL Server Instance is not advertised by the SQL Server Browser service. To maintain a higher level of protection for database instances, we recommend that SQL Server Instance be hidden when it is not required. Please note that this test does not include Clustered Instances as turning off this feature may cause issues with the Clustered environment.\r\n\r\n','','execute sp_executesql N\'\r\n\r\nDECLARE @getValue INT\r\n\r\nEXEC master.sys.xp_instance_regread\r\n@rootkey = N\'\'HKEY_LOCAL_MACHINE\'\',\r\n@key = N\'\'SOFTWARE\\Microsoft\\Microsoft SQL Server\\MSSQLServer\\SuperSocketNetLib\'\',\r\n@value_name = N\'\'HideInstance\'\',\r\n@value = @getValue OUTPUT\r\n\r\nSELECT isnull(@getvalue,0)\'','==1','','execute sp_executesql N\'\r\n\r\nDECLARE @getValue INT\r\n\r\nEXEC master.sys.xp_instance_regread\r\n@rootkey = N\'\'HKEY_LOCAL_MACHINE\'\',\r\n@key = N\'\'SOFTWARE\\Microsoft\\Microsoft SQL Server\\MSSQLServer\\SuperSocketNetLib\'\',\r\n@value_name = N\'\'HideInstance\'\',\r\n@value = @getValue OUTPUT\r\n\r\nSELECT isnull(@getvalue,0)\'','SQL Server Instance is  hidden.','SQL Server Instance is not hidden. Hide the instance','fail','\n-\n0',NULL,'2026-01-25 11:34:25'),(1414,202601,46,38,'AA_SqlServer_300_No Access To General Extended procedures','major','PRIV','This test checks for the existence of, and user permissions on, extended stored procedures.  Either these procedures should be completely dropped, or access to them should be strictly limited. xp_cmdshell, xp_enumgroups, xp_grantlogin ,xp_logevent, xp_logininfo,    xp_msver, xp_revokelogin, xp_sprintf, xp_sqlmaint, xp_sscanf\r\n','','SELECT \r\ncount(*) \r\nFROM \r\n  [master].sys.system_objects o \r\n  JOIN [master].sys.database_permissions p ON o.object_id = p.major_id \r\n  JOIN [master].sys.database_principals u ON p.grantee_principal_id = u.principal_id \r\nWHERE \r\n    o.name in ( \r\n	\'xp_cmdshell\', \r\n	\'xp_enumgroups\', \r\n    \'xp_grantlogin\' ,\r\n	\'xp_logevent\', \r\n	\'xp_logininfo\', \r\n    \'xp_msver\', \r\n	\'xp_revokelogin\', \r\n	\'xp_sprintf\', \r\n    \'xp_sqlmaint\', \r\n	\'xp_sscanf\' )\r\n  AND p.type = \'EX\' ','== 0','','SELECT \r\n  \'Principal : \'+u.name  COLLATE DATABASE_DEFAULT +\r\n  \' Extended Procedure Name : \'+o.name COLLATE DATABASE_DEFAULT +\r\n  \' Type : \'+ u.type_desc COLLATE DATABASE_DEFAULT \r\nFROM \r\n  [master].sys.system_objects o \r\n  JOIN [master].sys.database_permissions p ON o.object_id = p.major_id \r\n  JOIN [master].sys.database_principals u ON p.grantee_principal_id = u.principal_id \r\nWHERE \r\n    o.name in ( \r\n	\'xp_cmdshell\', \r\n	\'xp_enumgroups\', \r\n    \'xp_grantlogin\' ,\r\n	\'xp_logevent\', \r\n	\'xp_logininfo\', \r\n    \'xp_msver\', \r\n	\'xp_revokelogin\', \r\n	\'xp_sprintf\', \r\n    \'xp_sqlmaint\', \r\n	\'xp_sscanf\' )\r\n  AND p.type = \'EX\' ','There are no permissions on general extended stored procedures\r\n','There are some persmissions permissions on general extended stored procedures.\r\n','fail','\n----------------------------------------------------------------------------------\n\'Principal : public Extended Procedure Name : xp_msver Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_sscanf Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_revokelogin Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_grantlogin Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_sprintf Type : DATABASE_ROLE\'',NULL,'2026-01-25 11:34:25'),(1415,202601,46,39,'AA_SqlServer_310_No Access to OLE Automation procedures','major','CONFIG','This test checks for the existence of,and user permissions on OLE automation extended stored procedures.  Either these procedures should be completely dropped, or access to them should be strictly limited.      \r\n','','SELECT CAST(value as int) +\r\n       CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Ole Automation Procedures\'   \r\n','== 0','','SELECT CAST(value as int) +\r\n       CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Ole Automation Procedures\'\r\n  \r\n','OLE Automation procedures  option is disabled\r\n','OLE Automation procedures  option  is not disabled. Disable this option\r\n','pass',NULL,NULL,'2026-01-25 11:34:25'),(1416,202601,46,17,'AA_SqlServer_130_Disable Ole Automation Procedures option','minor','CONFIG','This test checks if Ole Automation Procedures option is disabled. Ole Automation Procedures option allows SQL Server users to execute functions external to SQL Server. Enabling this option will increase the attack surface of SQL Server and allow users to execute functions in the security context of SQL Server. We recommend that the Ole Automation Procedures option to be disabled when it is not document as a requirement.\r\n\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Ole Automation Procedures\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \'Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'Ole Automation Procedures\'',' Ole Automation Procedures option is disabled',' Ole Automation Procedures option  is not disabled. Disable this option','pass',NULL,NULL,'2026-01-25 11:34:25'),(1417,202601,46,18,'AA_SqlServer_140_Disable Scan for Startup Procedures option','minor','CONFIG','This test checks if scan for startup procedures is disabled. This feature causes SQL Server to scan for and automatically run all stored procedures that are set to execute upon service startup. If there are no user-defined stored procedures set to execute when SQL server starts, we recommend this feature to be disabled.\r\n\r\n','','SELECT CAST(value as int) +\r\n       CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'scan for startup procs\'','== 0','','SELECT name + \' value : \'+cast( value as varchar ) +\r\n\' value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'scan for startup procs\'','Scan for Startup Procedures  option is disabled','Scan for Startup Procedures  option  is not disabled. Disable this option','pass',NULL,NULL,'2026-01-25 11:34:25'),(1418,202601,46,9,'AA_SqlServer_040_Rename the sa Login Account','major','ACCOUNT','The \'sa\' account is a well-known account.  Well-known account names provide an easier target for attack.  Renaming the sa account helps reduce the risk of an attack to this built-in account.','','SELECT count(*)\r\nFROM sys.server_principals\r\nWHERE sid = 0x01 and name=\'sa\'','== 0','','SELECT name\r\nFROM sys.server_principals\r\nWHERE sid = 0x01','sa Login Account is renamed','sa Login Account is not renamed. Rename this account','fail','name\n----\n\'sa\'',NULL,'2026-01-25 11:34:25'),(1419,202601,47,24,'AA_SqlServer_190_Public server role permision','critical','PRIV','public is a special fixed server role containing all logins. Unlike other fixed server roles,\r\npermissions can be changed for the public role. In keeping with the principle of least\r\nprivileges, the public server role should not be used to grant permissions at the server\r\nscope as these would be inherited by all users.\r\n\r\nEvery SQL Server login belongs to the public role and cannot be removed from this role.\r\nTherefore, any permissions granted to this role will be available to all logins unless they\r\nhave been explicitly denied to specific logins or user-defined server roles.','','Select \r\n  count (permission_name) \r\nfrom \r\n  sys.server_permissions \r\nwhere \r\n  SUSER_NAME(grantee_principal_id) = \'public\' \r\n  and permission_name not in (\'VIEW ANY DATABASE\', \'CONNECT\')\r\n','== 0','','Select \r\n  permission_name \r\nfrom \r\n  sys.server_permissions \r\nwhere \r\n  SUSER_NAME(grantee_principal_id) = \'public\' \r\n  and permission_name not in (\'VIEW ANY DATABASE\', \'CONNECT\')\r\n\r\n','No server permissions are granted to public.','Some server permissions are granted to public.','pass',NULL,NULL,'2026-01-25 11:34:25'),(1420,202601,47,5,'AA_SqlServer_010_Supported SQL Server version','critical','PATCH','This test checks whether your current SQL Server version is a vendor-supported version.  Microsoft does not provide security fixes or software updates to unsupported software versions','','SELECT cast(ISNULL(SERVERPROPERTY(\'ProductMajorVersion\'),0) as int)   ','>=11','','SELECT \'Product Major version \' +  cast(ISNULL(SERVERPROPERTY(\'ProductMajorVersion\'),\'Null\' ) as  char ) ','The version of the database is acceptable.','The version of the database is not acceptable. The database version should SQL Sever 2012 or upper.','pass',NULL,NULL,'2026-01-25 11:34:25'),(1421,202601,47,6,'AA_SqlServer_020_Disable the sa Login Account','critical','ACCOUNT','This test checks if the \'sa\' Login Account is disabled. The sa account is a widely known and often widely used SQL Server account with sysadmin privileges. Enforcing this control reduces the probability of an attacker executing brute force attacks against a well-known principal.','','SELECT  count(*)\r\nFROM sys.server_principals\r\nWHERE sid = 0x01\r\nAND is_disabled = 0','== 0','','SELECT \'sa user name : \'+ name+\' is disabled : \' +  cast( is_disabled as char)\r\nFROM sys.server_principals\r\nWHERE sid = 0x01\r\n','sa Login Account is disabled','Disable sa login account','fail','\n----------------------------------------------------------------\n\'sa user name : sa is disabled : 0                             \'',NULL,'2026-01-25 11:34:25'),(1422,202601,47,7,'AA_SqlServer_025_sa Change password','critical','ACCOUNT','This test checks that sa password change . The sa password should be changed in every two days','','select datediff( day,  modify_date , getdate() ) FROM sys.server_principals\r\nWHERE sid = 0x01  ','< 3','','select datediff( day,  modify_date , getdate() ) FROM sys.server_principals\r\nWHERE sid = 0x01 ','sa password was changed in two days','','fail','\n--\n11',NULL,'2026-01-25 11:34:25'),(1423,202601,47,8,'AA_SqlServer_030_Ensure no Login exists with sa Login Account','critical','ACCOUNT','The \'sa\' account is a well-known account.  Well-known account names provide an easier target for attack. The lack of the sa account helps reduce the risk of an attack to this built-in account.','','SELECT count(*)\r\nFROM sys.server_principals\r\nWHERE name = \'sa\'','== 0','','SELECT name\r\nFROM sys.server_principals\r\nWHERE name = \'sa\'','There is no the sa account in the database.','There is the sa Login account in the database.Drop this user or rename et.','fail','name\n----\n\'sa\'',NULL,'2026-01-25 11:34:25'),(1424,202601,47,25,'AA_SqlServer_200_Fixed Server Role members for users','critical','PRIV','This test checks fixed server roles for analyst , developers and real persons. Fixed server roles could not be assigned to real person users ( Developer, Analyst users ) . Only Admin can use fixed server role.\r\n','','Select     count(*)   from      sys.server_role_members    where      (       suser_name(member_principal_id) like \'ODEABANK%.%\'    	AND       suser_name(member_principal_id) not like \'%admin%\'         AND       suser_name(member_principal_id) not like \'%t.coban%\'     )      OR (       suser_name(member_principal_id) like \'ODEABANK\\Cyberark_Intertech%\'     )      \r\n','== 0','','Select      suser_name(role_principal_id) + \'   \' + suser_name(member_principal_id)    from      sys.server_role_members    where      (       suser_name(member_principal_id) like \'ODEABANK%.%\'    	AND       suser_name(member_principal_id) not like \'%admin%\'         AND       suser_name(member_principal_id) not like \'%t.coban%\'     )      OR (       suser_name(member_principal_id) like \'ODEABANK\\Cyberark_Intertech%\'     )          \r\n','Fixed Server role usage is correct.\r\n','Fixed Server role usage is not correct.\r\n','pass',NULL,NULL,'2026-01-25 11:34:25'),(1425,202601,47,26,'AA_SqlServer_210_Database Role members for users','critical','PRIV','This test checks database role members for analyst and real person users. Database roles  except  db_datareader could not be assigned to real person users ( Developer, Analyst users ) .\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      EXEC sp_MSforeachdb \'\' USE [?]    INSERT INTO #TEMP   SELECT \'\'\'\'DB Name : \'\'\'\'+Cast (DB_NAME() as varchar)+\'\'\'\' Role Name : \'\'\'\'+USER_NAME(role_principal_id)  +\'\'\'\' User Name \'\'\'\'+  USER_NAME(member_principal_id)    from  sys.database_role_members   	Where   	(   	( USER_NAME(member_principal_id)  like \'\'\'\'%ODEABANK%.%\'\'\'\'  and   USER_NAME(member_principal_id)  not like \'\'\'\'%admin%\'\'\'\' )     	OR   	  (suser_name(member_principal_id) like \'\'\'\'%ODEABANK%Cyberark%\'\'\'\')       )    	AND   	DB_NAME() <> \'\'\'\'master\'\'\'\' and   	USER_NAME(role_principal_id) not in (\'\'\'\'db_datareader\'\'\'\',\'\'\'\'db_viewdefinition\'\'\'\',\'\'\'\'db_denydatareader\'\'\'\',\'\'\'\'db_deny_maas\'\'\'\');   \'\'      Select  count(*)  from #TEMP;   \'\r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      EXEC sp_MSforeachdb \'\' USE [?]    INSERT INTO #TEMP   SELECT \'\'\'\'DB Name : \'\'\'\'+Cast (DB_NAME() as varchar)+\'\'\'\' Role Name : \'\'\'\'+USER_NAME(role_principal_id)  +\'\'\'\' User Name \'\'\'\'+  USER_NAME(member_principal_id)    from  sys.database_role_members   	Where   (   	( USER_NAME(member_principal_id)  like \'\'\'\'%ODEABANK%.%\'\'\'\'  and   USER_NAME(member_principal_id)  not like \'\'\'\'%admin%\'\'\'\' )     	OR   	(suser_name(member_principal_id) like \'\'\'\'%ODEABANK%Cyberark%\'\'\'\')   )    	AND   	DB_NAME() <> \'\'\'\'master\'\'\'\' and   	USER_NAME(role_principal_id) not in  (\'\'\'\'db_datareader\'\'\'\',\'\'\'\'db_viewdefinition\'\'\'\',\'\'\'\'db_denydatareader\'\'\'\',\'\'\'\'db_deny_maas\'\'\'\');   \'\'      Select  * from #TEMP;   \'\r\n','Database role member usage for users  is correct\r\n','Database role member usage for users  is not correct\r\n','pass',NULL,NULL,'2026-01-25 11:34:25'),(1426,202601,47,27,'AA_SqlServer_220_2_Public Database Permissions','critical','PRIV','This test checks database permisions for public . Public is a special role and permissions should not be granted to public role.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP ( row varchar(500));          exec sp_MSforeachdb \'\'   USE [?]   iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'public\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND OBJECT_NAME(MAJOR_iD) NOT LiKE (\'\'\'\'%fn_cdc_get_net_changes_application_data%\'\'\'\')   AND NOT (OBJECT_SCHEMA_NAME(MAJOR_iD) = \'\'\'\'cdc\'\'\'\' and PERMiSSiON_NAME=\'\'\'\'SELECT\'\'\'\')   AND NOT (PERMiSSiON_NAME IN (\'\'\'\'REFERENCES\'\'\'\',\'\'\'\'SEND\'\'\'\',   \'\'\'\'VIEW ANY COLUMN ENCRYPTION KEY DEFINITION\'\'\'\',   \'\'\'\'VIEW ANY COLUMN MASTER KEY DEFINITION\'\'\'\' ) and OBJECT_SCHEMA_NAME(MAJOR_iD) IS NULL)   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select count(*) from #TEMP;   \'\r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP ( row varchar(500));          exec sp_MSforeachdb \'\'   USE [?]   iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'public\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND OBJECT_NAME(MAJOR_iD) NOT LiKE (\'\'\'\'%fn_cdc_get_net_changes_application_data%\'\'\'\')   AND NOT (OBJECT_SCHEMA_NAME(MAJOR_iD) = \'\'\'\'cdc\'\'\'\' and PERMiSSiON_NAME=\'\'\'\'SELECT\'\'\'\')   AND NOT (PERMiSSiON_NAME IN (\'\'\'\'REFERENCES\'\'\'\',\'\'\'\'SEND\'\'\'\',   \'\'\'\'VIEW ANY COLUMN ENCRYPTION KEY DEFINITION\'\'\'\',   \'\'\'\'VIEW ANY COLUMN MASTER KEY DEFINITION\'\'\'\' ) and OBJECT_SCHEMA_NAME(MAJOR_iD) IS NULL)   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select * from #TEMP;   \'','There are no permissions which are assigned to public.\r\n','There are some persmissions which are assigned to public\r\n','pass',NULL,NULL,'2026-01-25 11:34:25'),(1427,202601,47,28,'AA_SqlServer_220_Public Database Permissions','critical','PRIV','This test checks database permisions for public . Public is a special role and permissions should not be granted to public role.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      exec sp_msforeachdb \'\'   USE [?]     iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'public\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND OBJECT_NAME(MAJOR_iD) NOT LiKE (\'\'\'\'%fn_cdc_get_net_changes_application_data%\'\'\'\')   AND NOT (OBJECT_SCHEMA_NAME(MAJOR_iD) = \'\'\'\'cdc\'\'\'\' and PERMiSSiON_NAME=\'\'\'\'SELECT\'\'\'\')   AND NOT (PERMiSSiON_NAME IN (\'\'\'\'REFERENCES\'\'\'\',\'\'\'\'SEND\'\'\'\',   \'\'\'\'VIEW ANY COLUMN ENCRYPTION KEY DEFINITION\'\'\'\',   \'\'\'\'VIEW ANY COLUMN MASTER KEY DEFINITION\'\'\'\' ) and OBJECT_SCHEMA_NAME(MAJOR_iD) IS NULL)   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select count(*) from #TEMP;   \' \r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      exec sp_msforeachdb \'\'   USE [?]     iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'public\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND OBJECT_NAME(MAJOR_iD) NOT LiKE (\'\'\'\'%fn_cdc_get_net_changes_application_data%\'\'\'\')   AND NOT (OBJECT_SCHEMA_NAME(MAJOR_iD) = \'\'\'\'cdc\'\'\'\' and PERMiSSiON_NAME=\'\'\'\'SELECT\'\'\'\')   AND NOT (PERMiSSiON_NAME IN (\'\'\'\'REFERENCES\'\'\'\',\'\'\'\'SEND\'\'\'\',   \'\'\'\'VIEW ANY COLUMN ENCRYPTION KEY DEFINITION\'\'\'\',   \'\'\'\'VIEW ANY COLUMN MASTER KEY DEFINITION\'\'\'\' ) and OBJECT_SCHEMA_NAME(MAJOR_iD) IS NULL)   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select * from #TEMP;   \' \r\n','There are no permissions which are assigned to public.\r\n','There are some persmissions which are assigned to public\r\n','pass',NULL,NULL,'2026-01-25 11:34:26'),(1428,202601,47,29,'AA_SqlServer_230_Real person users','critical','ACCOUNT','All logins to the database should be made with AD groups, real person users should  not be connected database directly\r\n','','Select      count(*)   from      sys.server_principals    where      name like \'ODEABANK%.%\'      and is_disabled = 0   \r\n','== 0','','Select      name     from      sys.server_principals    where      name like \'ODEABANK%.%\'      and is_disabled = 0;\r\n','Real person users are not found in the logins\r\n','Some real person users are found in the logins\r\n','pass',NULL,NULL,'2026-01-25 11:34:26'),(1429,202601,47,30,'AA_SqlServer_240_2_guest Database Permissions','critical','ACCOUNT','This test checks database permisions for guest . guest is a special user and permissions should not be granted to guest user.\r\n','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP ( row varchar(500));\r\n\r\nexec sp_MSforeachdb \'\'\r\nUSE [?]\r\niNSERT iNTO #TEMP\r\nSELECT\r\n\'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +\r\n\'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +\r\n\'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +\r\n\'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )\r\nFROM\r\nsys.database_permissions\r\nWHERE\r\nUSER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'guest\'\'\'\' )\r\nAND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'\r\nAND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')\r\nAND STATE_DESC=\'\'\'\'GRANT\'\'\'\'\r\n;\r\n\'\'\r\nselect count(*) from #TEMP;\r\n\'','== 0','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP ( row varchar(500));\r\n\r\nexec sp_MSforeachdb \'\'\r\nUSE [?]\r\niNSERT iNTO #TEMP\r\nSELECT\r\n\'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +\r\n\'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +\r\n\'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +\r\n\'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )\r\nFROM\r\nsys.database_permissions\r\nWHERE\r\nUSER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'guest\'\'\'\' )\r\nAND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'\r\nAND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')\r\nAND STATE_DESC=\'\'\'\'GRANT\'\'\'\'\r\n;\r\n\'\'\r\nselect * from #TEMP;\r\n\'','There are no permissions which are assigned to guest.\r\n','There are some persmissions which are assigned to guest\r\n','pass',NULL,NULL,'2026-01-25 11:34:26'),(1430,202601,47,31,'AA_SqlServer_240_guest Database Permissions','critical','PRIV','This test checks database permisions for guest . guest is a special user and permissions should not be granted to guest user.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      exec sp_msforeachdb \'\'   USE [?]     iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'guest\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select count(*) from #TEMP;   \' \r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      exec sp_msforeachdb \'\'   USE [?]     iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'guest\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select  *  from #TEMP;   \' \r\n','There are no permissions which are assigned to guest.\r\n','There are some persmissions which are assigned to guest\r\n','pass',NULL,NULL,'2026-01-25 11:34:26'),(1431,202601,47,32,'AA_SqlServer_250_Database Role members for guest','critical','PRIV','This test checks database role members for guest  user. Database roles  could not be assigned to guest role.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      EXEC sp_MSforeachdb \'\' USE [?]    INSERT INTO #TEMP   SELECT \'\'\'\'DB Name : \'\'\'\'+Cast (DB_NAME() as varchar)+\'\'\'\' Role Name : \'\'\'\'+USER_NAME(role_principal_id)  +\'\'\'\' User Name \'\'\'\'+  USER_NAME(member_principal_id)    from  sys.database_role_members   	Where     USER_NAME(member_principal_id)  = \'\'\'\'guest\'\'\'\'     ;   \'\'      Select count(*)  from #TEMP;   \'\r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      EXEC sp_MSforeachdb \'\' USE [?]    INSERT INTO #TEMP   SELECT \'\'\'\'DB Name : \'\'\'\'+Cast (DB_NAME() as varchar)+\'\'\'\' Role Name : \'\'\'\'+USER_NAME(role_principal_id)  +\'\'\'\' User Name \'\'\'\'+  USER_NAME(member_principal_id)    from  sys.database_role_members   	Where     USER_NAME(member_principal_id)  = \'\'\'\'guest\'\'\'\'     ;   \'\'      Select  *  from #TEMP;   \'\r\n','Database role member usage for guest user  is correct\r\n','Database role member usage for guest user  is not correct\r\n','pass',NULL,NULL,'2026-01-25 11:34:26'),(1432,202601,47,33,'AA_SqlServer_260_SQL Logins with Null Password','critical','ACCOUNT','This test checks sql logins with null password. SQL Logins should not have null passwords.\r\n','','SELECT      count(name)   from      sys.sql_logins    WHERE      PWDCOMPARE(\'\', password_hash)= 1\r\n','== 0','','SELECT      name    from      sys.sql_logins    WHERE      PWDCOMPARE(\'\', password_hash)= 1   \r\n','There are no sql logins with null paswords\r\n','There are some sql logins with null passwords.\r\n','pass',NULL,NULL,'2026-01-25 11:34:26'),(1433,202601,47,34,'AA_SqlServer_270_SQL Logins with username and passwords are equal','critical','ACCOUNT','This test checks sql login password which are egual to username. Username and password must be different for SQL logins.\r\n','','SELECT      count(name)   from      sys.sql_logins    WHERE      PWDCOMPARE(name,password_hash)=1 \r\n','== 0','','SELECT      name    from      sys.sql_logins    WHERE      PWDCOMPARE(name,password_hash)=1    \r\n','There is no SQL login name which is equal to password.\r\n','There are some sql logins whose passwords are egual to usernames.\r\n','pass',NULL,NULL,'2026-01-25 11:34:26'),(1434,202601,47,35,'AA_SqlServer_280_No Sample Databases','critical','CONFIG','This test checks whether the sample databases created optionally on installation are present.  These sample databases contain many default permissions, and can be used as an entry point to your systems. \r\n','','select      count(name)    from      sys.databases    where      name in (       \'AdventureWorks\', \'AdventureWorksDW\',        \'Northwind\', \'Pubs\'     )   \r\n','== 0','','select      name    from      sys.databases    where      name in (       \'AdventureWorks\', \'AdventureWorksDW\',        \'Northwind\', \'Pubs\'     )   \r\n','There are no sample databases in the server\r\n','There are some sample databases in the server\r\n','pass',NULL,NULL,'2026-01-25 11:34:26'),(1435,202601,47,43,'AA_SqlServer_350_User Password Policy Is Checked','critical','ACCOUNT','This test checks that CHECK_POLICY is enabled for all users.  Enabling CHECK_POLICY ensures that Windows passwords policies are enforced.','','select count(*) from sys.sql_logins  \r\nwhere \r\nis_policy_checked=0 and\r\nname not like \'##%\'','== 0','','select name from sys.sql_logins  \r\nwhere \r\nis_policy_checked=0 and\r\nname not like \'##%\'','CHECK_POLICY is enabled for all users','CHECK_POLICY is not enabled for all users','pass',NULL,NULL,'2026-01-25 11:34:26'),(1436,202601,47,44,'AA_SqlServer_360_CHECK_EXPIRATION Is Checked','critical','ACCOUNT','This test checks that CHECK_EXPIRATION is enabled for all users.  Passwords that have been in use for long periods of time are likely to become known to unauthorized users.\r\n','','select count(*) from sys.sql_logins     where    is_expiration_checked=0 and   name not like \'##%\'\r\n','== 0','','select name from sys.sql_logins     where    is_expiration_checked=0 and   name not like \'##%\'\r\n','CHECK_EXPIRATION is enabled for all users\r\n','CHECK_EXPIRATION is not enabled for all users\r\n','fail','name\n----\n\'sa\'',NULL,'2026-01-25 11:34:26'),(1437,202601,47,22,'AA_SqlServer_170_Windows Authentication','major','AUTH','This test checks that the authentication mode is set to Windows authentication only.  Windows provides a more robust authentication mechanism than SQL Server authentication.','',' SELECT cast( SERVERPROPERTY(\'IsIntegratedSecurityOnly\') as int) ','==1','','SELECT cast( SERVERPROPERTY(\'IsIntegratedSecurityOnly\') as varchar)','The authentication mode is set to Windows authentication only. ','The authentication mode is not set to Windows authentication only.','fail','\n---\n\'0\'',NULL,'2026-01-25 11:34:26'),(1438,202601,47,23,'AA_SqlServer_180_No Guest User Accounts','major','ACCOUNT','This test checks for the existence of guest user accounts with CONNECT permission in database other than master, msdb and tempdb.  This test also exclude databases that are flagged as distributor. If the GUEST user exists and a specific login has not been granted to a database, a login will be mapped to GUEST. The presence of the GUEST user allows all logins to access the database.\r\n','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP  ( row int);\r\n\r\nEXEC sp_MSforeachdb \'\' USE [?]\r\n	INSERT INTO #TEMP\r\n	SELECT count(*) \r\n	FROM sys.database_permissions\r\n	WHERE [grantee_principal_id] = DATABASE_PRINCIPAL_ID(\'\'\'\'guest\'\'\'\')\r\n	AND [state_desc] LIKE \'\'\'\'GRANT%\'\'\'\'\r\n	AND [permission_name] = \'\'\'\'CONNECT\'\'\'\'\r\n	AND DB_NAME() NOT IN (\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'msdb\'\'\'\') ;\r\n\'\'\r\n\r\nSelect sum(row) from #TEMP;\r\ndrop table #TEMP;\r\n\'','== 0','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP  ( row varchar(500));\r\n\r\nEXEC sp_MSforeachdb \'\' USE  [?] \r\n	INSERT INTO #TEMP\r\n	SELECT \'\'\'\' DB NAME : \'\'\'\' + Cast (DB_NAME() as varchar) + \'\'\'\' guest user has CONNECT permission \'\'\'\'\r\n	FROM sys.database_permissions\r\n	WHERE [grantee_principal_id] = DATABASE_PRINCIPAL_ID(\'\'\'\'guest\'\'\'\')\r\n	AND [state_desc] LIKE \'\'\'\'GRANT%\'\'\'\'\r\n	AND [permission_name] = \'\'\'\'CONNECT\'\'\'\'\r\n	AND DB_NAME() NOT IN (\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'msdb\'\'\'\') ;\r\n\'\'\r\n\r\nSelect * from #TEMP;\r\ndrop table #TEMP;\r\n\'','There is no guest user with CONNECT permission. ','There are   guest users with CONNECT permission. Remove these users','pass',NULL,NULL,'2026-01-25 11:34:26'),(1439,202601,47,36,'AA_SqlServer_290_2_No Permissions with GRANT Option','major','PRIV','This test checks database permisions  with grant option. No permission with grant option should be defined in the database.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP ( row varchar(500));      exec sp_MSforeachdb \'\'   USE [?]   iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   STATE_DESC like \'\'\'\'%WITH_GRANT%\'\'\'\'   ;   \'\'   select count(*) from #TEMP;   \'\r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP ( row varchar(500));      exec sp_MSforeachdb \'\'   USE [?]   iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   STATE_DESC like \'\'\'\'%WITH_GRANT%\'\'\'\'   ;   \'\'   select * from #TEMP;   \'\r\n','There are no permissions with grant option.\r\n','There are some persmissions  with grant option.\r\n','pass',NULL,NULL,'2026-01-25 11:34:26'),(1440,202601,47,37,'AA_SqlServer_290_No Permissions with GRANT Option','major','PRIV','','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP  ( row varchar(500));\r\n\r\nexec sp_msforeachdb \'\'\r\nUSE [?]  \r\niNSERT iNTO #TEMP\r\nSELECT\r\n\'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +\r\n\'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +\r\n\'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +\r\n\'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )\r\nFROM\r\nsys.database_permissions\r\nWHERE\r\nSTATE_DESC like \'\'\'\'%WITH_GRANT%\'\'\'\'\r\n;\r\n\'\'\r\nselect  count(*)  from #TEMP;\r\n\' ','== 0','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP  ( row varchar(500));\r\n\r\nexec sp_msforeachdb \'\'\r\nUSE [?]  \r\niNSERT iNTO #TEMP\r\nSELECT\r\n\'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +\r\n\'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +\r\n\'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +\r\n\'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )\r\nFROM\r\nsys.database_permissions\r\nWHERE\r\nSTATE_DESC like \'\'\'\'%WITH_GRANT%\'\'\'\'\r\n;\r\n\'\'\r\nselect * from #TEMP;\r\n\' ','There are no permissions with grant option.\r\n','There are some persmissions  with grant option.\r\n','pass',NULL,NULL,'2026-01-25 11:34:26'),(1441,202601,47,40,'AA_SqlServer_320_No Access to Registry Access Extended procedures','major','PRIV','This test checks for the existence of, and user permissions on, registry access extended stored procedures.  Either these procedures should be completely dropped, or access to them should be strictly limited. xp_reg%,xp_instance_reg%\r\n','','SELECT \r\ncount(*) \r\nFROM \r\n  [master].sys.system_objects o \r\n  JOIN [master].sys.database_permissions p ON o.object_id = p.major_id \r\n  JOIN [master].sys.database_principals u ON p.grantee_principal_id = u.principal_id \r\nWHERE \r\n( o.name LIKE \'xp_reg%\' OR o.name LIKE \'xp_instance_reg%\')\r\n  AND p.type = \'EX\' ','== 0','','SELECT \r\n  \'Principal : \'+u.name  COLLATE DATABASE_DEFAULT +\r\n  \' Extended Procedure Name : \'+o.name COLLATE DATABASE_DEFAULT +\r\n  \' Type : \'+ u.type_desc COLLATE DATABASE_DEFAULT \r\nFROM \r\n  [master].sys.system_objects o \r\n  JOIN [master].sys.database_permissions p ON o.object_id = p.major_id \r\n  JOIN [master].sys.database_principals u ON p.grantee_principal_id = u.principal_id \r\nWHERE \r\n( o.name LIKE \'xp_reg%\' OR o.name LIKE \'xp_instance_reg%\')\r\n  AND p.type = \'EX\' ','There are no permissions on registry access extended stored procedures\r\n','There are some persmissions permissions on registry access extended stored procedures\r\n','fail','\n---------------------------------------------------------------------------------------\n\'Principal : public Extended Procedure Name : xp_instance_regread Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_regread Type : DATABASE_ROLE\'',NULL,'2026-01-25 11:34:26'),(1442,202601,47,41,'AA_SqlServer_330_Revoke public login from SQL Server agent proxy account','major','PRIV','The public database role contains every user in the msdb database. SQL Agent proxies   define a security context in which a job step can run.Granting access to SQL Agent proxies for the public role would allow all users to utilize the proxy which may have high privileges. This would likely break the principle of least   privileges.\r\n','','SELECT count(*)\r\nFROM msdb.dbo.sysproxylogin spl\r\nJOIN sys.database_principals dp\r\nON dp.sid = spl.sid\r\nJOIN msdb.dbo.sysproxies sp\r\nON sp.proxy_id = spl.proxy_id\r\nWHERE principal_id = USER_ID(\'public\')','== 0','','SELECT \'proxyname : \'+CAST(sp.name  as varchar)\r\nFROM msdb.dbo.sysproxylogin spl\r\nJOIN sys.database_principals dp\r\nON dp.sid = spl.sid\r\nJOIN msdb.dbo.sysproxies sp\r\nON sp.proxy_id = spl.proxy_id\r\nWHERE principal_id = USER_ID(\'public\')','There are no public permissions on SQL Server agent proxy account\r\n','There are some public permissions on SQL Server agent proxy account\r\n','pass',NULL,NULL,'2026-01-25 11:34:26'),(1443,202601,47,42,'AA_SqlServer_340_No Individual User Access To syscomment and sp_helptext','minor','PRIV','This test checks for grants on SYSCOMMENTS.TEXT.  Such grants allow any user to read the text comments associated with a database object, making the text publicly viewable.\r\n','','SELECT count(*)\r\nFROM msdb.dbo.sysproxylogin spl\r\nJOIN sys.database_principals dp\r\nON dp.sid = spl.sid\r\nJOIN msdb.dbo.sysproxies sp\r\nON sp.proxy_id = spl.proxy_id\r\nWHERE principal_id = USER_ID(\'public\')\r\n','== 0','','SELECT count(*)\r\nFROM msdb.dbo.sysproxylogin spl\r\nJOIN sys.database_principals dp\r\nON dp.sid = spl.sid\r\nJOIN msdb.dbo.sysproxies sp\r\nON sp.proxy_id = spl.proxy_id\r\nWHERE principal_id = USER_ID(\'public\')','There are no public permissions on SQL Server agent proxy account','There are some public permissions on SQL Server agent proxy account','pass',NULL,NULL,'2026-01-25 11:34:26'),(1444,202601,47,10,'AA_SqlServer_050_Disable Ad hoc distributed queries option','major','CONFIG','Adhoc queries allow undefined access to remote database sources.  Access to untrusted databases could result in execution of malicious applications and/or a compromise of local data confidentiality and integrity. The DBA will configure the database to disable access from the database to objects stored externally to the database on the local host unless mission and/or operationally required and documented.\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Ad Hoc Distributed Queries\'','== 0','','SELECT name + \' Value : \'+ cast( value as varchar ) + \' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'Ad Hoc Distributed Queries\'','Ad Hoc Distributed Queries is disabled','Ad Hoc Distributed Queries is not disabled. Disable this option','pass',NULL,NULL,'2026-01-25 11:34:26'),(1445,202601,47,11,'AA_SqlServer_060_Disable CLR option','major','CONFIG','The clr_enabled parameter configures SQL Server to allow or disallow use of Command Language Runtime objects.  CLR objects is managed code that integrates with the .NET Framework.  This is a more secure method than external stored procedures, although it still contains some risk.  Where no external application execution requirements are required, disallowing use of any improves the overall security posture of the database.\r\n\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'clr enabled\'','== 0','','SELECT name + \' Value : \'+ cast( value as varchar ) + \' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'clr enabled\'','CLR option is disabled','CLR option is not disabled. Disable this option','pass',NULL,NULL,'2026-01-25 11:34:26'),(1446,202601,47,12,'AA_SqlServer_070_Disable Cross db ownership chaining option','major','CONFIG','Cross database ownership chaining allows permissions to objects to be assigned by users other than the Information Owner.  This allows access to objects that are not authorized directly by the Information Owner based on job functions defined by the owner.  Unauthorized access may lead to a compromise of data integrity or confidentiality. The DBA will ensure database privileges are assigned via roles and not directly assigned to database accounts. Privileges may be assigned directly to application owner accounts where the DBMS does not otherwise support access via roles.\r\n\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'cross db ownership chaining\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'cross db ownership chaining\'','Cross db ownership chaining  option is disabled','Cross db ownership chaining option  is not disabled. Disable this option','pass',NULL,NULL,'2026-01-25 11:34:26'),(1447,202601,47,13,'AA_SqlServer_080_Disable Database Mail XPs option','major','CONFIG','SQL Mail accepts incoming database commands via email. This can introduce malicious codes or viruses into the SQL server environment.','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Database Mail XPs\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \'Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'Database Mail XPs\'','Database Mail XPs option is disabled','Database Mail XPs option  is not disabled. Disable this option','pass',NULL,NULL,'2026-01-25 11:34:26'),(1448,202601,47,14,'AA_SqlServer_100_Disable xp_cmdshell Server Configuration option','major','CONFIG','The xp_cmdshell extended stored procedures allows execution of host executables outside the controls of database access permissions.  This access may be exploited by malicious users who have compromised the integrity of the SQL Server database process to control the host operating system to perpetrate additional malicious activity. The DBA should disable the use of external procedures by the database unless it is mission critical or operationally required','','SELECT CAST(value as int) +\r\n       CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'xp_cmdshell\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) +\r\n\' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'xp_cmdshell\'','xp_cmdshell Server Configuration option is disabled','xp_cmdshell Server Configuration option is not disabled. This option must be disabled','pass',NULL,NULL,'2026-01-25 11:34:26'),(1449,202601,47,15,'AA_SqlServer_110_Disable Remote Access option','major','CONFIG','The remote access option controls the execution of local stored procedures on remote\r\nservers or remote stored procedures on local server.Functionality can be abused to launch a Denial-of-Service (DoS) attack on remote servers\r\nby off-loading query processing to a target.\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'remote access\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \' Value in use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'remote access\'','Remote Access option is disabled','Remote Access option  is not disabled. Disable this option','fail','\n------------------------------------------\n\'remote access Value : 1 Value in use : 1\'',NULL,'2026-01-25 11:34:26'),(1450,202601,47,16,'AA_SqlServer_120_Disable Remote Admin Connections option','major','CONFIG','The remote admin connections option controls whether a client application on a remote\r\ncomputer can use the Dedicated Administrator Connection (DAC).The Dedicated Administrator Connection (DAC) lets an administrator access a running\r\nserver to execute diagnostic functions or Transact-SQL statements, or to troubleshoot\r\nproblems on the server, even when the server is locked or running in an abnormal state\r\nand not responding to a SQL Server Database Engine connection. In a cluster scenario, the\r\nadministrator may not actually be logged on to the same node that is currently hosting the\r\nSQL Server instance and thus is considered \"remote\". Therefore, this setting should usually\r\nbe enabled (1) for SQL Server failover clusters; otherwise it should be disabled (0) which is\r\nthe default.\r\n','','execute sp_executesql N\'\r\n\r\nDECLARE @x int;\r\n\r\nSELECT @x=isnull(CAST(value as int) + CAST(value_in_use as int),100)\r\nFROM sys.configurations\r\nWHERE name = \'\'remote admin connections\'\'\r\n\r\nIF @x = 100\r\n       SELECT 0 ;\r\nELSE \r\n   SELECT CAST(value as int) + CAST(value_in_use as int) \r\n   FROM sys.configurations\r\n   WHERE name = \'\'remote admin connections\'\'\r\n\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'remote admin connections\'','Remote Admin Connections option is disabled','Remote Admin Connections option  is not disabled. Disable this option','pass',NULL,NULL,'2026-01-25 11:34:26'),(1451,202601,47,19,'AA_SqlServer_150_Disable database trustworthy status','major','CONFIG','The TRUSTWORTHY database setting restricts access to database resources by databases that contain assemblies with the EXTERNAL_ACCESS or UNSAFE permission settings and modules that use impersonation of accounts assigned elevated privileges.  Unless all assemblies and code for the database have been reviewed, especially in the case where databases have been detached and attached between server instances, leaving the TRUSTWORTHY status to off can help reduce threats from malicious assemblies or modules.','','SELECT count(name)\r\nFROM sys.databases\r\nWHERE is_trustworthy_on = 1\r\nAND name != \'msdb\';','== 0','','SELECT name\r\nFROM sys.databases\r\nWHERE is_trustworthy_on = 1\r\nAND name != \'msdb\';','database trustworthy status is disabled','database trustworthy status is not disabled. Disable this option','pass',NULL,NULL,'2026-01-25 11:34:26'),(1452,202601,47,20,'Checkpoint başarıyla oluşturuldu.','major','CONFIG','This test checks if SQL Server Instance is not advertised by the SQL Server Browser service. To maintain a higher level of protection for database instances, we recommend that SQL Server Instance be hidden when it is not required. Please note that this test does not include Clustered Instances as turning off this feature may cause issues with the Clustered environment.\r\n\r\n','','execute sp_executesql N\'\r\n\r\nDECLARE @getValue INT\r\n\r\nEXEC master.sys.xp_instance_regread\r\n@rootkey = N\'\'HKEY_LOCAL_MACHINE\'\',\r\n@key = N\'\'SOFTWARE\\Microsoft\\Microsoft SQL Server\\MSSQLServer\\SuperSocketNetLib\'\',\r\n@value_name = N\'\'HideInstance\'\',\r\n@value = @getValue OUTPUT\r\n\r\nSELECT isnull(@getvalue,0)\'','==1','','execute sp_executesql N\'\r\n\r\nDECLARE @getValue INT\r\n\r\nEXEC master.sys.xp_instance_regread\r\n@rootkey = N\'\'HKEY_LOCAL_MACHINE\'\',\r\n@key = N\'\'SOFTWARE\\Microsoft\\Microsoft SQL Server\\MSSQLServer\\SuperSocketNetLib\'\',\r\n@value_name = N\'\'HideInstance\'\',\r\n@value = @getValue OUTPUT\r\n\r\nSELECT isnull(@getvalue,0)\'','SQL Server Instance is  hidden.\r\n','SQL Server Instance is not hidden. Hide the instance','fail','\n-\n0',NULL,'2026-01-25 11:34:26'),(1453,202601,47,21,'AA_SqlServer_160_Hide SQL Server Instance','major','CONFIG','This test checks if SQL Server Instance is not advertised by the SQL Server Browser service. To maintain a higher level of protection for database instances, we recommend that SQL Server Instance be hidden when it is not required. Please note that this test does not include Clustered Instances as turning off this feature may cause issues with the Clustered environment.\r\n\r\n','','execute sp_executesql N\'\r\n\r\nDECLARE @getValue INT\r\n\r\nEXEC master.sys.xp_instance_regread\r\n@rootkey = N\'\'HKEY_LOCAL_MACHINE\'\',\r\n@key = N\'\'SOFTWARE\\Microsoft\\Microsoft SQL Server\\MSSQLServer\\SuperSocketNetLib\'\',\r\n@value_name = N\'\'HideInstance\'\',\r\n@value = @getValue OUTPUT\r\n\r\nSELECT isnull(@getvalue,0)\'','==1','','execute sp_executesql N\'\r\n\r\nDECLARE @getValue INT\r\n\r\nEXEC master.sys.xp_instance_regread\r\n@rootkey = N\'\'HKEY_LOCAL_MACHINE\'\',\r\n@key = N\'\'SOFTWARE\\Microsoft\\Microsoft SQL Server\\MSSQLServer\\SuperSocketNetLib\'\',\r\n@value_name = N\'\'HideInstance\'\',\r\n@value = @getValue OUTPUT\r\n\r\nSELECT isnull(@getvalue,0)\'','SQL Server Instance is  hidden.','SQL Server Instance is not hidden. Hide the instance','fail','\n-\n0',NULL,'2026-01-25 11:34:26'),(1454,202601,47,38,'AA_SqlServer_300_No Access To General Extended procedures','major','PRIV','This test checks for the existence of, and user permissions on, extended stored procedures.  Either these procedures should be completely dropped, or access to them should be strictly limited. xp_cmdshell, xp_enumgroups, xp_grantlogin ,xp_logevent, xp_logininfo,    xp_msver, xp_revokelogin, xp_sprintf, xp_sqlmaint, xp_sscanf\r\n','','SELECT \r\ncount(*) \r\nFROM \r\n  [master].sys.system_objects o \r\n  JOIN [master].sys.database_permissions p ON o.object_id = p.major_id \r\n  JOIN [master].sys.database_principals u ON p.grantee_principal_id = u.principal_id \r\nWHERE \r\n    o.name in ( \r\n	\'xp_cmdshell\', \r\n	\'xp_enumgroups\', \r\n    \'xp_grantlogin\' ,\r\n	\'xp_logevent\', \r\n	\'xp_logininfo\', \r\n    \'xp_msver\', \r\n	\'xp_revokelogin\', \r\n	\'xp_sprintf\', \r\n    \'xp_sqlmaint\', \r\n	\'xp_sscanf\' )\r\n  AND p.type = \'EX\' ','== 0','','SELECT \r\n  \'Principal : \'+u.name  COLLATE DATABASE_DEFAULT +\r\n  \' Extended Procedure Name : \'+o.name COLLATE DATABASE_DEFAULT +\r\n  \' Type : \'+ u.type_desc COLLATE DATABASE_DEFAULT \r\nFROM \r\n  [master].sys.system_objects o \r\n  JOIN [master].sys.database_permissions p ON o.object_id = p.major_id \r\n  JOIN [master].sys.database_principals u ON p.grantee_principal_id = u.principal_id \r\nWHERE \r\n    o.name in ( \r\n	\'xp_cmdshell\', \r\n	\'xp_enumgroups\', \r\n    \'xp_grantlogin\' ,\r\n	\'xp_logevent\', \r\n	\'xp_logininfo\', \r\n    \'xp_msver\', \r\n	\'xp_revokelogin\', \r\n	\'xp_sprintf\', \r\n    \'xp_sqlmaint\', \r\n	\'xp_sscanf\' )\r\n  AND p.type = \'EX\' ','There are no permissions on general extended stored procedures\r\n','There are some persmissions permissions on general extended stored procedures.\r\n','fail','\n----------------------------------------------------------------------------------\n\'Principal : public Extended Procedure Name : xp_msver Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_sscanf Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_revokelogin Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_grantlogin Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_sprintf Type : DATABASE_ROLE\'',NULL,'2026-01-25 11:34:26'),(1455,202601,47,39,'AA_SqlServer_310_No Access to OLE Automation procedures','major','CONFIG','This test checks for the existence of,and user permissions on OLE automation extended stored procedures.  Either these procedures should be completely dropped, or access to them should be strictly limited.      \r\n','','SELECT CAST(value as int) +\r\n       CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Ole Automation Procedures\'   \r\n','== 0','','SELECT CAST(value as int) +\r\n       CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Ole Automation Procedures\'\r\n  \r\n','OLE Automation procedures  option is disabled\r\n','OLE Automation procedures  option  is not disabled. Disable this option\r\n','pass',NULL,NULL,'2026-01-25 11:34:26'),(1456,202601,47,17,'AA_SqlServer_130_Disable Ole Automation Procedures option','minor','CONFIG','This test checks if Ole Automation Procedures option is disabled. Ole Automation Procedures option allows SQL Server users to execute functions external to SQL Server. Enabling this option will increase the attack surface of SQL Server and allow users to execute functions in the security context of SQL Server. We recommend that the Ole Automation Procedures option to be disabled when it is not document as a requirement.\r\n\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Ole Automation Procedures\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \'Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'Ole Automation Procedures\'',' Ole Automation Procedures option is disabled',' Ole Automation Procedures option  is not disabled. Disable this option','pass',NULL,NULL,'2026-01-25 11:34:26'),(1457,202601,47,18,'AA_SqlServer_140_Disable Scan for Startup Procedures option','minor','CONFIG','This test checks if scan for startup procedures is disabled. This feature causes SQL Server to scan for and automatically run all stored procedures that are set to execute upon service startup. If there are no user-defined stored procedures set to execute when SQL server starts, we recommend this feature to be disabled.\r\n\r\n','','SELECT CAST(value as int) +\r\n       CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'scan for startup procs\'','== 0','','SELECT name + \' value : \'+cast( value as varchar ) +\r\n\' value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'scan for startup procs\'','Scan for Startup Procedures  option is disabled','Scan for Startup Procedures  option  is not disabled. Disable this option','pass',NULL,NULL,'2026-01-25 11:34:26'),(1458,202601,47,9,'AA_SqlServer_040_Rename the sa Login Account','major','ACCOUNT','The \'sa\' account is a well-known account.  Well-known account names provide an easier target for attack.  Renaming the sa account helps reduce the risk of an attack to this built-in account.','','SELECT count(*)\r\nFROM sys.server_principals\r\nWHERE sid = 0x01 and name=\'sa\'','== 0','','SELECT name\r\nFROM sys.server_principals\r\nWHERE sid = 0x01','sa Login Account is renamed','sa Login Account is not renamed. Rename this account','fail','name\n----\n\'sa\'',NULL,'2026-01-25 11:34:26'),(1459,202602,48,24,'AA_SqlServer_190_Public server role permision','critical','PRIV','public is a special fixed server role containing all logins. Unlike other fixed server roles,\r\npermissions can be changed for the public role. In keeping with the principle of least\r\nprivileges, the public server role should not be used to grant permissions at the server\r\nscope as these would be inherited by all users.\r\n\r\nEvery SQL Server login belongs to the public role and cannot be removed from this role.\r\nTherefore, any permissions granted to this role will be available to all logins unless they\r\nhave been explicitly denied to specific logins or user-defined server roles.','','Select \r\n  count (permission_name) \r\nfrom \r\n  sys.server_permissions \r\nwhere \r\n  SUSER_NAME(grantee_principal_id) = \'public\' \r\n  and permission_name not in (\'VIEW ANY DATABASE\', \'CONNECT\')\r\n','== 0','','Select \r\n  permission_name \r\nfrom \r\n  sys.server_permissions \r\nwhere \r\n  SUSER_NAME(grantee_principal_id) = \'public\' \r\n  and permission_name not in (\'VIEW ANY DATABASE\', \'CONNECT\')\r\n\r\n','No server permissions are granted to public.','Some server permissions are granted to public.','pass',NULL,NULL,'2026-02-11 17:17:09'),(1460,202602,48,5,'AA_SqlServer_010_Supported SQL Server version','critical','PATCH','This test checks whether your current SQL Server version is a vendor-supported version.  Microsoft does not provide security fixes or software updates to unsupported software versions','','SELECT cast(ISNULL(SERVERPROPERTY(\'ProductMajorVersion\'),0) as int)   ','>=11','','SELECT \'Product Major version \' +  cast(ISNULL(SERVERPROPERTY(\'ProductMajorVersion\'),\'Null\' ) as  char ) ','The version of the database is acceptable.','The version of the database is not acceptable. The database version should SQL Sever 2012 or upper.','pass',NULL,NULL,'2026-02-11 17:17:09'),(1461,202602,48,6,'AA_SqlServer_020_Disable the sa Login Account','critical','ACCOUNT','This test checks if the \'sa\' Login Account is disabled. The sa account is a widely known and often widely used SQL Server account with sysadmin privileges. Enforcing this control reduces the probability of an attacker executing brute force attacks against a well-known principal.','','SELECT  count(*)\r\nFROM sys.server_principals\r\nWHERE sid = 0x01\r\nAND is_disabled = 0','== 0','','SELECT \'sa user name : \'+ name+\' is disabled : \' +  cast( is_disabled as char)\r\nFROM sys.server_principals\r\nWHERE sid = 0x01\r\n','sa Login Account is disabled','Disable sa login account','fail','\n----------------------------------------------------------------\n\'sa user name : sa is disabled : 0                             \'',NULL,'2026-02-11 17:17:10'),(1462,202602,48,7,'AA_SqlServer_025_sa Change password','critical','ACCOUNT','This test checks that sa password change . The sa password should be changed in every two days','','select datediff( day,  modify_date , getdate() ) FROM sys.server_principals\r\nWHERE sid = 0x01  ','< 3','','select datediff( day,  modify_date , getdate() ) FROM sys.server_principals\r\nWHERE sid = 0x01 ','sa password was changed in two days','','fail','\n--\n28',NULL,'2026-02-11 17:17:10'),(1463,202602,48,8,'AA_SqlServer_030_Ensure no Login exists with sa Login Account','critical','ACCOUNT','The \'sa\' account is a well-known account.  Well-known account names provide an easier target for attack. The lack of the sa account helps reduce the risk of an attack to this built-in account.','','SELECT count(*)\r\nFROM sys.server_principals\r\nWHERE name = \'sa\'','== 0','','SELECT name\r\nFROM sys.server_principals\r\nWHERE name = \'sa\'','There is no the sa account in the database.','There is the sa Login account in the database.Drop this user or rename et.','fail','name\n----\n\'sa\'',NULL,'2026-02-11 17:17:10'),(1464,202602,48,25,'AA_SqlServer_200_Fixed Server Role members for users','critical','PRIV','This test checks fixed server roles for analyst , developers and real persons. Fixed server roles could not be assigned to real person users ( Developer, Analyst users ) . Only Admin can use fixed server role.\r\n','','Select     count(*)   from      sys.server_role_members    where      (       suser_name(member_principal_id) like \'ODEABANK%.%\'    	AND       suser_name(member_principal_id) not like \'%admin%\'         AND       suser_name(member_principal_id) not like \'%t.coban%\'     )      OR (       suser_name(member_principal_id) like \'ODEABANK\\Cyberark_Intertech%\'     )      \r\n','== 0','','Select      suser_name(role_principal_id) + \'   \' + suser_name(member_principal_id)    from      sys.server_role_members    where      (       suser_name(member_principal_id) like \'ODEABANK%.%\'    	AND       suser_name(member_principal_id) not like \'%admin%\'         AND       suser_name(member_principal_id) not like \'%t.coban%\'     )      OR (       suser_name(member_principal_id) like \'ODEABANK\\Cyberark_Intertech%\'     )          \r\n','Fixed Server role usage is correct.\r\n','Fixed Server role usage is not correct.\r\n','pass',NULL,NULL,'2026-02-11 17:17:10'),(1465,202602,48,26,'AA_SqlServer_210_Database Role members for users','critical','PRIV','This test checks database role members for analyst and real person users. Database roles  except  db_datareader could not be assigned to real person users ( Developer, Analyst users ) .\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      EXEC sp_MSforeachdb \'\' USE [?]    INSERT INTO #TEMP   SELECT \'\'\'\'DB Name : \'\'\'\'+Cast (DB_NAME() as varchar)+\'\'\'\' Role Name : \'\'\'\'+USER_NAME(role_principal_id)  +\'\'\'\' User Name \'\'\'\'+  USER_NAME(member_principal_id)    from  sys.database_role_members   	Where   	(   	( USER_NAME(member_principal_id)  like \'\'\'\'%ODEABANK%.%\'\'\'\'  and   USER_NAME(member_principal_id)  not like \'\'\'\'%admin%\'\'\'\' )     	OR   	  (suser_name(member_principal_id) like \'\'\'\'%ODEABANK%Cyberark%\'\'\'\')       )    	AND   	DB_NAME() <> \'\'\'\'master\'\'\'\' and   	USER_NAME(role_principal_id) not in (\'\'\'\'db_datareader\'\'\'\',\'\'\'\'db_viewdefinition\'\'\'\',\'\'\'\'db_denydatareader\'\'\'\',\'\'\'\'db_deny_maas\'\'\'\');   \'\'      Select  count(*)  from #TEMP;   \'\r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      EXEC sp_MSforeachdb \'\' USE [?]    INSERT INTO #TEMP   SELECT \'\'\'\'DB Name : \'\'\'\'+Cast (DB_NAME() as varchar)+\'\'\'\' Role Name : \'\'\'\'+USER_NAME(role_principal_id)  +\'\'\'\' User Name \'\'\'\'+  USER_NAME(member_principal_id)    from  sys.database_role_members   	Where   (   	( USER_NAME(member_principal_id)  like \'\'\'\'%ODEABANK%.%\'\'\'\'  and   USER_NAME(member_principal_id)  not like \'\'\'\'%admin%\'\'\'\' )     	OR   	(suser_name(member_principal_id) like \'\'\'\'%ODEABANK%Cyberark%\'\'\'\')   )    	AND   	DB_NAME() <> \'\'\'\'master\'\'\'\' and   	USER_NAME(role_principal_id) not in  (\'\'\'\'db_datareader\'\'\'\',\'\'\'\'db_viewdefinition\'\'\'\',\'\'\'\'db_denydatareader\'\'\'\',\'\'\'\'db_deny_maas\'\'\'\');   \'\'      Select  * from #TEMP;   \'\r\n','Database role member usage for users  is correct\r\n','Database role member usage for users  is not correct\r\n','pass',NULL,NULL,'2026-02-11 17:17:14'),(1466,202602,48,27,'AA_SqlServer_220_2_Public Database Permissions','critical','PRIV','This test checks database permisions for public . Public is a special role and permissions should not be granted to public role.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP ( row varchar(500));          exec sp_MSforeachdb \'\'   USE [?]   iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'public\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND OBJECT_NAME(MAJOR_iD) NOT LiKE (\'\'\'\'%fn_cdc_get_net_changes_application_data%\'\'\'\')   AND NOT (OBJECT_SCHEMA_NAME(MAJOR_iD) = \'\'\'\'cdc\'\'\'\' and PERMiSSiON_NAME=\'\'\'\'SELECT\'\'\'\')   AND NOT (PERMiSSiON_NAME IN (\'\'\'\'REFERENCES\'\'\'\',\'\'\'\'SEND\'\'\'\',   \'\'\'\'VIEW ANY COLUMN ENCRYPTION KEY DEFINITION\'\'\'\',   \'\'\'\'VIEW ANY COLUMN MASTER KEY DEFINITION\'\'\'\' ) and OBJECT_SCHEMA_NAME(MAJOR_iD) IS NULL)   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select count(*) from #TEMP;   \'\r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP ( row varchar(500));          exec sp_MSforeachdb \'\'   USE [?]   iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'public\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND OBJECT_NAME(MAJOR_iD) NOT LiKE (\'\'\'\'%fn_cdc_get_net_changes_application_data%\'\'\'\')   AND NOT (OBJECT_SCHEMA_NAME(MAJOR_iD) = \'\'\'\'cdc\'\'\'\' and PERMiSSiON_NAME=\'\'\'\'SELECT\'\'\'\')   AND NOT (PERMiSSiON_NAME IN (\'\'\'\'REFERENCES\'\'\'\',\'\'\'\'SEND\'\'\'\',   \'\'\'\'VIEW ANY COLUMN ENCRYPTION KEY DEFINITION\'\'\'\',   \'\'\'\'VIEW ANY COLUMN MASTER KEY DEFINITION\'\'\'\' ) and OBJECT_SCHEMA_NAME(MAJOR_iD) IS NULL)   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select * from #TEMP;   \'','There are no permissions which are assigned to public.\r\n','There are some persmissions which are assigned to public\r\n','pass',NULL,NULL,'2026-02-11 17:17:15'),(1467,202602,48,28,'AA_SqlServer_220_Public Database Permissions','critical','PRIV','This test checks database permisions for public . Public is a special role and permissions should not be granted to public role.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      exec sp_msforeachdb \'\'   USE [?]     iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'public\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND OBJECT_NAME(MAJOR_iD) NOT LiKE (\'\'\'\'%fn_cdc_get_net_changes_application_data%\'\'\'\')   AND NOT (OBJECT_SCHEMA_NAME(MAJOR_iD) = \'\'\'\'cdc\'\'\'\' and PERMiSSiON_NAME=\'\'\'\'SELECT\'\'\'\')   AND NOT (PERMiSSiON_NAME IN (\'\'\'\'REFERENCES\'\'\'\',\'\'\'\'SEND\'\'\'\',   \'\'\'\'VIEW ANY COLUMN ENCRYPTION KEY DEFINITION\'\'\'\',   \'\'\'\'VIEW ANY COLUMN MASTER KEY DEFINITION\'\'\'\' ) and OBJECT_SCHEMA_NAME(MAJOR_iD) IS NULL)   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select count(*) from #TEMP;   \' \r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      exec sp_msforeachdb \'\'   USE [?]     iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'public\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND OBJECT_NAME(MAJOR_iD) NOT LiKE (\'\'\'\'%fn_cdc_get_net_changes_application_data%\'\'\'\')   AND NOT (OBJECT_SCHEMA_NAME(MAJOR_iD) = \'\'\'\'cdc\'\'\'\' and PERMiSSiON_NAME=\'\'\'\'SELECT\'\'\'\')   AND NOT (PERMiSSiON_NAME IN (\'\'\'\'REFERENCES\'\'\'\',\'\'\'\'SEND\'\'\'\',   \'\'\'\'VIEW ANY COLUMN ENCRYPTION KEY DEFINITION\'\'\'\',   \'\'\'\'VIEW ANY COLUMN MASTER KEY DEFINITION\'\'\'\' ) and OBJECT_SCHEMA_NAME(MAJOR_iD) IS NULL)   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select * from #TEMP;   \' \r\n','There are no permissions which are assigned to public.\r\n','There are some persmissions which are assigned to public\r\n','pass',NULL,NULL,'2026-02-11 17:17:15'),(1468,202602,48,29,'AA_SqlServer_230_Real person users','critical','ACCOUNT','All logins to the database should be made with AD groups, real person users should  not be connected database directly\r\n','','Select      count(*)   from      sys.server_principals    where      name like \'ODEABANK%.%\'      and is_disabled = 0   \r\n','== 0','','Select      name     from      sys.server_principals    where      name like \'ODEABANK%.%\'      and is_disabled = 0;\r\n','Real person users are not found in the logins\r\n','Some real person users are found in the logins\r\n','pass',NULL,NULL,'2026-02-11 17:17:15'),(1469,202602,48,30,'AA_SqlServer_240_2_guest Database Permissions','critical','ACCOUNT','This test checks database permisions for guest . guest is a special user and permissions should not be granted to guest user.\r\n','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP ( row varchar(500));\r\n\r\nexec sp_MSforeachdb \'\'\r\nUSE [?]\r\niNSERT iNTO #TEMP\r\nSELECT\r\n\'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +\r\n\'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +\r\n\'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +\r\n\'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )\r\nFROM\r\nsys.database_permissions\r\nWHERE\r\nUSER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'guest\'\'\'\' )\r\nAND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'\r\nAND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')\r\nAND STATE_DESC=\'\'\'\'GRANT\'\'\'\'\r\n;\r\n\'\'\r\nselect count(*) from #TEMP;\r\n\'','== 0','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP ( row varchar(500));\r\n\r\nexec sp_MSforeachdb \'\'\r\nUSE [?]\r\niNSERT iNTO #TEMP\r\nSELECT\r\n\'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +\r\n\'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +\r\n\'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +\r\n\'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )\r\nFROM\r\nsys.database_permissions\r\nWHERE\r\nUSER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'guest\'\'\'\' )\r\nAND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'\r\nAND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')\r\nAND STATE_DESC=\'\'\'\'GRANT\'\'\'\'\r\n;\r\n\'\'\r\nselect * from #TEMP;\r\n\'','There are no permissions which are assigned to guest.\r\n','There are some persmissions which are assigned to guest\r\n','pass',NULL,NULL,'2026-02-11 17:17:15'),(1470,202602,48,31,'AA_SqlServer_240_guest Database Permissions','critical','PRIV','This test checks database permisions for guest . guest is a special user and permissions should not be granted to guest user.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      exec sp_msforeachdb \'\'   USE [?]     iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'guest\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select count(*) from #TEMP;   \' \r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      exec sp_msforeachdb \'\'   USE [?]     iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'guest\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select  *  from #TEMP;   \' \r\n','There are no permissions which are assigned to guest.\r\n','There are some persmissions which are assigned to guest\r\n','pass',NULL,NULL,'2026-02-11 17:17:15'),(1471,202602,48,32,'AA_SqlServer_250_Database Role members for guest','critical','PRIV','This test checks database role members for guest  user. Database roles  could not be assigned to guest role.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      EXEC sp_MSforeachdb \'\' USE [?]    INSERT INTO #TEMP   SELECT \'\'\'\'DB Name : \'\'\'\'+Cast (DB_NAME() as varchar)+\'\'\'\' Role Name : \'\'\'\'+USER_NAME(role_principal_id)  +\'\'\'\' User Name \'\'\'\'+  USER_NAME(member_principal_id)    from  sys.database_role_members   	Where     USER_NAME(member_principal_id)  = \'\'\'\'guest\'\'\'\'     ;   \'\'      Select count(*)  from #TEMP;   \'\r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      EXEC sp_MSforeachdb \'\' USE [?]    INSERT INTO #TEMP   SELECT \'\'\'\'DB Name : \'\'\'\'+Cast (DB_NAME() as varchar)+\'\'\'\' Role Name : \'\'\'\'+USER_NAME(role_principal_id)  +\'\'\'\' User Name \'\'\'\'+  USER_NAME(member_principal_id)    from  sys.database_role_members   	Where     USER_NAME(member_principal_id)  = \'\'\'\'guest\'\'\'\'     ;   \'\'      Select  *  from #TEMP;   \'\r\n','Database role member usage for guest user  is correct\r\n','Database role member usage for guest user  is not correct\r\n','pass',NULL,NULL,'2026-02-11 17:17:15'),(1472,202602,48,33,'AA_SqlServer_260_SQL Logins with Null Password','critical','ACCOUNT','This test checks sql logins with null password. SQL Logins should not have null passwords.\r\n','','SELECT      count(name)   from      sys.sql_logins    WHERE      PWDCOMPARE(\'\', password_hash)= 1\r\n','== 0','','SELECT      name    from      sys.sql_logins    WHERE      PWDCOMPARE(\'\', password_hash)= 1   \r\n','There are no sql logins with null paswords\r\n','There are some sql logins with null passwords.\r\n','pass',NULL,NULL,'2026-02-11 17:17:15'),(1473,202602,48,34,'AA_SqlServer_270_SQL Logins with username and passwords are equal','critical','ACCOUNT','This test checks sql login password which are egual to username. Username and password must be different for SQL logins.\r\n','','SELECT      count(name)   from      sys.sql_logins    WHERE      PWDCOMPARE(name,password_hash)=1 \r\n','== 0','','SELECT      name    from      sys.sql_logins    WHERE      PWDCOMPARE(name,password_hash)=1    \r\n','There is no SQL login name which is equal to password.\r\n','There are some sql logins whose passwords are egual to usernames.\r\n','pass',NULL,NULL,'2026-02-11 17:17:15'),(1474,202602,48,35,'AA_SqlServer_280_No Sample Databases','critical','CONFIG','This test checks whether the sample databases created optionally on installation are present.  These sample databases contain many default permissions, and can be used as an entry point to your systems. \r\n','','select      count(name)    from      sys.databases    where      name in (       \'AdventureWorks\', \'AdventureWorksDW\',        \'Northwind\', \'Pubs\'     )   \r\n','== 0','','select      name    from      sys.databases    where      name in (       \'AdventureWorks\', \'AdventureWorksDW\',        \'Northwind\', \'Pubs\'     )   \r\n','There are no sample databases in the server\r\n','There are some sample databases in the server\r\n','pass',NULL,NULL,'2026-02-11 17:17:19'),(1475,202602,48,43,'AA_SqlServer_350_User Password Policy Is Checked','critical','ACCOUNT','This test checks that CHECK_POLICY is enabled for all users.  Enabling CHECK_POLICY ensures that Windows passwords policies are enforced.','','select count(*) from sys.sql_logins  \r\nwhere \r\nis_policy_checked=0 and\r\nname not like \'##%\'','== 0','','select name from sys.sql_logins  \r\nwhere \r\nis_policy_checked=0 and\r\nname not like \'##%\'','CHECK_POLICY is enabled for all users','CHECK_POLICY is not enabled for all users','pass',NULL,NULL,'2026-02-11 17:17:19'),(1476,202602,48,44,'AA_SqlServer_360_CHECK_EXPIRATION Is Checked','critical','ACCOUNT','This test checks that CHECK_EXPIRATION is enabled for all users.  Passwords that have been in use for long periods of time are likely to become known to unauthorized users.\r\n','','select count(*) from sys.sql_logins     where    is_expiration_checked=0 and   name not like \'##%\'\r\n','== 0','','select name from sys.sql_logins     where    is_expiration_checked=0 and   name not like \'##%\'\r\n','CHECK_EXPIRATION is enabled for all users\r\n','CHECK_EXPIRATION is not enabled for all users\r\n','fail','name\n----\n\'sa\'',NULL,'2026-02-11 17:17:19'),(1477,202602,48,22,'AA_SqlServer_170_Windows Authentication','major','AUTH','This test checks that the authentication mode is set to Windows authentication only.  Windows provides a more robust authentication mechanism than SQL Server authentication.','',' SELECT cast( SERVERPROPERTY(\'IsIntegratedSecurityOnly\') as int) ','==1','','SELECT cast( SERVERPROPERTY(\'IsIntegratedSecurityOnly\') as varchar)','The authentication mode is set to Windows authentication only. ','The authentication mode is not set to Windows authentication only.','fail','\n---\n\'0\'',NULL,'2026-02-11 17:17:19'),(1478,202602,48,23,'AA_SqlServer_180_No Guest User Accounts','major','ACCOUNT','This test checks for the existence of guest user accounts with CONNECT permission in database other than master, msdb and tempdb.  This test also exclude databases that are flagged as distributor. If the GUEST user exists and a specific login has not been granted to a database, a login will be mapped to GUEST. The presence of the GUEST user allows all logins to access the database.\r\n','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP  ( row int);\r\n\r\nEXEC sp_MSforeachdb \'\' USE [?]\r\n	INSERT INTO #TEMP\r\n	SELECT count(*) \r\n	FROM sys.database_permissions\r\n	WHERE [grantee_principal_id] = DATABASE_PRINCIPAL_ID(\'\'\'\'guest\'\'\'\')\r\n	AND [state_desc] LIKE \'\'\'\'GRANT%\'\'\'\'\r\n	AND [permission_name] = \'\'\'\'CONNECT\'\'\'\'\r\n	AND DB_NAME() NOT IN (\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'msdb\'\'\'\') ;\r\n\'\'\r\n\r\nSelect sum(row) from #TEMP;\r\ndrop table #TEMP;\r\n\'','== 0','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP  ( row varchar(500));\r\n\r\nEXEC sp_MSforeachdb \'\' USE  [?] \r\n	INSERT INTO #TEMP\r\n	SELECT \'\'\'\' DB NAME : \'\'\'\' + Cast (DB_NAME() as varchar) + \'\'\'\' guest user has CONNECT permission \'\'\'\'\r\n	FROM sys.database_permissions\r\n	WHERE [grantee_principal_id] = DATABASE_PRINCIPAL_ID(\'\'\'\'guest\'\'\'\')\r\n	AND [state_desc] LIKE \'\'\'\'GRANT%\'\'\'\'\r\n	AND [permission_name] = \'\'\'\'CONNECT\'\'\'\'\r\n	AND DB_NAME() NOT IN (\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'msdb\'\'\'\') ;\r\n\'\'\r\n\r\nSelect * from #TEMP;\r\ndrop table #TEMP;\r\n\'','There is no guest user with CONNECT permission. ','There are   guest users with CONNECT permission. Remove these users','pass',NULL,NULL,'2026-02-11 17:17:20'),(1479,202602,48,36,'AA_SqlServer_290_2_No Permissions with GRANT Option','major','PRIV','This test checks database permisions  with grant option. No permission with grant option should be defined in the database.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP ( row varchar(500));      exec sp_MSforeachdb \'\'   USE [?]   iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   STATE_DESC like \'\'\'\'%WITH_GRANT%\'\'\'\'   ;   \'\'   select count(*) from #TEMP;   \'\r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP ( row varchar(500));      exec sp_MSforeachdb \'\'   USE [?]   iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   STATE_DESC like \'\'\'\'%WITH_GRANT%\'\'\'\'   ;   \'\'   select * from #TEMP;   \'\r\n','There are no permissions with grant option.\r\n','There are some persmissions  with grant option.\r\n','pass',NULL,NULL,'2026-02-11 17:17:20'),(1480,202602,48,37,'AA_SqlServer_290_No Permissions with GRANT Option','major','PRIV','','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP  ( row varchar(500));\r\n\r\nexec sp_msforeachdb \'\'\r\nUSE [?]  \r\niNSERT iNTO #TEMP\r\nSELECT\r\n\'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +\r\n\'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +\r\n\'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +\r\n\'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )\r\nFROM\r\nsys.database_permissions\r\nWHERE\r\nSTATE_DESC like \'\'\'\'%WITH_GRANT%\'\'\'\'\r\n;\r\n\'\'\r\nselect  count(*)  from #TEMP;\r\n\' ','== 0','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP  ( row varchar(500));\r\n\r\nexec sp_msforeachdb \'\'\r\nUSE [?]  \r\niNSERT iNTO #TEMP\r\nSELECT\r\n\'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +\r\n\'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +\r\n\'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +\r\n\'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )\r\nFROM\r\nsys.database_permissions\r\nWHERE\r\nSTATE_DESC like \'\'\'\'%WITH_GRANT%\'\'\'\'\r\n;\r\n\'\'\r\nselect * from #TEMP;\r\n\' ','There are no permissions with grant option.\r\n','There are some persmissions  with grant option.\r\n','pass',NULL,NULL,'2026-02-11 17:17:20'),(1481,202602,48,40,'AA_SqlServer_320_No Access to Registry Access Extended procedures','major','PRIV','This test checks for the existence of, and user permissions on, registry access extended stored procedures.  Either these procedures should be completely dropped, or access to them should be strictly limited. xp_reg%,xp_instance_reg%\r\n','','SELECT \r\ncount(*) \r\nFROM \r\n  [master].sys.system_objects o \r\n  JOIN [master].sys.database_permissions p ON o.object_id = p.major_id \r\n  JOIN [master].sys.database_principals u ON p.grantee_principal_id = u.principal_id \r\nWHERE \r\n( o.name LIKE \'xp_reg%\' OR o.name LIKE \'xp_instance_reg%\')\r\n  AND p.type = \'EX\' ','== 0','','SELECT \r\n  \'Principal : \'+u.name  COLLATE DATABASE_DEFAULT +\r\n  \' Extended Procedure Name : \'+o.name COLLATE DATABASE_DEFAULT +\r\n  \' Type : \'+ u.type_desc COLLATE DATABASE_DEFAULT \r\nFROM \r\n  [master].sys.system_objects o \r\n  JOIN [master].sys.database_permissions p ON o.object_id = p.major_id \r\n  JOIN [master].sys.database_principals u ON p.grantee_principal_id = u.principal_id \r\nWHERE \r\n( o.name LIKE \'xp_reg%\' OR o.name LIKE \'xp_instance_reg%\')\r\n  AND p.type = \'EX\' ','There are no permissions on registry access extended stored procedures\r\n','There are some persmissions permissions on registry access extended stored procedures\r\n','fail','\n---------------------------------------------------------------------------------------\n\'Principal : public Extended Procedure Name : xp_instance_regread Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_regread Type : DATABASE_ROLE\'',NULL,'2026-02-11 17:17:22'),(1482,202602,48,41,'AA_SqlServer_330_Revoke public login from SQL Server agent proxy account','major','PRIV','The public database role contains every user in the msdb database. SQL Agent proxies   define a security context in which a job step can run.Granting access to SQL Agent proxies for the public role would allow all users to utilize the proxy which may have high privileges. This would likely break the principle of least   privileges.\r\n','','SELECT count(*)\r\nFROM msdb.dbo.sysproxylogin spl\r\nJOIN sys.database_principals dp\r\nON dp.sid = spl.sid\r\nJOIN msdb.dbo.sysproxies sp\r\nON sp.proxy_id = spl.proxy_id\r\nWHERE principal_id = USER_ID(\'public\')','== 0','','SELECT \'proxyname : \'+CAST(sp.name  as varchar)\r\nFROM msdb.dbo.sysproxylogin spl\r\nJOIN sys.database_principals dp\r\nON dp.sid = spl.sid\r\nJOIN msdb.dbo.sysproxies sp\r\nON sp.proxy_id = spl.proxy_id\r\nWHERE principal_id = USER_ID(\'public\')','There are no public permissions on SQL Server agent proxy account\r\n','There are some public permissions on SQL Server agent proxy account\r\n','pass',NULL,NULL,'2026-02-11 17:17:22'),(1483,202602,48,42,'AA_SqlServer_340_No Individual User Access To syscomment and sp_helptext','minor','PRIV','This test checks for grants on SYSCOMMENTS.TEXT.  Such grants allow any user to read the text comments associated with a database object, making the text publicly viewable.\r\n','','SELECT count(*)\r\nFROM msdb.dbo.sysproxylogin spl\r\nJOIN sys.database_principals dp\r\nON dp.sid = spl.sid\r\nJOIN msdb.dbo.sysproxies sp\r\nON sp.proxy_id = spl.proxy_id\r\nWHERE principal_id = USER_ID(\'public\')\r\n','== 0','','SELECT count(*)\r\nFROM msdb.dbo.sysproxylogin spl\r\nJOIN sys.database_principals dp\r\nON dp.sid = spl.sid\r\nJOIN msdb.dbo.sysproxies sp\r\nON sp.proxy_id = spl.proxy_id\r\nWHERE principal_id = USER_ID(\'public\')','There are no public permissions on SQL Server agent proxy account','There are some public permissions on SQL Server agent proxy account','pass',NULL,NULL,'2026-02-11 17:17:22'),(1484,202602,48,10,'AA_SqlServer_050_Disable Ad hoc distributed queries option','major','CONFIG','Adhoc queries allow undefined access to remote database sources.  Access to untrusted databases could result in execution of malicious applications and/or a compromise of local data confidentiality and integrity. The DBA will configure the database to disable access from the database to objects stored externally to the database on the local host unless mission and/or operationally required and documented.\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Ad Hoc Distributed Queries\'','== 0','','SELECT name + \' Value : \'+ cast( value as varchar ) + \' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'Ad Hoc Distributed Queries\'','Ad Hoc Distributed Queries is disabled','Ad Hoc Distributed Queries is not disabled. Disable this option','pass',NULL,NULL,'2026-02-11 17:17:23'),(1485,202602,48,11,'AA_SqlServer_060_Disable CLR option','major','CONFIG','The clr_enabled parameter configures SQL Server to allow or disallow use of Command Language Runtime objects.  CLR objects is managed code that integrates with the .NET Framework.  This is a more secure method than external stored procedures, although it still contains some risk.  Where no external application execution requirements are required, disallowing use of any improves the overall security posture of the database.\r\n\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'clr enabled\'','== 0','','SELECT name + \' Value : \'+ cast( value as varchar ) + \' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'clr enabled\'','CLR option is disabled','CLR option is not disabled. Disable this option','pass',NULL,NULL,'2026-02-11 17:17:23'),(1486,202602,48,12,'AA_SqlServer_070_Disable Cross db ownership chaining option','major','CONFIG','Cross database ownership chaining allows permissions to objects to be assigned by users other than the Information Owner.  This allows access to objects that are not authorized directly by the Information Owner based on job functions defined by the owner.  Unauthorized access may lead to a compromise of data integrity or confidentiality. The DBA will ensure database privileges are assigned via roles and not directly assigned to database accounts. Privileges may be assigned directly to application owner accounts where the DBMS does not otherwise support access via roles.\r\n\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'cross db ownership chaining\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'cross db ownership chaining\'','Cross db ownership chaining  option is disabled','Cross db ownership chaining option  is not disabled. Disable this option','pass',NULL,NULL,'2026-02-11 17:17:23'),(1487,202602,48,13,'AA_SqlServer_080_Disable Database Mail XPs option','major','CONFIG','SQL Mail accepts incoming database commands via email. This can introduce malicious codes or viruses into the SQL server environment.','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Database Mail XPs\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \'Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'Database Mail XPs\'','Database Mail XPs option is disabled','Database Mail XPs option  is not disabled. Disable this option','pass',NULL,NULL,'2026-02-11 17:17:23'),(1488,202602,48,14,'AA_SqlServer_100_Disable xp_cmdshell Server Configuration option','major','CONFIG','The xp_cmdshell extended stored procedures allows execution of host executables outside the controls of database access permissions.  This access may be exploited by malicious users who have compromised the integrity of the SQL Server database process to control the host operating system to perpetrate additional malicious activity. The DBA should disable the use of external procedures by the database unless it is mission critical or operationally required','','SELECT CAST(value as int) +\r\n       CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'xp_cmdshell\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) +\r\n\' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'xp_cmdshell\'','xp_cmdshell Server Configuration option is disabled','xp_cmdshell Server Configuration option is not disabled. This option must be disabled','pass',NULL,NULL,'2026-02-11 17:17:23'),(1489,202602,48,15,'AA_SqlServer_110_Disable Remote Access option','major','CONFIG','The remote access option controls the execution of local stored procedures on remote\r\nservers or remote stored procedures on local server.Functionality can be abused to launch a Denial-of-Service (DoS) attack on remote servers\r\nby off-loading query processing to a target.\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'remote access\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \' Value in use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'remote access\'','Remote Access option is disabled','Remote Access option  is not disabled. Disable this option','fail','\n------------------------------------------\n\'remote access Value : 1 Value in use : 1\'',NULL,'2026-02-11 17:17:23'),(1490,202602,48,16,'AA_SqlServer_120_Disable Remote Admin Connections option','major','CONFIG','The remote admin connections option controls whether a client application on a remote\r\ncomputer can use the Dedicated Administrator Connection (DAC).The Dedicated Administrator Connection (DAC) lets an administrator access a running\r\nserver to execute diagnostic functions or Transact-SQL statements, or to troubleshoot\r\nproblems on the server, even when the server is locked or running in an abnormal state\r\nand not responding to a SQL Server Database Engine connection. In a cluster scenario, the\r\nadministrator may not actually be logged on to the same node that is currently hosting the\r\nSQL Server instance and thus is considered \"remote\". Therefore, this setting should usually\r\nbe enabled (1) for SQL Server failover clusters; otherwise it should be disabled (0) which is\r\nthe default.\r\n','','execute sp_executesql N\'\r\n\r\nDECLARE @x int;\r\n\r\nSELECT @x=isnull(CAST(value as int) + CAST(value_in_use as int),100)\r\nFROM sys.configurations\r\nWHERE name = \'\'remote admin connections\'\'\r\n\r\nIF @x = 100\r\n       SELECT 0 ;\r\nELSE \r\n   SELECT CAST(value as int) + CAST(value_in_use as int) \r\n   FROM sys.configurations\r\n   WHERE name = \'\'remote admin connections\'\'\r\n\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'remote admin connections\'','Remote Admin Connections option is disabled','Remote Admin Connections option  is not disabled. Disable this option','pass',NULL,NULL,'2026-02-11 17:17:23'),(1491,202602,48,19,'AA_SqlServer_150_Disable database trustworthy status','major','CONFIG','The TRUSTWORTHY database setting restricts access to database resources by databases that contain assemblies with the EXTERNAL_ACCESS or UNSAFE permission settings and modules that use impersonation of accounts assigned elevated privileges.  Unless all assemblies and code for the database have been reviewed, especially in the case where databases have been detached and attached between server instances, leaving the TRUSTWORTHY status to off can help reduce threats from malicious assemblies or modules.','','SELECT count(name)\r\nFROM sys.databases\r\nWHERE is_trustworthy_on = 1\r\nAND name != \'msdb\';','== 0','','SELECT name\r\nFROM sys.databases\r\nWHERE is_trustworthy_on = 1\r\nAND name != \'msdb\';','database trustworthy status is disabled','database trustworthy status is not disabled. Disable this option','pass',NULL,NULL,'2026-02-11 17:17:23'),(1492,202602,48,20,'Checkpoint başarıyla oluşturuldu.','major','CONFIG','This test checks if SQL Server Instance is not advertised by the SQL Server Browser service. To maintain a higher level of protection for database instances, we recommend that SQL Server Instance be hidden when it is not required. Please note that this test does not include Clustered Instances as turning off this feature may cause issues with the Clustered environment.\r\n\r\n','','execute sp_executesql N\'\r\n\r\nDECLARE @getValue INT\r\n\r\nEXEC master.sys.xp_instance_regread\r\n@rootkey = N\'\'HKEY_LOCAL_MACHINE\'\',\r\n@key = N\'\'SOFTWARE\\Microsoft\\Microsoft SQL Server\\MSSQLServer\\SuperSocketNetLib\'\',\r\n@value_name = N\'\'HideInstance\'\',\r\n@value = @getValue OUTPUT\r\n\r\nSELECT isnull(@getvalue,0)\'','==1','','execute sp_executesql N\'\r\n\r\nDECLARE @getValue INT\r\n\r\nEXEC master.sys.xp_instance_regread\r\n@rootkey = N\'\'HKEY_LOCAL_MACHINE\'\',\r\n@key = N\'\'SOFTWARE\\Microsoft\\Microsoft SQL Server\\MSSQLServer\\SuperSocketNetLib\'\',\r\n@value_name = N\'\'HideInstance\'\',\r\n@value = @getValue OUTPUT\r\n\r\nSELECT isnull(@getvalue,0)\'','SQL Server Instance is  hidden.\r\n','SQL Server Instance is not hidden. Hide the instance','fail','\n-\n0',NULL,'2026-02-11 17:17:25'),(1493,202602,48,21,'AA_SqlServer_160_Hide SQL Server Instance','major','CONFIG','This test checks if SQL Server Instance is not advertised by the SQL Server Browser service. To maintain a higher level of protection for database instances, we recommend that SQL Server Instance be hidden when it is not required. Please note that this test does not include Clustered Instances as turning off this feature may cause issues with the Clustered environment.\r\n\r\n','','execute sp_executesql N\'\r\n\r\nDECLARE @getValue INT\r\n\r\nEXEC master.sys.xp_instance_regread\r\n@rootkey = N\'\'HKEY_LOCAL_MACHINE\'\',\r\n@key = N\'\'SOFTWARE\\Microsoft\\Microsoft SQL Server\\MSSQLServer\\SuperSocketNetLib\'\',\r\n@value_name = N\'\'HideInstance\'\',\r\n@value = @getValue OUTPUT\r\n\r\nSELECT isnull(@getvalue,0)\'','==1','','execute sp_executesql N\'\r\n\r\nDECLARE @getValue INT\r\n\r\nEXEC master.sys.xp_instance_regread\r\n@rootkey = N\'\'HKEY_LOCAL_MACHINE\'\',\r\n@key = N\'\'SOFTWARE\\Microsoft\\Microsoft SQL Server\\MSSQLServer\\SuperSocketNetLib\'\',\r\n@value_name = N\'\'HideInstance\'\',\r\n@value = @getValue OUTPUT\r\n\r\nSELECT isnull(@getvalue,0)\'','SQL Server Instance is  hidden.','SQL Server Instance is not hidden. Hide the instance','fail','\n-\n0',NULL,'2026-02-11 17:17:25'),(1494,202602,48,38,'AA_SqlServer_300_No Access To General Extended procedures','major','PRIV','This test checks for the existence of, and user permissions on, extended stored procedures.  Either these procedures should be completely dropped, or access to them should be strictly limited. xp_cmdshell, xp_enumgroups, xp_grantlogin ,xp_logevent, xp_logininfo,    xp_msver, xp_revokelogin, xp_sprintf, xp_sqlmaint, xp_sscanf\r\n','','SELECT \r\ncount(*) \r\nFROM \r\n  [master].sys.system_objects o \r\n  JOIN [master].sys.database_permissions p ON o.object_id = p.major_id \r\n  JOIN [master].sys.database_principals u ON p.grantee_principal_id = u.principal_id \r\nWHERE \r\n    o.name in ( \r\n	\'xp_cmdshell\', \r\n	\'xp_enumgroups\', \r\n    \'xp_grantlogin\' ,\r\n	\'xp_logevent\', \r\n	\'xp_logininfo\', \r\n    \'xp_msver\', \r\n	\'xp_revokelogin\', \r\n	\'xp_sprintf\', \r\n    \'xp_sqlmaint\', \r\n	\'xp_sscanf\' )\r\n  AND p.type = \'EX\' ','== 0','','SELECT \r\n  \'Principal : \'+u.name  COLLATE DATABASE_DEFAULT +\r\n  \' Extended Procedure Name : \'+o.name COLLATE DATABASE_DEFAULT +\r\n  \' Type : \'+ u.type_desc COLLATE DATABASE_DEFAULT \r\nFROM \r\n  [master].sys.system_objects o \r\n  JOIN [master].sys.database_permissions p ON o.object_id = p.major_id \r\n  JOIN [master].sys.database_principals u ON p.grantee_principal_id = u.principal_id \r\nWHERE \r\n    o.name in ( \r\n	\'xp_cmdshell\', \r\n	\'xp_enumgroups\', \r\n    \'xp_grantlogin\' ,\r\n	\'xp_logevent\', \r\n	\'xp_logininfo\', \r\n    \'xp_msver\', \r\n	\'xp_revokelogin\', \r\n	\'xp_sprintf\', \r\n    \'xp_sqlmaint\', \r\n	\'xp_sscanf\' )\r\n  AND p.type = \'EX\' ','There are no permissions on general extended stored procedures\r\n','There are some persmissions permissions on general extended stored procedures.\r\n','fail','\n----------------------------------------------------------------------------------\n\'Principal : public Extended Procedure Name : xp_msver Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_sscanf Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_revokelogin Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_grantlogin Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_sprintf Type : DATABASE_ROLE\'',NULL,'2026-02-11 17:17:25'),(1495,202602,48,39,'AA_SqlServer_310_No Access to OLE Automation procedures','major','CONFIG','This test checks for the existence of,and user permissions on OLE automation extended stored procedures.  Either these procedures should be completely dropped, or access to them should be strictly limited.      \r\n','','SELECT CAST(value as int) +\r\n       CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Ole Automation Procedures\'   \r\n','== 0','','SELECT CAST(value as int) +\r\n       CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Ole Automation Procedures\'\r\n  \r\n','OLE Automation procedures  option is disabled\r\n','OLE Automation procedures  option  is not disabled. Disable this option\r\n','pass',NULL,NULL,'2026-02-11 17:17:25'),(1496,202602,48,17,'AA_SqlServer_130_Disable Ole Automation Procedures option','minor','CONFIG','This test checks if Ole Automation Procedures option is disabled. Ole Automation Procedures option allows SQL Server users to execute functions external to SQL Server. Enabling this option will increase the attack surface of SQL Server and allow users to execute functions in the security context of SQL Server. We recommend that the Ole Automation Procedures option to be disabled when it is not document as a requirement.\r\n\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Ole Automation Procedures\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \'Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'Ole Automation Procedures\'',' Ole Automation Procedures option is disabled',' Ole Automation Procedures option  is not disabled. Disable this option','pass',NULL,NULL,'2026-02-11 17:17:25'),(1497,202602,48,18,'AA_SqlServer_140_Disable Scan for Startup Procedures option','minor','CONFIG','This test checks if scan for startup procedures is disabled. This feature causes SQL Server to scan for and automatically run all stored procedures that are set to execute upon service startup. If there are no user-defined stored procedures set to execute when SQL server starts, we recommend this feature to be disabled.\r\n\r\n','','SELECT CAST(value as int) +\r\n       CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'scan for startup procs\'','== 0','','SELECT name + \' value : \'+cast( value as varchar ) +\r\n\' value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'scan for startup procs\'','Scan for Startup Procedures  option is disabled','Scan for Startup Procedures  option  is not disabled. Disable this option','pass',NULL,NULL,'2026-02-11 17:17:25'),(1498,202602,48,9,'AA_SqlServer_040_Rename the sa Login Account','major','ACCOUNT','The \'sa\' account is a well-known account.  Well-known account names provide an easier target for attack.  Renaming the sa account helps reduce the risk of an attack to this built-in account.','','SELECT count(*)\r\nFROM sys.server_principals\r\nWHERE sid = 0x01 and name=\'sa\'','== 0','','SELECT name\r\nFROM sys.server_principals\r\nWHERE sid = 0x01','sa Login Account is renamed','sa Login Account is not renamed. Rename this account','fail','name\n----\n\'sa\'',NULL,'2026-02-11 17:17:25'),(1499,202602,49,24,'AA_SqlServer_190_Public server role permision','critical','PRIV','public is a special fixed server role containing all logins. Unlike other fixed server roles,\r\npermissions can be changed for the public role. In keeping with the principle of least\r\nprivileges, the public server role should not be used to grant permissions at the server\r\nscope as these would be inherited by all users.\r\n\r\nEvery SQL Server login belongs to the public role and cannot be removed from this role.\r\nTherefore, any permissions granted to this role will be available to all logins unless they\r\nhave been explicitly denied to specific logins or user-defined server roles.','','Select \r\n  count (permission_name) \r\nfrom \r\n  sys.server_permissions \r\nwhere \r\n  SUSER_NAME(grantee_principal_id) = \'public\' \r\n  and permission_name not in (\'VIEW ANY DATABASE\', \'CONNECT\')\r\n','== 0','','Select \r\n  permission_name \r\nfrom \r\n  sys.server_permissions \r\nwhere \r\n  SUSER_NAME(grantee_principal_id) = \'public\' \r\n  and permission_name not in (\'VIEW ANY DATABASE\', \'CONNECT\')\r\n\r\n','No server permissions are granted to public.','Some server permissions are granted to public.','pass',NULL,NULL,'2026-02-11 17:32:31'),(1500,202602,49,5,'AA_SqlServer_010_Supported SQL Server version','critical','PATCH','This test checks whether your current SQL Server version is a vendor-supported version.  Microsoft does not provide security fixes or software updates to unsupported software versions','','SELECT cast(ISNULL(SERVERPROPERTY(\'ProductMajorVersion\'),0) as int)   ','>=11','','SELECT \'Product Major version \' +  cast(ISNULL(SERVERPROPERTY(\'ProductMajorVersion\'),\'Null\' ) as  char ) ','The version of the database is acceptable.','The version of the database is not acceptable. The database version should SQL Sever 2012 or upper.','pass',NULL,NULL,'2026-02-11 17:32:31'),(1501,202602,49,6,'AA_SqlServer_020_Disable the sa Login Account','critical','ACCOUNT','This test checks if the \'sa\' Login Account is disabled. The sa account is a widely known and often widely used SQL Server account with sysadmin privileges. Enforcing this control reduces the probability of an attacker executing brute force attacks against a well-known principal.','','SELECT  count(*)\r\nFROM sys.server_principals\r\nWHERE sid = 0x01\r\nAND is_disabled = 0','== 0','','SELECT \'sa user name : \'+ name+\' is disabled : \' +  cast( is_disabled as char)\r\nFROM sys.server_principals\r\nWHERE sid = 0x01\r\n','sa Login Account is disabled','Disable sa login account','fail','\n----------------------------------------------------------------\n\'sa user name : sa is disabled : 0                             \'',NULL,'2026-02-11 17:32:31'),(1502,202602,49,7,'AA_SqlServer_025_sa Change password','critical','ACCOUNT','This test checks that sa password change . The sa password should be changed in every two days','','select datediff( day,  modify_date , getdate() ) FROM sys.server_principals\r\nWHERE sid = 0x01  ','< 3','','select datediff( day,  modify_date , getdate() ) FROM sys.server_principals\r\nWHERE sid = 0x01 ','sa password was changed in two days','','fail','\n--\n28',NULL,'2026-02-11 17:32:31'),(1503,202602,49,8,'AA_SqlServer_030_Ensure no Login exists with sa Login Account','critical','ACCOUNT','The \'sa\' account is a well-known account.  Well-known account names provide an easier target for attack. The lack of the sa account helps reduce the risk of an attack to this built-in account.','','SELECT count(*)\r\nFROM sys.server_principals\r\nWHERE name = \'sa\'','== 0','','SELECT name\r\nFROM sys.server_principals\r\nWHERE name = \'sa\'','There is no the sa account in the database.','There is the sa Login account in the database.Drop this user or rename et.','fail','name\n----\n\'sa\'',NULL,'2026-02-11 17:32:31'),(1504,202602,49,25,'AA_SqlServer_200_Fixed Server Role members for users','critical','PRIV','This test checks fixed server roles for analyst , developers and real persons. Fixed server roles could not be assigned to real person users ( Developer, Analyst users ) . Only Admin can use fixed server role.\r\n','','Select     count(*)   from      sys.server_role_members    where      (       suser_name(member_principal_id) like \'ODEABANK%.%\'    	AND       suser_name(member_principal_id) not like \'%admin%\'         AND       suser_name(member_principal_id) not like \'%t.coban%\'     )      OR (       suser_name(member_principal_id) like \'ODEABANK\\Cyberark_Intertech%\'     )      \r\n','== 0','','Select      suser_name(role_principal_id) + \'   \' + suser_name(member_principal_id)    from      sys.server_role_members    where      (       suser_name(member_principal_id) like \'ODEABANK%.%\'    	AND       suser_name(member_principal_id) not like \'%admin%\'         AND       suser_name(member_principal_id) not like \'%t.coban%\'     )      OR (       suser_name(member_principal_id) like \'ODEABANK\\Cyberark_Intertech%\'     )          \r\n','Fixed Server role usage is correct.\r\n','Fixed Server role usage is not correct.\r\n','pass',NULL,NULL,'2026-02-11 17:32:31'),(1505,202602,49,26,'AA_SqlServer_210_Database Role members for users','critical','PRIV','This test checks database role members for analyst and real person users. Database roles  except  db_datareader could not be assigned to real person users ( Developer, Analyst users ) .\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      EXEC sp_MSforeachdb \'\' USE [?]    INSERT INTO #TEMP   SELECT \'\'\'\'DB Name : \'\'\'\'+Cast (DB_NAME() as varchar)+\'\'\'\' Role Name : \'\'\'\'+USER_NAME(role_principal_id)  +\'\'\'\' User Name \'\'\'\'+  USER_NAME(member_principal_id)    from  sys.database_role_members   	Where   	(   	( USER_NAME(member_principal_id)  like \'\'\'\'%ODEABANK%.%\'\'\'\'  and   USER_NAME(member_principal_id)  not like \'\'\'\'%admin%\'\'\'\' )     	OR   	  (suser_name(member_principal_id) like \'\'\'\'%ODEABANK%Cyberark%\'\'\'\')       )    	AND   	DB_NAME() <> \'\'\'\'master\'\'\'\' and   	USER_NAME(role_principal_id) not in (\'\'\'\'db_datareader\'\'\'\',\'\'\'\'db_viewdefinition\'\'\'\',\'\'\'\'db_denydatareader\'\'\'\',\'\'\'\'db_deny_maas\'\'\'\');   \'\'      Select  count(*)  from #TEMP;   \'\r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      EXEC sp_MSforeachdb \'\' USE [?]    INSERT INTO #TEMP   SELECT \'\'\'\'DB Name : \'\'\'\'+Cast (DB_NAME() as varchar)+\'\'\'\' Role Name : \'\'\'\'+USER_NAME(role_principal_id)  +\'\'\'\' User Name \'\'\'\'+  USER_NAME(member_principal_id)    from  sys.database_role_members   	Where   (   	( USER_NAME(member_principal_id)  like \'\'\'\'%ODEABANK%.%\'\'\'\'  and   USER_NAME(member_principal_id)  not like \'\'\'\'%admin%\'\'\'\' )     	OR   	(suser_name(member_principal_id) like \'\'\'\'%ODEABANK%Cyberark%\'\'\'\')   )    	AND   	DB_NAME() <> \'\'\'\'master\'\'\'\' and   	USER_NAME(role_principal_id) not in  (\'\'\'\'db_datareader\'\'\'\',\'\'\'\'db_viewdefinition\'\'\'\',\'\'\'\'db_denydatareader\'\'\'\',\'\'\'\'db_deny_maas\'\'\'\');   \'\'      Select  * from #TEMP;   \'\r\n','Database role member usage for users  is correct\r\n','Database role member usage for users  is not correct\r\n','pass',NULL,NULL,'2026-02-11 17:32:31'),(1506,202602,49,27,'AA_SqlServer_220_2_Public Database Permissions','critical','PRIV','This test checks database permisions for public . Public is a special role and permissions should not be granted to public role.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP ( row varchar(500));          exec sp_MSforeachdb \'\'   USE [?]   iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'public\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND OBJECT_NAME(MAJOR_iD) NOT LiKE (\'\'\'\'%fn_cdc_get_net_changes_application_data%\'\'\'\')   AND NOT (OBJECT_SCHEMA_NAME(MAJOR_iD) = \'\'\'\'cdc\'\'\'\' and PERMiSSiON_NAME=\'\'\'\'SELECT\'\'\'\')   AND NOT (PERMiSSiON_NAME IN (\'\'\'\'REFERENCES\'\'\'\',\'\'\'\'SEND\'\'\'\',   \'\'\'\'VIEW ANY COLUMN ENCRYPTION KEY DEFINITION\'\'\'\',   \'\'\'\'VIEW ANY COLUMN MASTER KEY DEFINITION\'\'\'\' ) and OBJECT_SCHEMA_NAME(MAJOR_iD) IS NULL)   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select count(*) from #TEMP;   \'\r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP ( row varchar(500));          exec sp_MSforeachdb \'\'   USE [?]   iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'public\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND OBJECT_NAME(MAJOR_iD) NOT LiKE (\'\'\'\'%fn_cdc_get_net_changes_application_data%\'\'\'\')   AND NOT (OBJECT_SCHEMA_NAME(MAJOR_iD) = \'\'\'\'cdc\'\'\'\' and PERMiSSiON_NAME=\'\'\'\'SELECT\'\'\'\')   AND NOT (PERMiSSiON_NAME IN (\'\'\'\'REFERENCES\'\'\'\',\'\'\'\'SEND\'\'\'\',   \'\'\'\'VIEW ANY COLUMN ENCRYPTION KEY DEFINITION\'\'\'\',   \'\'\'\'VIEW ANY COLUMN MASTER KEY DEFINITION\'\'\'\' ) and OBJECT_SCHEMA_NAME(MAJOR_iD) IS NULL)   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select * from #TEMP;   \'','There are no permissions which are assigned to public.\r\n','There are some persmissions which are assigned to public\r\n','pass',NULL,NULL,'2026-02-11 17:32:31'),(1507,202602,49,28,'AA_SqlServer_220_Public Database Permissions','critical','PRIV','This test checks database permisions for public . Public is a special role and permissions should not be granted to public role.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      exec sp_msforeachdb \'\'   USE [?]     iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'public\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND OBJECT_NAME(MAJOR_iD) NOT LiKE (\'\'\'\'%fn_cdc_get_net_changes_application_data%\'\'\'\')   AND NOT (OBJECT_SCHEMA_NAME(MAJOR_iD) = \'\'\'\'cdc\'\'\'\' and PERMiSSiON_NAME=\'\'\'\'SELECT\'\'\'\')   AND NOT (PERMiSSiON_NAME IN (\'\'\'\'REFERENCES\'\'\'\',\'\'\'\'SEND\'\'\'\',   \'\'\'\'VIEW ANY COLUMN ENCRYPTION KEY DEFINITION\'\'\'\',   \'\'\'\'VIEW ANY COLUMN MASTER KEY DEFINITION\'\'\'\' ) and OBJECT_SCHEMA_NAME(MAJOR_iD) IS NULL)   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select count(*) from #TEMP;   \' \r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      exec sp_msforeachdb \'\'   USE [?]     iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'public\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND OBJECT_NAME(MAJOR_iD) NOT LiKE (\'\'\'\'%fn_cdc_get_net_changes_application_data%\'\'\'\')   AND NOT (OBJECT_SCHEMA_NAME(MAJOR_iD) = \'\'\'\'cdc\'\'\'\' and PERMiSSiON_NAME=\'\'\'\'SELECT\'\'\'\')   AND NOT (PERMiSSiON_NAME IN (\'\'\'\'REFERENCES\'\'\'\',\'\'\'\'SEND\'\'\'\',   \'\'\'\'VIEW ANY COLUMN ENCRYPTION KEY DEFINITION\'\'\'\',   \'\'\'\'VIEW ANY COLUMN MASTER KEY DEFINITION\'\'\'\' ) and OBJECT_SCHEMA_NAME(MAJOR_iD) IS NULL)   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select * from #TEMP;   \' \r\n','There are no permissions which are assigned to public.\r\n','There are some persmissions which are assigned to public\r\n','pass',NULL,NULL,'2026-02-11 17:32:31'),(1508,202602,49,29,'AA_SqlServer_230_Real person users','critical','ACCOUNT','All logins to the database should be made with AD groups, real person users should  not be connected database directly\r\n','','Select      count(*)   from      sys.server_principals    where      name like \'ODEABANK%.%\'      and is_disabled = 0   \r\n','== 0','','Select      name     from      sys.server_principals    where      name like \'ODEABANK%.%\'      and is_disabled = 0;\r\n','Real person users are not found in the logins\r\n','Some real person users are found in the logins\r\n','pass',NULL,NULL,'2026-02-11 17:32:31'),(1509,202602,49,30,'AA_SqlServer_240_2_guest Database Permissions','critical','ACCOUNT','This test checks database permisions for guest . guest is a special user and permissions should not be granted to guest user.\r\n','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP ( row varchar(500));\r\n\r\nexec sp_MSforeachdb \'\'\r\nUSE [?]\r\niNSERT iNTO #TEMP\r\nSELECT\r\n\'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +\r\n\'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +\r\n\'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +\r\n\'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )\r\nFROM\r\nsys.database_permissions\r\nWHERE\r\nUSER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'guest\'\'\'\' )\r\nAND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'\r\nAND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')\r\nAND STATE_DESC=\'\'\'\'GRANT\'\'\'\'\r\n;\r\n\'\'\r\nselect count(*) from #TEMP;\r\n\'','== 0','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP ( row varchar(500));\r\n\r\nexec sp_MSforeachdb \'\'\r\nUSE [?]\r\niNSERT iNTO #TEMP\r\nSELECT\r\n\'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +\r\n\'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +\r\n\'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +\r\n\'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )\r\nFROM\r\nsys.database_permissions\r\nWHERE\r\nUSER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'guest\'\'\'\' )\r\nAND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'\r\nAND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')\r\nAND STATE_DESC=\'\'\'\'GRANT\'\'\'\'\r\n;\r\n\'\'\r\nselect * from #TEMP;\r\n\'','There are no permissions which are assigned to guest.\r\n','There are some persmissions which are assigned to guest\r\n','pass',NULL,NULL,'2026-02-11 17:32:31'),(1510,202602,49,31,'AA_SqlServer_240_guest Database Permissions','critical','PRIV','This test checks database permisions for guest . guest is a special user and permissions should not be granted to guest user.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      exec sp_msforeachdb \'\'   USE [?]     iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'guest\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select count(*) from #TEMP;   \' \r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      exec sp_msforeachdb \'\'   USE [?]     iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'guest\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select  *  from #TEMP;   \' \r\n','There are no permissions which are assigned to guest.\r\n','There are some persmissions which are assigned to guest\r\n','pass',NULL,NULL,'2026-02-11 17:32:31'),(1511,202602,49,32,'AA_SqlServer_250_Database Role members for guest','critical','PRIV','This test checks database role members for guest  user. Database roles  could not be assigned to guest role.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      EXEC sp_MSforeachdb \'\' USE [?]    INSERT INTO #TEMP   SELECT \'\'\'\'DB Name : \'\'\'\'+Cast (DB_NAME() as varchar)+\'\'\'\' Role Name : \'\'\'\'+USER_NAME(role_principal_id)  +\'\'\'\' User Name \'\'\'\'+  USER_NAME(member_principal_id)    from  sys.database_role_members   	Where     USER_NAME(member_principal_id)  = \'\'\'\'guest\'\'\'\'     ;   \'\'      Select count(*)  from #TEMP;   \'\r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      EXEC sp_MSforeachdb \'\' USE [?]    INSERT INTO #TEMP   SELECT \'\'\'\'DB Name : \'\'\'\'+Cast (DB_NAME() as varchar)+\'\'\'\' Role Name : \'\'\'\'+USER_NAME(role_principal_id)  +\'\'\'\' User Name \'\'\'\'+  USER_NAME(member_principal_id)    from  sys.database_role_members   	Where     USER_NAME(member_principal_id)  = \'\'\'\'guest\'\'\'\'     ;   \'\'      Select  *  from #TEMP;   \'\r\n','Database role member usage for guest user  is correct\r\n','Database role member usage for guest user  is not correct\r\n','pass',NULL,NULL,'2026-02-11 17:32:31'),(1512,202602,49,33,'AA_SqlServer_260_SQL Logins with Null Password','critical','ACCOUNT','This test checks sql logins with null password. SQL Logins should not have null passwords.\r\n','','SELECT      count(name)   from      sys.sql_logins    WHERE      PWDCOMPARE(\'\', password_hash)= 1\r\n','== 0','','SELECT      name    from      sys.sql_logins    WHERE      PWDCOMPARE(\'\', password_hash)= 1   \r\n','There are no sql logins with null paswords\r\n','There are some sql logins with null passwords.\r\n','pass',NULL,NULL,'2026-02-11 17:32:31'),(1513,202602,49,34,'AA_SqlServer_270_SQL Logins with username and passwords are equal','critical','ACCOUNT','This test checks sql login password which are egual to username. Username and password must be different for SQL logins.\r\n','','SELECT      count(name)   from      sys.sql_logins    WHERE      PWDCOMPARE(name,password_hash)=1 \r\n','== 0','','SELECT      name    from      sys.sql_logins    WHERE      PWDCOMPARE(name,password_hash)=1    \r\n','There is no SQL login name which is equal to password.\r\n','There are some sql logins whose passwords are egual to usernames.\r\n','pass',NULL,NULL,'2026-02-11 17:32:31'),(1514,202602,49,35,'AA_SqlServer_280_No Sample Databases','critical','CONFIG','This test checks whether the sample databases created optionally on installation are present.  These sample databases contain many default permissions, and can be used as an entry point to your systems. \r\n','','select      count(name)    from      sys.databases    where      name in (       \'AdventureWorks\', \'AdventureWorksDW\',        \'Northwind\', \'Pubs\'     )   \r\n','== 0','','select      name    from      sys.databases    where      name in (       \'AdventureWorks\', \'AdventureWorksDW\',        \'Northwind\', \'Pubs\'     )   \r\n','There are no sample databases in the server\r\n','There are some sample databases in the server\r\n','pass',NULL,NULL,'2026-02-11 17:32:31'),(1515,202602,49,43,'AA_SqlServer_350_User Password Policy Is Checked','critical','ACCOUNT','This test checks that CHECK_POLICY is enabled for all users.  Enabling CHECK_POLICY ensures that Windows passwords policies are enforced.','','select count(*) from sys.sql_logins  \r\nwhere \r\nis_policy_checked=0 and\r\nname not like \'##%\'','== 0','','select name from sys.sql_logins  \r\nwhere \r\nis_policy_checked=0 and\r\nname not like \'##%\'','CHECK_POLICY is enabled for all users','CHECK_POLICY is not enabled for all users','pass',NULL,NULL,'2026-02-11 17:32:31'),(1516,202602,49,44,'AA_SqlServer_360_CHECK_EXPIRATION Is Checked','critical','ACCOUNT','This test checks that CHECK_EXPIRATION is enabled for all users.  Passwords that have been in use for long periods of time are likely to become known to unauthorized users.\r\n','','select count(*) from sys.sql_logins     where    is_expiration_checked=0 and   name not like \'##%\'\r\n','== 0','','select name from sys.sql_logins     where    is_expiration_checked=0 and   name not like \'##%\'\r\n','CHECK_EXPIRATION is enabled for all users\r\n','CHECK_EXPIRATION is not enabled for all users\r\n','fail','name\n----\n\'sa\'',NULL,'2026-02-11 17:32:31'),(1517,202602,49,22,'AA_SqlServer_170_Windows Authentication','major','AUTH','This test checks that the authentication mode is set to Windows authentication only.  Windows provides a more robust authentication mechanism than SQL Server authentication.','',' SELECT cast( SERVERPROPERTY(\'IsIntegratedSecurityOnly\') as int) ','==1','','SELECT cast( SERVERPROPERTY(\'IsIntegratedSecurityOnly\') as varchar)','The authentication mode is set to Windows authentication only. ','The authentication mode is not set to Windows authentication only.','fail','\n---\n\'0\'',NULL,'2026-02-11 17:32:31'),(1518,202602,49,23,'AA_SqlServer_180_No Guest User Accounts','major','ACCOUNT','This test checks for the existence of guest user accounts with CONNECT permission in database other than master, msdb and tempdb.  This test also exclude databases that are flagged as distributor. If the GUEST user exists and a specific login has not been granted to a database, a login will be mapped to GUEST. The presence of the GUEST user allows all logins to access the database.\r\n','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP  ( row int);\r\n\r\nEXEC sp_MSforeachdb \'\' USE [?]\r\n	INSERT INTO #TEMP\r\n	SELECT count(*) \r\n	FROM sys.database_permissions\r\n	WHERE [grantee_principal_id] = DATABASE_PRINCIPAL_ID(\'\'\'\'guest\'\'\'\')\r\n	AND [state_desc] LIKE \'\'\'\'GRANT%\'\'\'\'\r\n	AND [permission_name] = \'\'\'\'CONNECT\'\'\'\'\r\n	AND DB_NAME() NOT IN (\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'msdb\'\'\'\') ;\r\n\'\'\r\n\r\nSelect sum(row) from #TEMP;\r\ndrop table #TEMP;\r\n\'','== 0','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP  ( row varchar(500));\r\n\r\nEXEC sp_MSforeachdb \'\' USE  [?] \r\n	INSERT INTO #TEMP\r\n	SELECT \'\'\'\' DB NAME : \'\'\'\' + Cast (DB_NAME() as varchar) + \'\'\'\' guest user has CONNECT permission \'\'\'\'\r\n	FROM sys.database_permissions\r\n	WHERE [grantee_principal_id] = DATABASE_PRINCIPAL_ID(\'\'\'\'guest\'\'\'\')\r\n	AND [state_desc] LIKE \'\'\'\'GRANT%\'\'\'\'\r\n	AND [permission_name] = \'\'\'\'CONNECT\'\'\'\'\r\n	AND DB_NAME() NOT IN (\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'msdb\'\'\'\') ;\r\n\'\'\r\n\r\nSelect * from #TEMP;\r\ndrop table #TEMP;\r\n\'','There is no guest user with CONNECT permission. ','There are   guest users with CONNECT permission. Remove these users','pass',NULL,NULL,'2026-02-11 17:32:31'),(1519,202602,49,36,'AA_SqlServer_290_2_No Permissions with GRANT Option','major','PRIV','This test checks database permisions  with grant option. No permission with grant option should be defined in the database.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP ( row varchar(500));      exec sp_MSforeachdb \'\'   USE [?]   iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   STATE_DESC like \'\'\'\'%WITH_GRANT%\'\'\'\'   ;   \'\'   select count(*) from #TEMP;   \'\r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP ( row varchar(500));      exec sp_MSforeachdb \'\'   USE [?]   iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   STATE_DESC like \'\'\'\'%WITH_GRANT%\'\'\'\'   ;   \'\'   select * from #TEMP;   \'\r\n','There are no permissions with grant option.\r\n','There are some persmissions  with grant option.\r\n','pass',NULL,NULL,'2026-02-11 17:32:31'),(1520,202602,49,37,'AA_SqlServer_290_No Permissions with GRANT Option','major','PRIV','','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP  ( row varchar(500));\r\n\r\nexec sp_msforeachdb \'\'\r\nUSE [?]  \r\niNSERT iNTO #TEMP\r\nSELECT\r\n\'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +\r\n\'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +\r\n\'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +\r\n\'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )\r\nFROM\r\nsys.database_permissions\r\nWHERE\r\nSTATE_DESC like \'\'\'\'%WITH_GRANT%\'\'\'\'\r\n;\r\n\'\'\r\nselect  count(*)  from #TEMP;\r\n\' ','== 0','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP  ( row varchar(500));\r\n\r\nexec sp_msforeachdb \'\'\r\nUSE [?]  \r\niNSERT iNTO #TEMP\r\nSELECT\r\n\'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +\r\n\'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +\r\n\'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +\r\n\'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )\r\nFROM\r\nsys.database_permissions\r\nWHERE\r\nSTATE_DESC like \'\'\'\'%WITH_GRANT%\'\'\'\'\r\n;\r\n\'\'\r\nselect * from #TEMP;\r\n\' ','There are no permissions with grant option.\r\n','There are some persmissions  with grant option.\r\n','pass',NULL,NULL,'2026-02-11 17:32:31'),(1521,202602,49,40,'AA_SqlServer_320_No Access to Registry Access Extended procedures','major','PRIV','This test checks for the existence of, and user permissions on, registry access extended stored procedures.  Either these procedures should be completely dropped, or access to them should be strictly limited. xp_reg%,xp_instance_reg%\r\n','','SELECT \r\ncount(*) \r\nFROM \r\n  [master].sys.system_objects o \r\n  JOIN [master].sys.database_permissions p ON o.object_id = p.major_id \r\n  JOIN [master].sys.database_principals u ON p.grantee_principal_id = u.principal_id \r\nWHERE \r\n( o.name LIKE \'xp_reg%\' OR o.name LIKE \'xp_instance_reg%\')\r\n  AND p.type = \'EX\' ','== 0','','SELECT \r\n  \'Principal : \'+u.name  COLLATE DATABASE_DEFAULT +\r\n  \' Extended Procedure Name : \'+o.name COLLATE DATABASE_DEFAULT +\r\n  \' Type : \'+ u.type_desc COLLATE DATABASE_DEFAULT \r\nFROM \r\n  [master].sys.system_objects o \r\n  JOIN [master].sys.database_permissions p ON o.object_id = p.major_id \r\n  JOIN [master].sys.database_principals u ON p.grantee_principal_id = u.principal_id \r\nWHERE \r\n( o.name LIKE \'xp_reg%\' OR o.name LIKE \'xp_instance_reg%\')\r\n  AND p.type = \'EX\' ','There are no permissions on registry access extended stored procedures\r\n','There are some persmissions permissions on registry access extended stored procedures\r\n','fail','\n---------------------------------------------------------------------------------------\n\'Principal : public Extended Procedure Name : xp_instance_regread Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_regread Type : DATABASE_ROLE\'',NULL,'2026-02-11 17:32:31'),(1522,202602,49,41,'AA_SqlServer_330_Revoke public login from SQL Server agent proxy account','major','PRIV','The public database role contains every user in the msdb database. SQL Agent proxies   define a security context in which a job step can run.Granting access to SQL Agent proxies for the public role would allow all users to utilize the proxy which may have high privileges. This would likely break the principle of least   privileges.\r\n','','SELECT count(*)\r\nFROM msdb.dbo.sysproxylogin spl\r\nJOIN sys.database_principals dp\r\nON dp.sid = spl.sid\r\nJOIN msdb.dbo.sysproxies sp\r\nON sp.proxy_id = spl.proxy_id\r\nWHERE principal_id = USER_ID(\'public\')','== 0','','SELECT \'proxyname : \'+CAST(sp.name  as varchar)\r\nFROM msdb.dbo.sysproxylogin spl\r\nJOIN sys.database_principals dp\r\nON dp.sid = spl.sid\r\nJOIN msdb.dbo.sysproxies sp\r\nON sp.proxy_id = spl.proxy_id\r\nWHERE principal_id = USER_ID(\'public\')','There are no public permissions on SQL Server agent proxy account\r\n','There are some public permissions on SQL Server agent proxy account\r\n','pass',NULL,NULL,'2026-02-11 17:32:31'),(1523,202602,49,42,'AA_SqlServer_340_No Individual User Access To syscomment and sp_helptext','minor','PRIV','This test checks for grants on SYSCOMMENTS.TEXT.  Such grants allow any user to read the text comments associated with a database object, making the text publicly viewable.\r\n','','SELECT count(*)\r\nFROM msdb.dbo.sysproxylogin spl\r\nJOIN sys.database_principals dp\r\nON dp.sid = spl.sid\r\nJOIN msdb.dbo.sysproxies sp\r\nON sp.proxy_id = spl.proxy_id\r\nWHERE principal_id = USER_ID(\'public\')\r\n','== 0','','SELECT count(*)\r\nFROM msdb.dbo.sysproxylogin spl\r\nJOIN sys.database_principals dp\r\nON dp.sid = spl.sid\r\nJOIN msdb.dbo.sysproxies sp\r\nON sp.proxy_id = spl.proxy_id\r\nWHERE principal_id = USER_ID(\'public\')','There are no public permissions on SQL Server agent proxy account','There are some public permissions on SQL Server agent proxy account','pass',NULL,NULL,'2026-02-11 17:32:31'),(1524,202602,49,10,'AA_SqlServer_050_Disable Ad hoc distributed queries option','major','CONFIG','Adhoc queries allow undefined access to remote database sources.  Access to untrusted databases could result in execution of malicious applications and/or a compromise of local data confidentiality and integrity. The DBA will configure the database to disable access from the database to objects stored externally to the database on the local host unless mission and/or operationally required and documented.\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Ad Hoc Distributed Queries\'','== 0','','SELECT name + \' Value : \'+ cast( value as varchar ) + \' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'Ad Hoc Distributed Queries\'','Ad Hoc Distributed Queries is disabled','Ad Hoc Distributed Queries is not disabled. Disable this option','pass',NULL,NULL,'2026-02-11 17:32:31'),(1525,202602,49,11,'AA_SqlServer_060_Disable CLR option','major','CONFIG','The clr_enabled parameter configures SQL Server to allow or disallow use of Command Language Runtime objects.  CLR objects is managed code that integrates with the .NET Framework.  This is a more secure method than external stored procedures, although it still contains some risk.  Where no external application execution requirements are required, disallowing use of any improves the overall security posture of the database.\r\n\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'clr enabled\'','== 0','','SELECT name + \' Value : \'+ cast( value as varchar ) + \' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'clr enabled\'','CLR option is disabled','CLR option is not disabled. Disable this option','pass',NULL,NULL,'2026-02-11 17:32:31'),(1526,202602,49,12,'AA_SqlServer_070_Disable Cross db ownership chaining option','major','CONFIG','Cross database ownership chaining allows permissions to objects to be assigned by users other than the Information Owner.  This allows access to objects that are not authorized directly by the Information Owner based on job functions defined by the owner.  Unauthorized access may lead to a compromise of data integrity or confidentiality. The DBA will ensure database privileges are assigned via roles and not directly assigned to database accounts. Privileges may be assigned directly to application owner accounts where the DBMS does not otherwise support access via roles.\r\n\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'cross db ownership chaining\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'cross db ownership chaining\'','Cross db ownership chaining  option is disabled','Cross db ownership chaining option  is not disabled. Disable this option','pass',NULL,NULL,'2026-02-11 17:32:31'),(1527,202602,49,13,'AA_SqlServer_080_Disable Database Mail XPs option','major','CONFIG','SQL Mail accepts incoming database commands via email. This can introduce malicious codes or viruses into the SQL server environment.','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Database Mail XPs\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \'Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'Database Mail XPs\'','Database Mail XPs option is disabled','Database Mail XPs option  is not disabled. Disable this option','pass',NULL,NULL,'2026-02-11 17:32:31'),(1528,202602,49,14,'AA_SqlServer_100_Disable xp_cmdshell Server Configuration option','major','CONFIG','The xp_cmdshell extended stored procedures allows execution of host executables outside the controls of database access permissions.  This access may be exploited by malicious users who have compromised the integrity of the SQL Server database process to control the host operating system to perpetrate additional malicious activity. The DBA should disable the use of external procedures by the database unless it is mission critical or operationally required','','SELECT CAST(value as int) +\r\n       CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'xp_cmdshell\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) +\r\n\' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'xp_cmdshell\'','xp_cmdshell Server Configuration option is disabled','xp_cmdshell Server Configuration option is not disabled. This option must be disabled','pass',NULL,NULL,'2026-02-11 17:32:31'),(1529,202602,49,15,'AA_SqlServer_110_Disable Remote Access option','major','CONFIG','The remote access option controls the execution of local stored procedures on remote\r\nservers or remote stored procedures on local server.Functionality can be abused to launch a Denial-of-Service (DoS) attack on remote servers\r\nby off-loading query processing to a target.\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'remote access\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \' Value in use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'remote access\'','Remote Access option is disabled','Remote Access option  is not disabled. Disable this option','fail','\n------------------------------------------\n\'remote access Value : 1 Value in use : 1\'',NULL,'2026-02-11 17:32:31'),(1530,202602,49,16,'AA_SqlServer_120_Disable Remote Admin Connections option','major','CONFIG','The remote admin connections option controls whether a client application on a remote\r\ncomputer can use the Dedicated Administrator Connection (DAC).The Dedicated Administrator Connection (DAC) lets an administrator access a running\r\nserver to execute diagnostic functions or Transact-SQL statements, or to troubleshoot\r\nproblems on the server, even when the server is locked or running in an abnormal state\r\nand not responding to a SQL Server Database Engine connection. In a cluster scenario, the\r\nadministrator may not actually be logged on to the same node that is currently hosting the\r\nSQL Server instance and thus is considered \"remote\". Therefore, this setting should usually\r\nbe enabled (1) for SQL Server failover clusters; otherwise it should be disabled (0) which is\r\nthe default.\r\n','','execute sp_executesql N\'\r\n\r\nDECLARE @x int;\r\n\r\nSELECT @x=isnull(CAST(value as int) + CAST(value_in_use as int),100)\r\nFROM sys.configurations\r\nWHERE name = \'\'remote admin connections\'\'\r\n\r\nIF @x = 100\r\n       SELECT 0 ;\r\nELSE \r\n   SELECT CAST(value as int) + CAST(value_in_use as int) \r\n   FROM sys.configurations\r\n   WHERE name = \'\'remote admin connections\'\'\r\n\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'remote admin connections\'','Remote Admin Connections option is disabled','Remote Admin Connections option  is not disabled. Disable this option','pass',NULL,NULL,'2026-02-11 17:32:31'),(1531,202602,49,19,'AA_SqlServer_150_Disable database trustworthy status','major','CONFIG','The TRUSTWORTHY database setting restricts access to database resources by databases that contain assemblies with the EXTERNAL_ACCESS or UNSAFE permission settings and modules that use impersonation of accounts assigned elevated privileges.  Unless all assemblies and code for the database have been reviewed, especially in the case where databases have been detached and attached between server instances, leaving the TRUSTWORTHY status to off can help reduce threats from malicious assemblies or modules.','','SELECT count(name)\r\nFROM sys.databases\r\nWHERE is_trustworthy_on = 1\r\nAND name != \'msdb\';','== 0','','SELECT name\r\nFROM sys.databases\r\nWHERE is_trustworthy_on = 1\r\nAND name != \'msdb\';','database trustworthy status is disabled','database trustworthy status is not disabled. Disable this option','pass',NULL,NULL,'2026-02-11 17:32:31'),(1532,202602,49,20,'Checkpoint başarıyla oluşturuldu.','major','CONFIG','This test checks if SQL Server Instance is not advertised by the SQL Server Browser service. To maintain a higher level of protection for database instances, we recommend that SQL Server Instance be hidden when it is not required. Please note that this test does not include Clustered Instances as turning off this feature may cause issues with the Clustered environment.\r\n\r\n','','execute sp_executesql N\'\r\n\r\nDECLARE @getValue INT\r\n\r\nEXEC master.sys.xp_instance_regread\r\n@rootkey = N\'\'HKEY_LOCAL_MACHINE\'\',\r\n@key = N\'\'SOFTWARE\\Microsoft\\Microsoft SQL Server\\MSSQLServer\\SuperSocketNetLib\'\',\r\n@value_name = N\'\'HideInstance\'\',\r\n@value = @getValue OUTPUT\r\n\r\nSELECT isnull(@getvalue,0)\'','==1','','execute sp_executesql N\'\r\n\r\nDECLARE @getValue INT\r\n\r\nEXEC master.sys.xp_instance_regread\r\n@rootkey = N\'\'HKEY_LOCAL_MACHINE\'\',\r\n@key = N\'\'SOFTWARE\\Microsoft\\Microsoft SQL Server\\MSSQLServer\\SuperSocketNetLib\'\',\r\n@value_name = N\'\'HideInstance\'\',\r\n@value = @getValue OUTPUT\r\n\r\nSELECT isnull(@getvalue,0)\'','SQL Server Instance is  hidden.\r\n','SQL Server Instance is not hidden. Hide the instance','fail','\n-\n0',NULL,'2026-02-11 17:32:31'),(1533,202602,49,21,'AA_SqlServer_160_Hide SQL Server Instance','major','CONFIG','This test checks if SQL Server Instance is not advertised by the SQL Server Browser service. To maintain a higher level of protection for database instances, we recommend that SQL Server Instance be hidden when it is not required. Please note that this test does not include Clustered Instances as turning off this feature may cause issues with the Clustered environment.\r\n\r\n','','execute sp_executesql N\'\r\n\r\nDECLARE @getValue INT\r\n\r\nEXEC master.sys.xp_instance_regread\r\n@rootkey = N\'\'HKEY_LOCAL_MACHINE\'\',\r\n@key = N\'\'SOFTWARE\\Microsoft\\Microsoft SQL Server\\MSSQLServer\\SuperSocketNetLib\'\',\r\n@value_name = N\'\'HideInstance\'\',\r\n@value = @getValue OUTPUT\r\n\r\nSELECT isnull(@getvalue,0)\'','==1','','execute sp_executesql N\'\r\n\r\nDECLARE @getValue INT\r\n\r\nEXEC master.sys.xp_instance_regread\r\n@rootkey = N\'\'HKEY_LOCAL_MACHINE\'\',\r\n@key = N\'\'SOFTWARE\\Microsoft\\Microsoft SQL Server\\MSSQLServer\\SuperSocketNetLib\'\',\r\n@value_name = N\'\'HideInstance\'\',\r\n@value = @getValue OUTPUT\r\n\r\nSELECT isnull(@getvalue,0)\'','SQL Server Instance is  hidden.','SQL Server Instance is not hidden. Hide the instance','fail','\n-\n0',NULL,'2026-02-11 17:32:31'),(1534,202602,49,38,'AA_SqlServer_300_No Access To General Extended procedures','major','PRIV','This test checks for the existence of, and user permissions on, extended stored procedures.  Either these procedures should be completely dropped, or access to them should be strictly limited. xp_cmdshell, xp_enumgroups, xp_grantlogin ,xp_logevent, xp_logininfo,    xp_msver, xp_revokelogin, xp_sprintf, xp_sqlmaint, xp_sscanf\r\n','','SELECT \r\ncount(*) \r\nFROM \r\n  [master].sys.system_objects o \r\n  JOIN [master].sys.database_permissions p ON o.object_id = p.major_id \r\n  JOIN [master].sys.database_principals u ON p.grantee_principal_id = u.principal_id \r\nWHERE \r\n    o.name in ( \r\n	\'xp_cmdshell\', \r\n	\'xp_enumgroups\', \r\n    \'xp_grantlogin\' ,\r\n	\'xp_logevent\', \r\n	\'xp_logininfo\', \r\n    \'xp_msver\', \r\n	\'xp_revokelogin\', \r\n	\'xp_sprintf\', \r\n    \'xp_sqlmaint\', \r\n	\'xp_sscanf\' )\r\n  AND p.type = \'EX\' ','== 0','','SELECT \r\n  \'Principal : \'+u.name  COLLATE DATABASE_DEFAULT +\r\n  \' Extended Procedure Name : \'+o.name COLLATE DATABASE_DEFAULT +\r\n  \' Type : \'+ u.type_desc COLLATE DATABASE_DEFAULT \r\nFROM \r\n  [master].sys.system_objects o \r\n  JOIN [master].sys.database_permissions p ON o.object_id = p.major_id \r\n  JOIN [master].sys.database_principals u ON p.grantee_principal_id = u.principal_id \r\nWHERE \r\n    o.name in ( \r\n	\'xp_cmdshell\', \r\n	\'xp_enumgroups\', \r\n    \'xp_grantlogin\' ,\r\n	\'xp_logevent\', \r\n	\'xp_logininfo\', \r\n    \'xp_msver\', \r\n	\'xp_revokelogin\', \r\n	\'xp_sprintf\', \r\n    \'xp_sqlmaint\', \r\n	\'xp_sscanf\' )\r\n  AND p.type = \'EX\' ','There are no permissions on general extended stored procedures\r\n','There are some persmissions permissions on general extended stored procedures.\r\n','fail','\n----------------------------------------------------------------------------------\n\'Principal : public Extended Procedure Name : xp_msver Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_sscanf Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_revokelogin Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_grantlogin Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_sprintf Type : DATABASE_ROLE\'',NULL,'2026-02-11 17:32:31'),(1535,202602,49,39,'AA_SqlServer_310_No Access to OLE Automation procedures','major','CONFIG','This test checks for the existence of,and user permissions on OLE automation extended stored procedures.  Either these procedures should be completely dropped, or access to them should be strictly limited.      \r\n','','SELECT CAST(value as int) +\r\n       CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Ole Automation Procedures\'   \r\n','== 0','','SELECT CAST(value as int) +\r\n       CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Ole Automation Procedures\'\r\n  \r\n','OLE Automation procedures  option is disabled\r\n','OLE Automation procedures  option  is not disabled. Disable this option\r\n','pass',NULL,NULL,'2026-02-11 17:32:31'),(1536,202602,49,17,'AA_SqlServer_130_Disable Ole Automation Procedures option','minor','CONFIG','This test checks if Ole Automation Procedures option is disabled. Ole Automation Procedures option allows SQL Server users to execute functions external to SQL Server. Enabling this option will increase the attack surface of SQL Server and allow users to execute functions in the security context of SQL Server. We recommend that the Ole Automation Procedures option to be disabled when it is not document as a requirement.\r\n\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Ole Automation Procedures\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \'Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'Ole Automation Procedures\'',' Ole Automation Procedures option is disabled',' Ole Automation Procedures option  is not disabled. Disable this option','pass',NULL,NULL,'2026-02-11 17:32:31'),(1537,202602,49,18,'AA_SqlServer_140_Disable Scan for Startup Procedures option','minor','CONFIG','This test checks if scan for startup procedures is disabled. This feature causes SQL Server to scan for and automatically run all stored procedures that are set to execute upon service startup. If there are no user-defined stored procedures set to execute when SQL server starts, we recommend this feature to be disabled.\r\n\r\n','','SELECT CAST(value as int) +\r\n       CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'scan for startup procs\'','== 0','','SELECT name + \' value : \'+cast( value as varchar ) +\r\n\' value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'scan for startup procs\'','Scan for Startup Procedures  option is disabled','Scan for Startup Procedures  option  is not disabled. Disable this option','pass',NULL,NULL,'2026-02-11 17:32:31'),(1538,202602,49,9,'AA_SqlServer_040_Rename the sa Login Account','major','ACCOUNT','The \'sa\' account is a well-known account.  Well-known account names provide an easier target for attack.  Renaming the sa account helps reduce the risk of an attack to this built-in account.','','SELECT count(*)\r\nFROM sys.server_principals\r\nWHERE sid = 0x01 and name=\'sa\'','== 0','','SELECT name\r\nFROM sys.server_principals\r\nWHERE sid = 0x01','sa Login Account is renamed','sa Login Account is not renamed. Rename this account','fail','name\n----\n\'sa\'',NULL,'2026-02-11 17:32:31'),(1539,202602,50,24,'AA_SqlServer_190_Public server role permision','critical','PRIV','public is a special fixed server role containing all logins. Unlike other fixed server roles,\r\npermissions can be changed for the public role. In keeping with the principle of least\r\nprivileges, the public server role should not be used to grant permissions at the server\r\nscope as these would be inherited by all users.\r\n\r\nEvery SQL Server login belongs to the public role and cannot be removed from this role.\r\nTherefore, any permissions granted to this role will be available to all logins unless they\r\nhave been explicitly denied to specific logins or user-defined server roles.','','Select \r\n  count (permission_name) \r\nfrom \r\n  sys.server_permissions \r\nwhere \r\n  SUSER_NAME(grantee_principal_id) = \'public\' \r\n  and permission_name not in (\'VIEW ANY DATABASE\', \'CONNECT\')\r\n','== 0','','Select \r\n  permission_name \r\nfrom \r\n  sys.server_permissions \r\nwhere \r\n  SUSER_NAME(grantee_principal_id) = \'public\' \r\n  and permission_name not in (\'VIEW ANY DATABASE\', \'CONNECT\')\r\n\r\n','No server permissions are granted to public.','Some server permissions are granted to public.','pass',NULL,NULL,'2026-02-11 17:34:34'),(1540,202602,50,5,'AA_SqlServer_010_Supported SQL Server version','critical','PATCH','This test checks whether your current SQL Server version is a vendor-supported version.  Microsoft does not provide security fixes or software updates to unsupported software versions','','SELECT cast(ISNULL(SERVERPROPERTY(\'ProductMajorVersion\'),0) as int)   ','>=11','','SELECT \'Product Major version \' +  cast(ISNULL(SERVERPROPERTY(\'ProductMajorVersion\'),\'Null\' ) as  char ) ','The version of the database is acceptable.','The version of the database is not acceptable. The database version should SQL Sever 2012 or upper.','pass',NULL,NULL,'2026-02-11 17:34:34'),(1541,202602,50,6,'AA_SqlServer_020_Disable the sa Login Account','critical','ACCOUNT','This test checks if the \'sa\' Login Account is disabled. The sa account is a widely known and often widely used SQL Server account with sysadmin privileges. Enforcing this control reduces the probability of an attacker executing brute force attacks against a well-known principal.','','SELECT  count(*)\r\nFROM sys.server_principals\r\nWHERE sid = 0x01\r\nAND is_disabled = 0','== 0','','SELECT \'sa user name : \'+ name+\' is disabled : \' +  cast( is_disabled as char)\r\nFROM sys.server_principals\r\nWHERE sid = 0x01\r\n','sa Login Account is disabled','Disable sa login account','fail','\n----------------------------------------------------------------\n\'sa user name : sa is disabled : 0                             \'',NULL,'2026-02-11 17:34:34'),(1542,202602,50,7,'AA_SqlServer_025_sa Change password','critical','ACCOUNT','This test checks that sa password change . The sa password should be changed in every two days','','select datediff( day,  modify_date , getdate() ) FROM sys.server_principals\r\nWHERE sid = 0x01  ','< 3','','select datediff( day,  modify_date , getdate() ) FROM sys.server_principals\r\nWHERE sid = 0x01 ','sa password was changed in two days','','fail','\n--\n28',NULL,'2026-02-11 17:34:34'),(1543,202602,50,8,'AA_SqlServer_030_Ensure no Login exists with sa Login Account','critical','ACCOUNT','The \'sa\' account is a well-known account.  Well-known account names provide an easier target for attack. The lack of the sa account helps reduce the risk of an attack to this built-in account.','','SELECT count(*)\r\nFROM sys.server_principals\r\nWHERE name = \'sa\'','== 0','','SELECT name\r\nFROM sys.server_principals\r\nWHERE name = \'sa\'','There is no the sa account in the database.','There is the sa Login account in the database.Drop this user or rename et.','fail','name\n----\n\'sa\'',NULL,'2026-02-11 17:34:34'),(1544,202602,50,25,'AA_SqlServer_200_Fixed Server Role members for users','critical','PRIV','This test checks fixed server roles for analyst , developers and real persons. Fixed server roles could not be assigned to real person users ( Developer, Analyst users ) . Only Admin can use fixed server role.\r\n','','Select     count(*)   from      sys.server_role_members    where      (       suser_name(member_principal_id) like \'ODEABANK%.%\'    	AND       suser_name(member_principal_id) not like \'%admin%\'         AND       suser_name(member_principal_id) not like \'%t.coban%\'     )      OR (       suser_name(member_principal_id) like \'ODEABANK\\Cyberark_Intertech%\'     )      \r\n','== 0','','Select      suser_name(role_principal_id) + \'   \' + suser_name(member_principal_id)    from      sys.server_role_members    where      (       suser_name(member_principal_id) like \'ODEABANK%.%\'    	AND       suser_name(member_principal_id) not like \'%admin%\'         AND       suser_name(member_principal_id) not like \'%t.coban%\'     )      OR (       suser_name(member_principal_id) like \'ODEABANK\\Cyberark_Intertech%\'     )          \r\n','Fixed Server role usage is correct.\r\n','Fixed Server role usage is not correct.\r\n','pass',NULL,NULL,'2026-02-11 17:34:34'),(1545,202602,50,26,'AA_SqlServer_210_Database Role members for users','critical','PRIV','This test checks database role members for analyst and real person users. Database roles  except  db_datareader could not be assigned to real person users ( Developer, Analyst users ) .\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      EXEC sp_MSforeachdb \'\' USE [?]    INSERT INTO #TEMP   SELECT \'\'\'\'DB Name : \'\'\'\'+Cast (DB_NAME() as varchar)+\'\'\'\' Role Name : \'\'\'\'+USER_NAME(role_principal_id)  +\'\'\'\' User Name \'\'\'\'+  USER_NAME(member_principal_id)    from  sys.database_role_members   	Where   	(   	( USER_NAME(member_principal_id)  like \'\'\'\'%ODEABANK%.%\'\'\'\'  and   USER_NAME(member_principal_id)  not like \'\'\'\'%admin%\'\'\'\' )     	OR   	  (suser_name(member_principal_id) like \'\'\'\'%ODEABANK%Cyberark%\'\'\'\')       )    	AND   	DB_NAME() <> \'\'\'\'master\'\'\'\' and   	USER_NAME(role_principal_id) not in (\'\'\'\'db_datareader\'\'\'\',\'\'\'\'db_viewdefinition\'\'\'\',\'\'\'\'db_denydatareader\'\'\'\',\'\'\'\'db_deny_maas\'\'\'\');   \'\'      Select  count(*)  from #TEMP;   \'\r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      EXEC sp_MSforeachdb \'\' USE [?]    INSERT INTO #TEMP   SELECT \'\'\'\'DB Name : \'\'\'\'+Cast (DB_NAME() as varchar)+\'\'\'\' Role Name : \'\'\'\'+USER_NAME(role_principal_id)  +\'\'\'\' User Name \'\'\'\'+  USER_NAME(member_principal_id)    from  sys.database_role_members   	Where   (   	( USER_NAME(member_principal_id)  like \'\'\'\'%ODEABANK%.%\'\'\'\'  and   USER_NAME(member_principal_id)  not like \'\'\'\'%admin%\'\'\'\' )     	OR   	(suser_name(member_principal_id) like \'\'\'\'%ODEABANK%Cyberark%\'\'\'\')   )    	AND   	DB_NAME() <> \'\'\'\'master\'\'\'\' and   	USER_NAME(role_principal_id) not in  (\'\'\'\'db_datareader\'\'\'\',\'\'\'\'db_viewdefinition\'\'\'\',\'\'\'\'db_denydatareader\'\'\'\',\'\'\'\'db_deny_maas\'\'\'\');   \'\'      Select  * from #TEMP;   \'\r\n','Database role member usage for users  is correct\r\n','Database role member usage for users  is not correct\r\n','pass',NULL,NULL,'2026-02-11 17:34:34'),(1546,202602,50,27,'AA_SqlServer_220_2_Public Database Permissions','critical','PRIV','This test checks database permisions for public . Public is a special role and permissions should not be granted to public role.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP ( row varchar(500));          exec sp_MSforeachdb \'\'   USE [?]   iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'public\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND OBJECT_NAME(MAJOR_iD) NOT LiKE (\'\'\'\'%fn_cdc_get_net_changes_application_data%\'\'\'\')   AND NOT (OBJECT_SCHEMA_NAME(MAJOR_iD) = \'\'\'\'cdc\'\'\'\' and PERMiSSiON_NAME=\'\'\'\'SELECT\'\'\'\')   AND NOT (PERMiSSiON_NAME IN (\'\'\'\'REFERENCES\'\'\'\',\'\'\'\'SEND\'\'\'\',   \'\'\'\'VIEW ANY COLUMN ENCRYPTION KEY DEFINITION\'\'\'\',   \'\'\'\'VIEW ANY COLUMN MASTER KEY DEFINITION\'\'\'\' ) and OBJECT_SCHEMA_NAME(MAJOR_iD) IS NULL)   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select count(*) from #TEMP;   \'\r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP ( row varchar(500));          exec sp_MSforeachdb \'\'   USE [?]   iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'public\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND OBJECT_NAME(MAJOR_iD) NOT LiKE (\'\'\'\'%fn_cdc_get_net_changes_application_data%\'\'\'\')   AND NOT (OBJECT_SCHEMA_NAME(MAJOR_iD) = \'\'\'\'cdc\'\'\'\' and PERMiSSiON_NAME=\'\'\'\'SELECT\'\'\'\')   AND NOT (PERMiSSiON_NAME IN (\'\'\'\'REFERENCES\'\'\'\',\'\'\'\'SEND\'\'\'\',   \'\'\'\'VIEW ANY COLUMN ENCRYPTION KEY DEFINITION\'\'\'\',   \'\'\'\'VIEW ANY COLUMN MASTER KEY DEFINITION\'\'\'\' ) and OBJECT_SCHEMA_NAME(MAJOR_iD) IS NULL)   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select * from #TEMP;   \'','There are no permissions which are assigned to public.\r\n','There are some persmissions which are assigned to public\r\n','pass',NULL,NULL,'2026-02-11 17:34:34'),(1547,202602,50,28,'AA_SqlServer_220_Public Database Permissions','critical','PRIV','This test checks database permisions for public . Public is a special role and permissions should not be granted to public role.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      exec sp_msforeachdb \'\'   USE [?]     iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'public\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND OBJECT_NAME(MAJOR_iD) NOT LiKE (\'\'\'\'%fn_cdc_get_net_changes_application_data%\'\'\'\')   AND NOT (OBJECT_SCHEMA_NAME(MAJOR_iD) = \'\'\'\'cdc\'\'\'\' and PERMiSSiON_NAME=\'\'\'\'SELECT\'\'\'\')   AND NOT (PERMiSSiON_NAME IN (\'\'\'\'REFERENCES\'\'\'\',\'\'\'\'SEND\'\'\'\',   \'\'\'\'VIEW ANY COLUMN ENCRYPTION KEY DEFINITION\'\'\'\',   \'\'\'\'VIEW ANY COLUMN MASTER KEY DEFINITION\'\'\'\' ) and OBJECT_SCHEMA_NAME(MAJOR_iD) IS NULL)   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select count(*) from #TEMP;   \' \r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      exec sp_msforeachdb \'\'   USE [?]     iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'public\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND OBJECT_NAME(MAJOR_iD) NOT LiKE (\'\'\'\'%fn_cdc_get_net_changes_application_data%\'\'\'\')   AND NOT (OBJECT_SCHEMA_NAME(MAJOR_iD) = \'\'\'\'cdc\'\'\'\' and PERMiSSiON_NAME=\'\'\'\'SELECT\'\'\'\')   AND NOT (PERMiSSiON_NAME IN (\'\'\'\'REFERENCES\'\'\'\',\'\'\'\'SEND\'\'\'\',   \'\'\'\'VIEW ANY COLUMN ENCRYPTION KEY DEFINITION\'\'\'\',   \'\'\'\'VIEW ANY COLUMN MASTER KEY DEFINITION\'\'\'\' ) and OBJECT_SCHEMA_NAME(MAJOR_iD) IS NULL)   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select * from #TEMP;   \' \r\n','There are no permissions which are assigned to public.\r\n','There are some persmissions which are assigned to public\r\n','pass',NULL,NULL,'2026-02-11 17:34:34'),(1548,202602,50,29,'AA_SqlServer_230_Real person users','critical','ACCOUNT','All logins to the database should be made with AD groups, real person users should  not be connected database directly\r\n','','Select      count(*)   from      sys.server_principals    where      name like \'ODEABANK%.%\'      and is_disabled = 0   \r\n','== 0','','Select      name     from      sys.server_principals    where      name like \'ODEABANK%.%\'      and is_disabled = 0;\r\n','Real person users are not found in the logins\r\n','Some real person users are found in the logins\r\n','pass',NULL,NULL,'2026-02-11 17:34:34'),(1549,202602,50,30,'AA_SqlServer_240_2_guest Database Permissions','critical','ACCOUNT','This test checks database permisions for guest . guest is a special user and permissions should not be granted to guest user.\r\n','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP ( row varchar(500));\r\n\r\nexec sp_MSforeachdb \'\'\r\nUSE [?]\r\niNSERT iNTO #TEMP\r\nSELECT\r\n\'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +\r\n\'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +\r\n\'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +\r\n\'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )\r\nFROM\r\nsys.database_permissions\r\nWHERE\r\nUSER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'guest\'\'\'\' )\r\nAND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'\r\nAND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')\r\nAND STATE_DESC=\'\'\'\'GRANT\'\'\'\'\r\n;\r\n\'\'\r\nselect count(*) from #TEMP;\r\n\'','== 0','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP ( row varchar(500));\r\n\r\nexec sp_MSforeachdb \'\'\r\nUSE [?]\r\niNSERT iNTO #TEMP\r\nSELECT\r\n\'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +\r\n\'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +\r\n\'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +\r\n\'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )\r\nFROM\r\nsys.database_permissions\r\nWHERE\r\nUSER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'guest\'\'\'\' )\r\nAND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'\r\nAND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')\r\nAND STATE_DESC=\'\'\'\'GRANT\'\'\'\'\r\n;\r\n\'\'\r\nselect * from #TEMP;\r\n\'','There are no permissions which are assigned to guest.\r\n','There are some persmissions which are assigned to guest\r\n','pass',NULL,NULL,'2026-02-11 17:34:34'),(1550,202602,50,31,'AA_SqlServer_240_guest Database Permissions','critical','PRIV','This test checks database permisions for guest . guest is a special user and permissions should not be granted to guest user.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      exec sp_msforeachdb \'\'   USE [?]     iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'guest\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select count(*) from #TEMP;   \' \r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      exec sp_msforeachdb \'\'   USE [?]     iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'guest\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select  *  from #TEMP;   \' \r\n','There are no permissions which are assigned to guest.\r\n','There are some persmissions which are assigned to guest\r\n','pass',NULL,NULL,'2026-02-11 17:34:34'),(1551,202602,50,32,'AA_SqlServer_250_Database Role members for guest','critical','PRIV','This test checks database role members for guest  user. Database roles  could not be assigned to guest role.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      EXEC sp_MSforeachdb \'\' USE [?]    INSERT INTO #TEMP   SELECT \'\'\'\'DB Name : \'\'\'\'+Cast (DB_NAME() as varchar)+\'\'\'\' Role Name : \'\'\'\'+USER_NAME(role_principal_id)  +\'\'\'\' User Name \'\'\'\'+  USER_NAME(member_principal_id)    from  sys.database_role_members   	Where     USER_NAME(member_principal_id)  = \'\'\'\'guest\'\'\'\'     ;   \'\'      Select count(*)  from #TEMP;   \'\r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      EXEC sp_MSforeachdb \'\' USE [?]    INSERT INTO #TEMP   SELECT \'\'\'\'DB Name : \'\'\'\'+Cast (DB_NAME() as varchar)+\'\'\'\' Role Name : \'\'\'\'+USER_NAME(role_principal_id)  +\'\'\'\' User Name \'\'\'\'+  USER_NAME(member_principal_id)    from  sys.database_role_members   	Where     USER_NAME(member_principal_id)  = \'\'\'\'guest\'\'\'\'     ;   \'\'      Select  *  from #TEMP;   \'\r\n','Database role member usage for guest user  is correct\r\n','Database role member usage for guest user  is not correct\r\n','pass',NULL,NULL,'2026-02-11 17:34:34'),(1552,202602,50,33,'AA_SqlServer_260_SQL Logins with Null Password','critical','ACCOUNT','This test checks sql logins with null password. SQL Logins should not have null passwords.\r\n','','SELECT      count(name)   from      sys.sql_logins    WHERE      PWDCOMPARE(\'\', password_hash)= 1\r\n','== 0','','SELECT      name    from      sys.sql_logins    WHERE      PWDCOMPARE(\'\', password_hash)= 1   \r\n','There are no sql logins with null paswords\r\n','There are some sql logins with null passwords.\r\n','pass',NULL,NULL,'2026-02-11 17:34:34'),(1553,202602,50,34,'AA_SqlServer_270_SQL Logins with username and passwords are equal','critical','ACCOUNT','This test checks sql login password which are egual to username. Username and password must be different for SQL logins.\r\n','','SELECT      count(name)   from      sys.sql_logins    WHERE      PWDCOMPARE(name,password_hash)=1 \r\n','== 0','','SELECT      name    from      sys.sql_logins    WHERE      PWDCOMPARE(name,password_hash)=1    \r\n','There is no SQL login name which is equal to password.\r\n','There are some sql logins whose passwords are egual to usernames.\r\n','pass',NULL,NULL,'2026-02-11 17:34:34'),(1554,202602,50,35,'AA_SqlServer_280_No Sample Databases','critical','CONFIG','This test checks whether the sample databases created optionally on installation are present.  These sample databases contain many default permissions, and can be used as an entry point to your systems. \r\n','','select      count(name)    from      sys.databases    where      name in (       \'AdventureWorks\', \'AdventureWorksDW\',        \'Northwind\', \'Pubs\'     )   \r\n','== 0','','select      name    from      sys.databases    where      name in (       \'AdventureWorks\', \'AdventureWorksDW\',        \'Northwind\', \'Pubs\'     )   \r\n','There are no sample databases in the server\r\n','There are some sample databases in the server\r\n','pass',NULL,NULL,'2026-02-11 17:34:34'),(1555,202602,50,43,'AA_SqlServer_350_User Password Policy Is Checked','critical','ACCOUNT','This test checks that CHECK_POLICY is enabled for all users.  Enabling CHECK_POLICY ensures that Windows passwords policies are enforced.','','select count(*) from sys.sql_logins  \r\nwhere \r\nis_policy_checked=0 and\r\nname not like \'##%\'','== 0','','select name from sys.sql_logins  \r\nwhere \r\nis_policy_checked=0 and\r\nname not like \'##%\'','CHECK_POLICY is enabled for all users','CHECK_POLICY is not enabled for all users','pass',NULL,NULL,'2026-02-11 17:34:34'),(1556,202602,50,44,'AA_SqlServer_360_CHECK_EXPIRATION Is Checked','critical','ACCOUNT','This test checks that CHECK_EXPIRATION is enabled for all users.  Passwords that have been in use for long periods of time are likely to become known to unauthorized users.\r\n','','select count(*) from sys.sql_logins     where    is_expiration_checked=0 and   name not like \'##%\'\r\n','== 0','','select name from sys.sql_logins     where    is_expiration_checked=0 and   name not like \'##%\'\r\n','CHECK_EXPIRATION is enabled for all users\r\n','CHECK_EXPIRATION is not enabled for all users\r\n','fail','name\n----\n\'sa\'',NULL,'2026-02-11 17:34:34'),(1557,202602,50,22,'AA_SqlServer_170_Windows Authentication','major','AUTH','This test checks that the authentication mode is set to Windows authentication only.  Windows provides a more robust authentication mechanism than SQL Server authentication.','',' SELECT cast( SERVERPROPERTY(\'IsIntegratedSecurityOnly\') as int) ','==1','','SELECT cast( SERVERPROPERTY(\'IsIntegratedSecurityOnly\') as varchar)','The authentication mode is set to Windows authentication only. ','The authentication mode is not set to Windows authentication only.','fail','\n---\n\'0\'',NULL,'2026-02-11 17:34:34'),(1558,202602,50,23,'AA_SqlServer_180_No Guest User Accounts','major','ACCOUNT','This test checks for the existence of guest user accounts with CONNECT permission in database other than master, msdb and tempdb.  This test also exclude databases that are flagged as distributor. If the GUEST user exists and a specific login has not been granted to a database, a login will be mapped to GUEST. The presence of the GUEST user allows all logins to access the database.\r\n','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP  ( row int);\r\n\r\nEXEC sp_MSforeachdb \'\' USE [?]\r\n	INSERT INTO #TEMP\r\n	SELECT count(*) \r\n	FROM sys.database_permissions\r\n	WHERE [grantee_principal_id] = DATABASE_PRINCIPAL_ID(\'\'\'\'guest\'\'\'\')\r\n	AND [state_desc] LIKE \'\'\'\'GRANT%\'\'\'\'\r\n	AND [permission_name] = \'\'\'\'CONNECT\'\'\'\'\r\n	AND DB_NAME() NOT IN (\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'msdb\'\'\'\') ;\r\n\'\'\r\n\r\nSelect sum(row) from #TEMP;\r\ndrop table #TEMP;\r\n\'','== 0','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP  ( row varchar(500));\r\n\r\nEXEC sp_MSforeachdb \'\' USE  [?] \r\n	INSERT INTO #TEMP\r\n	SELECT \'\'\'\' DB NAME : \'\'\'\' + Cast (DB_NAME() as varchar) + \'\'\'\' guest user has CONNECT permission \'\'\'\'\r\n	FROM sys.database_permissions\r\n	WHERE [grantee_principal_id] = DATABASE_PRINCIPAL_ID(\'\'\'\'guest\'\'\'\')\r\n	AND [state_desc] LIKE \'\'\'\'GRANT%\'\'\'\'\r\n	AND [permission_name] = \'\'\'\'CONNECT\'\'\'\'\r\n	AND DB_NAME() NOT IN (\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'msdb\'\'\'\') ;\r\n\'\'\r\n\r\nSelect * from #TEMP;\r\ndrop table #TEMP;\r\n\'','There is no guest user with CONNECT permission. ','There are   guest users with CONNECT permission. Remove these users','pass',NULL,NULL,'2026-02-11 17:34:34'),(1559,202602,50,36,'AA_SqlServer_290_2_No Permissions with GRANT Option','major','PRIV','This test checks database permisions  with grant option. No permission with grant option should be defined in the database.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP ( row varchar(500));      exec sp_MSforeachdb \'\'   USE [?]   iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   STATE_DESC like \'\'\'\'%WITH_GRANT%\'\'\'\'   ;   \'\'   select count(*) from #TEMP;   \'\r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP ( row varchar(500));      exec sp_MSforeachdb \'\'   USE [?]   iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   STATE_DESC like \'\'\'\'%WITH_GRANT%\'\'\'\'   ;   \'\'   select * from #TEMP;   \'\r\n','There are no permissions with grant option.\r\n','There are some persmissions  with grant option.\r\n','pass',NULL,NULL,'2026-02-11 17:34:34'),(1560,202602,50,37,'AA_SqlServer_290_No Permissions with GRANT Option','major','PRIV','','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP  ( row varchar(500));\r\n\r\nexec sp_msforeachdb \'\'\r\nUSE [?]  \r\niNSERT iNTO #TEMP\r\nSELECT\r\n\'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +\r\n\'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +\r\n\'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +\r\n\'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )\r\nFROM\r\nsys.database_permissions\r\nWHERE\r\nSTATE_DESC like \'\'\'\'%WITH_GRANT%\'\'\'\'\r\n;\r\n\'\'\r\nselect  count(*)  from #TEMP;\r\n\' ','== 0','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP  ( row varchar(500));\r\n\r\nexec sp_msforeachdb \'\'\r\nUSE [?]  \r\niNSERT iNTO #TEMP\r\nSELECT\r\n\'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +\r\n\'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +\r\n\'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +\r\n\'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )\r\nFROM\r\nsys.database_permissions\r\nWHERE\r\nSTATE_DESC like \'\'\'\'%WITH_GRANT%\'\'\'\'\r\n;\r\n\'\'\r\nselect * from #TEMP;\r\n\' ','There are no permissions with grant option.\r\n','There are some persmissions  with grant option.\r\n','pass',NULL,NULL,'2026-02-11 17:34:34'),(1561,202602,50,40,'AA_SqlServer_320_No Access to Registry Access Extended procedures','major','PRIV','This test checks for the existence of, and user permissions on, registry access extended stored procedures.  Either these procedures should be completely dropped, or access to them should be strictly limited. xp_reg%,xp_instance_reg%\r\n','','SELECT \r\ncount(*) \r\nFROM \r\n  [master].sys.system_objects o \r\n  JOIN [master].sys.database_permissions p ON o.object_id = p.major_id \r\n  JOIN [master].sys.database_principals u ON p.grantee_principal_id = u.principal_id \r\nWHERE \r\n( o.name LIKE \'xp_reg%\' OR o.name LIKE \'xp_instance_reg%\')\r\n  AND p.type = \'EX\' ','== 0','','SELECT \r\n  \'Principal : \'+u.name  COLLATE DATABASE_DEFAULT +\r\n  \' Extended Procedure Name : \'+o.name COLLATE DATABASE_DEFAULT +\r\n  \' Type : \'+ u.type_desc COLLATE DATABASE_DEFAULT \r\nFROM \r\n  [master].sys.system_objects o \r\n  JOIN [master].sys.database_permissions p ON o.object_id = p.major_id \r\n  JOIN [master].sys.database_principals u ON p.grantee_principal_id = u.principal_id \r\nWHERE \r\n( o.name LIKE \'xp_reg%\' OR o.name LIKE \'xp_instance_reg%\')\r\n  AND p.type = \'EX\' ','There are no permissions on registry access extended stored procedures\r\n','There are some persmissions permissions on registry access extended stored procedures\r\n','fail','\n---------------------------------------------------------------------------------------\n\'Principal : public Extended Procedure Name : xp_instance_regread Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_regread Type : DATABASE_ROLE\'',NULL,'2026-02-11 17:34:34'),(1562,202602,50,41,'AA_SqlServer_330_Revoke public login from SQL Server agent proxy account','major','PRIV','The public database role contains every user in the msdb database. SQL Agent proxies   define a security context in which a job step can run.Granting access to SQL Agent proxies for the public role would allow all users to utilize the proxy which may have high privileges. This would likely break the principle of least   privileges.\r\n','','SELECT count(*)\r\nFROM msdb.dbo.sysproxylogin spl\r\nJOIN sys.database_principals dp\r\nON dp.sid = spl.sid\r\nJOIN msdb.dbo.sysproxies sp\r\nON sp.proxy_id = spl.proxy_id\r\nWHERE principal_id = USER_ID(\'public\')','== 0','','SELECT \'proxyname : \'+CAST(sp.name  as varchar)\r\nFROM msdb.dbo.sysproxylogin spl\r\nJOIN sys.database_principals dp\r\nON dp.sid = spl.sid\r\nJOIN msdb.dbo.sysproxies sp\r\nON sp.proxy_id = spl.proxy_id\r\nWHERE principal_id = USER_ID(\'public\')','There are no public permissions on SQL Server agent proxy account\r\n','There are some public permissions on SQL Server agent proxy account\r\n','pass',NULL,NULL,'2026-02-11 17:34:34'),(1563,202602,50,42,'AA_SqlServer_340_No Individual User Access To syscomment and sp_helptext','minor','PRIV','This test checks for grants on SYSCOMMENTS.TEXT.  Such grants allow any user to read the text comments associated with a database object, making the text publicly viewable.\r\n','','SELECT count(*)\r\nFROM msdb.dbo.sysproxylogin spl\r\nJOIN sys.database_principals dp\r\nON dp.sid = spl.sid\r\nJOIN msdb.dbo.sysproxies sp\r\nON sp.proxy_id = spl.proxy_id\r\nWHERE principal_id = USER_ID(\'public\')\r\n','== 0','','SELECT count(*)\r\nFROM msdb.dbo.sysproxylogin spl\r\nJOIN sys.database_principals dp\r\nON dp.sid = spl.sid\r\nJOIN msdb.dbo.sysproxies sp\r\nON sp.proxy_id = spl.proxy_id\r\nWHERE principal_id = USER_ID(\'public\')','There are no public permissions on SQL Server agent proxy account','There are some public permissions on SQL Server agent proxy account','pass',NULL,NULL,'2026-02-11 17:34:34'),(1564,202602,50,10,'AA_SqlServer_050_Disable Ad hoc distributed queries option','major','CONFIG','Adhoc queries allow undefined access to remote database sources.  Access to untrusted databases could result in execution of malicious applications and/or a compromise of local data confidentiality and integrity. The DBA will configure the database to disable access from the database to objects stored externally to the database on the local host unless mission and/or operationally required and documented.\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Ad Hoc Distributed Queries\'','== 0','','SELECT name + \' Value : \'+ cast( value as varchar ) + \' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'Ad Hoc Distributed Queries\'','Ad Hoc Distributed Queries is disabled','Ad Hoc Distributed Queries is not disabled. Disable this option','pass',NULL,NULL,'2026-02-11 17:34:34'),(1565,202602,50,11,'AA_SqlServer_060_Disable CLR option','major','CONFIG','The clr_enabled parameter configures SQL Server to allow or disallow use of Command Language Runtime objects.  CLR objects is managed code that integrates with the .NET Framework.  This is a more secure method than external stored procedures, although it still contains some risk.  Where no external application execution requirements are required, disallowing use of any improves the overall security posture of the database.\r\n\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'clr enabled\'','== 0','','SELECT name + \' Value : \'+ cast( value as varchar ) + \' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'clr enabled\'','CLR option is disabled','CLR option is not disabled. Disable this option','pass',NULL,NULL,'2026-02-11 17:34:34'),(1566,202602,50,12,'AA_SqlServer_070_Disable Cross db ownership chaining option','major','CONFIG','Cross database ownership chaining allows permissions to objects to be assigned by users other than the Information Owner.  This allows access to objects that are not authorized directly by the Information Owner based on job functions defined by the owner.  Unauthorized access may lead to a compromise of data integrity or confidentiality. The DBA will ensure database privileges are assigned via roles and not directly assigned to database accounts. Privileges may be assigned directly to application owner accounts where the DBMS does not otherwise support access via roles.\r\n\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'cross db ownership chaining\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'cross db ownership chaining\'','Cross db ownership chaining  option is disabled','Cross db ownership chaining option  is not disabled. Disable this option','pass',NULL,NULL,'2026-02-11 17:34:34'),(1567,202602,50,13,'AA_SqlServer_080_Disable Database Mail XPs option','major','CONFIG','SQL Mail accepts incoming database commands via email. This can introduce malicious codes or viruses into the SQL server environment.','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Database Mail XPs\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \'Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'Database Mail XPs\'','Database Mail XPs option is disabled','Database Mail XPs option  is not disabled. Disable this option','pass',NULL,NULL,'2026-02-11 17:34:34'),(1568,202602,50,14,'AA_SqlServer_100_Disable xp_cmdshell Server Configuration option','major','CONFIG','The xp_cmdshell extended stored procedures allows execution of host executables outside the controls of database access permissions.  This access may be exploited by malicious users who have compromised the integrity of the SQL Server database process to control the host operating system to perpetrate additional malicious activity. The DBA should disable the use of external procedures by the database unless it is mission critical or operationally required','','SELECT CAST(value as int) +\r\n       CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'xp_cmdshell\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) +\r\n\' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'xp_cmdshell\'','xp_cmdshell Server Configuration option is disabled','xp_cmdshell Server Configuration option is not disabled. This option must be disabled','pass',NULL,NULL,'2026-02-11 17:34:34'),(1569,202602,50,15,'AA_SqlServer_110_Disable Remote Access option','major','CONFIG','The remote access option controls the execution of local stored procedures on remote\r\nservers or remote stored procedures on local server.Functionality can be abused to launch a Denial-of-Service (DoS) attack on remote servers\r\nby off-loading query processing to a target.\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'remote access\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \' Value in use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'remote access\'','Remote Access option is disabled','Remote Access option  is not disabled. Disable this option','fail','\n------------------------------------------\n\'remote access Value : 1 Value in use : 1\'',NULL,'2026-02-11 17:34:34'),(1570,202602,50,16,'AA_SqlServer_120_Disable Remote Admin Connections option','major','CONFIG','The remote admin connections option controls whether a client application on a remote\r\ncomputer can use the Dedicated Administrator Connection (DAC).The Dedicated Administrator Connection (DAC) lets an administrator access a running\r\nserver to execute diagnostic functions or Transact-SQL statements, or to troubleshoot\r\nproblems on the server, even when the server is locked or running in an abnormal state\r\nand not responding to a SQL Server Database Engine connection. In a cluster scenario, the\r\nadministrator may not actually be logged on to the same node that is currently hosting the\r\nSQL Server instance and thus is considered \"remote\". Therefore, this setting should usually\r\nbe enabled (1) for SQL Server failover clusters; otherwise it should be disabled (0) which is\r\nthe default.\r\n','','execute sp_executesql N\'\r\n\r\nDECLARE @x int;\r\n\r\nSELECT @x=isnull(CAST(value as int) + CAST(value_in_use as int),100)\r\nFROM sys.configurations\r\nWHERE name = \'\'remote admin connections\'\'\r\n\r\nIF @x = 100\r\n       SELECT 0 ;\r\nELSE \r\n   SELECT CAST(value as int) + CAST(value_in_use as int) \r\n   FROM sys.configurations\r\n   WHERE name = \'\'remote admin connections\'\'\r\n\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'remote admin connections\'','Remote Admin Connections option is disabled','Remote Admin Connections option  is not disabled. Disable this option','pass',NULL,NULL,'2026-02-11 17:34:34'),(1571,202602,50,19,'AA_SqlServer_150_Disable database trustworthy status','major','CONFIG','The TRUSTWORTHY database setting restricts access to database resources by databases that contain assemblies with the EXTERNAL_ACCESS or UNSAFE permission settings and modules that use impersonation of accounts assigned elevated privileges.  Unless all assemblies and code for the database have been reviewed, especially in the case where databases have been detached and attached between server instances, leaving the TRUSTWORTHY status to off can help reduce threats from malicious assemblies or modules.','','SELECT count(name)\r\nFROM sys.databases\r\nWHERE is_trustworthy_on = 1\r\nAND name != \'msdb\';','== 0','','SELECT name\r\nFROM sys.databases\r\nWHERE is_trustworthy_on = 1\r\nAND name != \'msdb\';','database trustworthy status is disabled','database trustworthy status is not disabled. Disable this option','pass',NULL,NULL,'2026-02-11 17:34:34'),(1572,202602,50,20,'Checkpoint başarıyla oluşturuldu.','major','CONFIG','This test checks if SQL Server Instance is not advertised by the SQL Server Browser service. To maintain a higher level of protection for database instances, we recommend that SQL Server Instance be hidden when it is not required. Please note that this test does not include Clustered Instances as turning off this feature may cause issues with the Clustered environment.\r\n\r\n','','execute sp_executesql N\'\r\n\r\nDECLARE @getValue INT\r\n\r\nEXEC master.sys.xp_instance_regread\r\n@rootkey = N\'\'HKEY_LOCAL_MACHINE\'\',\r\n@key = N\'\'SOFTWARE\\Microsoft\\Microsoft SQL Server\\MSSQLServer\\SuperSocketNetLib\'\',\r\n@value_name = N\'\'HideInstance\'\',\r\n@value = @getValue OUTPUT\r\n\r\nSELECT isnull(@getvalue,0)\'','==1','','execute sp_executesql N\'\r\n\r\nDECLARE @getValue INT\r\n\r\nEXEC master.sys.xp_instance_regread\r\n@rootkey = N\'\'HKEY_LOCAL_MACHINE\'\',\r\n@key = N\'\'SOFTWARE\\Microsoft\\Microsoft SQL Server\\MSSQLServer\\SuperSocketNetLib\'\',\r\n@value_name = N\'\'HideInstance\'\',\r\n@value = @getValue OUTPUT\r\n\r\nSELECT isnull(@getvalue,0)\'','SQL Server Instance is  hidden.\r\n','SQL Server Instance is not hidden. Hide the instance','fail','\n-\n0',NULL,'2026-02-11 17:34:34'),(1573,202602,50,21,'AA_SqlServer_160_Hide SQL Server Instance','major','CONFIG','This test checks if SQL Server Instance is not advertised by the SQL Server Browser service. To maintain a higher level of protection for database instances, we recommend that SQL Server Instance be hidden when it is not required. Please note that this test does not include Clustered Instances as turning off this feature may cause issues with the Clustered environment.\r\n\r\n','','execute sp_executesql N\'\r\n\r\nDECLARE @getValue INT\r\n\r\nEXEC master.sys.xp_instance_regread\r\n@rootkey = N\'\'HKEY_LOCAL_MACHINE\'\',\r\n@key = N\'\'SOFTWARE\\Microsoft\\Microsoft SQL Server\\MSSQLServer\\SuperSocketNetLib\'\',\r\n@value_name = N\'\'HideInstance\'\',\r\n@value = @getValue OUTPUT\r\n\r\nSELECT isnull(@getvalue,0)\'','==1','','execute sp_executesql N\'\r\n\r\nDECLARE @getValue INT\r\n\r\nEXEC master.sys.xp_instance_regread\r\n@rootkey = N\'\'HKEY_LOCAL_MACHINE\'\',\r\n@key = N\'\'SOFTWARE\\Microsoft\\Microsoft SQL Server\\MSSQLServer\\SuperSocketNetLib\'\',\r\n@value_name = N\'\'HideInstance\'\',\r\n@value = @getValue OUTPUT\r\n\r\nSELECT isnull(@getvalue,0)\'','SQL Server Instance is  hidden.','SQL Server Instance is not hidden. Hide the instance','fail','\n-\n0',NULL,'2026-02-11 17:34:34'),(1574,202602,50,38,'AA_SqlServer_300_No Access To General Extended procedures','major','PRIV','This test checks for the existence of, and user permissions on, extended stored procedures.  Either these procedures should be completely dropped, or access to them should be strictly limited. xp_cmdshell, xp_enumgroups, xp_grantlogin ,xp_logevent, xp_logininfo,    xp_msver, xp_revokelogin, xp_sprintf, xp_sqlmaint, xp_sscanf\r\n','','SELECT \r\ncount(*) \r\nFROM \r\n  [master].sys.system_objects o \r\n  JOIN [master].sys.database_permissions p ON o.object_id = p.major_id \r\n  JOIN [master].sys.database_principals u ON p.grantee_principal_id = u.principal_id \r\nWHERE \r\n    o.name in ( \r\n	\'xp_cmdshell\', \r\n	\'xp_enumgroups\', \r\n    \'xp_grantlogin\' ,\r\n	\'xp_logevent\', \r\n	\'xp_logininfo\', \r\n    \'xp_msver\', \r\n	\'xp_revokelogin\', \r\n	\'xp_sprintf\', \r\n    \'xp_sqlmaint\', \r\n	\'xp_sscanf\' )\r\n  AND p.type = \'EX\' ','== 0','','SELECT \r\n  \'Principal : \'+u.name  COLLATE DATABASE_DEFAULT +\r\n  \' Extended Procedure Name : \'+o.name COLLATE DATABASE_DEFAULT +\r\n  \' Type : \'+ u.type_desc COLLATE DATABASE_DEFAULT \r\nFROM \r\n  [master].sys.system_objects o \r\n  JOIN [master].sys.database_permissions p ON o.object_id = p.major_id \r\n  JOIN [master].sys.database_principals u ON p.grantee_principal_id = u.principal_id \r\nWHERE \r\n    o.name in ( \r\n	\'xp_cmdshell\', \r\n	\'xp_enumgroups\', \r\n    \'xp_grantlogin\' ,\r\n	\'xp_logevent\', \r\n	\'xp_logininfo\', \r\n    \'xp_msver\', \r\n	\'xp_revokelogin\', \r\n	\'xp_sprintf\', \r\n    \'xp_sqlmaint\', \r\n	\'xp_sscanf\' )\r\n  AND p.type = \'EX\' ','There are no permissions on general extended stored procedures\r\n','There are some persmissions permissions on general extended stored procedures.\r\n','fail','\n----------------------------------------------------------------------------------\n\'Principal : public Extended Procedure Name : xp_msver Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_sscanf Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_revokelogin Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_grantlogin Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_sprintf Type : DATABASE_ROLE\'',NULL,'2026-02-11 17:34:34'),(1575,202602,50,39,'AA_SqlServer_310_No Access to OLE Automation procedures','major','CONFIG','This test checks for the existence of,and user permissions on OLE automation extended stored procedures.  Either these procedures should be completely dropped, or access to them should be strictly limited.      \r\n','','SELECT CAST(value as int) +\r\n       CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Ole Automation Procedures\'   \r\n','== 0','','SELECT CAST(value as int) +\r\n       CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Ole Automation Procedures\'\r\n  \r\n','OLE Automation procedures  option is disabled\r\n','OLE Automation procedures  option  is not disabled. Disable this option\r\n','pass',NULL,NULL,'2026-02-11 17:34:34'),(1576,202602,50,17,'AA_SqlServer_130_Disable Ole Automation Procedures option','minor','CONFIG','This test checks if Ole Automation Procedures option is disabled. Ole Automation Procedures option allows SQL Server users to execute functions external to SQL Server. Enabling this option will increase the attack surface of SQL Server and allow users to execute functions in the security context of SQL Server. We recommend that the Ole Automation Procedures option to be disabled when it is not document as a requirement.\r\n\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Ole Automation Procedures\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \'Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'Ole Automation Procedures\'',' Ole Automation Procedures option is disabled',' Ole Automation Procedures option  is not disabled. Disable this option','pass',NULL,NULL,'2026-02-11 17:34:34'),(1577,202602,50,18,'AA_SqlServer_140_Disable Scan for Startup Procedures option','minor','CONFIG','This test checks if scan for startup procedures is disabled. This feature causes SQL Server to scan for and automatically run all stored procedures that are set to execute upon service startup. If there are no user-defined stored procedures set to execute when SQL server starts, we recommend this feature to be disabled.\r\n\r\n','','SELECT CAST(value as int) +\r\n       CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'scan for startup procs\'','== 0','','SELECT name + \' value : \'+cast( value as varchar ) +\r\n\' value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'scan for startup procs\'','Scan for Startup Procedures  option is disabled','Scan for Startup Procedures  option  is not disabled. Disable this option','pass',NULL,NULL,'2026-02-11 17:34:34'),(1578,202602,50,9,'AA_SqlServer_040_Rename the sa Login Account','major','ACCOUNT','The \'sa\' account is a well-known account.  Well-known account names provide an easier target for attack.  Renaming the sa account helps reduce the risk of an attack to this built-in account.','','SELECT count(*)\r\nFROM sys.server_principals\r\nWHERE sid = 0x01 and name=\'sa\'','== 0','','SELECT name\r\nFROM sys.server_principals\r\nWHERE sid = 0x01','sa Login Account is renamed','sa Login Account is not renamed. Rename this account','fail','name\n----\n\'sa\'',NULL,'2026-02-11 17:34:34'),(1579,202602,51,24,'AA_SqlServer_190_Public server role permision','critical','PRIV','public is a special fixed server role containing all logins. Unlike other fixed server roles,\r\npermissions can be changed for the public role. In keeping with the principle of least\r\nprivileges, the public server role should not be used to grant permissions at the server\r\nscope as these would be inherited by all users.\r\n\r\nEvery SQL Server login belongs to the public role and cannot be removed from this role.\r\nTherefore, any permissions granted to this role will be available to all logins unless they\r\nhave been explicitly denied to specific logins or user-defined server roles.','','Select \r\n  count (permission_name) \r\nfrom \r\n  sys.server_permissions \r\nwhere \r\n  SUSER_NAME(grantee_principal_id) = \'public\' \r\n  and permission_name not in (\'VIEW ANY DATABASE\', \'CONNECT\')\r\n','== 0','','Select \r\n  permission_name \r\nfrom \r\n  sys.server_permissions \r\nwhere \r\n  SUSER_NAME(grantee_principal_id) = \'public\' \r\n  and permission_name not in (\'VIEW ANY DATABASE\', \'CONNECT\')\r\n\r\n','No server permissions are granted to public.','Some server permissions are granted to public.','pass',NULL,NULL,'2026-02-11 17:47:34'),(1580,202602,51,5,'AA_SqlServer_010_Supported SQL Server version','critical','PATCH','This test checks whether your current SQL Server version is a vendor-supported version.  Microsoft does not provide security fixes or software updates to unsupported software versions','','SELECT cast(ISNULL(SERVERPROPERTY(\'ProductMajorVersion\'),0) as int)   ','>=11','','SELECT \'Product Major version \' +  cast(ISNULL(SERVERPROPERTY(\'ProductMajorVersion\'),\'Null\' ) as  char ) ','The version of the database is acceptable.','The version of the database is not acceptable. The database version should SQL Sever 2012 or upper.','pass',NULL,NULL,'2026-02-11 17:47:34'),(1581,202602,51,6,'AA_SqlServer_020_Disable the sa Login Account','critical','ACCOUNT','This test checks if the \'sa\' Login Account is disabled. The sa account is a widely known and often widely used SQL Server account with sysadmin privileges. Enforcing this control reduces the probability of an attacker executing brute force attacks against a well-known principal.','','SELECT  count(*)\r\nFROM sys.server_principals\r\nWHERE sid = 0x01\r\nAND is_disabled = 0','== 0','','SELECT \'sa user name : \'+ name+\' is disabled : \' +  cast( is_disabled as char)\r\nFROM sys.server_principals\r\nWHERE sid = 0x01\r\n','sa Login Account is disabled','Disable sa login account','fail','\n----------------------------------------------------------------\n\'sa user name : sa is disabled : 0                             \'',NULL,'2026-02-11 17:47:34'),(1582,202602,51,7,'AA_SqlServer_025_sa Change password','critical','ACCOUNT','This test checks that sa password change . The sa password should be changed in every two days','','select datediff( day,  modify_date , getdate() ) FROM sys.server_principals\r\nWHERE sid = 0x01  ','< 3','','select datediff( day,  modify_date , getdate() ) FROM sys.server_principals\r\nWHERE sid = 0x01 ','sa password was changed in two days','','fail','\n--\n28',NULL,'2026-02-11 17:47:34'),(1583,202602,51,8,'AA_SqlServer_030_Ensure no Login exists with sa Login Account','critical','ACCOUNT','The \'sa\' account is a well-known account.  Well-known account names provide an easier target for attack. The lack of the sa account helps reduce the risk of an attack to this built-in account.','','SELECT count(*)\r\nFROM sys.server_principals\r\nWHERE name = \'sa\'','== 0','','SELECT name\r\nFROM sys.server_principals\r\nWHERE name = \'sa\'','There is no the sa account in the database.','There is the sa Login account in the database.Drop this user or rename et.','fail','name\n----\n\'sa\'',NULL,'2026-02-11 17:47:34'),(1584,202602,51,25,'AA_SqlServer_200_Fixed Server Role members for users','critical','PRIV','This test checks fixed server roles for analyst , developers and real persons. Fixed server roles could not be assigned to real person users ( Developer, Analyst users ) . Only Admin can use fixed server role.\r\n','','Select     count(*)   from      sys.server_role_members    where      (       suser_name(member_principal_id) like \'ODEABANK%.%\'    	AND       suser_name(member_principal_id) not like \'%admin%\'         AND       suser_name(member_principal_id) not like \'%t.coban%\'     )      OR (       suser_name(member_principal_id) like \'ODEABANK\\Cyberark_Intertech%\'     )      \r\n','== 0','','Select      suser_name(role_principal_id) + \'   \' + suser_name(member_principal_id)    from      sys.server_role_members    where      (       suser_name(member_principal_id) like \'ODEABANK%.%\'    	AND       suser_name(member_principal_id) not like \'%admin%\'         AND       suser_name(member_principal_id) not like \'%t.coban%\'     )      OR (       suser_name(member_principal_id) like \'ODEABANK\\Cyberark_Intertech%\'     )          \r\n','Fixed Server role usage is correct.\r\n','Fixed Server role usage is not correct.\r\n','pass',NULL,NULL,'2026-02-11 17:47:34'),(1585,202602,51,26,'AA_SqlServer_210_Database Role members for users','critical','PRIV','This test checks database role members for analyst and real person users. Database roles  except  db_datareader could not be assigned to real person users ( Developer, Analyst users ) .\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      EXEC sp_MSforeachdb \'\' USE [?]    INSERT INTO #TEMP   SELECT \'\'\'\'DB Name : \'\'\'\'+Cast (DB_NAME() as varchar)+\'\'\'\' Role Name : \'\'\'\'+USER_NAME(role_principal_id)  +\'\'\'\' User Name \'\'\'\'+  USER_NAME(member_principal_id)    from  sys.database_role_members   	Where   	(   	( USER_NAME(member_principal_id)  like \'\'\'\'%ODEABANK%.%\'\'\'\'  and   USER_NAME(member_principal_id)  not like \'\'\'\'%admin%\'\'\'\' )     	OR   	  (suser_name(member_principal_id) like \'\'\'\'%ODEABANK%Cyberark%\'\'\'\')       )    	AND   	DB_NAME() <> \'\'\'\'master\'\'\'\' and   	USER_NAME(role_principal_id) not in (\'\'\'\'db_datareader\'\'\'\',\'\'\'\'db_viewdefinition\'\'\'\',\'\'\'\'db_denydatareader\'\'\'\',\'\'\'\'db_deny_maas\'\'\'\');   \'\'      Select  count(*)  from #TEMP;   \'\r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      EXEC sp_MSforeachdb \'\' USE [?]    INSERT INTO #TEMP   SELECT \'\'\'\'DB Name : \'\'\'\'+Cast (DB_NAME() as varchar)+\'\'\'\' Role Name : \'\'\'\'+USER_NAME(role_principal_id)  +\'\'\'\' User Name \'\'\'\'+  USER_NAME(member_principal_id)    from  sys.database_role_members   	Where   (   	( USER_NAME(member_principal_id)  like \'\'\'\'%ODEABANK%.%\'\'\'\'  and   USER_NAME(member_principal_id)  not like \'\'\'\'%admin%\'\'\'\' )     	OR   	(suser_name(member_principal_id) like \'\'\'\'%ODEABANK%Cyberark%\'\'\'\')   )    	AND   	DB_NAME() <> \'\'\'\'master\'\'\'\' and   	USER_NAME(role_principal_id) not in  (\'\'\'\'db_datareader\'\'\'\',\'\'\'\'db_viewdefinition\'\'\'\',\'\'\'\'db_denydatareader\'\'\'\',\'\'\'\'db_deny_maas\'\'\'\');   \'\'      Select  * from #TEMP;   \'\r\n','Database role member usage for users  is correct\r\n','Database role member usage for users  is not correct\r\n','pass',NULL,NULL,'2026-02-11 17:47:34'),(1586,202602,51,27,'AA_SqlServer_220_2_Public Database Permissions','critical','PRIV','This test checks database permisions for public . Public is a special role and permissions should not be granted to public role.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP ( row varchar(500));          exec sp_MSforeachdb \'\'   USE [?]   iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'public\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND OBJECT_NAME(MAJOR_iD) NOT LiKE (\'\'\'\'%fn_cdc_get_net_changes_application_data%\'\'\'\')   AND NOT (OBJECT_SCHEMA_NAME(MAJOR_iD) = \'\'\'\'cdc\'\'\'\' and PERMiSSiON_NAME=\'\'\'\'SELECT\'\'\'\')   AND NOT (PERMiSSiON_NAME IN (\'\'\'\'REFERENCES\'\'\'\',\'\'\'\'SEND\'\'\'\',   \'\'\'\'VIEW ANY COLUMN ENCRYPTION KEY DEFINITION\'\'\'\',   \'\'\'\'VIEW ANY COLUMN MASTER KEY DEFINITION\'\'\'\' ) and OBJECT_SCHEMA_NAME(MAJOR_iD) IS NULL)   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select count(*) from #TEMP;   \'\r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP ( row varchar(500));          exec sp_MSforeachdb \'\'   USE [?]   iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'public\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND OBJECT_NAME(MAJOR_iD) NOT LiKE (\'\'\'\'%fn_cdc_get_net_changes_application_data%\'\'\'\')   AND NOT (OBJECT_SCHEMA_NAME(MAJOR_iD) = \'\'\'\'cdc\'\'\'\' and PERMiSSiON_NAME=\'\'\'\'SELECT\'\'\'\')   AND NOT (PERMiSSiON_NAME IN (\'\'\'\'REFERENCES\'\'\'\',\'\'\'\'SEND\'\'\'\',   \'\'\'\'VIEW ANY COLUMN ENCRYPTION KEY DEFINITION\'\'\'\',   \'\'\'\'VIEW ANY COLUMN MASTER KEY DEFINITION\'\'\'\' ) and OBJECT_SCHEMA_NAME(MAJOR_iD) IS NULL)   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select * from #TEMP;   \'','There are no permissions which are assigned to public.\r\n','There are some persmissions which are assigned to public\r\n','pass',NULL,NULL,'2026-02-11 17:47:34'),(1587,202602,51,28,'AA_SqlServer_220_Public Database Permissions','critical','PRIV','This test checks database permisions for public . Public is a special role and permissions should not be granted to public role.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      exec sp_msforeachdb \'\'   USE [?]     iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'public\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND OBJECT_NAME(MAJOR_iD) NOT LiKE (\'\'\'\'%fn_cdc_get_net_changes_application_data%\'\'\'\')   AND NOT (OBJECT_SCHEMA_NAME(MAJOR_iD) = \'\'\'\'cdc\'\'\'\' and PERMiSSiON_NAME=\'\'\'\'SELECT\'\'\'\')   AND NOT (PERMiSSiON_NAME IN (\'\'\'\'REFERENCES\'\'\'\',\'\'\'\'SEND\'\'\'\',   \'\'\'\'VIEW ANY COLUMN ENCRYPTION KEY DEFINITION\'\'\'\',   \'\'\'\'VIEW ANY COLUMN MASTER KEY DEFINITION\'\'\'\' ) and OBJECT_SCHEMA_NAME(MAJOR_iD) IS NULL)   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select count(*) from #TEMP;   \' \r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      exec sp_msforeachdb \'\'   USE [?]     iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'public\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND OBJECT_NAME(MAJOR_iD) NOT LiKE (\'\'\'\'%fn_cdc_get_net_changes_application_data%\'\'\'\')   AND NOT (OBJECT_SCHEMA_NAME(MAJOR_iD) = \'\'\'\'cdc\'\'\'\' and PERMiSSiON_NAME=\'\'\'\'SELECT\'\'\'\')   AND NOT (PERMiSSiON_NAME IN (\'\'\'\'REFERENCES\'\'\'\',\'\'\'\'SEND\'\'\'\',   \'\'\'\'VIEW ANY COLUMN ENCRYPTION KEY DEFINITION\'\'\'\',   \'\'\'\'VIEW ANY COLUMN MASTER KEY DEFINITION\'\'\'\' ) and OBJECT_SCHEMA_NAME(MAJOR_iD) IS NULL)   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select * from #TEMP;   \' \r\n','There are no permissions which are assigned to public.\r\n','There are some persmissions which are assigned to public\r\n','pass',NULL,NULL,'2026-02-11 17:47:34'),(1588,202602,51,29,'AA_SqlServer_230_Real person users','critical','ACCOUNT','All logins to the database should be made with AD groups, real person users should  not be connected database directly\r\n','','Select      count(*)   from      sys.server_principals    where      name like \'ODEABANK%.%\'      and is_disabled = 0   \r\n','== 0','','Select      name     from      sys.server_principals    where      name like \'ODEABANK%.%\'      and is_disabled = 0;\r\n','Real person users are not found in the logins\r\n','Some real person users are found in the logins\r\n','pass',NULL,NULL,'2026-02-11 17:47:34'),(1589,202602,51,30,'AA_SqlServer_240_2_guest Database Permissions','critical','ACCOUNT','This test checks database permisions for guest . guest is a special user and permissions should not be granted to guest user.\r\n','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP ( row varchar(500));\r\n\r\nexec sp_MSforeachdb \'\'\r\nUSE [?]\r\niNSERT iNTO #TEMP\r\nSELECT\r\n\'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +\r\n\'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +\r\n\'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +\r\n\'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )\r\nFROM\r\nsys.database_permissions\r\nWHERE\r\nUSER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'guest\'\'\'\' )\r\nAND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'\r\nAND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')\r\nAND STATE_DESC=\'\'\'\'GRANT\'\'\'\'\r\n;\r\n\'\'\r\nselect count(*) from #TEMP;\r\n\'','== 0','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP ( row varchar(500));\r\n\r\nexec sp_MSforeachdb \'\'\r\nUSE [?]\r\niNSERT iNTO #TEMP\r\nSELECT\r\n\'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +\r\n\'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +\r\n\'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +\r\n\'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )\r\nFROM\r\nsys.database_permissions\r\nWHERE\r\nUSER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'guest\'\'\'\' )\r\nAND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'\r\nAND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')\r\nAND STATE_DESC=\'\'\'\'GRANT\'\'\'\'\r\n;\r\n\'\'\r\nselect * from #TEMP;\r\n\'','There are no permissions which are assigned to guest.\r\n','There are some persmissions which are assigned to guest\r\n','pass',NULL,NULL,'2026-02-11 17:47:34'),(1590,202602,51,31,'AA_SqlServer_240_guest Database Permissions','critical','PRIV','This test checks database permisions for guest . guest is a special user and permissions should not be granted to guest user.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      exec sp_msforeachdb \'\'   USE [?]     iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'guest\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select count(*) from #TEMP;   \' \r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      exec sp_msforeachdb \'\'   USE [?]     iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'guest\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select  *  from #TEMP;   \' \r\n','There are no permissions which are assigned to guest.\r\n','There are some persmissions which are assigned to guest\r\n','pass',NULL,NULL,'2026-02-11 17:47:34'),(1591,202602,51,32,'AA_SqlServer_250_Database Role members for guest','critical','PRIV','This test checks database role members for guest  user. Database roles  could not be assigned to guest role.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      EXEC sp_MSforeachdb \'\' USE [?]    INSERT INTO #TEMP   SELECT \'\'\'\'DB Name : \'\'\'\'+Cast (DB_NAME() as varchar)+\'\'\'\' Role Name : \'\'\'\'+USER_NAME(role_principal_id)  +\'\'\'\' User Name \'\'\'\'+  USER_NAME(member_principal_id)    from  sys.database_role_members   	Where     USER_NAME(member_principal_id)  = \'\'\'\'guest\'\'\'\'     ;   \'\'      Select count(*)  from #TEMP;   \'\r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      EXEC sp_MSforeachdb \'\' USE [?]    INSERT INTO #TEMP   SELECT \'\'\'\'DB Name : \'\'\'\'+Cast (DB_NAME() as varchar)+\'\'\'\' Role Name : \'\'\'\'+USER_NAME(role_principal_id)  +\'\'\'\' User Name \'\'\'\'+  USER_NAME(member_principal_id)    from  sys.database_role_members   	Where     USER_NAME(member_principal_id)  = \'\'\'\'guest\'\'\'\'     ;   \'\'      Select  *  from #TEMP;   \'\r\n','Database role member usage for guest user  is correct\r\n','Database role member usage for guest user  is not correct\r\n','pass',NULL,NULL,'2026-02-11 17:47:34'),(1592,202602,51,33,'AA_SqlServer_260_SQL Logins with Null Password','critical','ACCOUNT','This test checks sql logins with null password. SQL Logins should not have null passwords.\r\n','','SELECT      count(name)   from      sys.sql_logins    WHERE      PWDCOMPARE(\'\', password_hash)= 1\r\n','== 0','','SELECT      name    from      sys.sql_logins    WHERE      PWDCOMPARE(\'\', password_hash)= 1   \r\n','There are no sql logins with null paswords\r\n','There are some sql logins with null passwords.\r\n','pass',NULL,NULL,'2026-02-11 17:47:34'),(1593,202602,51,34,'AA_SqlServer_270_SQL Logins with username and passwords are equal','critical','ACCOUNT','This test checks sql login password which are egual to username. Username and password must be different for SQL logins.\r\n','','SELECT      count(name)   from      sys.sql_logins    WHERE      PWDCOMPARE(name,password_hash)=1 \r\n','== 0','','SELECT      name    from      sys.sql_logins    WHERE      PWDCOMPARE(name,password_hash)=1    \r\n','There is no SQL login name which is equal to password.\r\n','There are some sql logins whose passwords are egual to usernames.\r\n','pass',NULL,NULL,'2026-02-11 17:47:34'),(1594,202602,51,35,'AA_SqlServer_280_No Sample Databases','critical','CONFIG','This test checks whether the sample databases created optionally on installation are present.  These sample databases contain many default permissions, and can be used as an entry point to your systems. \r\n','','select      count(name)    from      sys.databases    where      name in (       \'AdventureWorks\', \'AdventureWorksDW\',        \'Northwind\', \'Pubs\'     )   \r\n','== 0','','select      name    from      sys.databases    where      name in (       \'AdventureWorks\', \'AdventureWorksDW\',        \'Northwind\', \'Pubs\'     )   \r\n','There are no sample databases in the server\r\n','There are some sample databases in the server\r\n','pass',NULL,NULL,'2026-02-11 17:47:34'),(1595,202602,51,43,'AA_SqlServer_350_User Password Policy Is Checked','critical','ACCOUNT','This test checks that CHECK_POLICY is enabled for all users.  Enabling CHECK_POLICY ensures that Windows passwords policies are enforced.','','select count(*) from sys.sql_logins  \r\nwhere \r\nis_policy_checked=0 and\r\nname not like \'##%\'','== 0','','select name from sys.sql_logins  \r\nwhere \r\nis_policy_checked=0 and\r\nname not like \'##%\'','CHECK_POLICY is enabled for all users','CHECK_POLICY is not enabled for all users','pass',NULL,NULL,'2026-02-11 17:47:34'),(1596,202602,51,44,'AA_SqlServer_360_CHECK_EXPIRATION Is Checked','critical','ACCOUNT','This test checks that CHECK_EXPIRATION is enabled for all users.  Passwords that have been in use for long periods of time are likely to become known to unauthorized users.\r\n','','select count(*) from sys.sql_logins     where    is_expiration_checked=0 and   name not like \'##%\'\r\n','== 0','','select name from sys.sql_logins     where    is_expiration_checked=0 and   name not like \'##%\'\r\n','CHECK_EXPIRATION is enabled for all users\r\n','CHECK_EXPIRATION is not enabled for all users\r\n','fail','name\n----\n\'sa\'',NULL,'2026-02-11 17:47:34'),(1597,202602,51,22,'AA_SqlServer_170_Windows Authentication','major','AUTH','This test checks that the authentication mode is set to Windows authentication only.  Windows provides a more robust authentication mechanism than SQL Server authentication.','',' SELECT cast( SERVERPROPERTY(\'IsIntegratedSecurityOnly\') as int) ','==1','','SELECT cast( SERVERPROPERTY(\'IsIntegratedSecurityOnly\') as varchar)','The authentication mode is set to Windows authentication only. ','The authentication mode is not set to Windows authentication only.','fail','\n---\n\'0\'',NULL,'2026-02-11 17:47:34'),(1598,202602,51,23,'AA_SqlServer_180_No Guest User Accounts','major','ACCOUNT','This test checks for the existence of guest user accounts with CONNECT permission in database other than master, msdb and tempdb.  This test also exclude databases that are flagged as distributor. If the GUEST user exists and a specific login has not been granted to a database, a login will be mapped to GUEST. The presence of the GUEST user allows all logins to access the database.\r\n','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP  ( row int);\r\n\r\nEXEC sp_MSforeachdb \'\' USE [?]\r\n	INSERT INTO #TEMP\r\n	SELECT count(*) \r\n	FROM sys.database_permissions\r\n	WHERE [grantee_principal_id] = DATABASE_PRINCIPAL_ID(\'\'\'\'guest\'\'\'\')\r\n	AND [state_desc] LIKE \'\'\'\'GRANT%\'\'\'\'\r\n	AND [permission_name] = \'\'\'\'CONNECT\'\'\'\'\r\n	AND DB_NAME() NOT IN (\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'msdb\'\'\'\') ;\r\n\'\'\r\n\r\nSelect sum(row) from #TEMP;\r\ndrop table #TEMP;\r\n\'','== 0','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP  ( row varchar(500));\r\n\r\nEXEC sp_MSforeachdb \'\' USE  [?] \r\n	INSERT INTO #TEMP\r\n	SELECT \'\'\'\' DB NAME : \'\'\'\' + Cast (DB_NAME() as varchar) + \'\'\'\' guest user has CONNECT permission \'\'\'\'\r\n	FROM sys.database_permissions\r\n	WHERE [grantee_principal_id] = DATABASE_PRINCIPAL_ID(\'\'\'\'guest\'\'\'\')\r\n	AND [state_desc] LIKE \'\'\'\'GRANT%\'\'\'\'\r\n	AND [permission_name] = \'\'\'\'CONNECT\'\'\'\'\r\n	AND DB_NAME() NOT IN (\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'msdb\'\'\'\') ;\r\n\'\'\r\n\r\nSelect * from #TEMP;\r\ndrop table #TEMP;\r\n\'','There is no guest user with CONNECT permission. ','There are   guest users with CONNECT permission. Remove these users','pass',NULL,NULL,'2026-02-11 17:47:34'),(1599,202602,51,36,'AA_SqlServer_290_2_No Permissions with GRANT Option','major','PRIV','This test checks database permisions  with grant option. No permission with grant option should be defined in the database.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP ( row varchar(500));      exec sp_MSforeachdb \'\'   USE [?]   iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   STATE_DESC like \'\'\'\'%WITH_GRANT%\'\'\'\'   ;   \'\'   select count(*) from #TEMP;   \'\r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP ( row varchar(500));      exec sp_MSforeachdb \'\'   USE [?]   iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   STATE_DESC like \'\'\'\'%WITH_GRANT%\'\'\'\'   ;   \'\'   select * from #TEMP;   \'\r\n','There are no permissions with grant option.\r\n','There are some persmissions  with grant option.\r\n','pass',NULL,NULL,'2026-02-11 17:47:34'),(1600,202602,51,37,'AA_SqlServer_290_No Permissions with GRANT Option','major','PRIV','','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP  ( row varchar(500));\r\n\r\nexec sp_msforeachdb \'\'\r\nUSE [?]  \r\niNSERT iNTO #TEMP\r\nSELECT\r\n\'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +\r\n\'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +\r\n\'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +\r\n\'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )\r\nFROM\r\nsys.database_permissions\r\nWHERE\r\nSTATE_DESC like \'\'\'\'%WITH_GRANT%\'\'\'\'\r\n;\r\n\'\'\r\nselect  count(*)  from #TEMP;\r\n\' ','== 0','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP  ( row varchar(500));\r\n\r\nexec sp_msforeachdb \'\'\r\nUSE [?]  \r\niNSERT iNTO #TEMP\r\nSELECT\r\n\'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +\r\n\'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +\r\n\'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +\r\n\'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )\r\nFROM\r\nsys.database_permissions\r\nWHERE\r\nSTATE_DESC like \'\'\'\'%WITH_GRANT%\'\'\'\'\r\n;\r\n\'\'\r\nselect * from #TEMP;\r\n\' ','There are no permissions with grant option.\r\n','There are some persmissions  with grant option.\r\n','pass',NULL,NULL,'2026-02-11 17:47:34'),(1601,202602,51,40,'AA_SqlServer_320_No Access to Registry Access Extended procedures','major','PRIV','This test checks for the existence of, and user permissions on, registry access extended stored procedures.  Either these procedures should be completely dropped, or access to them should be strictly limited. xp_reg%,xp_instance_reg%\r\n','','SELECT \r\ncount(*) \r\nFROM \r\n  [master].sys.system_objects o \r\n  JOIN [master].sys.database_permissions p ON o.object_id = p.major_id \r\n  JOIN [master].sys.database_principals u ON p.grantee_principal_id = u.principal_id \r\nWHERE \r\n( o.name LIKE \'xp_reg%\' OR o.name LIKE \'xp_instance_reg%\')\r\n  AND p.type = \'EX\' ','== 0','','SELECT \r\n  \'Principal : \'+u.name  COLLATE DATABASE_DEFAULT +\r\n  \' Extended Procedure Name : \'+o.name COLLATE DATABASE_DEFAULT +\r\n  \' Type : \'+ u.type_desc COLLATE DATABASE_DEFAULT \r\nFROM \r\n  [master].sys.system_objects o \r\n  JOIN [master].sys.database_permissions p ON o.object_id = p.major_id \r\n  JOIN [master].sys.database_principals u ON p.grantee_principal_id = u.principal_id \r\nWHERE \r\n( o.name LIKE \'xp_reg%\' OR o.name LIKE \'xp_instance_reg%\')\r\n  AND p.type = \'EX\' ','There are no permissions on registry access extended stored procedures\r\n','There are some persmissions permissions on registry access extended stored procedures\r\n','fail','\n---------------------------------------------------------------------------------------\n\'Principal : public Extended Procedure Name : xp_instance_regread Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_regread Type : DATABASE_ROLE\'',NULL,'2026-02-11 17:47:35'),(1602,202602,51,41,'AA_SqlServer_330_Revoke public login from SQL Server agent proxy account','major','PRIV','The public database role contains every user in the msdb database. SQL Agent proxies   define a security context in which a job step can run.Granting access to SQL Agent proxies for the public role would allow all users to utilize the proxy which may have high privileges. This would likely break the principle of least   privileges.\r\n','','SELECT count(*)\r\nFROM msdb.dbo.sysproxylogin spl\r\nJOIN sys.database_principals dp\r\nON dp.sid = spl.sid\r\nJOIN msdb.dbo.sysproxies sp\r\nON sp.proxy_id = spl.proxy_id\r\nWHERE principal_id = USER_ID(\'public\')','== 0','','SELECT \'proxyname : \'+CAST(sp.name  as varchar)\r\nFROM msdb.dbo.sysproxylogin spl\r\nJOIN sys.database_principals dp\r\nON dp.sid = spl.sid\r\nJOIN msdb.dbo.sysproxies sp\r\nON sp.proxy_id = spl.proxy_id\r\nWHERE principal_id = USER_ID(\'public\')','There are no public permissions on SQL Server agent proxy account\r\n','There are some public permissions on SQL Server agent proxy account\r\n','pass',NULL,NULL,'2026-02-11 17:47:35'),(1603,202602,51,42,'AA_SqlServer_340_No Individual User Access To syscomment and sp_helptext','minor','PRIV','This test checks for grants on SYSCOMMENTS.TEXT.  Such grants allow any user to read the text comments associated with a database object, making the text publicly viewable.\r\n','','SELECT count(*)\r\nFROM msdb.dbo.sysproxylogin spl\r\nJOIN sys.database_principals dp\r\nON dp.sid = spl.sid\r\nJOIN msdb.dbo.sysproxies sp\r\nON sp.proxy_id = spl.proxy_id\r\nWHERE principal_id = USER_ID(\'public\')\r\n','== 0','','SELECT count(*)\r\nFROM msdb.dbo.sysproxylogin spl\r\nJOIN sys.database_principals dp\r\nON dp.sid = spl.sid\r\nJOIN msdb.dbo.sysproxies sp\r\nON sp.proxy_id = spl.proxy_id\r\nWHERE principal_id = USER_ID(\'public\')','There are no public permissions on SQL Server agent proxy account','There are some public permissions on SQL Server agent proxy account','pass',NULL,NULL,'2026-02-11 17:47:35'),(1604,202602,51,10,'AA_SqlServer_050_Disable Ad hoc distributed queries option','major','CONFIG','Adhoc queries allow undefined access to remote database sources.  Access to untrusted databases could result in execution of malicious applications and/or a compromise of local data confidentiality and integrity. The DBA will configure the database to disable access from the database to objects stored externally to the database on the local host unless mission and/or operationally required and documented.\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Ad Hoc Distributed Queries\'','== 0','','SELECT name + \' Value : \'+ cast( value as varchar ) + \' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'Ad Hoc Distributed Queries\'','Ad Hoc Distributed Queries is disabled','Ad Hoc Distributed Queries is not disabled. Disable this option','pass',NULL,NULL,'2026-02-11 17:47:35'),(1605,202602,51,11,'AA_SqlServer_060_Disable CLR option','major','CONFIG','The clr_enabled parameter configures SQL Server to allow or disallow use of Command Language Runtime objects.  CLR objects is managed code that integrates with the .NET Framework.  This is a more secure method than external stored procedures, although it still contains some risk.  Where no external application execution requirements are required, disallowing use of any improves the overall security posture of the database.\r\n\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'clr enabled\'','== 0','','SELECT name + \' Value : \'+ cast( value as varchar ) + \' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'clr enabled\'','CLR option is disabled','CLR option is not disabled. Disable this option','pass',NULL,NULL,'2026-02-11 17:47:35'),(1606,202602,51,12,'AA_SqlServer_070_Disable Cross db ownership chaining option','major','CONFIG','Cross database ownership chaining allows permissions to objects to be assigned by users other than the Information Owner.  This allows access to objects that are not authorized directly by the Information Owner based on job functions defined by the owner.  Unauthorized access may lead to a compromise of data integrity or confidentiality. The DBA will ensure database privileges are assigned via roles and not directly assigned to database accounts. Privileges may be assigned directly to application owner accounts where the DBMS does not otherwise support access via roles.\r\n\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'cross db ownership chaining\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'cross db ownership chaining\'','Cross db ownership chaining  option is disabled','Cross db ownership chaining option  is not disabled. Disable this option','pass',NULL,NULL,'2026-02-11 17:47:35'),(1607,202602,51,13,'AA_SqlServer_080_Disable Database Mail XPs option','major','CONFIG','SQL Mail accepts incoming database commands via email. This can introduce malicious codes or viruses into the SQL server environment.','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Database Mail XPs\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \'Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'Database Mail XPs\'','Database Mail XPs option is disabled','Database Mail XPs option  is not disabled. Disable this option','pass',NULL,NULL,'2026-02-11 17:47:35'),(1608,202602,51,14,'AA_SqlServer_100_Disable xp_cmdshell Server Configuration option','major','CONFIG','The xp_cmdshell extended stored procedures allows execution of host executables outside the controls of database access permissions.  This access may be exploited by malicious users who have compromised the integrity of the SQL Server database process to control the host operating system to perpetrate additional malicious activity. The DBA should disable the use of external procedures by the database unless it is mission critical or operationally required','','SELECT CAST(value as int) +\r\n       CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'xp_cmdshell\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) +\r\n\' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'xp_cmdshell\'','xp_cmdshell Server Configuration option is disabled','xp_cmdshell Server Configuration option is not disabled. This option must be disabled','pass',NULL,NULL,'2026-02-11 17:47:35'),(1609,202602,51,15,'AA_SqlServer_110_Disable Remote Access option','major','CONFIG','The remote access option controls the execution of local stored procedures on remote\r\nservers or remote stored procedures on local server.Functionality can be abused to launch a Denial-of-Service (DoS) attack on remote servers\r\nby off-loading query processing to a target.\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'remote access\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \' Value in use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'remote access\'','Remote Access option is disabled','Remote Access option  is not disabled. Disable this option','fail','\n------------------------------------------\n\'remote access Value : 1 Value in use : 1\'',NULL,'2026-02-11 17:47:35'),(1610,202602,51,16,'AA_SqlServer_120_Disable Remote Admin Connections option','major','CONFIG','The remote admin connections option controls whether a client application on a remote\r\ncomputer can use the Dedicated Administrator Connection (DAC).The Dedicated Administrator Connection (DAC) lets an administrator access a running\r\nserver to execute diagnostic functions or Transact-SQL statements, or to troubleshoot\r\nproblems on the server, even when the server is locked or running in an abnormal state\r\nand not responding to a SQL Server Database Engine connection. In a cluster scenario, the\r\nadministrator may not actually be logged on to the same node that is currently hosting the\r\nSQL Server instance and thus is considered \"remote\". Therefore, this setting should usually\r\nbe enabled (1) for SQL Server failover clusters; otherwise it should be disabled (0) which is\r\nthe default.\r\n','','execute sp_executesql N\'\r\n\r\nDECLARE @x int;\r\n\r\nSELECT @x=isnull(CAST(value as int) + CAST(value_in_use as int),100)\r\nFROM sys.configurations\r\nWHERE name = \'\'remote admin connections\'\'\r\n\r\nIF @x = 100\r\n       SELECT 0 ;\r\nELSE \r\n   SELECT CAST(value as int) + CAST(value_in_use as int) \r\n   FROM sys.configurations\r\n   WHERE name = \'\'remote admin connections\'\'\r\n\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'remote admin connections\'','Remote Admin Connections option is disabled','Remote Admin Connections option  is not disabled. Disable this option','pass',NULL,NULL,'2026-02-11 17:47:35'),(1611,202602,51,19,'AA_SqlServer_150_Disable database trustworthy status','major','CONFIG','The TRUSTWORTHY database setting restricts access to database resources by databases that contain assemblies with the EXTERNAL_ACCESS or UNSAFE permission settings and modules that use impersonation of accounts assigned elevated privileges.  Unless all assemblies and code for the database have been reviewed, especially in the case where databases have been detached and attached between server instances, leaving the TRUSTWORTHY status to off can help reduce threats from malicious assemblies or modules.','','SELECT count(name)\r\nFROM sys.databases\r\nWHERE is_trustworthy_on = 1\r\nAND name != \'msdb\';','== 0','','SELECT name\r\nFROM sys.databases\r\nWHERE is_trustworthy_on = 1\r\nAND name != \'msdb\';','database trustworthy status is disabled','database trustworthy status is not disabled. Disable this option','pass',NULL,NULL,'2026-02-11 17:47:35'),(1612,202602,51,20,'Checkpoint başarıyla oluşturuldu.','major','CONFIG','This test checks if SQL Server Instance is not advertised by the SQL Server Browser service. To maintain a higher level of protection for database instances, we recommend that SQL Server Instance be hidden when it is not required. Please note that this test does not include Clustered Instances as turning off this feature may cause issues with the Clustered environment.\r\n\r\n','','execute sp_executesql N\'\r\n\r\nDECLARE @getValue INT\r\n\r\nEXEC master.sys.xp_instance_regread\r\n@rootkey = N\'\'HKEY_LOCAL_MACHINE\'\',\r\n@key = N\'\'SOFTWARE\\Microsoft\\Microsoft SQL Server\\MSSQLServer\\SuperSocketNetLib\'\',\r\n@value_name = N\'\'HideInstance\'\',\r\n@value = @getValue OUTPUT\r\n\r\nSELECT isnull(@getvalue,0)\'','==1','','execute sp_executesql N\'\r\n\r\nDECLARE @getValue INT\r\n\r\nEXEC master.sys.xp_instance_regread\r\n@rootkey = N\'\'HKEY_LOCAL_MACHINE\'\',\r\n@key = N\'\'SOFTWARE\\Microsoft\\Microsoft SQL Server\\MSSQLServer\\SuperSocketNetLib\'\',\r\n@value_name = N\'\'HideInstance\'\',\r\n@value = @getValue OUTPUT\r\n\r\nSELECT isnull(@getvalue,0)\'','SQL Server Instance is  hidden.\r\n','SQL Server Instance is not hidden. Hide the instance','fail','\n-\n0',NULL,'2026-02-11 17:47:35'),(1613,202602,51,21,'AA_SqlServer_160_Hide SQL Server Instance','major','CONFIG','This test checks if SQL Server Instance is not advertised by the SQL Server Browser service. To maintain a higher level of protection for database instances, we recommend that SQL Server Instance be hidden when it is not required. Please note that this test does not include Clustered Instances as turning off this feature may cause issues with the Clustered environment.\r\n\r\n','','execute sp_executesql N\'\r\n\r\nDECLARE @getValue INT\r\n\r\nEXEC master.sys.xp_instance_regread\r\n@rootkey = N\'\'HKEY_LOCAL_MACHINE\'\',\r\n@key = N\'\'SOFTWARE\\Microsoft\\Microsoft SQL Server\\MSSQLServer\\SuperSocketNetLib\'\',\r\n@value_name = N\'\'HideInstance\'\',\r\n@value = @getValue OUTPUT\r\n\r\nSELECT isnull(@getvalue,0)\'','==1','','execute sp_executesql N\'\r\n\r\nDECLARE @getValue INT\r\n\r\nEXEC master.sys.xp_instance_regread\r\n@rootkey = N\'\'HKEY_LOCAL_MACHINE\'\',\r\n@key = N\'\'SOFTWARE\\Microsoft\\Microsoft SQL Server\\MSSQLServer\\SuperSocketNetLib\'\',\r\n@value_name = N\'\'HideInstance\'\',\r\n@value = @getValue OUTPUT\r\n\r\nSELECT isnull(@getvalue,0)\'','SQL Server Instance is  hidden.','SQL Server Instance is not hidden. Hide the instance','fail','\n-\n0',NULL,'2026-02-11 17:47:35'),(1614,202602,51,38,'AA_SqlServer_300_No Access To General Extended procedures','major','PRIV','This test checks for the existence of, and user permissions on, extended stored procedures.  Either these procedures should be completely dropped, or access to them should be strictly limited. xp_cmdshell, xp_enumgroups, xp_grantlogin ,xp_logevent, xp_logininfo,    xp_msver, xp_revokelogin, xp_sprintf, xp_sqlmaint, xp_sscanf\r\n','','SELECT \r\ncount(*) \r\nFROM \r\n  [master].sys.system_objects o \r\n  JOIN [master].sys.database_permissions p ON o.object_id = p.major_id \r\n  JOIN [master].sys.database_principals u ON p.grantee_principal_id = u.principal_id \r\nWHERE \r\n    o.name in ( \r\n	\'xp_cmdshell\', \r\n	\'xp_enumgroups\', \r\n    \'xp_grantlogin\' ,\r\n	\'xp_logevent\', \r\n	\'xp_logininfo\', \r\n    \'xp_msver\', \r\n	\'xp_revokelogin\', \r\n	\'xp_sprintf\', \r\n    \'xp_sqlmaint\', \r\n	\'xp_sscanf\' )\r\n  AND p.type = \'EX\' ','== 0','','SELECT \r\n  \'Principal : \'+u.name  COLLATE DATABASE_DEFAULT +\r\n  \' Extended Procedure Name : \'+o.name COLLATE DATABASE_DEFAULT +\r\n  \' Type : \'+ u.type_desc COLLATE DATABASE_DEFAULT \r\nFROM \r\n  [master].sys.system_objects o \r\n  JOIN [master].sys.database_permissions p ON o.object_id = p.major_id \r\n  JOIN [master].sys.database_principals u ON p.grantee_principal_id = u.principal_id \r\nWHERE \r\n    o.name in ( \r\n	\'xp_cmdshell\', \r\n	\'xp_enumgroups\', \r\n    \'xp_grantlogin\' ,\r\n	\'xp_logevent\', \r\n	\'xp_logininfo\', \r\n    \'xp_msver\', \r\n	\'xp_revokelogin\', \r\n	\'xp_sprintf\', \r\n    \'xp_sqlmaint\', \r\n	\'xp_sscanf\' )\r\n  AND p.type = \'EX\' ','There are no permissions on general extended stored procedures\r\n','There are some persmissions permissions on general extended stored procedures.\r\n','fail','\n----------------------------------------------------------------------------------\n\'Principal : public Extended Procedure Name : xp_msver Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_sscanf Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_revokelogin Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_grantlogin Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_sprintf Type : DATABASE_ROLE\'',NULL,'2026-02-11 17:47:35'),(1615,202602,51,39,'AA_SqlServer_310_No Access to OLE Automation procedures','major','CONFIG','This test checks for the existence of,and user permissions on OLE automation extended stored procedures.  Either these procedures should be completely dropped, or access to them should be strictly limited.      \r\n','','SELECT CAST(value as int) +\r\n       CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Ole Automation Procedures\'   \r\n','== 0','','SELECT CAST(value as int) +\r\n       CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Ole Automation Procedures\'\r\n  \r\n','OLE Automation procedures  option is disabled\r\n','OLE Automation procedures  option  is not disabled. Disable this option\r\n','pass',NULL,NULL,'2026-02-11 17:47:35'),(1616,202602,51,17,'AA_SqlServer_130_Disable Ole Automation Procedures option','minor','CONFIG','This test checks if Ole Automation Procedures option is disabled. Ole Automation Procedures option allows SQL Server users to execute functions external to SQL Server. Enabling this option will increase the attack surface of SQL Server and allow users to execute functions in the security context of SQL Server. We recommend that the Ole Automation Procedures option to be disabled when it is not document as a requirement.\r\n\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Ole Automation Procedures\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \'Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'Ole Automation Procedures\'',' Ole Automation Procedures option is disabled',' Ole Automation Procedures option  is not disabled. Disable this option','pass',NULL,NULL,'2026-02-11 17:47:35'),(1617,202602,51,18,'AA_SqlServer_140_Disable Scan for Startup Procedures option','minor','CONFIG','This test checks if scan for startup procedures is disabled. This feature causes SQL Server to scan for and automatically run all stored procedures that are set to execute upon service startup. If there are no user-defined stored procedures set to execute when SQL server starts, we recommend this feature to be disabled.\r\n\r\n','','SELECT CAST(value as int) +\r\n       CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'scan for startup procs\'','== 0','','SELECT name + \' value : \'+cast( value as varchar ) +\r\n\' value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'scan for startup procs\'','Scan for Startup Procedures  option is disabled','Scan for Startup Procedures  option  is not disabled. Disable this option','pass',NULL,NULL,'2026-02-11 17:47:35'),(1618,202602,51,9,'AA_SqlServer_040_Rename the sa Login Account','major','ACCOUNT','The \'sa\' account is a well-known account.  Well-known account names provide an easier target for attack.  Renaming the sa account helps reduce the risk of an attack to this built-in account.','','SELECT count(*)\r\nFROM sys.server_principals\r\nWHERE sid = 0x01 and name=\'sa\'','== 0','','SELECT name\r\nFROM sys.server_principals\r\nWHERE sid = 0x01','sa Login Account is renamed','sa Login Account is not renamed. Rename this account','fail','name\n----\n\'sa\'',NULL,'2026-02-11 17:47:35'),(1619,202602,52,24,'AA_SqlServer_190_Public server role permision','critical','PRIV','public is a special fixed server role containing all logins. Unlike other fixed server roles,\r\npermissions can be changed for the public role. In keeping with the principle of least\r\nprivileges, the public server role should not be used to grant permissions at the server\r\nscope as these would be inherited by all users.\r\n\r\nEvery SQL Server login belongs to the public role and cannot be removed from this role.\r\nTherefore, any permissions granted to this role will be available to all logins unless they\r\nhave been explicitly denied to specific logins or user-defined server roles.','','Select \r\n  count (permission_name) \r\nfrom \r\n  sys.server_permissions \r\nwhere \r\n  SUSER_NAME(grantee_principal_id) = \'public\' \r\n  and permission_name not in (\'VIEW ANY DATABASE\', \'CONNECT\')\r\n','== 0','','Select \r\n  permission_name \r\nfrom \r\n  sys.server_permissions \r\nwhere \r\n  SUSER_NAME(grantee_principal_id) = \'public\' \r\n  and permission_name not in (\'VIEW ANY DATABASE\', \'CONNECT\')\r\n\r\n','No server permissions are granted to public.','Some server permissions are granted to public.','pass',NULL,NULL,'2026-02-11 17:51:59'),(1620,202602,52,5,'AA_SqlServer_010_Supported SQL Server version','critical','PATCH','This test checks whether your current SQL Server version is a vendor-supported version.  Microsoft does not provide security fixes or software updates to unsupported software versions','','SELECT cast(ISNULL(SERVERPROPERTY(\'ProductMajorVersion\'),0) as int)   ','>=11','','SELECT \'Product Major version \' +  cast(ISNULL(SERVERPROPERTY(\'ProductMajorVersion\'),\'Null\' ) as  char ) ','The version of the database is acceptable.','The version of the database is not acceptable. The database version should SQL Sever 2012 or upper.','pass',NULL,NULL,'2026-02-11 17:51:59'),(1621,202602,52,6,'AA_SqlServer_020_Disable the sa Login Account','critical','ACCOUNT','This test checks if the \'sa\' Login Account is disabled. The sa account is a widely known and often widely used SQL Server account with sysadmin privileges. Enforcing this control reduces the probability of an attacker executing brute force attacks against a well-known principal.','','SELECT  count(*)\r\nFROM sys.server_principals\r\nWHERE sid = 0x01\r\nAND is_disabled = 0','== 0','','SELECT \'sa user name : \'+ name+\' is disabled : \' +  cast( is_disabled as char)\r\nFROM sys.server_principals\r\nWHERE sid = 0x01\r\n','sa Login Account is disabled','Disable sa login account','fail','\n----------------------------------------------------------------\n\'sa user name : sa is disabled : 0                             \'',NULL,'2026-02-11 17:51:59'),(1622,202602,52,7,'AA_SqlServer_025_sa Change password','critical','ACCOUNT','This test checks that sa password change . The sa password should be changed in every two days','','select datediff( day,  modify_date , getdate() ) FROM sys.server_principals\r\nWHERE sid = 0x01  ','< 3','','select datediff( day,  modify_date , getdate() ) FROM sys.server_principals\r\nWHERE sid = 0x01 ','sa password was changed in two days','','fail','\n--\n28',NULL,'2026-02-11 17:51:59'),(1623,202602,52,8,'AA_SqlServer_030_Ensure no Login exists with sa Login Account','critical','ACCOUNT','The \'sa\' account is a well-known account.  Well-known account names provide an easier target for attack. The lack of the sa account helps reduce the risk of an attack to this built-in account.','','SELECT count(*)\r\nFROM sys.server_principals\r\nWHERE name = \'sa\'','== 0','','SELECT name\r\nFROM sys.server_principals\r\nWHERE name = \'sa\'','There is no the sa account in the database.','There is the sa Login account in the database.Drop this user or rename et.','fail','name\n----\n\'sa\'',NULL,'2026-02-11 17:51:59'),(1624,202602,52,25,'AA_SqlServer_200_Fixed Server Role members for users','critical','PRIV','This test checks fixed server roles for analyst , developers and real persons. Fixed server roles could not be assigned to real person users ( Developer, Analyst users ) . Only Admin can use fixed server role.\r\n','','Select     count(*)   from      sys.server_role_members    where      (       suser_name(member_principal_id) like \'ODEABANK%.%\'    	AND       suser_name(member_principal_id) not like \'%admin%\'         AND       suser_name(member_principal_id) not like \'%t.coban%\'     )      OR (       suser_name(member_principal_id) like \'ODEABANK\\Cyberark_Intertech%\'     )      \r\n','== 0','','Select      suser_name(role_principal_id) + \'   \' + suser_name(member_principal_id)    from      sys.server_role_members    where      (       suser_name(member_principal_id) like \'ODEABANK%.%\'    	AND       suser_name(member_principal_id) not like \'%admin%\'         AND       suser_name(member_principal_id) not like \'%t.coban%\'     )      OR (       suser_name(member_principal_id) like \'ODEABANK\\Cyberark_Intertech%\'     )          \r\n','Fixed Server role usage is correct.\r\n','Fixed Server role usage is not correct.\r\n','pass',NULL,NULL,'2026-02-11 17:51:59'),(1625,202602,52,26,'AA_SqlServer_210_Database Role members for users','critical','PRIV','This test checks database role members for analyst and real person users. Database roles  except  db_datareader could not be assigned to real person users ( Developer, Analyst users ) .\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      EXEC sp_MSforeachdb \'\' USE [?]    INSERT INTO #TEMP   SELECT \'\'\'\'DB Name : \'\'\'\'+Cast (DB_NAME() as varchar)+\'\'\'\' Role Name : \'\'\'\'+USER_NAME(role_principal_id)  +\'\'\'\' User Name \'\'\'\'+  USER_NAME(member_principal_id)    from  sys.database_role_members   	Where   	(   	( USER_NAME(member_principal_id)  like \'\'\'\'%ODEABANK%.%\'\'\'\'  and   USER_NAME(member_principal_id)  not like \'\'\'\'%admin%\'\'\'\' )     	OR   	  (suser_name(member_principal_id) like \'\'\'\'%ODEABANK%Cyberark%\'\'\'\')       )    	AND   	DB_NAME() <> \'\'\'\'master\'\'\'\' and   	USER_NAME(role_principal_id) not in (\'\'\'\'db_datareader\'\'\'\',\'\'\'\'db_viewdefinition\'\'\'\',\'\'\'\'db_denydatareader\'\'\'\',\'\'\'\'db_deny_maas\'\'\'\');   \'\'      Select  count(*)  from #TEMP;   \'\r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      EXEC sp_MSforeachdb \'\' USE [?]    INSERT INTO #TEMP   SELECT \'\'\'\'DB Name : \'\'\'\'+Cast (DB_NAME() as varchar)+\'\'\'\' Role Name : \'\'\'\'+USER_NAME(role_principal_id)  +\'\'\'\' User Name \'\'\'\'+  USER_NAME(member_principal_id)    from  sys.database_role_members   	Where   (   	( USER_NAME(member_principal_id)  like \'\'\'\'%ODEABANK%.%\'\'\'\'  and   USER_NAME(member_principal_id)  not like \'\'\'\'%admin%\'\'\'\' )     	OR   	(suser_name(member_principal_id) like \'\'\'\'%ODEABANK%Cyberark%\'\'\'\')   )    	AND   	DB_NAME() <> \'\'\'\'master\'\'\'\' and   	USER_NAME(role_principal_id) not in  (\'\'\'\'db_datareader\'\'\'\',\'\'\'\'db_viewdefinition\'\'\'\',\'\'\'\'db_denydatareader\'\'\'\',\'\'\'\'db_deny_maas\'\'\'\');   \'\'      Select  * from #TEMP;   \'\r\n','Database role member usage for users  is correct\r\n','Database role member usage for users  is not correct\r\n','pass',NULL,NULL,'2026-02-11 17:51:59'),(1626,202602,52,27,'AA_SqlServer_220_2_Public Database Permissions','critical','PRIV','This test checks database permisions for public . Public is a special role and permissions should not be granted to public role.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP ( row varchar(500));          exec sp_MSforeachdb \'\'   USE [?]   iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'public\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND OBJECT_NAME(MAJOR_iD) NOT LiKE (\'\'\'\'%fn_cdc_get_net_changes_application_data%\'\'\'\')   AND NOT (OBJECT_SCHEMA_NAME(MAJOR_iD) = \'\'\'\'cdc\'\'\'\' and PERMiSSiON_NAME=\'\'\'\'SELECT\'\'\'\')   AND NOT (PERMiSSiON_NAME IN (\'\'\'\'REFERENCES\'\'\'\',\'\'\'\'SEND\'\'\'\',   \'\'\'\'VIEW ANY COLUMN ENCRYPTION KEY DEFINITION\'\'\'\',   \'\'\'\'VIEW ANY COLUMN MASTER KEY DEFINITION\'\'\'\' ) and OBJECT_SCHEMA_NAME(MAJOR_iD) IS NULL)   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select count(*) from #TEMP;   \'\r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP ( row varchar(500));          exec sp_MSforeachdb \'\'   USE [?]   iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'public\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND OBJECT_NAME(MAJOR_iD) NOT LiKE (\'\'\'\'%fn_cdc_get_net_changes_application_data%\'\'\'\')   AND NOT (OBJECT_SCHEMA_NAME(MAJOR_iD) = \'\'\'\'cdc\'\'\'\' and PERMiSSiON_NAME=\'\'\'\'SELECT\'\'\'\')   AND NOT (PERMiSSiON_NAME IN (\'\'\'\'REFERENCES\'\'\'\',\'\'\'\'SEND\'\'\'\',   \'\'\'\'VIEW ANY COLUMN ENCRYPTION KEY DEFINITION\'\'\'\',   \'\'\'\'VIEW ANY COLUMN MASTER KEY DEFINITION\'\'\'\' ) and OBJECT_SCHEMA_NAME(MAJOR_iD) IS NULL)   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select * from #TEMP;   \'','There are no permissions which are assigned to public.\r\n','There are some persmissions which are assigned to public\r\n','pass',NULL,NULL,'2026-02-11 17:51:59'),(1627,202602,52,28,'AA_SqlServer_220_Public Database Permissions','critical','PRIV','This test checks database permisions for public . Public is a special role and permissions should not be granted to public role.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      exec sp_msforeachdb \'\'   USE [?]     iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'public\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND OBJECT_NAME(MAJOR_iD) NOT LiKE (\'\'\'\'%fn_cdc_get_net_changes_application_data%\'\'\'\')   AND NOT (OBJECT_SCHEMA_NAME(MAJOR_iD) = \'\'\'\'cdc\'\'\'\' and PERMiSSiON_NAME=\'\'\'\'SELECT\'\'\'\')   AND NOT (PERMiSSiON_NAME IN (\'\'\'\'REFERENCES\'\'\'\',\'\'\'\'SEND\'\'\'\',   \'\'\'\'VIEW ANY COLUMN ENCRYPTION KEY DEFINITION\'\'\'\',   \'\'\'\'VIEW ANY COLUMN MASTER KEY DEFINITION\'\'\'\' ) and OBJECT_SCHEMA_NAME(MAJOR_iD) IS NULL)   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select count(*) from #TEMP;   \' \r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      exec sp_msforeachdb \'\'   USE [?]     iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'public\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND OBJECT_NAME(MAJOR_iD) NOT LiKE (\'\'\'\'%fn_cdc_get_net_changes_application_data%\'\'\'\')   AND NOT (OBJECT_SCHEMA_NAME(MAJOR_iD) = \'\'\'\'cdc\'\'\'\' and PERMiSSiON_NAME=\'\'\'\'SELECT\'\'\'\')   AND NOT (PERMiSSiON_NAME IN (\'\'\'\'REFERENCES\'\'\'\',\'\'\'\'SEND\'\'\'\',   \'\'\'\'VIEW ANY COLUMN ENCRYPTION KEY DEFINITION\'\'\'\',   \'\'\'\'VIEW ANY COLUMN MASTER KEY DEFINITION\'\'\'\' ) and OBJECT_SCHEMA_NAME(MAJOR_iD) IS NULL)   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select * from #TEMP;   \' \r\n','There are no permissions which are assigned to public.\r\n','There are some persmissions which are assigned to public\r\n','pass',NULL,NULL,'2026-02-11 17:51:59'),(1628,202602,52,29,'AA_SqlServer_230_Real person users','critical','ACCOUNT','All logins to the database should be made with AD groups, real person users should  not be connected database directly\r\n','','Select      count(*)   from      sys.server_principals    where      name like \'ODEABANK%.%\'      and is_disabled = 0   \r\n','== 0','','Select      name     from      sys.server_principals    where      name like \'ODEABANK%.%\'      and is_disabled = 0;\r\n','Real person users are not found in the logins\r\n','Some real person users are found in the logins\r\n','pass',NULL,NULL,'2026-02-11 17:51:59'),(1629,202602,52,30,'AA_SqlServer_240_2_guest Database Permissions','critical','ACCOUNT','This test checks database permisions for guest . guest is a special user and permissions should not be granted to guest user.\r\n','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP ( row varchar(500));\r\n\r\nexec sp_MSforeachdb \'\'\r\nUSE [?]\r\niNSERT iNTO #TEMP\r\nSELECT\r\n\'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +\r\n\'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +\r\n\'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +\r\n\'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )\r\nFROM\r\nsys.database_permissions\r\nWHERE\r\nUSER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'guest\'\'\'\' )\r\nAND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'\r\nAND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')\r\nAND STATE_DESC=\'\'\'\'GRANT\'\'\'\'\r\n;\r\n\'\'\r\nselect count(*) from #TEMP;\r\n\'','== 0','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP ( row varchar(500));\r\n\r\nexec sp_MSforeachdb \'\'\r\nUSE [?]\r\niNSERT iNTO #TEMP\r\nSELECT\r\n\'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +\r\n\'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +\r\n\'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +\r\n\'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )\r\nFROM\r\nsys.database_permissions\r\nWHERE\r\nUSER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'guest\'\'\'\' )\r\nAND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'\r\nAND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')\r\nAND STATE_DESC=\'\'\'\'GRANT\'\'\'\'\r\n;\r\n\'\'\r\nselect * from #TEMP;\r\n\'','There are no permissions which are assigned to guest.\r\n','There are some persmissions which are assigned to guest\r\n','pass',NULL,NULL,'2026-02-11 17:51:59'),(1630,202602,52,31,'AA_SqlServer_240_guest Database Permissions','critical','PRIV','This test checks database permisions for guest . guest is a special user and permissions should not be granted to guest user.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      exec sp_msforeachdb \'\'   USE [?]     iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'guest\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select count(*) from #TEMP;   \' \r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      exec sp_msforeachdb \'\'   USE [?]     iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'guest\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select  *  from #TEMP;   \' \r\n','There are no permissions which are assigned to guest.\r\n','There are some persmissions which are assigned to guest\r\n','pass',NULL,NULL,'2026-02-11 17:51:59'),(1631,202602,52,32,'AA_SqlServer_250_Database Role members for guest','critical','PRIV','This test checks database role members for guest  user. Database roles  could not be assigned to guest role.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      EXEC sp_MSforeachdb \'\' USE [?]    INSERT INTO #TEMP   SELECT \'\'\'\'DB Name : \'\'\'\'+Cast (DB_NAME() as varchar)+\'\'\'\' Role Name : \'\'\'\'+USER_NAME(role_principal_id)  +\'\'\'\' User Name \'\'\'\'+  USER_NAME(member_principal_id)    from  sys.database_role_members   	Where     USER_NAME(member_principal_id)  = \'\'\'\'guest\'\'\'\'     ;   \'\'      Select count(*)  from #TEMP;   \'\r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      EXEC sp_MSforeachdb \'\' USE [?]    INSERT INTO #TEMP   SELECT \'\'\'\'DB Name : \'\'\'\'+Cast (DB_NAME() as varchar)+\'\'\'\' Role Name : \'\'\'\'+USER_NAME(role_principal_id)  +\'\'\'\' User Name \'\'\'\'+  USER_NAME(member_principal_id)    from  sys.database_role_members   	Where     USER_NAME(member_principal_id)  = \'\'\'\'guest\'\'\'\'     ;   \'\'      Select  *  from #TEMP;   \'\r\n','Database role member usage for guest user  is correct\r\n','Database role member usage for guest user  is not correct\r\n','pass',NULL,NULL,'2026-02-11 17:51:59'),(1632,202602,52,33,'AA_SqlServer_260_SQL Logins with Null Password','critical','ACCOUNT','This test checks sql logins with null password. SQL Logins should not have null passwords.\r\n','','SELECT      count(name)   from      sys.sql_logins    WHERE      PWDCOMPARE(\'\', password_hash)= 1\r\n','== 0','','SELECT      name    from      sys.sql_logins    WHERE      PWDCOMPARE(\'\', password_hash)= 1   \r\n','There are no sql logins with null paswords\r\n','There are some sql logins with null passwords.\r\n','pass',NULL,NULL,'2026-02-11 17:51:59'),(1633,202602,52,34,'AA_SqlServer_270_SQL Logins with username and passwords are equal','critical','ACCOUNT','This test checks sql login password which are egual to username. Username and password must be different for SQL logins.\r\n','','SELECT      count(name)   from      sys.sql_logins    WHERE      PWDCOMPARE(name,password_hash)=1 \r\n','== 0','','SELECT      name    from      sys.sql_logins    WHERE      PWDCOMPARE(name,password_hash)=1    \r\n','There is no SQL login name which is equal to password.\r\n','There are some sql logins whose passwords are egual to usernames.\r\n','pass',NULL,NULL,'2026-02-11 17:51:59'),(1634,202602,52,35,'AA_SqlServer_280_No Sample Databases','critical','CONFIG','This test checks whether the sample databases created optionally on installation are present.  These sample databases contain many default permissions, and can be used as an entry point to your systems. \r\n','','select      count(name)    from      sys.databases    where      name in (       \'AdventureWorks\', \'AdventureWorksDW\',        \'Northwind\', \'Pubs\'     )   \r\n','== 0','','select      name    from      sys.databases    where      name in (       \'AdventureWorks\', \'AdventureWorksDW\',        \'Northwind\', \'Pubs\'     )   \r\n','There are no sample databases in the server\r\n','There are some sample databases in the server\r\n','pass',NULL,NULL,'2026-02-11 17:51:59'),(1635,202602,52,43,'AA_SqlServer_350_User Password Policy Is Checked','critical','ACCOUNT','This test checks that CHECK_POLICY is enabled for all users.  Enabling CHECK_POLICY ensures that Windows passwords policies are enforced.','','select count(*) from sys.sql_logins  \r\nwhere \r\nis_policy_checked=0 and\r\nname not like \'##%\'','== 0','','select name from sys.sql_logins  \r\nwhere \r\nis_policy_checked=0 and\r\nname not like \'##%\'','CHECK_POLICY is enabled for all users','CHECK_POLICY is not enabled for all users','pass',NULL,NULL,'2026-02-11 17:51:59'),(1636,202602,52,44,'AA_SqlServer_360_CHECK_EXPIRATION Is Checked','critical','ACCOUNT','This test checks that CHECK_EXPIRATION is enabled for all users.  Passwords that have been in use for long periods of time are likely to become known to unauthorized users.\r\n','','select count(*) from sys.sql_logins     where    is_expiration_checked=0 and   name not like \'##%\'\r\n','== 0','','select name from sys.sql_logins     where    is_expiration_checked=0 and   name not like \'##%\'\r\n','CHECK_EXPIRATION is enabled for all users\r\n','CHECK_EXPIRATION is not enabled for all users\r\n','fail','name\n----\n\'sa\'',NULL,'2026-02-11 17:51:59'),(1637,202602,52,22,'AA_SqlServer_170_Windows Authentication','major','AUTH','This test checks that the authentication mode is set to Windows authentication only.  Windows provides a more robust authentication mechanism than SQL Server authentication.','',' SELECT cast( SERVERPROPERTY(\'IsIntegratedSecurityOnly\') as int) ','==1','','SELECT cast( SERVERPROPERTY(\'IsIntegratedSecurityOnly\') as varchar)','The authentication mode is set to Windows authentication only. ','The authentication mode is not set to Windows authentication only.','fail','\n---\n\'0\'',NULL,'2026-02-11 17:51:59'),(1638,202602,52,23,'AA_SqlServer_180_No Guest User Accounts','major','ACCOUNT','This test checks for the existence of guest user accounts with CONNECT permission in database other than master, msdb and tempdb.  This test also exclude databases that are flagged as distributor. If the GUEST user exists and a specific login has not been granted to a database, a login will be mapped to GUEST. The presence of the GUEST user allows all logins to access the database.\r\n','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP  ( row int);\r\n\r\nEXEC sp_MSforeachdb \'\' USE [?]\r\n	INSERT INTO #TEMP\r\n	SELECT count(*) \r\n	FROM sys.database_permissions\r\n	WHERE [grantee_principal_id] = DATABASE_PRINCIPAL_ID(\'\'\'\'guest\'\'\'\')\r\n	AND [state_desc] LIKE \'\'\'\'GRANT%\'\'\'\'\r\n	AND [permission_name] = \'\'\'\'CONNECT\'\'\'\'\r\n	AND DB_NAME() NOT IN (\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'msdb\'\'\'\') ;\r\n\'\'\r\n\r\nSelect sum(row) from #TEMP;\r\ndrop table #TEMP;\r\n\'','== 0','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP  ( row varchar(500));\r\n\r\nEXEC sp_MSforeachdb \'\' USE  [?] \r\n	INSERT INTO #TEMP\r\n	SELECT \'\'\'\' DB NAME : \'\'\'\' + Cast (DB_NAME() as varchar) + \'\'\'\' guest user has CONNECT permission \'\'\'\'\r\n	FROM sys.database_permissions\r\n	WHERE [grantee_principal_id] = DATABASE_PRINCIPAL_ID(\'\'\'\'guest\'\'\'\')\r\n	AND [state_desc] LIKE \'\'\'\'GRANT%\'\'\'\'\r\n	AND [permission_name] = \'\'\'\'CONNECT\'\'\'\'\r\n	AND DB_NAME() NOT IN (\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'msdb\'\'\'\') ;\r\n\'\'\r\n\r\nSelect * from #TEMP;\r\ndrop table #TEMP;\r\n\'','There is no guest user with CONNECT permission. ','There are   guest users with CONNECT permission. Remove these users','pass',NULL,NULL,'2026-02-11 17:51:59'),(1639,202602,52,36,'AA_SqlServer_290_2_No Permissions with GRANT Option','major','PRIV','This test checks database permisions  with grant option. No permission with grant option should be defined in the database.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP ( row varchar(500));      exec sp_MSforeachdb \'\'   USE [?]   iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   STATE_DESC like \'\'\'\'%WITH_GRANT%\'\'\'\'   ;   \'\'   select count(*) from #TEMP;   \'\r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP ( row varchar(500));      exec sp_MSforeachdb \'\'   USE [?]   iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   STATE_DESC like \'\'\'\'%WITH_GRANT%\'\'\'\'   ;   \'\'   select * from #TEMP;   \'\r\n','There are no permissions with grant option.\r\n','There are some persmissions  with grant option.\r\n','pass',NULL,NULL,'2026-02-11 17:51:59'),(1640,202602,52,37,'AA_SqlServer_290_No Permissions with GRANT Option','major','PRIV','','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP  ( row varchar(500));\r\n\r\nexec sp_msforeachdb \'\'\r\nUSE [?]  \r\niNSERT iNTO #TEMP\r\nSELECT\r\n\'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +\r\n\'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +\r\n\'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +\r\n\'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )\r\nFROM\r\nsys.database_permissions\r\nWHERE\r\nSTATE_DESC like \'\'\'\'%WITH_GRANT%\'\'\'\'\r\n;\r\n\'\'\r\nselect  count(*)  from #TEMP;\r\n\' ','== 0','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP  ( row varchar(500));\r\n\r\nexec sp_msforeachdb \'\'\r\nUSE [?]  \r\niNSERT iNTO #TEMP\r\nSELECT\r\n\'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +\r\n\'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +\r\n\'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +\r\n\'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )\r\nFROM\r\nsys.database_permissions\r\nWHERE\r\nSTATE_DESC like \'\'\'\'%WITH_GRANT%\'\'\'\'\r\n;\r\n\'\'\r\nselect * from #TEMP;\r\n\' ','There are no permissions with grant option.\r\n','There are some persmissions  with grant option.\r\n','pass',NULL,NULL,'2026-02-11 17:51:59'),(1641,202602,52,40,'AA_SqlServer_320_No Access to Registry Access Extended procedures','major','PRIV','This test checks for the existence of, and user permissions on, registry access extended stored procedures.  Either these procedures should be completely dropped, or access to them should be strictly limited. xp_reg%,xp_instance_reg%\r\n','','SELECT \r\ncount(*) \r\nFROM \r\n  [master].sys.system_objects o \r\n  JOIN [master].sys.database_permissions p ON o.object_id = p.major_id \r\n  JOIN [master].sys.database_principals u ON p.grantee_principal_id = u.principal_id \r\nWHERE \r\n( o.name LIKE \'xp_reg%\' OR o.name LIKE \'xp_instance_reg%\')\r\n  AND p.type = \'EX\' ','== 0','','SELECT \r\n  \'Principal : \'+u.name  COLLATE DATABASE_DEFAULT +\r\n  \' Extended Procedure Name : \'+o.name COLLATE DATABASE_DEFAULT +\r\n  \' Type : \'+ u.type_desc COLLATE DATABASE_DEFAULT \r\nFROM \r\n  [master].sys.system_objects o \r\n  JOIN [master].sys.database_permissions p ON o.object_id = p.major_id \r\n  JOIN [master].sys.database_principals u ON p.grantee_principal_id = u.principal_id \r\nWHERE \r\n( o.name LIKE \'xp_reg%\' OR o.name LIKE \'xp_instance_reg%\')\r\n  AND p.type = \'EX\' ','There are no permissions on registry access extended stored procedures\r\n','There are some persmissions permissions on registry access extended stored procedures\r\n','fail','\n---------------------------------------------------------------------------------------\n\'Principal : public Extended Procedure Name : xp_instance_regread Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_regread Type : DATABASE_ROLE\'',NULL,'2026-02-11 17:51:59'),(1642,202602,52,41,'AA_SqlServer_330_Revoke public login from SQL Server agent proxy account','major','PRIV','The public database role contains every user in the msdb database. SQL Agent proxies   define a security context in which a job step can run.Granting access to SQL Agent proxies for the public role would allow all users to utilize the proxy which may have high privileges. This would likely break the principle of least   privileges.\r\n','','SELECT count(*)\r\nFROM msdb.dbo.sysproxylogin spl\r\nJOIN sys.database_principals dp\r\nON dp.sid = spl.sid\r\nJOIN msdb.dbo.sysproxies sp\r\nON sp.proxy_id = spl.proxy_id\r\nWHERE principal_id = USER_ID(\'public\')','== 0','','SELECT \'proxyname : \'+CAST(sp.name  as varchar)\r\nFROM msdb.dbo.sysproxylogin spl\r\nJOIN sys.database_principals dp\r\nON dp.sid = spl.sid\r\nJOIN msdb.dbo.sysproxies sp\r\nON sp.proxy_id = spl.proxy_id\r\nWHERE principal_id = USER_ID(\'public\')','There are no public permissions on SQL Server agent proxy account\r\n','There are some public permissions on SQL Server agent proxy account\r\n','pass',NULL,NULL,'2026-02-11 17:51:59'),(1643,202602,52,42,'AA_SqlServer_340_No Individual User Access To syscomment and sp_helptext','minor','PRIV','This test checks for grants on SYSCOMMENTS.TEXT.  Such grants allow any user to read the text comments associated with a database object, making the text publicly viewable.\r\n','','SELECT count(*)\r\nFROM msdb.dbo.sysproxylogin spl\r\nJOIN sys.database_principals dp\r\nON dp.sid = spl.sid\r\nJOIN msdb.dbo.sysproxies sp\r\nON sp.proxy_id = spl.proxy_id\r\nWHERE principal_id = USER_ID(\'public\')\r\n','== 0','','SELECT count(*)\r\nFROM msdb.dbo.sysproxylogin spl\r\nJOIN sys.database_principals dp\r\nON dp.sid = spl.sid\r\nJOIN msdb.dbo.sysproxies sp\r\nON sp.proxy_id = spl.proxy_id\r\nWHERE principal_id = USER_ID(\'public\')','There are no public permissions on SQL Server agent proxy account','There are some public permissions on SQL Server agent proxy account','pass',NULL,NULL,'2026-02-11 17:51:59'),(1644,202602,52,10,'AA_SqlServer_050_Disable Ad hoc distributed queries option','major','CONFIG','Adhoc queries allow undefined access to remote database sources.  Access to untrusted databases could result in execution of malicious applications and/or a compromise of local data confidentiality and integrity. The DBA will configure the database to disable access from the database to objects stored externally to the database on the local host unless mission and/or operationally required and documented.\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Ad Hoc Distributed Queries\'','== 0','','SELECT name + \' Value : \'+ cast( value as varchar ) + \' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'Ad Hoc Distributed Queries\'','Ad Hoc Distributed Queries is disabled','Ad Hoc Distributed Queries is not disabled. Disable this option','pass',NULL,NULL,'2026-02-11 17:51:59'),(1645,202602,52,11,'AA_SqlServer_060_Disable CLR option','major','CONFIG','The clr_enabled parameter configures SQL Server to allow or disallow use of Command Language Runtime objects.  CLR objects is managed code that integrates with the .NET Framework.  This is a more secure method than external stored procedures, although it still contains some risk.  Where no external application execution requirements are required, disallowing use of any improves the overall security posture of the database.\r\n\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'clr enabled\'','== 0','','SELECT name + \' Value : \'+ cast( value as varchar ) + \' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'clr enabled\'','CLR option is disabled','CLR option is not disabled. Disable this option','pass',NULL,NULL,'2026-02-11 17:51:59'),(1646,202602,52,12,'AA_SqlServer_070_Disable Cross db ownership chaining option','major','CONFIG','Cross database ownership chaining allows permissions to objects to be assigned by users other than the Information Owner.  This allows access to objects that are not authorized directly by the Information Owner based on job functions defined by the owner.  Unauthorized access may lead to a compromise of data integrity or confidentiality. The DBA will ensure database privileges are assigned via roles and not directly assigned to database accounts. Privileges may be assigned directly to application owner accounts where the DBMS does not otherwise support access via roles.\r\n\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'cross db ownership chaining\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'cross db ownership chaining\'','Cross db ownership chaining  option is disabled','Cross db ownership chaining option  is not disabled. Disable this option','pass',NULL,NULL,'2026-02-11 17:51:59'),(1647,202602,52,13,'AA_SqlServer_080_Disable Database Mail XPs option','major','CONFIG','SQL Mail accepts incoming database commands via email. This can introduce malicious codes or viruses into the SQL server environment.','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Database Mail XPs\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \'Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'Database Mail XPs\'','Database Mail XPs option is disabled','Database Mail XPs option  is not disabled. Disable this option','pass',NULL,NULL,'2026-02-11 17:51:59'),(1648,202602,52,14,'AA_SqlServer_100_Disable xp_cmdshell Server Configuration option','major','CONFIG','The xp_cmdshell extended stored procedures allows execution of host executables outside the controls of database access permissions.  This access may be exploited by malicious users who have compromised the integrity of the SQL Server database process to control the host operating system to perpetrate additional malicious activity. The DBA should disable the use of external procedures by the database unless it is mission critical or operationally required','','SELECT CAST(value as int) +\r\n       CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'xp_cmdshell\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) +\r\n\' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'xp_cmdshell\'','xp_cmdshell Server Configuration option is disabled','xp_cmdshell Server Configuration option is not disabled. This option must be disabled','pass',NULL,NULL,'2026-02-11 17:51:59'),(1649,202602,52,15,'AA_SqlServer_110_Disable Remote Access option','major','CONFIG','The remote access option controls the execution of local stored procedures on remote\r\nservers or remote stored procedures on local server.Functionality can be abused to launch a Denial-of-Service (DoS) attack on remote servers\r\nby off-loading query processing to a target.\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'remote access\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \' Value in use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'remote access\'','Remote Access option is disabled','Remote Access option  is not disabled. Disable this option','fail','\n------------------------------------------\n\'remote access Value : 1 Value in use : 1\'',NULL,'2026-02-11 17:51:59'),(1650,202602,52,16,'AA_SqlServer_120_Disable Remote Admin Connections option','major','CONFIG','The remote admin connections option controls whether a client application on a remote\r\ncomputer can use the Dedicated Administrator Connection (DAC).The Dedicated Administrator Connection (DAC) lets an administrator access a running\r\nserver to execute diagnostic functions or Transact-SQL statements, or to troubleshoot\r\nproblems on the server, even when the server is locked or running in an abnormal state\r\nand not responding to a SQL Server Database Engine connection. In a cluster scenario, the\r\nadministrator may not actually be logged on to the same node that is currently hosting the\r\nSQL Server instance and thus is considered \"remote\". Therefore, this setting should usually\r\nbe enabled (1) for SQL Server failover clusters; otherwise it should be disabled (0) which is\r\nthe default.\r\n','','execute sp_executesql N\'\r\n\r\nDECLARE @x int;\r\n\r\nSELECT @x=isnull(CAST(value as int) + CAST(value_in_use as int),100)\r\nFROM sys.configurations\r\nWHERE name = \'\'remote admin connections\'\'\r\n\r\nIF @x = 100\r\n       SELECT 0 ;\r\nELSE \r\n   SELECT CAST(value as int) + CAST(value_in_use as int) \r\n   FROM sys.configurations\r\n   WHERE name = \'\'remote admin connections\'\'\r\n\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'remote admin connections\'','Remote Admin Connections option is disabled','Remote Admin Connections option  is not disabled. Disable this option','pass',NULL,NULL,'2026-02-11 17:51:59'),(1651,202602,52,19,'AA_SqlServer_150_Disable database trustworthy status','major','CONFIG','The TRUSTWORTHY database setting restricts access to database resources by databases that contain assemblies with the EXTERNAL_ACCESS or UNSAFE permission settings and modules that use impersonation of accounts assigned elevated privileges.  Unless all assemblies and code for the database have been reviewed, especially in the case where databases have been detached and attached between server instances, leaving the TRUSTWORTHY status to off can help reduce threats from malicious assemblies or modules.','','SELECT count(name)\r\nFROM sys.databases\r\nWHERE is_trustworthy_on = 1\r\nAND name != \'msdb\';','== 0','','SELECT name\r\nFROM sys.databases\r\nWHERE is_trustworthy_on = 1\r\nAND name != \'msdb\';','database trustworthy status is disabled','database trustworthy status is not disabled. Disable this option','pass',NULL,NULL,'2026-02-11 17:51:59'),(1652,202602,52,20,'Checkpoint başarıyla oluşturuldu.','major','CONFIG','This test checks if SQL Server Instance is not advertised by the SQL Server Browser service. To maintain a higher level of protection for database instances, we recommend that SQL Server Instance be hidden when it is not required. Please note that this test does not include Clustered Instances as turning off this feature may cause issues with the Clustered environment.\r\n\r\n','','execute sp_executesql N\'\r\n\r\nDECLARE @getValue INT\r\n\r\nEXEC master.sys.xp_instance_regread\r\n@rootkey = N\'\'HKEY_LOCAL_MACHINE\'\',\r\n@key = N\'\'SOFTWARE\\Microsoft\\Microsoft SQL Server\\MSSQLServer\\SuperSocketNetLib\'\',\r\n@value_name = N\'\'HideInstance\'\',\r\n@value = @getValue OUTPUT\r\n\r\nSELECT isnull(@getvalue,0)\'','==1','','execute sp_executesql N\'\r\n\r\nDECLARE @getValue INT\r\n\r\nEXEC master.sys.xp_instance_regread\r\n@rootkey = N\'\'HKEY_LOCAL_MACHINE\'\',\r\n@key = N\'\'SOFTWARE\\Microsoft\\Microsoft SQL Server\\MSSQLServer\\SuperSocketNetLib\'\',\r\n@value_name = N\'\'HideInstance\'\',\r\n@value = @getValue OUTPUT\r\n\r\nSELECT isnull(@getvalue,0)\'','SQL Server Instance is  hidden.\r\n','SQL Server Instance is not hidden. Hide the instance','fail','\n-\n0',NULL,'2026-02-11 17:51:59'),(1653,202602,52,21,'AA_SqlServer_160_Hide SQL Server Instance','major','CONFIG','This test checks if SQL Server Instance is not advertised by the SQL Server Browser service. To maintain a higher level of protection for database instances, we recommend that SQL Server Instance be hidden when it is not required. Please note that this test does not include Clustered Instances as turning off this feature may cause issues with the Clustered environment.\r\n\r\n','','execute sp_executesql N\'\r\n\r\nDECLARE @getValue INT\r\n\r\nEXEC master.sys.xp_instance_regread\r\n@rootkey = N\'\'HKEY_LOCAL_MACHINE\'\',\r\n@key = N\'\'SOFTWARE\\Microsoft\\Microsoft SQL Server\\MSSQLServer\\SuperSocketNetLib\'\',\r\n@value_name = N\'\'HideInstance\'\',\r\n@value = @getValue OUTPUT\r\n\r\nSELECT isnull(@getvalue,0)\'','==1','','execute sp_executesql N\'\r\n\r\nDECLARE @getValue INT\r\n\r\nEXEC master.sys.xp_instance_regread\r\n@rootkey = N\'\'HKEY_LOCAL_MACHINE\'\',\r\n@key = N\'\'SOFTWARE\\Microsoft\\Microsoft SQL Server\\MSSQLServer\\SuperSocketNetLib\'\',\r\n@value_name = N\'\'HideInstance\'\',\r\n@value = @getValue OUTPUT\r\n\r\nSELECT isnull(@getvalue,0)\'','SQL Server Instance is  hidden.','SQL Server Instance is not hidden. Hide the instance','fail','\n-\n0',NULL,'2026-02-11 17:51:59'),(1654,202602,52,38,'AA_SqlServer_300_No Access To General Extended procedures','major','PRIV','This test checks for the existence of, and user permissions on, extended stored procedures.  Either these procedures should be completely dropped, or access to them should be strictly limited. xp_cmdshell, xp_enumgroups, xp_grantlogin ,xp_logevent, xp_logininfo,    xp_msver, xp_revokelogin, xp_sprintf, xp_sqlmaint, xp_sscanf\r\n','','SELECT \r\ncount(*) \r\nFROM \r\n  [master].sys.system_objects o \r\n  JOIN [master].sys.database_permissions p ON o.object_id = p.major_id \r\n  JOIN [master].sys.database_principals u ON p.grantee_principal_id = u.principal_id \r\nWHERE \r\n    o.name in ( \r\n	\'xp_cmdshell\', \r\n	\'xp_enumgroups\', \r\n    \'xp_grantlogin\' ,\r\n	\'xp_logevent\', \r\n	\'xp_logininfo\', \r\n    \'xp_msver\', \r\n	\'xp_revokelogin\', \r\n	\'xp_sprintf\', \r\n    \'xp_sqlmaint\', \r\n	\'xp_sscanf\' )\r\n  AND p.type = \'EX\' ','== 0','','SELECT \r\n  \'Principal : \'+u.name  COLLATE DATABASE_DEFAULT +\r\n  \' Extended Procedure Name : \'+o.name COLLATE DATABASE_DEFAULT +\r\n  \' Type : \'+ u.type_desc COLLATE DATABASE_DEFAULT \r\nFROM \r\n  [master].sys.system_objects o \r\n  JOIN [master].sys.database_permissions p ON o.object_id = p.major_id \r\n  JOIN [master].sys.database_principals u ON p.grantee_principal_id = u.principal_id \r\nWHERE \r\n    o.name in ( \r\n	\'xp_cmdshell\', \r\n	\'xp_enumgroups\', \r\n    \'xp_grantlogin\' ,\r\n	\'xp_logevent\', \r\n	\'xp_logininfo\', \r\n    \'xp_msver\', \r\n	\'xp_revokelogin\', \r\n	\'xp_sprintf\', \r\n    \'xp_sqlmaint\', \r\n	\'xp_sscanf\' )\r\n  AND p.type = \'EX\' ','There are no permissions on general extended stored procedures\r\n','There are some persmissions permissions on general extended stored procedures.\r\n','fail','\n----------------------------------------------------------------------------------\n\'Principal : public Extended Procedure Name : xp_msver Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_sscanf Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_revokelogin Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_grantlogin Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_sprintf Type : DATABASE_ROLE\'',NULL,'2026-02-11 17:51:59'),(1655,202602,52,39,'AA_SqlServer_310_No Access to OLE Automation procedures','major','CONFIG','This test checks for the existence of,and user permissions on OLE automation extended stored procedures.  Either these procedures should be completely dropped, or access to them should be strictly limited.      \r\n','','SELECT CAST(value as int) +\r\n       CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Ole Automation Procedures\'   \r\n','== 0','','SELECT CAST(value as int) +\r\n       CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Ole Automation Procedures\'\r\n  \r\n','OLE Automation procedures  option is disabled\r\n','OLE Automation procedures  option  is not disabled. Disable this option\r\n','pass',NULL,NULL,'2026-02-11 17:51:59'),(1656,202602,52,17,'AA_SqlServer_130_Disable Ole Automation Procedures option','minor','CONFIG','This test checks if Ole Automation Procedures option is disabled. Ole Automation Procedures option allows SQL Server users to execute functions external to SQL Server. Enabling this option will increase the attack surface of SQL Server and allow users to execute functions in the security context of SQL Server. We recommend that the Ole Automation Procedures option to be disabled when it is not document as a requirement.\r\n\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Ole Automation Procedures\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \'Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'Ole Automation Procedures\'',' Ole Automation Procedures option is disabled',' Ole Automation Procedures option  is not disabled. Disable this option','pass',NULL,NULL,'2026-02-11 17:51:59'),(1657,202602,52,18,'AA_SqlServer_140_Disable Scan for Startup Procedures option','minor','CONFIG','This test checks if scan for startup procedures is disabled. This feature causes SQL Server to scan for and automatically run all stored procedures that are set to execute upon service startup. If there are no user-defined stored procedures set to execute when SQL server starts, we recommend this feature to be disabled.\r\n\r\n','','SELECT CAST(value as int) +\r\n       CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'scan for startup procs\'','== 0','','SELECT name + \' value : \'+cast( value as varchar ) +\r\n\' value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'scan for startup procs\'','Scan for Startup Procedures  option is disabled','Scan for Startup Procedures  option  is not disabled. Disable this option','pass',NULL,NULL,'2026-02-11 17:51:59'),(1658,202602,52,9,'AA_SqlServer_040_Rename the sa Login Account','major','ACCOUNT','The \'sa\' account is a well-known account.  Well-known account names provide an easier target for attack.  Renaming the sa account helps reduce the risk of an attack to this built-in account.','','SELECT count(*)\r\nFROM sys.server_principals\r\nWHERE sid = 0x01 and name=\'sa\'','== 0','','SELECT name\r\nFROM sys.server_principals\r\nWHERE sid = 0x01','sa Login Account is renamed','sa Login Account is not renamed. Rename this account','fail','name\n----\n\'sa\'',NULL,'2026-02-11 17:51:59'),(1659,202602,53,24,'AA_SqlServer_190_Public server role permision','critical','PRIV','public is a special fixed server role containing all logins. Unlike other fixed server roles,\r\npermissions can be changed for the public role. In keeping with the principle of least\r\nprivileges, the public server role should not be used to grant permissions at the server\r\nscope as these would be inherited by all users.\r\n\r\nEvery SQL Server login belongs to the public role and cannot be removed from this role.\r\nTherefore, any permissions granted to this role will be available to all logins unless they\r\nhave been explicitly denied to specific logins or user-defined server roles.','','Select \r\n  count (permission_name) \r\nfrom \r\n  sys.server_permissions \r\nwhere \r\n  SUSER_NAME(grantee_principal_id) = \'public\' \r\n  and permission_name not in (\'VIEW ANY DATABASE\', \'CONNECT\')\r\n','== 0','','Select \r\n  permission_name \r\nfrom \r\n  sys.server_permissions \r\nwhere \r\n  SUSER_NAME(grantee_principal_id) = \'public\' \r\n  and permission_name not in (\'VIEW ANY DATABASE\', \'CONNECT\')\r\n\r\n','No server permissions are granted to public.','Some server permissions are granted to public.','pass',NULL,NULL,'2026-02-11 17:55:59'),(1660,202602,53,5,'AA_SqlServer_010_Supported SQL Server version','critical','PATCH','This test checks whether your current SQL Server version is a vendor-supported version.  Microsoft does not provide security fixes or software updates to unsupported software versions','','SELECT cast(ISNULL(SERVERPROPERTY(\'ProductMajorVersion\'),0) as int)   ','>=11','','SELECT \'Product Major version \' +  cast(ISNULL(SERVERPROPERTY(\'ProductMajorVersion\'),\'Null\' ) as  char ) ','The version of the database is acceptable.','The version of the database is not acceptable. The database version should SQL Sever 2012 or upper.','pass',NULL,NULL,'2026-02-11 17:55:59'),(1661,202602,53,6,'AA_SqlServer_020_Disable the sa Login Account','critical','ACCOUNT','This test checks if the \'sa\' Login Account is disabled. The sa account is a widely known and often widely used SQL Server account with sysadmin privileges. Enforcing this control reduces the probability of an attacker executing brute force attacks against a well-known principal.','','SELECT  count(*)\r\nFROM sys.server_principals\r\nWHERE sid = 0x01\r\nAND is_disabled = 0','== 0','','SELECT \'sa user name : \'+ name+\' is disabled : \' +  cast( is_disabled as char)\r\nFROM sys.server_principals\r\nWHERE sid = 0x01\r\n','sa Login Account is disabled','Disable sa login account','fail','\n----------------------------------------------------------------\n\'sa user name : sa is disabled : 0                             \'',NULL,'2026-02-11 17:55:59'),(1662,202602,53,7,'AA_SqlServer_025_sa Change password','critical','ACCOUNT','This test checks that sa password change . The sa password should be changed in every two days','','select datediff( day,  modify_date , getdate() ) FROM sys.server_principals\r\nWHERE sid = 0x01  ','< 3','','select datediff( day,  modify_date , getdate() ) FROM sys.server_principals\r\nWHERE sid = 0x01 ','sa password was changed in two days','','fail','\n--\n28',NULL,'2026-02-11 17:55:59'),(1663,202602,53,8,'AA_SqlServer_030_Ensure no Login exists with sa Login Account','critical','ACCOUNT','The \'sa\' account is a well-known account.  Well-known account names provide an easier target for attack. The lack of the sa account helps reduce the risk of an attack to this built-in account.','','SELECT count(*)\r\nFROM sys.server_principals\r\nWHERE name = \'sa\'','== 0','','SELECT name\r\nFROM sys.server_principals\r\nWHERE name = \'sa\'','There is no the sa account in the database.','There is the sa Login account in the database.Drop this user or rename et.','fail','name\n----\n\'sa\'',NULL,'2026-02-11 17:55:59'),(1664,202602,53,25,'AA_SqlServer_200_Fixed Server Role members for users','critical','PRIV','This test checks fixed server roles for analyst , developers and real persons. Fixed server roles could not be assigned to real person users ( Developer, Analyst users ) . Only Admin can use fixed server role.\r\n','','Select     count(*)   from      sys.server_role_members    where      (       suser_name(member_principal_id) like \'ODEABANK%.%\'    	AND       suser_name(member_principal_id) not like \'%admin%\'         AND       suser_name(member_principal_id) not like \'%t.coban%\'     )      OR (       suser_name(member_principal_id) like \'ODEABANK\\Cyberark_Intertech%\'     )      \r\n','== 0','','Select      suser_name(role_principal_id) + \'   \' + suser_name(member_principal_id)    from      sys.server_role_members    where      (       suser_name(member_principal_id) like \'ODEABANK%.%\'    	AND       suser_name(member_principal_id) not like \'%admin%\'         AND       suser_name(member_principal_id) not like \'%t.coban%\'     )      OR (       suser_name(member_principal_id) like \'ODEABANK\\Cyberark_Intertech%\'     )          \r\n','Fixed Server role usage is correct.\r\n','Fixed Server role usage is not correct.\r\n','pass',NULL,NULL,'2026-02-11 17:55:59'),(1665,202602,53,26,'AA_SqlServer_210_Database Role members for users','critical','PRIV','This test checks database role members for analyst and real person users. Database roles  except  db_datareader could not be assigned to real person users ( Developer, Analyst users ) .\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      EXEC sp_MSforeachdb \'\' USE [?]    INSERT INTO #TEMP   SELECT \'\'\'\'DB Name : \'\'\'\'+Cast (DB_NAME() as varchar)+\'\'\'\' Role Name : \'\'\'\'+USER_NAME(role_principal_id)  +\'\'\'\' User Name \'\'\'\'+  USER_NAME(member_principal_id)    from  sys.database_role_members   	Where   	(   	( USER_NAME(member_principal_id)  like \'\'\'\'%ODEABANK%.%\'\'\'\'  and   USER_NAME(member_principal_id)  not like \'\'\'\'%admin%\'\'\'\' )     	OR   	  (suser_name(member_principal_id) like \'\'\'\'%ODEABANK%Cyberark%\'\'\'\')       )    	AND   	DB_NAME() <> \'\'\'\'master\'\'\'\' and   	USER_NAME(role_principal_id) not in (\'\'\'\'db_datareader\'\'\'\',\'\'\'\'db_viewdefinition\'\'\'\',\'\'\'\'db_denydatareader\'\'\'\',\'\'\'\'db_deny_maas\'\'\'\');   \'\'      Select  count(*)  from #TEMP;   \'\r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      EXEC sp_MSforeachdb \'\' USE [?]    INSERT INTO #TEMP   SELECT \'\'\'\'DB Name : \'\'\'\'+Cast (DB_NAME() as varchar)+\'\'\'\' Role Name : \'\'\'\'+USER_NAME(role_principal_id)  +\'\'\'\' User Name \'\'\'\'+  USER_NAME(member_principal_id)    from  sys.database_role_members   	Where   (   	( USER_NAME(member_principal_id)  like \'\'\'\'%ODEABANK%.%\'\'\'\'  and   USER_NAME(member_principal_id)  not like \'\'\'\'%admin%\'\'\'\' )     	OR   	(suser_name(member_principal_id) like \'\'\'\'%ODEABANK%Cyberark%\'\'\'\')   )    	AND   	DB_NAME() <> \'\'\'\'master\'\'\'\' and   	USER_NAME(role_principal_id) not in  (\'\'\'\'db_datareader\'\'\'\',\'\'\'\'db_viewdefinition\'\'\'\',\'\'\'\'db_denydatareader\'\'\'\',\'\'\'\'db_deny_maas\'\'\'\');   \'\'      Select  * from #TEMP;   \'\r\n','Database role member usage for users  is correct\r\n','Database role member usage for users  is not correct\r\n','pass',NULL,NULL,'2026-02-11 17:55:59'),(1666,202602,53,27,'AA_SqlServer_220_2_Public Database Permissions','critical','PRIV','This test checks database permisions for public . Public is a special role and permissions should not be granted to public role.\r\n','','execute sp_executesql N\'   CRE