MAJOR_iD) NOT LiKE (\'\'\'\'%fn_cdc_get_net_changes_application_data%\'\'\'\')   AND NOT (OBJECT_SCHEMA_NAME(MAJOR_iD) = \'\'\'\'cdc\'\'\'\' and PERMiSSiON_NAME=\'\'\'\'SELECT\'\'\'\')   AND NOT (PERMiSSiON_NAME IN (\'\'\'\'REFERENCES\'\'\'\',\'\'\'\'SEND\'\'\'\',   \'\'\'\'VIEW ANY COLUMN ENCRYPTION KEY DEFINITION\'\'\'\',   \'\'\'\'VIEW ANY COLUMN MASTER KEY DEFINITION\'\'\'\' ) and OBJECT_SCHEMA_NAME(MAJOR_iD) IS NULL)   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select * from #TEMP;   \'','There are no permissions which are assigned to public.\r\n','There are some persmissions which are assigned to public\r\n','pass',NULL,NULL,'2026-02-11 17:55:59'),(1667,202602,53,28,'AA_SqlServer_220_Public Database Permissions','critical','PRIV','This test checks database permisions for public . Public is a special role and permissions should not be granted to public role.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      exec sp_msforeachdb \'\'   USE [?]     iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'public\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND OBJECT_NAME(MAJOR_iD) NOT LiKE (\'\'\'\'%fn_cdc_get_net_changes_application_data%\'\'\'\')   AND NOT (OBJECT_SCHEMA_NAME(MAJOR_iD) = \'\'\'\'cdc\'\'\'\' and PERMiSSiON_NAME=\'\'\'\'SELECT\'\'\'\')   AND NOT (PERMiSSiON_NAME IN (\'\'\'\'REFERENCES\'\'\'\',\'\'\'\'SEND\'\'\'\',   \'\'\'\'VIEW ANY COLUMN ENCRYPTION KEY DEFINITION\'\'\'\',   \'\'\'\'VIEW ANY COLUMN MASTER KEY DEFINITION\'\'\'\' ) and OBJECT_SCHEMA_NAME(MAJOR_iD) IS NULL)   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select count(*) from #TEMP;   \' \r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      exec sp_msforeachdb \'\'   USE [?]     iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'public\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND OBJECT_NAME(MAJOR_iD) NOT LiKE (\'\'\'\'%fn_cdc_get_net_changes_application_data%\'\'\'\')   AND NOT (OBJECT_SCHEMA_NAME(MAJOR_iD) = \'\'\'\'cdc\'\'\'\' and PERMiSSiON_NAME=\'\'\'\'SELECT\'\'\'\')   AND NOT (PERMiSSiON_NAME IN (\'\'\'\'REFERENCES\'\'\'\',\'\'\'\'SEND\'\'\'\',   \'\'\'\'VIEW ANY COLUMN ENCRYPTION KEY DEFINITION\'\'\'\',   \'\'\'\'VIEW ANY COLUMN MASTER KEY DEFINITION\'\'\'\' ) and OBJECT_SCHEMA_NAME(MAJOR_iD) IS NULL)   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select * from #TEMP;   \' \r\n','There are no permissions which are assigned to public.\r\n','There are some persmissions which are assigned to public\r\n','pass',NULL,NULL,'2026-02-11 17:55:59'),(1668,202602,53,29,'AA_SqlServer_230_Real person users','critical','ACCOUNT','All logins to the database should be made with AD groups, real person users should  not be connected database directly\r\n','','Select      count(*)   from      sys.server_principals    where      name like \'ODEABANK%.%\'      and is_disabled = 0   \r\n','== 0','','Select      name     from      sys.server_principals    where      name like \'ODEABANK%.%\'      and is_disabled = 0;\r\n','Real person users are not found in the logins\r\n','Some real person users are found in the logins\r\n','pass',NULL,NULL,'2026-02-11 17:55:59'),(1669,202602,53,30,'AA_SqlServer_240_2_guest Database Permissions','critical','ACCOUNT','This test checks database permisions for guest . guest is a special user and permissions should not be granted to guest user.\r\n','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP ( row varchar(500));\r\n\r\nexec sp_MSforeachdb \'\'\r\nUSE [?]\r\niNSERT iNTO #TEMP\r\nSELECT\r\n\'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +\r\n\'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +\r\n\'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +\r\n\'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )\r\nFROM\r\nsys.database_permissions\r\nWHERE\r\nUSER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'guest\'\'\'\' )\r\nAND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'\r\nAND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')\r\nAND STATE_DESC=\'\'\'\'GRANT\'\'\'\'\r\n;\r\n\'\'\r\nselect count(*) from #TEMP;\r\n\'','== 0','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP ( row varchar(500));\r\n\r\nexec sp_MSforeachdb \'\'\r\nUSE [?]\r\niNSERT iNTO #TEMP\r\nSELECT\r\n\'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +\r\n\'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +\r\n\'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +\r\n\'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )\r\nFROM\r\nsys.database_permissions\r\nWHERE\r\nUSER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'guest\'\'\'\' )\r\nAND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'\r\nAND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')\r\nAND STATE_DESC=\'\'\'\'GRANT\'\'\'\'\r\n;\r\n\'\'\r\nselect * from #TEMP;\r\n\'','There are no permissions which are assigned to guest.\r\n','There are some persmissions which are assigned to guest\r\n','pass',NULL,NULL,'2026-02-11 17:55:59'),(1670,202602,53,31,'AA_SqlServer_240_guest Database Permissions','critical','PRIV','This test checks database permisions for guest . guest is a special user and permissions should not be granted to guest user.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      exec sp_msforeachdb \'\'   USE [?]     iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'guest\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select count(*) from #TEMP;   \' \r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      exec sp_msforeachdb \'\'   USE [?]     iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'guest\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select  *  from #TEMP;   \' \r\n','There are no permissions which are assigned to guest.\r\n','There are some persmissions which are assigned to guest\r\n','pass',NULL,NULL,'2026-02-11 17:55:59'),(1671,202602,53,32,'AA_SqlServer_250_Database Role members for guest','critical','PRIV','This test checks database role members for guest  user. Database roles  could not be assigned to guest role.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      EXEC sp_MSforeachdb \'\' USE [?]    INSERT INTO #TEMP   SELECT \'\'\'\'DB Name : \'\'\'\'+Cast (DB_NAME() as varchar)+\'\'\'\' Role Name : \'\'\'\'+USER_NAME(role_principal_id)  +\'\'\'\' User Name \'\'\'\'+  USER_NAME(member_principal_id)    from  sys.database_role_members   	Where     USER_NAME(member_principal_id)  = \'\'\'\'guest\'\'\'\'     ;   \'\'      Select count(*)  from #TEMP;   \'\r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      EXEC sp_MSforeachdb \'\' USE [?]    INSERT INTO #TEMP   SELECT \'\'\'\'DB Name : \'\'\'\'+Cast (DB_NAME() as varchar)+\'\'\'\' Role Name : \'\'\'\'+USER_NAME(role_principal_id)  +\'\'\'\' User Name \'\'\'\'+  USER_NAME(member_principal_id)    from  sys.database_role_members   	Where     USER_NAME(member_principal_id)  = \'\'\'\'guest\'\'\'\'     ;   \'\'      Select  *  from #TEMP;   \'\r\n','Database role member usage for guest user  is correct\r\n','Database role member usage for guest user  is not correct\r\n','pass',NULL,NULL,'2026-02-11 17:55:59'),(1672,202602,53,33,'AA_SqlServer_260_SQL Logins with Null Password','critical','ACCOUNT','This test checks sql logins with null password. SQL Logins should not have null passwords.\r\n','','SELECT      count(name)   from      sys.sql_logins    WHERE      PWDCOMPARE(\'\', password_hash)= 1\r\n','== 0','','SELECT      name    from      sys.sql_logins    WHERE      PWDCOMPARE(\'\', password_hash)= 1   \r\n','There are no sql logins with null paswords\r\n','There are some sql logins with null passwords.\r\n','pass',NULL,NULL,'2026-02-11 17:55:59'),(1673,202602,53,34,'AA_SqlServer_270_SQL Logins with username and passwords are equal','critical','ACCOUNT','This test checks sql login password which are egual to username. Username and password must be different for SQL logins.\r\n','','SELECT      count(name)   from      sys.sql_logins    WHERE      PWDCOMPARE(name,password_hash)=1 \r\n','== 0','','SELECT      name    from      sys.sql_logins    WHERE      PWDCOMPARE(name,password_hash)=1    \r\n','There is no SQL login name which is equal to password.\r\n','There are some sql logins whose passwords are egual to usernames.\r\n','pass',NULL,NULL,'2026-02-11 17:55:59'),(1674,202602,53,35,'AA_SqlServer_280_No Sample Databases','critical','CONFIG','This test checks whether the sample databases created optionally on installation are present.  These sample databases contain many default permissions, and can be used as an entry point to your systems. \r\n','','select      count(name)    from      sys.databases    where      name in (       \'AdventureWorks\', \'AdventureWorksDW\',        \'Northwind\', \'Pubs\'     )   \r\n','== 0','','select      name    from      sys.databases    where      name in (       \'AdventureWorks\', \'AdventureWorksDW\',        \'Northwind\', \'Pubs\'     )   \r\n','There are no sample databases in the server\r\n','There are some sample databases in the server\r\n','pass',NULL,NULL,'2026-02-11 17:55:59'),(1675,202602,53,43,'AA_SqlServer_350_User Password Policy Is Checked','critical','ACCOUNT','This test checks that CHECK_POLICY is enabled for all users.  Enabling CHECK_POLICY ensures that Windows passwords policies are enforced.','','select count(*) from sys.sql_logins  \r\nwhere \r\nis_policy_checked=0 and\r\nname not like \'##%\'','== 0','','select name from sys.sql_logins  \r\nwhere \r\nis_policy_checked=0 and\r\nname not like \'##%\'','CHECK_POLICY is enabled for all users','CHECK_POLICY is not enabled for all users','pass',NULL,NULL,'2026-02-11 17:55:59'),(1676,202602,53,44,'AA_SqlServer_360_CHECK_EXPIRATION Is Checked','critical','ACCOUNT','This test checks that CHECK_EXPIRATION is enabled for all users.  Passwords that have been in use for long periods of time are likely to become known to unauthorized users.\r\n','','select count(*) from sys.sql_logins     where    is_expiration_checked=0 and   name not like \'##%\'\r\n','== 0','','select name from sys.sql_logins     where    is_expiration_checked=0 and   name not like \'##%\'\r\n','CHECK_EXPIRATION is enabled for all users\r\n','CHECK_EXPIRATION is not enabled for all users\r\n','fail','name\n----\n\'sa\'',NULL,'2026-02-11 17:55:59'),(1677,202602,53,22,'AA_SqlServer_170_Windows Authentication','major','AUTH','This test checks that the authentication mode is set to Windows authentication only.  Windows provides a more robust authentication mechanism than SQL Server authentication.','',' SELECT cast( SERVERPROPERTY(\'IsIntegratedSecurityOnly\') as int) ','==1','','SELECT cast( SERVERPROPERTY(\'IsIntegratedSecurityOnly\') as varchar)','The authentication mode is set to Windows authentication only. ','The authentication mode is not set to Windows authentication only.','fail','\n---\n\'0\'',NULL,'2026-02-11 17:55:59'),(1678,202602,53,23,'AA_SqlServer_180_No Guest User Accounts','major','ACCOUNT','This test checks for the existence of guest user accounts with CONNECT permission in database other than master, msdb and tempdb.  This test also exclude databases that are flagged as distributor. If the GUEST user exists and a specific login has not been granted to a database, a login will be mapped to GUEST. The presence of the GUEST user allows all logins to access the database.\r\n','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP  ( row int);\r\n\r\nEXEC sp_MSforeachdb \'\' USE [?]\r\n	INSERT INTO #TEMP\r\n	SELECT count(*) \r\n	FROM sys.database_permissions\r\n	WHERE [grantee_principal_id] = DATABASE_PRINCIPAL_ID(\'\'\'\'guest\'\'\'\')\r\n	AND [state_desc] LIKE \'\'\'\'GRANT%\'\'\'\'\r\n	AND [permission_name] = \'\'\'\'CONNECT\'\'\'\'\r\n	AND DB_NAME() NOT IN (\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'msdb\'\'\'\') ;\r\n\'\'\r\n\r\nSelect sum(row) from #TEMP;\r\ndrop table #TEMP;\r\n\'','== 0','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP  ( row varchar(500));\r\n\r\nEXEC sp_MSforeachdb \'\' USE  [?] \r\n	INSERT INTO #TEMP\r\n	SELECT \'\'\'\' DB NAME : \'\'\'\' + Cast (DB_NAME() as varchar) + \'\'\'\' guest user has CONNECT permission \'\'\'\'\r\n	FROM sys.database_permissions\r\n	WHERE [grantee_principal_id] = DATABASE_PRINCIPAL_ID(\'\'\'\'guest\'\'\'\')\r\n	AND [state_desc] LIKE \'\'\'\'GRANT%\'\'\'\'\r\n	AND [permission_name] = \'\'\'\'CONNECT\'\'\'\'\r\n	AND DB_NAME() NOT IN (\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'msdb\'\'\'\') ;\r\n\'\'\r\n\r\nSelect * from #TEMP;\r\ndrop table #TEMP;\r\n\'','There is no guest user with CONNECT permission. ','There are   guest users with CONNECT permission. Remove these users','pass',NULL,NULL,'2026-02-11 17:55:59'),(1679,202602,53,36,'AA_SqlServer_290_2_No Permissions with GRANT Option','major','PRIV','This test checks database permisions  with grant option. No permission with grant option should be defined in the database.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP ( row varchar(500));      exec sp_MSforeachdb \'\'   USE [?]   iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   STATE_DESC like \'\'\'\'%WITH_GRANT%\'\'\'\'   ;   \'\'   select count(*) from #TEMP;   \'\r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP ( row varchar(500));      exec sp_MSforeachdb \'\'   USE [?]   iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   STATE_DESC like \'\'\'\'%WITH_GRANT%\'\'\'\'   ;   \'\'   select * from #TEMP;   \'\r\n','There are no permissions with grant option.\r\n','There are some persmissions  with grant option.\r\n','pass',NULL,NULL,'2026-02-11 17:55:59'),(1680,202602,53,37,'AA_SqlServer_290_No Permissions with GRANT Option','major','PRIV','','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP  ( row varchar(500));\r\n\r\nexec sp_msforeachdb \'\'\r\nUSE [?]  \r\niNSERT iNTO #TEMP\r\nSELECT\r\n\'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +\r\n\'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +\r\n\'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +\r\n\'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )\r\nFROM\r\nsys.database_permissions\r\nWHERE\r\nSTATE_DESC like \'\'\'\'%WITH_GRANT%\'\'\'\'\r\n;\r\n\'\'\r\nselect  count(*)  from #TEMP;\r\n\' ','== 0','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP  ( row varchar(500));\r\n\r\nexec sp_msforeachdb \'\'\r\nUSE [?]  \r\niNSERT iNTO #TEMP\r\nSELECT\r\n\'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +\r\n\'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +\r\n\'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +\r\n\'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )\r\nFROM\r\nsys.database_permissions\r\nWHERE\r\nSTATE_DESC like \'\'\'\'%WITH_GRANT%\'\'\'\'\r\n;\r\n\'\'\r\nselect * from #TEMP;\r\n\' ','There are no permissions with grant option.\r\n','There are some persmissions  with grant option.\r\n','pass',NULL,NULL,'2026-02-11 17:55:59'),(1681,202602,53,40,'AA_SqlServer_320_No Access to Registry Access Extended procedures','major','PRIV','This test checks for the existence of, and user permissions on, registry access extended stored procedures.  Either these procedures should be completely dropped, or access to them should be strictly limited. xp_reg%,xp_instance_reg%\r\n','','SELECT \r\ncount(*) \r\nFROM \r\n  [master].sys.system_objects o \r\n  JOIN [master].sys.database_permissions p ON o.object_id = p.major_id \r\n  JOIN [master].sys.database_principals u ON p.grantee_principal_id = u.principal_id \r\nWHERE \r\n( o.name LIKE \'xp_reg%\' OR o.name LIKE \'xp_instance_reg%\')\r\n  AND p.type = \'EX\' ','== 0','','SELECT \r\n  \'Principal : \'+u.name  COLLATE DATABASE_DEFAULT +\r\n  \' Extended Procedure Name : \'+o.name COLLATE DATABASE_DEFAULT +\r\n  \' Type : \'+ u.type_desc COLLATE DATABASE_DEFAULT \r\nFROM \r\n  [master].sys.system_objects o \r\n  JOIN [master].sys.database_permissions p ON o.object_id = p.major_id \r\n  JOIN [master].sys.database_principals u ON p.grantee_principal_id = u.principal_id \r\nWHERE \r\n( o.name LIKE \'xp_reg%\' OR o.name LIKE \'xp_instance_reg%\')\r\n  AND p.type = \'EX\' ','There are no permissions on registry access extended stored procedures\r\n','There are some persmissions permissions on registry access extended stored procedures\r\n','fail','\n---------------------------------------------------------------------------------------\n\'Principal : public Extended Procedure Name : xp_instance_regread Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_regread Type : DATABASE_ROLE\'',NULL,'2026-02-11 17:55:59'),(1682,202602,53,41,'AA_SqlServer_330_Revoke public login from SQL Server agent proxy account','major','PRIV','The public database role contains every user in the msdb database. SQL Agent proxies   define a security context in which a job step can run.Granting access to SQL Agent proxies for the public role would allow all users to utilize the proxy which may have high privileges. This would likely break the principle of least   privileges.\r\n','','SELECT count(*)\r\nFROM msdb.dbo.sysproxylogin spl\r\nJOIN sys.database_principals dp\r\nON dp.sid = spl.sid\r\nJOIN msdb.dbo.sysproxies sp\r\nON sp.proxy_id = spl.proxy_id\r\nWHERE principal_id = USER_ID(\'public\')','== 0','','SELECT \'proxyname : \'+CAST(sp.name  as varchar)\r\nFROM msdb.dbo.sysproxylogin spl\r\nJOIN sys.database_principals dp\r\nON dp.sid = spl.sid\r\nJOIN msdb.dbo.sysproxies sp\r\nON sp.proxy_id = spl.proxy_id\r\nWHERE principal_id = USER_ID(\'public\')','There are no public permissions on SQL Server agent proxy account\r\n','There are some public permissions on SQL Server agent proxy account\r\n','pass',NULL,NULL,'2026-02-11 17:55:59'),(1683,202602,53,42,'AA_SqlServer_340_No Individual User Access To syscomment and sp_helptext','minor','PRIV','This test checks for grants on SYSCOMMENTS.TEXT.  Such grants allow any user to read the text comments associated with a database object, making the text publicly viewable.\r\n','','SELECT count(*)\r\nFROM msdb.dbo.sysproxylogin spl\r\nJOIN sys.database_principals dp\r\nON dp.sid = spl.sid\r\nJOIN msdb.dbo.sysproxies sp\r\nON sp.proxy_id = spl.proxy_id\r\nWHERE principal_id = USER_ID(\'public\')\r\n','== 0','','SELECT count(*)\r\nFROM msdb.dbo.sysproxylogin spl\r\nJOIN sys.database_principals dp\r\nON dp.sid = spl.sid\r\nJOIN msdb.dbo.sysproxies sp\r\nON sp.proxy_id = spl.proxy_id\r\nWHERE principal_id = USER_ID(\'public\')','There are no public permissions on SQL Server agent proxy account','There are some public permissions on SQL Server agent proxy account','pass',NULL,NULL,'2026-02-11 17:55:59'),(1684,202602,53,10,'AA_SqlServer_050_Disable Ad hoc distributed queries option','major','CONFIG','Adhoc queries allow undefined access to remote database sources.  Access to untrusted databases could result in execution of malicious applications and/or a compromise of local data confidentiality and integrity. The DBA will configure the database to disable access from the database to objects stored externally to the database on the local host unless mission and/or operationally required and documented.\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Ad Hoc Distributed Queries\'','== 0','','SELECT name + \' Value : \'+ cast( value as varchar ) + \' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'Ad Hoc Distributed Queries\'','Ad Hoc Distributed Queries is disabled','Ad Hoc Distributed Queries is not disabled. Disable this option','pass',NULL,NULL,'2026-02-11 17:55:59'),(1685,202602,53,11,'AA_SqlServer_060_Disable CLR option','major','CONFIG','The clr_enabled parameter configures SQL Server to allow or disallow use of Command Language Runtime objects.  CLR objects is managed code that integrates with the .NET Framework.  This is a more secure method than external stored procedures, although it still contains some risk.  Where no external application execution requirements are required, disallowing use of any improves the overall security posture of the database.\r\n\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'clr enabled\'','== 0','','SELECT name + \' Value : \'+ cast( value as varchar ) + \' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'clr enabled\'','CLR option is disabled','CLR option is not disabled. Disable this option','pass',NULL,NULL,'2026-02-11 17:55:59'),(1686,202602,53,12,'AA_SqlServer_070_Disable Cross db ownership chaining option','major','CONFIG','Cross database ownership chaining allows permissions to objects to be assigned by users other than the Information Owner.  This allows access to objects that are not authorized directly by the Information Owner based on job functions defined by the owner.  Unauthorized access may lead to a compromise of data integrity or confidentiality. The DBA will ensure database privileges are assigned via roles and not directly assigned to database accounts. Privileges may be assigned directly to application owner accounts where the DBMS does not otherwise support access via roles.\r\n\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'cross db ownership chaining\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'cross db ownership chaining\'','Cross db ownership chaining  option is disabled','Cross db ownership chaining option  is not disabled. Disable this option','pass',NULL,NULL,'2026-02-11 17:55:59'),(1687,202602,53,13,'AA_SqlServer_080_Disable Database Mail XPs option','major','CONFIG','SQL Mail accepts incoming database commands via email. This can introduce malicious codes or viruses into the SQL server environment.','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Database Mail XPs\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \'Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'Database Mail XPs\'','Database Mail XPs option is disabled','Database Mail XPs option  is not disabled. Disable this option','pass',NULL,NULL,'2026-02-11 17:55:59'),(1688,202602,53,14,'AA_SqlServer_100_Disable xp_cmdshell Server Configuration option','major','CONFIG','The xp_cmdshell extended stored procedures allows execution of host executables outside the controls of database access permissions.  This access may be exploited by malicious users who have compromised the integrity of the SQL Server database process to control the host operating system to perpetrate additional malicious activity. The DBA should disable the use of external procedures by the database unless it is mission critical or operationally required','','SELECT CAST(value as int) +\r\n       CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'xp_cmdshell\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) +\r\n\' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'xp_cmdshell\'','xp_cmdshell Server Configuration option is disabled','xp_cmdshell Server Configuration option is not disabled. This option must be disabled','pass',NULL,NULL,'2026-02-11 17:55:59'),(1689,202602,53,15,'AA_SqlServer_110_Disable Remote Access option','major','CONFIG','The remote access option controls the execution of local stored procedures on remote\r\nservers or remote stored procedures on local server.Functionality can be abused to launch a Denial-of-Service (DoS) attack on remote servers\r\nby off-loading query processing to a target.\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'remote access\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \' Value in use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'remote access\'','Remote Access option is disabled','Remote Access option  is not disabled. Disable this option','fail','\n------------------------------------------\n\'remote access Value : 1 Value in use : 1\'',NULL,'2026-02-11 17:55:59'),(1690,202602,53,16,'AA_SqlServer_120_Disable Remote Admin Connections option','major','CONFIG','The remote admin connections option controls whether a client application on a remote\r\ncomputer can use the Dedicated Administrator Connection (DAC).The Dedicated Administrator Connection (DAC) lets an administrator access a running\r\nserver to execute diagnostic functions or Transact-SQL statements, or to troubleshoot\r\nproblems on the server, even when the server is locked or running in an abnormal state\r\nand not responding to a SQL Server Database Engine connection. In a cluster scenario, the\r\nadministrator may not actually be logged on to the same node that is currently hosting the\r\nSQL Server instance and thus is considered \"remote\". Therefore, this setting should usually\r\nbe enabled (1) for SQL Server failover clusters; otherwise it should be disabled (0) which is\r\nthe default.\r\n','','execute sp_executesql N\'\r\n\r\nDECLARE @x int;\r\n\r\nSELECT @x=isnull(CAST(value as int) + CAST(value_in_use as int),100)\r\nFROM sys.configurations\r\nWHERE name = \'\'remote admin connections\'\'\r\n\r\nIF @x = 100\r\n       SELECT 0 ;\r\nELSE \r\n   SELECT CAST(value as int) + CAST(value_in_use as int) \r\n   FROM sys.configurations\r\n   WHERE name = \'\'remote admin connections\'\'\r\n\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'remote admin connections\'','Remote Admin Connections option is disabled','Remote Admin Connections option  is not disabled. Disable this option','pass',NULL,NULL,'2026-02-11 17:55:59'),(1691,202602,53,19,'AA_SqlServer_150_Disable database trustworthy status','major','CONFIG','The TRUSTWORTHY database setting restricts access to database resources by databases that contain assemblies with the EXTERNAL_ACCESS or UNSAFE permission settings and modules that use impersonation of accounts assigned elevated privileges.  Unless all assemblies and code for the database have been reviewed, especially in the case where databases have been detached and attached between server instances, leaving the TRUSTWORTHY status to off can help reduce threats from malicious assemblies or modules.','','SELECT count(name)\r\nFROM sys.databases\r\nWHERE is_trustworthy_on = 1\r\nAND name != \'msdb\';','== 0','','SELECT name\r\nFROM sys.databases\r\nWHERE is_trustworthy_on = 1\r\nAND name != \'msdb\';','database trustworthy status is disabled','database trustworthy status is not disabled. Disable this option','pass',NULL,NULL,'2026-02-11 17:55:59'),(1692,202602,53,20,'Checkpoint başarıyla oluşturuldu.','major','CONFIG','This test checks if SQL Server Instance is not advertised by the SQL Server Browser service. To maintain a higher level of protection for database instances, we recommend that SQL Server Instance be hidden when it is not required. Please note that this test does not include Clustered Instances as turning off this feature may cause issues with the Clustered environment.\r\n\r\n','','execute sp_executesql N\'\r\n\r\nDECLARE @getValue INT\r\n\r\nEXEC master.sys.xp_instance_regread\r\n@rootkey = N\'\'HKEY_LOCAL_MACHINE\'\',\r\n@key = N\'\'SOFTWARE\\Microsoft\\Microsoft SQL Server\\MSSQLServer\\SuperSocketNetLib\'\',\r\n@value_name = N\'\'HideInstance\'\',\r\n@value = @getValue OUTPUT\r\n\r\nSELECT isnull(@getvalue,0)\'','==1','','execute sp_executesql N\'\r\n\r\nDECLARE @getValue INT\r\n\r\nEXEC master.sys.xp_instance_regread\r\n@rootkey = N\'\'HKEY_LOCAL_MACHINE\'\',\r\n@key = N\'\'SOFTWARE\\Microsoft\\Microsoft SQL Server\\MSSQLServer\\SuperSocketNetLib\'\',\r\n@value_name = N\'\'HideInstance\'\',\r\n@value = @getValue OUTPUT\r\n\r\nSELECT isnull(@getvalue,0)\'','SQL Server Instance is  hidden.\r\n','SQL Server Instance is not hidden. Hide the instance','fail','\n-\n0',NULL,'2026-02-11 17:55:59'),(1693,202602,53,21,'AA_SqlServer_160_Hide SQL Server Instance','major','CONFIG','This test checks if SQL Server Instance is not advertised by the SQL Server Browser service. To maintain a higher level of protection for database instances, we recommend that SQL Server Instance be hidden when it is not required. Please note that this test does not include Clustered Instances as turning off this feature may cause issues with the Clustered environment.\r\n\r\n','','execute sp_executesql N\'\r\n\r\nDECLARE @getValue INT\r\n\r\nEXEC master.sys.xp_instance_regread\r\n@rootkey = N\'\'HKEY_LOCAL_MACHINE\'\',\r\n@key = N\'\'SOFTWARE\\Microsoft\\Microsoft SQL Server\\MSSQLServer\\SuperSocketNetLib\'\',\r\n@value_name = N\'\'HideInstance\'\',\r\n@value = @getValue OUTPUT\r\n\r\nSELECT isnull(@getvalue,0)\'','==1','','execute sp_executesql N\'\r\n\r\nDECLARE @getValue INT\r\n\r\nEXEC master.sys.xp_instance_regread\r\n@rootkey = N\'\'HKEY_LOCAL_MACHINE\'\',\r\n@key = N\'\'SOFTWARE\\Microsoft\\Microsoft SQL Server\\MSSQLServer\\SuperSocketNetLib\'\',\r\n@value_name = N\'\'HideInstance\'\',\r\n@value = @getValue OUTPUT\r\n\r\nSELECT isnull(@getvalue,0)\'','SQL Server Instance is  hidden.','SQL Server Instance is not hidden. Hide the instance','fail','\n-\n0',NULL,'2026-02-11 17:55:59'),(1694,202602,53,38,'AA_SqlServer_300_No Access To General Extended procedures','major','PRIV','This test checks for the existence of, and user permissions on, extended stored procedures.  Either these procedures should be completely dropped, or access to them should be strictly limited. xp_cmdshell, xp_enumgroups, xp_grantlogin ,xp_logevent, xp_logininfo,    xp_msver, xp_revokelogin, xp_sprintf, xp_sqlmaint, xp_sscanf\r\n','','SELECT \r\ncount(*) \r\nFROM \r\n  [master].sys.system_objects o \r\n  JOIN [master].sys.database_permissions p ON o.object_id = p.major_id \r\n  JOIN [master].sys.database_principals u ON p.grantee_principal_id = u.principal_id \r\nWHERE \r\n    o.name in ( \r\n	\'xp_cmdshell\', \r\n	\'xp_enumgroups\', \r\n    \'xp_grantlogin\' ,\r\n	\'xp_logevent\', \r\n	\'xp_logininfo\', \r\n    \'xp_msver\', \r\n	\'xp_revokelogin\', \r\n	\'xp_sprintf\', \r\n    \'xp_sqlmaint\', \r\n	\'xp_sscanf\' )\r\n  AND p.type = \'EX\' ','== 0','','SELECT \r\n  \'Principal : \'+u.name  COLLATE DATABASE_DEFAULT +\r\n  \' Extended Procedure Name : \'+o.name COLLATE DATABASE_DEFAULT +\r\n  \' Type : \'+ u.type_desc COLLATE DATABASE_DEFAULT \r\nFROM \r\n  [master].sys.system_objects o \r\n  JOIN [master].sys.database_permissions p ON o.object_id = p.major_id \r\n  JOIN [master].sys.database_principals u ON p.grantee_principal_id = u.principal_id \r\nWHERE \r\n    o.name in ( \r\n	\'xp_cmdshell\', \r\n	\'xp_enumgroups\', \r\n    \'xp_grantlogin\' ,\r\n	\'xp_logevent\', \r\n	\'xp_logininfo\', \r\n    \'xp_msver\', \r\n	\'xp_revokelogin\', \r\n	\'xp_sprintf\', \r\n    \'xp_sqlmaint\', \r\n	\'xp_sscanf\' )\r\n  AND p.type = \'EX\' ','There are no permissions on general extended stored procedures\r\n','There are some persmissions permissions on general extended stored procedures.\r\n','fail','\n----------------------------------------------------------------------------------\n\'Principal : public Extended Procedure Name : xp_msver Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_sscanf Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_revokelogin Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_grantlogin Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_sprintf Type : DATABASE_ROLE\'',NULL,'2026-02-11 17:55:59'),(1695,202602,53,39,'AA_SqlServer_310_No Access to OLE Automation procedures','major','CONFIG','This test checks for the existence of,and user permissions on OLE automation extended stored procedures.  Either these procedures should be completely dropped, or access to them should be strictly limited.      \r\n','','SELECT CAST(value as int) +\r\n       CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Ole Automation Procedures\'   \r\n','== 0','','SELECT CAST(value as int) +\r\n       CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Ole Automation Procedures\'\r\n  \r\n','OLE Automation procedures  option is disabled\r\n','OLE Automation procedures  option  is not disabled. Disable this option\r\n','pass',NULL,NULL,'2026-02-11 17:55:59'),(1696,202602,53,17,'AA_SqlServer_130_Disable Ole Automation Procedures option','minor','CONFIG','This test checks if Ole Automation Procedures option is disabled. Ole Automation Procedures option allows SQL Server users to execute functions external to SQL Server. Enabling this option will increase the attack surface of SQL Server and allow users to execute functions in the security context of SQL Server. We recommend that the Ole Automation Procedures option to be disabled when it is not document as a requirement.\r\n\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Ole Automation Procedures\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \'Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'Ole Automation Procedures\'',' Ole Automation Procedures option is disabled',' Ole Automation Procedures option  is not disabled. Disable this option','pass',NULL,NULL,'2026-02-11 17:55:59'),(1697,202602,53,18,'AA_SqlServer_140_Disable Scan for Startup Procedures option','minor','CONFIG','This test checks if scan for startup procedures is disabled. This feature causes SQL Server to scan for and automatically run all stored procedures that are set to execute upon service startup. If there are no user-defined stored procedures set to execute when SQL server starts, we recommend this feature to be disabled.\r\n\r\n','','SELECT CAST(value as int) +\r\n       CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'scan for startup procs\'','== 0','','SELECT name + \' value : \'+cast( value as varchar ) +\r\n\' value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'scan for startup procs\'','Scan for Startup Procedures  option is disabled','Scan for Startup Procedures  option  is not disabled. Disable this option','pass',NULL,NULL,'2026-02-11 17:55:59'),(1698,202602,53,9,'AA_SqlServer_040_Rename the sa Login Account','major','ACCOUNT','The \'sa\' account is a well-known account.  Well-known account names provide an easier target for attack.  Renaming the sa account helps reduce the risk of an attack to this built-in account.','','SELECT count(*)\r\nFROM sys.server_principals\r\nWHERE sid = 0x01 and name=\'sa\'','== 0','','SELECT name\r\nFROM sys.server_principals\r\nWHERE sid = 0x01','sa Login Account is renamed','sa Login Account is not renamed. Rename this account','fail','name\n----\n\'sa\'',NULL,'2026-02-11 17:55:59'),(1699,202602,54,24,'AA_SqlServer_190_Public server role permision','critical','PRIV','public is a special fixed server role containing all logins. Unlike other fixed server roles,\r\npermissions can be changed for the public role. In keeping with the principle of least\r\nprivileges, the public server role should not be used to grant permissions at the server\r\nscope as these would be inherited by all users.\r\n\r\nEvery SQL Server login belongs to the public role and cannot be removed from this role.\r\nTherefore, any permissions granted to this role will be available to all logins unless they\r\nhave been explicitly denied to specific logins or user-defined server roles.','','Select \r\n  count (permission_name) \r\nfrom \r\n  sys.server_permissions \r\nwhere \r\n  SUSER_NAME(grantee_principal_id) = \'public\' \r\n  and permission_name not in (\'VIEW ANY DATABASE\', \'CONNECT\')\r\n','== 0','','Select \r\n  permission_name \r\nfrom \r\n  sys.server_permissions \r\nwhere \r\n  SUSER_NAME(grantee_principal_id) = \'public\' \r\n  and permission_name not in (\'VIEW ANY DATABASE\', \'CONNECT\')\r\n\r\n','No server permissions are granted to public.','Some server permissions are granted to public.','pass',NULL,NULL,'2026-02-11 17:55:59'),(1700,202602,54,5,'AA_SqlServer_010_Supported SQL Server version','critical','PATCH','This test checks whether your current SQL Server version is a vendor-supported version.  Microsoft does not provide security fixes or software updates to unsupported software versions','','SELECT cast(ISNULL(SERVERPROPERTY(\'ProductMajorVersion\'),0) as int)   ','>=11','','SELECT \'Product Major version \' +  cast(ISNULL(SERVERPROPERTY(\'ProductMajorVersion\'),\'Null\' ) as  char ) ','The version of the database is acceptable.','The version of the database is not acceptable. The database version should SQL Sever 2012 or upper.','pass',NULL,NULL,'2026-02-11 17:55:59'),(1701,202602,54,6,'AA_SqlServer_020_Disable the sa Login Account','critical','ACCOUNT','This test checks if the \'sa\' Login Account is disabled. The sa account is a widely known and often widely used SQL Server account with sysadmin privileges. Enforcing this control reduces the probability of an attacker executing brute force attacks against a well-known principal.','','SELECT  count(*)\r\nFROM sys.server_principals\r\nWHERE sid = 0x01\r\nAND is_disabled = 0','== 0','','SELECT \'sa user name : \'+ name+\' is disabled : \' +  cast( is_disabled as char)\r\nFROM sys.server_principals\r\nWHERE sid = 0x01\r\n','sa Login Account is disabled','Disable sa login account','fail','\n----------------------------------------------------------------\n\'sa user name : sa is disabled : 0                             \'',NULL,'2026-02-11 17:55:59'),(1702,202602,54,7,'AA_SqlServer_025_sa Change password','critical','ACCOUNT','This test checks that sa password change . The sa password should be changed in every two days','','select datediff( day,  modify_date , getdate() ) FROM sys.server_principals\r\nWHERE sid = 0x01  ','< 3','','select datediff( day,  modify_date , getdate() ) FROM sys.server_principals\r\nWHERE sid = 0x01 ','sa password was changed in two days','','fail','\n--\n28',NULL,'2026-02-11 17:55:59'),(1703,202602,54,8,'AA_SqlServer_030_Ensure no Login exists with sa Login Account','critical','ACCOUNT','The \'sa\' account is a well-known account.  Well-known account names provide an easier target for attack. The lack of the sa account helps reduce the risk of an attack to this built-in account.','','SELECT count(*)\r\nFROM sys.server_principals\r\nWHERE name = \'sa\'','== 0','','SELECT name\r\nFROM sys.server_principals\r\nWHERE name = \'sa\'','There is no the sa account in the database.','There is the sa Login account in the database.Drop this user or rename et.','fail','name\n----\n\'sa\'',NULL,'2026-02-11 17:55:59'),(1704,202602,54,25,'AA_SqlServer_200_Fixed Server Role members for users','critical','PRIV','This test checks fixed server roles for analyst , developers and real persons. Fixed server roles could not be assigned to real person users ( Developer, Analyst users ) . Only Admin can use fixed server role.\r\n','','Select     count(*)   from      sys.server_role_members    where      (       suser_name(member_principal_id) like \'ODEABANK%.%\'    	AND       suser_name(member_principal_id) not like \'%admin%\'         AND       suser_name(member_principal_id) not like \'%t.coban%\'     )      OR (       suser_name(member_principal_id) like \'ODEABANK\\Cyberark_Intertech%\'     )      \r\n','== 0','','Select      suser_name(role_principal_id) + \'   \' + suser_name(member_principal_id)    from      sys.server_role_members    where      (       suser_name(member_principal_id) like \'ODEABANK%.%\'    	AND       suser_name(member_principal_id) not like \'%admin%\'         AND       suser_name(member_principal_id) not like \'%t.coban%\'     )      OR (       suser_name(member_principal_id) like \'ODEABANK\\Cyberark_Intertech%\'     )          \r\n','Fixed Server role usage is correct.\r\n','Fixed Server role usage is not correct.\r\n','pass',NULL,NULL,'2026-02-11 17:55:59'),(1705,202602,54,26,'AA_SqlServer_210_Database Role members for users','critical','PRIV','This test checks database role members for analyst and real person users. Database roles  except  db_datareader could not be assigned to real person users ( Developer, Analyst users ) .\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      EXEC sp_MSforeachdb \'\' USE [?]    INSERT INTO #TEMP   SELECT \'\'\'\'DB Name : \'\'\'\'+Cast (DB_NAME() as varchar)+\'\'\'\' Role Name : \'\'\'\'+USER_NAME(role_principal_id)  +\'\'\'\' User Name \'\'\'\'+  USER_NAME(member_principal_id)    from  sys.database_role_members   	Where   	(   	( USER_NAME(member_principal_id)  like \'\'\'\'%ODEABANK%.%\'\'\'\'  and   USER_NAME(member_principal_id)  not like \'\'\'\'%admin%\'\'\'\' )     	OR   	  (suser_name(member_principal_id) like \'\'\'\'%ODEABANK%Cyberark%\'\'\'\')       )    	AND   	DB_NAME() <> \'\'\'\'master\'\'\'\' and   	USER_NAME(role_principal_id) not in (\'\'\'\'db_datareader\'\'\'\',\'\'\'\'db_viewdefinition\'\'\'\',\'\'\'\'db_denydatareader\'\'\'\',\'\'\'\'db_deny_maas\'\'\'\');   \'\'      Select  count(*)  from #TEMP;   \'\r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      EXEC sp_MSforeachdb \'\' USE [?]    INSERT INTO #TEMP   SELECT \'\'\'\'DB Name : \'\'\'\'+Cast (DB_NAME() as varchar)+\'\'\'\' Role Name : \'\'\'\'+USER_NAME(role_principal_id)  +\'\'\'\' User Name \'\'\'\'+  USER_NAME(member_principal_id)    from  sys.database_role_members   	Where   (   	( USER_NAME(member_principal_id)  like \'\'\'\'%ODEABANK%.%\'\'\'\'  and   USER_NAME(member_principal_id)  not like \'\'\'\'%admin%\'\'\'\' )     	OR   	(suser_name(member_principal_id) like \'\'\'\'%ODEABANK%Cyberark%\'\'\'\')   )    	AND   	DB_NAME() <> \'\'\'\'master\'\'\'\' and   	USER_NAME(role_principal_id) not in  (\'\'\'\'db_datareader\'\'\'\',\'\'\'\'db_viewdefinition\'\'\'\',\'\'\'\'db_denydatareader\'\'\'\',\'\'\'\'db_deny_maas\'\'\'\');   \'\'      Select  * from #TEMP;   \'\r\n','Database role member usage for users  is correct\r\n','Database role member usage for users  is not correct\r\n','pass',NULL,NULL,'2026-02-11 17:56:00'),(1706,202602,54,27,'AA_SqlServer_220_2_Public Database Permissions','critical','PRIV','This test checks database permisions for public . Public is a special role and permissions should not be granted to public role.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP ( row varchar(500));          exec sp_MSforeachdb \'\'   USE [?]   iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'public\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND OBJECT_NAME(MAJOR_iD) NOT LiKE (\'\'\'\'%fn_cdc_get_net_changes_application_data%\'\'\'\')   AND NOT (OBJECT_SCHEMA_NAME(MAJOR_iD) = \'\'\'\'cdc\'\'\'\' and PERMiSSiON_NAME=\'\'\'\'SELECT\'\'\'\')   AND NOT (PERMiSSiON_NAME IN (\'\'\'\'REFERENCES\'\'\'\',\'\'\'\'SEND\'\'\'\',   \'\'\'\'VIEW ANY COLUMN ENCRYPTION KEY DEFINITION\'\'\'\',   \'\'\'\'VIEW ANY COLUMN MASTER KEY DEFINITION\'\'\'\' ) and OBJECT_SCHEMA_NAME(MAJOR_iD) IS NULL)   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select count(*) from #TEMP;   \'\r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP ( row varchar(500));          exec sp_MSforeachdb \'\'   USE [?]   iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'public\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND OBJECT_NAME(MAJOR_iD) NOT LiKE (\'\'\'\'%fn_cdc_get_net_changes_application_data%\'\'\'\')   AND NOT (OBJECT_SCHEMA_NAME(MAJOR_iD) = \'\'\'\'cdc\'\'\'\' and PERMiSSiON_NAME=\'\'\'\'SELECT\'\'\'\')   AND NOT (PERMiSSiON_NAME IN (\'\'\'\'REFERENCES\'\'\'\',\'\'\'\'SEND\'\'\'\',   \'\'\'\'VIEW ANY COLUMN ENCRYPTION KEY DEFINITION\'\'\'\',   \'\'\'\'VIEW ANY COLUMN MASTER KEY DEFINITION\'\'\'\' ) and OBJECT_SCHEMA_NAME(MAJOR_iD) IS NULL)   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select * from #TEMP;   \'','There are no permissions which are assigned to public.\r\n','There are some persmissions which are assigned to public\r\n','pass',NULL,NULL,'2026-02-11 17:56:00'),(1707,202602,54,28,'AA_SqlServer_220_Public Database Permissions','critical','PRIV','This test checks database permisions for public . Public is a special role and permissions should not be granted to public role.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      exec sp_msforeachdb \'\'   USE [?]     iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'public\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND OBJECT_NAME(MAJOR_iD) NOT LiKE (\'\'\'\'%fn_cdc_get_net_changes_application_data%\'\'\'\')   AND NOT (OBJECT_SCHEMA_NAME(MAJOR_iD) = \'\'\'\'cdc\'\'\'\' and PERMiSSiON_NAME=\'\'\'\'SELECT\'\'\'\')   AND NOT (PERMiSSiON_NAME IN (\'\'\'\'REFERENCES\'\'\'\',\'\'\'\'SEND\'\'\'\',   \'\'\'\'VIEW ANY COLUMN ENCRYPTION KEY DEFINITION\'\'\'\',   \'\'\'\'VIEW ANY COLUMN MASTER KEY DEFINITION\'\'\'\' ) and OBJECT_SCHEMA_NAME(MAJOR_iD) IS NULL)   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select count(*) from #TEMP;   \' \r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      exec sp_msforeachdb \'\'   USE [?]     iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'public\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND OBJECT_NAME(MAJOR_iD) NOT LiKE (\'\'\'\'%fn_cdc_get_net_changes_application_data%\'\'\'\')   AND NOT (OBJECT_SCHEMA_NAME(MAJOR_iD) = \'\'\'\'cdc\'\'\'\' and PERMiSSiON_NAME=\'\'\'\'SELECT\'\'\'\')   AND NOT (PERMiSSiON_NAME IN (\'\'\'\'REFERENCES\'\'\'\',\'\'\'\'SEND\'\'\'\',   \'\'\'\'VIEW ANY COLUMN ENCRYPTION KEY DEFINITION\'\'\'\',   \'\'\'\'VIEW ANY COLUMN MASTER KEY DEFINITION\'\'\'\' ) and OBJECT_SCHEMA_NAME(MAJOR_iD) IS NULL)   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select * from #TEMP;   \' \r\n','There are no permissions which are assigned to public.\r\n','There are some persmissions which are assigned to public\r\n','pass',NULL,NULL,'2026-02-11 17:56:00'),(1708,202602,54,29,'AA_SqlServer_230_Real person users','critical','ACCOUNT','All logins to the database should be made with AD groups, real person users should  not be connected database directly\r\n','','Select      count(*)   from      sys.server_principals    where      name like \'ODEABANK%.%\'      and is_disabled = 0   \r\n','== 0','','Select      name     from      sys.server_principals    where      name like \'ODEABANK%.%\'      and is_disabled = 0;\r\n','Real person users are not found in the logins\r\n','Some real person users are found in the logins\r\n','pass',NULL,NULL,'2026-02-11 17:56:00'),(1709,202602,54,30,'AA_SqlServer_240_2_guest Database Permissions','critical','ACCOUNT','This test checks database permisions for guest . guest is a special user and permissions should not be granted to guest user.\r\n','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP ( row varchar(500));\r\n\r\nexec sp_MSforeachdb \'\'\r\nUSE [?]\r\niNSERT iNTO #TEMP\r\nSELECT\r\n\'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +\r\n\'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +\r\n\'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +\r\n\'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )\r\nFROM\r\nsys.database_permissions\r\nWHERE\r\nUSER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'guest\'\'\'\' )\r\nAND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'\r\nAND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')\r\nAND STATE_DESC=\'\'\'\'GRANT\'\'\'\'\r\n;\r\n\'\'\r\nselect count(*) from #TEMP;\r\n\'','== 0','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP ( row varchar(500));\r\n\r\nexec sp_MSforeachdb \'\'\r\nUSE [?]\r\niNSERT iNTO #TEMP\r\nSELECT\r\n\'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +\r\n\'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +\r\n\'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +\r\n\'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )\r\nFROM\r\nsys.database_permissions\r\nWHERE\r\nUSER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'guest\'\'\'\' )\r\nAND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'\r\nAND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')\r\nAND STATE_DESC=\'\'\'\'GRANT\'\'\'\'\r\n;\r\n\'\'\r\nselect * from #TEMP;\r\n\'','There are no permissions which are assigned to guest.\r\n','There are some persmissions which are assigned to guest\r\n','pass',NULL,NULL,'2026-02-11 17:56:00'),(1710,202602,54,31,'AA_SqlServer_240_guest Database Permissions','critical','PRIV','This test checks database permisions for guest . guest is a special user and permissions should not be granted to guest user.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      exec sp_msforeachdb \'\'   USE [?]     iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'guest\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select count(*) from #TEMP;   \' \r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      exec sp_msforeachdb \'\'   USE [?]     iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'guest\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select  *  from #TEMP;   \' \r\n','There are no permissions which are assigned to guest.\r\n','There are some persmissions which are assigned to guest\r\n','pass',NULL,NULL,'2026-02-11 17:56:00'),(1711,202602,54,32,'AA_SqlServer_250_Database Role members for guest','critical','PRIV','This test checks database role members for guest  user. Database roles  could not be assigned to guest role.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      EXEC sp_MSforeachdb \'\' USE [?]    INSERT INTO #TEMP   SELECT \'\'\'\'DB Name : \'\'\'\'+Cast (DB_NAME() as varchar)+\'\'\'\' Role Name : \'\'\'\'+USER_NAME(role_principal_id)  +\'\'\'\' User Name \'\'\'\'+  USER_NAME(member_principal_id)    from  sys.database_role_members   	Where     USER_NAME(member_principal_id)  = \'\'\'\'guest\'\'\'\'     ;   \'\'      Select count(*)  from #TEMP;   \'\r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      EXEC sp_MSforeachdb \'\' USE [?]    INSERT INTO #TEMP   SELECT \'\'\'\'DB Name : \'\'\'\'+Cast (DB_NAME() as varchar)+\'\'\'\' Role Name : \'\'\'\'+USER_NAME(role_principal_id)  +\'\'\'\' User Name \'\'\'\'+  USER_NAME(member_principal_id)    from  sys.database_role_members   	Where     USER_NAME(member_principal_id)  = \'\'\'\'guest\'\'\'\'     ;   \'\'      Select  *  from #TEMP;   \'\r\n','Database role member usage for guest user  is correct\r\n','Database role member usage for guest user  is not correct\r\n','pass',NULL,NULL,'2026-02-11 17:56:00'),(1712,202602,54,33,'AA_SqlServer_260_SQL Logins with Null Password','critical','ACCOUNT','This test checks sql logins with null password. SQL Logins should not have null passwords.\r\n','','SELECT      count(name)   from      sys.sql_logins    WHERE      PWDCOMPARE(\'\', password_hash)= 1\r\n','== 0','','SELECT      name    from      sys.sql_logins    WHERE      PWDCOMPARE(\'\', password_hash)= 1   \r\n','There are no sql logins with null paswords\r\n','There are some sql logins with null passwords.\r\n','pass',NULL,NULL,'2026-02-11 17:56:00'),(1713,202602,54,34,'AA_SqlServer_270_SQL Logins with username and passwords are equal','critical','ACCOUNT','This test checks sql login password which are egual to username. Username and password must be different for SQL logins.\r\n','','SELECT      count(name)   from      sys.sql_logins    WHERE      PWDCOMPARE(name,password_hash)=1 \r\n','== 0','','SELECT      name    from      sys.sql_logins    WHERE      PWDCOMPARE(name,password_hash)=1    \r\n','There is no SQL login name which is equal to password.\r\n','There are some sql logins whose passwords are egual to usernames.\r\n','pass',NULL,NULL,'2026-02-11 17:56:00'),(1714,202602,54,35,'AA_SqlServer_280_No Sample Databases','critical','CONFIG','This test checks whether the sample databases created optionally on installation are present.  These sample databases contain many default permissions, and can be used as an entry point to your systems. \r\n','','select      count(name)    from      sys.databases    where      name in (       \'AdventureWorks\', \'AdventureWorksDW\',        \'Northwind\', \'Pubs\'     )   \r\n','== 0','','select      name    from      sys.databases    where      name in (       \'AdventureWorks\', \'AdventureWorksDW\',        \'Northwind\', \'Pubs\'     )   \r\n','There are no sample databases in the server\r\n','There are some sample databases in the server\r\n','pass',NULL,NULL,'2026-02-11 17:56:00'),(1715,202602,54,43,'AA_SqlServer_350_User Password Policy Is Checked','critical','ACCOUNT','This test checks that CHECK_POLICY is enabled for all users.  Enabling CHECK_POLICY ensures that Windows passwords policies are enforced.','','select count(*) from sys.sql_logins  \r\nwhere \r\nis_policy_checked=0 and\r\nname not like \'##%\'','== 0','','select name from sys.sql_logins  \r\nwhere \r\nis_policy_checked=0 and\r\nname not like \'##%\'','CHECK_POLICY is enabled for all users','CHECK_POLICY is not enabled for all users','pass',NULL,NULL,'2026-02-11 17:56:00'),(1716,202602,54,44,'AA_SqlServer_360_CHECK_EXPIRATION Is Checked','critical','ACCOUNT','This test checks that CHECK_EXPIRATION is enabled for all users.  Passwords that have been in use for long periods of time are likely to become known to unauthorized users.\r\n','','select count(*) from sys.sql_logins     where    is_expiration_checked=0 and   name not like \'##%\'\r\n','== 0','','select name from sys.sql_logins     where    is_expiration_checked=0 and   name not like \'##%\'\r\n','CHECK_EXPIRATION is enabled for all users\r\n','CHECK_EXPIRATION is not enabled for all users\r\n','fail','name\n----\n\'sa\'',NULL,'2026-02-11 17:56:00'),(1717,202602,54,22,'AA_SqlServer_170_Windows Authentication','major','AUTH','This test checks that the authentication mode is set to Windows authentication only.  Windows provides a more robust authentication mechanism than SQL Server authentication.','',' SELECT cast( SERVERPROPERTY(\'IsIntegratedSecurityOnly\') as int) ','==1','','SELECT cast( SERVERPROPERTY(\'IsIntegratedSecurityOnly\') as varchar)','The authentication mode is set to Windows authentication only. ','The authentication mode is not set to Windows authentication only.','fail','\n---\n\'0\'',NULL,'2026-02-11 17:56:00'),(1718,202602,54,23,'AA_SqlServer_180_No Guest User Accounts','major','ACCOUNT','This test checks for the existence of guest user accounts with CONNECT permission in database other than master, msdb and tempdb.  This test also exclude databases that are flagged as distributor. If the GUEST user exists and a specific login has not been granted to a database, a login will be mapped to GUEST. The presence of the GUEST user allows all logins to access the database.\r\n','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP  ( row int);\r\n\r\nEXEC sp_MSforeachdb \'\' USE [?]\r\n	INSERT INTO #TEMP\r\n	SELECT count(*) \r\n	FROM sys.database_permissions\r\n	WHERE [grantee_principal_id] = DATABASE_PRINCIPAL_ID(\'\'\'\'guest\'\'\'\')\r\n	AND [state_desc] LIKE \'\'\'\'GRANT%\'\'\'\'\r\n	AND [permission_name] = \'\'\'\'CONNECT\'\'\'\'\r\n	AND DB_NAME() NOT IN (\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'msdb\'\'\'\') ;\r\n\'\'\r\n\r\nSelect sum(row) from #TEMP;\r\ndrop table #TEMP;\r\n\'','== 0','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP  ( row varchar(500));\r\n\r\nEXEC sp_MSforeachdb \'\' USE  [?] \r\n	INSERT INTO #TEMP\r\n	SELECT \'\'\'\' DB NAME : \'\'\'\' + Cast (DB_NAME() as varchar) + \'\'\'\' guest user has CONNECT permission \'\'\'\'\r\n	FROM sys.database_permissions\r\n	WHERE [grantee_principal_id] = DATABASE_PRINCIPAL_ID(\'\'\'\'guest\'\'\'\')\r\n	AND [state_desc] LIKE \'\'\'\'GRANT%\'\'\'\'\r\n	AND [permission_name] = \'\'\'\'CONNECT\'\'\'\'\r\n	AND DB_NAME() NOT IN (\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'msdb\'\'\'\') ;\r\n\'\'\r\n\r\nSelect * from #TEMP;\r\ndrop table #TEMP;\r\n\'','There is no guest user with CONNECT permission. ','There are   guest users with CONNECT permission. Remove these users','pass',NULL,NULL,'2026-02-11 17:56:00'),(1719,202602,54,36,'AA_SqlServer_290_2_No Permissions with GRANT Option','major','PRIV','This test checks database permisions  with grant option. No permission with grant option should be defined in the database.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP ( row varchar(500));      exec sp_MSforeachdb \'\'   USE [?]   iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   STATE_DESC like \'\'\'\'%WITH_GRANT%\'\'\'\'   ;   \'\'   select count(*) from #TEMP;   \'\r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP ( row varchar(500));      exec sp_MSforeachdb \'\'   USE [?]   iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   STATE_DESC like \'\'\'\'%WITH_GRANT%\'\'\'\'   ;   \'\'   select * from #TEMP;   \'\r\n','There are no permissions with grant option.\r\n','There are some persmissions  with grant option.\r\n','pass',NULL,NULL,'2026-02-11 17:56:00'),(1720,202602,54,37,'AA_SqlServer_290_No Permissions with GRANT Option','major','PRIV','','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP  ( row varchar(500));\r\n\r\nexec sp_msforeachdb \'\'\r\nUSE [?]  \r\niNSERT iNTO #TEMP\r\nSELECT\r\n\'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +\r\n\'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +\r\n\'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +\r\n\'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )\r\nFROM\r\nsys.database_permissions\r\nWHERE\r\nSTATE_DESC like \'\'\'\'%WITH_GRANT%\'\'\'\'\r\n;\r\n\'\'\r\nselect  count(*)  from #TEMP;\r\n\' ','== 0','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP  ( row varchar(500));\r\n\r\nexec sp_msforeachdb \'\'\r\nUSE [?]  \r\niNSERT iNTO #TEMP\r\nSELECT\r\n\'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +\r\n\'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +\r\n\'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +\r\n\'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )\r\nFROM\r\nsys.database_permissions\r\nWHERE\r\nSTATE_DESC like \'\'\'\'%WITH_GRANT%\'\'\'\'\r\n;\r\n\'\'\r\nselect * from #TEMP;\r\n\' ','There are no permissions with grant option.\r\n','There are some persmissions  with grant option.\r\n','pass',NULL,NULL,'2026-02-11 17:56:00'),(1721,202602,54,40,'AA_SqlServer_320_No Access to Registry Access Extended procedures','major','PRIV','This test checks for the existence of, and user permissions on, registry access extended stored procedures.  Either these procedures should be completely dropped, or access to them should be strictly limited. xp_reg%,xp_instance_reg%\r\n','','SELECT \r\ncount(*) \r\nFROM \r\n  [master].sys.system_objects o \r\n  JOIN [master].sys.database_permissions p ON o.object_id = p.major_id \r\n  JOIN [master].sys.database_principals u ON p.grantee_principal_id = u.principal_id \r\nWHERE \r\n( o.name LIKE \'xp_reg%\' OR o.name LIKE \'xp_instance_reg%\')\r\n  AND p.type = \'EX\' ','== 0','','SELECT \r\n  \'Principal : \'+u.name  COLLATE DATABASE_DEFAULT +\r\n  \' Extended Procedure Name : \'+o.name COLLATE DATABASE_DEFAULT +\r\n  \' Type : \'+ u.type_desc COLLATE DATABASE_DEFAULT \r\nFROM \r\n  [master].sys.system_objects o \r\n  JOIN [master].sys.database_permissions p ON o.object_id = p.major_id \r\n  JOIN [master].sys.database_principals u ON p.grantee_principal_id = u.principal_id \r\nWHERE \r\n( o.name LIKE \'xp_reg%\' OR o.name LIKE \'xp_instance_reg%\')\r\n  AND p.type = \'EX\' ','There are no permissions on registry access extended stored procedures\r\n','There are some persmissions permissions on registry access extended stored procedures\r\n','fail','\n---------------------------------------------------------------------------------------\n\'Principal : public Extended Procedure Name : xp_instance_regread Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_regread Type : DATABASE_ROLE\'',NULL,'2026-02-11 17:56:00'),(1722,202602,54,41,'AA_SqlServer_330_Revoke public login from SQL Server agent proxy account','major','PRIV','The public database role contains every user in the msdb database. SQL Agent proxies   define a security context in which a job step can run.Granting access to SQL Agent proxies for the public role would allow all users to utilize the proxy which may have high privileges. This would likely break the principle of least   privileges.\r\n','','SELECT count(*)\r\nFROM msdb.dbo.sysproxylogin spl\r\nJOIN sys.database_principals dp\r\nON dp.sid = spl.sid\r\nJOIN msdb.dbo.sysproxies sp\r\nON sp.proxy_id = spl.proxy_id\r\nWHERE principal_id = USER_ID(\'public\')','== 0','','SELECT \'proxyname : \'+CAST(sp.name  as varchar)\r\nFROM msdb.dbo.sysproxylogin spl\r\nJOIN sys.database_principals dp\r\nON dp.sid = spl.sid\r\nJOIN msdb.dbo.sysproxies sp\r\nON sp.proxy_id = spl.proxy_id\r\nWHERE principal_id = USER_ID(\'public\')','There are no public permissions on SQL Server agent proxy account\r\n','There are some public permissions on SQL Server agent proxy account\r\n','pass',NULL,NULL,'2026-02-11 17:56:00'),(1723,202602,54,42,'AA_SqlServer_340_No Individual User Access To syscomment and sp_helptext','minor','PRIV','This test checks for grants on SYSCOMMENTS.TEXT.  Such grants allow any user to read the text comments associated with a database object, making the text publicly viewable.\r\n','','SELECT count(*)\r\nFROM msdb.dbo.sysproxylogin spl\r\nJOIN sys.database_principals dp\r\nON dp.sid = spl.sid\r\nJOIN msdb.dbo.sysproxies sp\r\nON sp.proxy_id = spl.proxy_id\r\nWHERE principal_id = USER_ID(\'public\')\r\n','== 0','','SELECT count(*)\r\nFROM msdb.dbo.sysproxylogin spl\r\nJOIN sys.database_principals dp\r\nON dp.sid = spl.sid\r\nJOIN msdb.dbo.sysproxies sp\r\nON sp.proxy_id = spl.proxy_id\r\nWHERE principal_id = USER_ID(\'public\')','There are no public permissions on SQL Server agent proxy account','There are some public permissions on SQL Server agent proxy account','pass',NULL,NULL,'2026-02-11 17:56:00'),(1724,202602,54,10,'AA_SqlServer_050_Disable Ad hoc distributed queries option','major','CONFIG','Adhoc queries allow undefined access to remote database sources.  Access to untrusted databases could result in execution of malicious applications and/or a compromise of local data confidentiality and integrity. The DBA will configure the database to disable access from the database to objects stored externally to the database on the local host unless mission and/or operationally required and documented.\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Ad Hoc Distributed Queries\'','== 0','','SELECT name + \' Value : \'+ cast( value as varchar ) + \' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'Ad Hoc Distributed Queries\'','Ad Hoc Distributed Queries is disabled','Ad Hoc Distributed Queries is not disabled. Disable this option','pass',NULL,NULL,'2026-02-11 17:56:00'),(1725,202602,54,11,'AA_SqlServer_060_Disable CLR option','major','CONFIG','The clr_enabled parameter configures SQL Server to allow or disallow use of Command Language Runtime objects.  CLR objects is managed code that integrates with the .NET Framework.  This is a more secure method than external stored procedures, although it still contains some risk.  Where no external application execution requirements are required, disallowing use of any improves the overall security posture of the database.\r\n\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'clr enabled\'','== 0','','SELECT name + \' Value : \'+ cast( value as varchar ) + \' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'clr enabled\'','CLR option is disabled','CLR option is not disabled. Disable this option','pass',NULL,NULL,'2026-02-11 17:56:00'),(1726,202602,54,12,'AA_SqlServer_070_Disable Cross db ownership chaining option','major','CONFIG','Cross database ownership chaining allows permissions to objects to be assigned by users other than the Information Owner.  This allows access to objects that are not authorized directly by the Information Owner based on job functions defined by the owner.  Unauthorized access may lead to a compromise of data integrity or confidentiality. The DBA will ensure database privileges are assigned via roles and not directly assigned to database accounts. Privileges may be assigned directly to application owner accounts where the DBMS does not otherwise support access via roles.\r\n\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'cross db ownership chaining\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'cross db ownership chaining\'','Cross db ownership chaining  option is disabled','Cross db ownership chaining option  is not disabled. Disable this option','pass',NULL,NULL,'2026-02-11 17:56:00'),(1727,202602,54,13,'AA_SqlServer_080_Disable Database Mail XPs option','major','CONFIG','SQL Mail accepts incoming database commands via email. This can introduce malicious codes or viruses into the SQL server environment.','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Database Mail XPs\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \'Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'Database Mail XPs\'','Database Mail XPs option is disabled','Database Mail XPs option  is not disabled. Disable this option','pass',NULL,NULL,'2026-02-11 17:56:00'),(1728,202602,54,14,'AA_SqlServer_100_Disable xp_cmdshell Server Configuration option','major','CONFIG','The xp_cmdshell extended stored procedures allows execution of host executables outside the controls of database access permissions.  This access may be exploited by malicious users who have compromised the integrity of the SQL Server database process to control the host operating system to perpetrate additional malicious activity. The DBA should disable the use of external procedures by the database unless it is mission critical or operationally required','','SELECT CAST(value as int) +\r\n       CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'xp_cmdshell\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) +\r\n\' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'xp_cmdshell\'','xp_cmdshell Server Configuration option is disabled','xp_cmdshell Server Configuration option is not disabled. This option must be disabled','pass',NULL,NULL,'2026-02-11 17:56:00'),(1729,202602,54,15,'AA_SqlServer_110_Disable Remote Access option','major','CONFIG','The remote access option controls the execution of local stored procedures on remote\r\nservers or remote stored procedures on local server.Functionality can be abused to launch a Denial-of-Service (DoS) attack on remote servers\r\nby off-loading query processing to a target.\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'remote access\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \' Value in use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'remote access\'','Remote Access option is disabled','Remote Access option  is not disabled. Disable this option','fail','\n------------------------------------------\n\'remote access Value : 1 Value in use : 1\'',NULL,'2026-02-11 17:56:00'),(1730,202602,54,16,'AA_SqlServer_120_Disable Remote Admin Connections option','major','CONFIG','The remote admin connections option controls whether a client application on a remote\r\ncomputer can use the Dedicated Administrator Connection (DAC).The Dedicated Administrator Connection (DAC) lets an administrator access a running\r\nserver to execute diagnostic functions or Transact-SQL statements, or to troubleshoot\r\nproblems on the server, even when the server is locked or running in an abnormal state\r\nand not responding to a SQL Server Database Engine connection. In a cluster scenario, the\r\nadministrator may not actually be logged on to the same node that is currently hosting the\r\nSQL Server instance and thus is considered \"remote\". Therefore, this setting should usually\r\nbe enabled (1) for SQL Server failover clusters; otherwise it should be disabled (0) which is\r\nthe default.\r\n','','execute sp_executesql N\'\r\n\r\nDECLARE @x int;\r\n\r\nSELECT @x=isnull(CAST(value as int) + CAST(value_in_use as int),100)\r\nFROM sys.configurations\r\nWHERE name = \'\'remote admin connections\'\'\r\n\r\nIF @x = 100\r\n       SELECT 0 ;\r\nELSE \r\n   SELECT CAST(value as int) + CAST(value_in_use as int) \r\n   FROM sys.configurations\r\n   WHERE name = \'\'remote admin connections\'\'\r\n\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'remote admin connections\'','Remote Admin Connections option is disabled','Remote Admin Connections option  is not disabled. Disable this option','pass',NULL,NULL,'2026-02-11 17:56:00'),(1731,202602,54,19,'AA_SqlServer_150_Disable database trustworthy status','major','CONFIG','The TRUSTWORTHY database setting restricts access to database resources by databases that contain assemblies with the EXTERNAL_ACCESS or UNSAFE permission settings and modules that use impersonation of accounts assigned elevated privileges.  Unless all assemblies and code for the database have been reviewed, especially in the case where databases have been detached and attached between server instances, leaving the TRUSTWORTHY status to off can help reduce threats from malicious assemblies or modules.','','SELECT count(name)\r\nFROM sys.databases\r\nWHERE is_trustworthy_on = 1\r\nAND name != \'msdb\';','== 0','','SELECT name\r\nFROM sys.databases\r\nWHERE is_trustworthy_on = 1\r\nAND name != \'msdb\';','database trustworthy status is disabled','database trustworthy status is not disabled. Disable this option','pass',NULL,NULL,'2026-02-11 17:56:00'),(1732,202602,54,20,'Checkpoint başarıyla oluşturuldu.','major','CONFIG','This test checks if SQL Server Instance is not advertised by the SQL Server Browser service. To maintain a higher level of protection for database instances, we recommend that SQL Server Instance be hidden when it is not required. Please note that this test does not include Clustered Instances as turning off this feature may cause issues with the Clustered environment.\r\n\r\n','','execute sp_executesql N\'\r\n\r\nDECLARE @getValue INT\r\n\r\nEXEC master.sys.xp_instance_regread\r\n@rootkey = N\'\'HKEY_LOCAL_MACHINE\'\',\r\n@key = N\'\'SOFTWARE\\Microsoft\\Microsoft SQL Server\\MSSQLServer\\SuperSocketNetLib\'\',\r\n@value_name = N\'\'HideInstance\'\',\r\n@value = @getValue OUTPUT\r\n\r\nSELECT isnull(@getvalue,0)\'','==1','','execute sp_executesql N\'\r\n\r\nDECLARE @getValue INT\r\n\r\nEXEC master.sys.xp_instance_regread\r\n@rootkey = N\'\'HKEY_LOCAL_MACHINE\'\',\r\n@key = N\'\'SOFTWARE\\Microsoft\\Microsoft SQL Server\\MSSQLServer\\SuperSocketNetLib\'\',\r\n@value_name = N\'\'HideInstance\'\',\r\n@value = @getValue OUTPUT\r\n\r\nSELECT isnull(@getvalue,0)\'','SQL Server Instance is  hidden.\r\n','SQL Server Instance is not hidden. Hide the instance','fail','\n-\n0',NULL,'2026-02-11 17:56:00'),(1733,202602,54,21,'AA_SqlServer_160_Hide SQL Server Instance','major','CONFIG','This test checks if SQL Server Instance is not advertised by the SQL Server Browser service. To maintain a higher level of protection for database instances, we recommend that SQL Server Instance be hidden when it is not required. Please note that this test does not include Clustered Instances as turning off this feature may cause issues with the Clustered environment.\r\n\r\n','','execute sp_executesql N\'\r\n\r\nDECLARE @getValue INT\r\n\r\nEXEC master.sys.xp_instance_regread\r\n@rootkey = N\'\'HKEY_LOCAL_MACHINE\'\',\r\n@key = N\'\'SOFTWARE\\Microsoft\\Microsoft SQL Server\\MSSQLServer\\SuperSocketNetLib\'\',\r\n@value_name = N\'\'HideInstance\'\',\r\n@value = @getValue OUTPUT\r\n\r\nSELECT isnull(@getvalue,0)\'','==1','','execute sp_executesql N\'\r\n\r\nDECLARE @getValue INT\r\n\r\nEXEC master.sys.xp_instance_regread\r\n@rootkey = N\'\'HKEY_LOCAL_MACHINE\'\',\r\n@key = N\'\'SOFTWARE\\Microsoft\\Microsoft SQL Server\\MSSQLServer\\SuperSocketNetLib\'\',\r\n@value_name = N\'\'HideInstance\'\',\r\n@value = @getValue OUTPUT\r\n\r\nSELECT isnull(@getvalue,0)\'','SQL Server Instance is  hidden.','SQL Server Instance is not hidden. Hide the instance','fail','\n-\n0',NULL,'2026-02-11 17:56:00'),(1734,202602,54,38,'AA_SqlServer_300_No Access To General Extended procedures','major','PRIV','This test checks for the existence of, and user permissions on, extended stored procedures.  Either these procedures should be completely dropped, or access to them should be strictly limited. xp_cmdshell, xp_enumgroups, xp_grantlogin ,xp_logevent, xp_logininfo,    xp_msver, xp_revokelogin, xp_sprintf, xp_sqlmaint, xp_sscanf\r\n','','SELECT \r\ncount(*) \r\nFROM \r\n  [master].sys.system_objects o \r\n  JOIN [master].sys.database_permissions p ON o.object_id = p.major_id \r\n  JOIN [master].sys.database_principals u ON p.grantee_principal_id = u.principal_id \r\nWHERE \r\n    o.name in ( \r\n	\'xp_cmdshell\', \r\n	\'xp_enumgroups\', \r\n    \'xp_grantlogin\' ,\r\n	\'xp_logevent\', \r\n	\'xp_logininfo\', \r\n    \'xp_msver\', \r\n	\'xp_revokelogin\', \r\n	\'xp_sprintf\', \r\n    \'xp_sqlmaint\', \r\n	\'xp_sscanf\' )\r\n  AND p.type = \'EX\' ','== 0','','SELECT \r\n  \'Principal : \'+u.name  COLLATE DATABASE_DEFAULT +\r\n  \' Extended Procedure Name : \'+o.name COLLATE DATABASE_DEFAULT +\r\n  \' Type : \'+ u.type_desc COLLATE DATABASE_DEFAULT \r\nFROM \r\n  [master].sys.system_objects o \r\n  JOIN [master].sys.database_permissions p ON o.object_id = p.major_id \r\n  JOIN [master].sys.database_principals u ON p.grantee_principal_id = u.principal_id \r\nWHERE \r\n    o.name in ( \r\n	\'xp_cmdshell\', \r\n	\'xp_enumgroups\', \r\n    \'xp_grantlogin\' ,\r\n	\'xp_logevent\', \r\n	\'xp_logininfo\', \r\n    \'xp_msver\', \r\n	\'xp_revokelogin\', \r\n	\'xp_sprintf\', \r\n    \'xp_sqlmaint\', \r\n	\'xp_sscanf\' )\r\n  AND p.type = \'EX\' ','There are no permissions on general extended stored procedures\r\n','There are some persmissions permissions on general extended stored procedures.\r\n','fail','\n----------------------------------------------------------------------------------\n\'Principal : public Extended Procedure Name : xp_msver Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_sscanf Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_revokelogin Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_grantlogin Type : DATABASE_ROLE\'\n\'Principal : public Extended Procedure Name : xp_sprintf Type : DATABASE_ROLE\'',NULL,'2026-02-11 17:56:00'),(1735,202602,54,39,'AA_SqlServer_310_No Access to OLE Automation procedures','major','CONFIG','This test checks for the existence of,and user permissions on OLE automation extended stored procedures.  Either these procedures should be completely dropped, or access to them should be strictly limited.      \r\n','','SELECT CAST(value as int) +\r\n       CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Ole Automation Procedures\'   \r\n','== 0','','SELECT CAST(value as int) +\r\n       CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Ole Automation Procedures\'\r\n  \r\n','OLE Automation procedures  option is disabled\r\n','OLE Automation procedures  option  is not disabled. Disable this option\r\n','pass',NULL,NULL,'2026-02-11 17:56:00'),(1736,202602,54,17,'AA_SqlServer_130_Disable Ole Automation Procedures option','minor','CONFIG','This test checks if Ole Automation Procedures option is disabled. Ole Automation Procedures option allows SQL Server users to execute functions external to SQL Server. Enabling this option will increase the attack surface of SQL Server and allow users to execute functions in the security context of SQL Server. We recommend that the Ole Automation Procedures option to be disabled when it is not document as a requirement.\r\n\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Ole Automation Procedures\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \'Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'Ole Automation Procedures\'',' Ole Automation Procedures option is disabled',' Ole Automation Procedures option  is not disabled. Disable this option','pass',NULL,NULL,'2026-02-11 17:56:00'),(1737,202602,54,18,'AA_SqlServer_140_Disable Scan for Startup Procedures option','minor','CONFIG','This test checks if scan for startup procedures is disabled. This feature causes SQL Server to scan for and automatically run all stored procedures that are set to execute upon service startup. If there are no user-defined stored procedures set to execute when SQL server starts, we recommend this feature to be disabled.\r\n\r\n','','SELECT CAST(value as int) +\r\n       CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'scan for startup procs\'','== 0','','SELECT name + \' value : \'+cast( value as varchar ) +\r\n\' value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'scan for startup procs\'','Scan for Startup Procedures  option is disabled','Scan for Startup Procedures  option  is not disabled. Disable this option','pass',NULL,NULL,'2026-02-11 17:56:00'),(1738,202602,54,9,'AA_SqlServer_040_Rename the sa Login Account','major','ACCOUNT','The \'sa\' account is a well-known account.  Well-known account names provide an easier target for attack.  Renaming the sa account helps reduce the risk of an attack to this built-in account.','','SELECT count(*)\r\nFROM sys.server_principals\r\nWHERE sid = 0x01 and name=\'sa\'','== 0','','SELECT name\r\nFROM sys.server_principals\r\nWHERE sid = 0x01','sa Login Account is renamed','sa Login Account is not renamed. Rename this account','fail','name\n----\n\'sa\'',NULL,'2026-02-11 17:56:00'),(1739,202602,55,24,'AA_SqlServer_190_Public server role permision','critical','PRIV','public is a special fixed server role containing all logins. Unlike other fixed server roles,\r\npermissions can be changed for the public role. In keeping with the principle of least\r\nprivileges, the public server role should not be used to grant permissions at the server\r\nscope as these would be inherited by all users.\r\n\r\nEvery SQL Server login belongs to the public role and cannot be removed from this role.\r\nTherefore, any permissions granted to this role will be available to all logins unless they\r\nhave been explicitly denied to specific logins or user-defined server roles.','','Select \r\n  count (permission_name) \r\nfrom \r\n  sys.server_permissions \r\nwhere \r\n  SUSER_NAME(grantee_principal_id) = \'public\' \r\n  and permission_name not in (\'VIEW ANY DATABASE\', \'CONNECT\')\r\n','== 0','','Select \r\n  permission_name \r\nfrom \r\n  sys.server_permissions \r\nwhere \r\n  SUSER_NAME(grantee_principal_id) = \'public\' \r\n  and permission_name not in (\'VIEW ANY DATABASE\', \'CONNECT\')\r\n\r\n','No server permissions are granted to public.','Some server permissions are granted to public.','pass',NULL,NULL,'2026-02-11 17:59:14'),(1740,202602,55,5,'AA_SqlServer_010_Supported SQL Server version','critical','PATCH','This test checks whether your current SQL Server version is a vendor-supported version.  Microsoft does not provide security fixes or software updates to unsupported software versions','','SELECT cast(ISNULL(SERVERPROPERTY(\'ProductMajorVersion\'),0) as int)   ','>=11','','SELECT \'Product Major version \' +  cast(ISNULL(SERVERPROPERTY(\'ProductMajorVersion\'),\'Null\' ) as  char ) ','The version of the database is acceptable.','The version of the database is not acceptable. The database version should SQL Sever 2012 or upper.','pass',NULL,NULL,'2026-02-11 17:59:14'),(1741,202602,55,6,'AA_SqlServer_020_Disable the sa Login Account','critical','ACCOUNT','This test checks if the \'sa\' Login Account is disabled. The sa account is a widely known and often widely used SQL Server account with sysadmin privileges. Enforcing this control reduces the probability of an attacker executing brute force attacks against a well-known principal.','','SELECT  count(*)\r\nFROM sys.server_principals\r\nWHERE sid = 0x01\r\nAND is_disabled = 0','== 0','','SELECT \'sa user name : \'+ name+\' is disabled : \' +  cast( is_disabled as char)\r\nFROM sys.server_principals\r\nWHERE sid = 0x01\r\n','sa Login Account is disabled','Disable sa login account','fail','\n----------------------------------------------------------------\n\'sa user name : sa is disabled : 0                             \'',NULL,'2026-02-11 17:59:14'),(1742,202602,55,7,'AA_SqlServer_025_sa Change password','critical','ACCOUNT','This test checks that sa password change . The sa password should be changed in every two days','','select datediff( day,  modify_date , getdate() ) FROM sys.server_principals\r\nWHERE sid = 0x01  ','< 3','','select datediff( day,  modify_date , getdate() ) FROM sys.server_principals\r\nWHERE sid = 0x01 ','sa password was changed in two days','','fail','\n--\n28',NULL,'2026-02-11 17:59:14'),(1743,202602,55,8,'AA_SqlServer_030_Ensure no Login exists with sa Login Account','critical','ACCOUNT','The \'sa\' account is a well-known account.  Well-known account names provide an easier target for attack. The lack of the sa account helps reduce the risk of an attack to this built-in account.','','SELECT count(*)\r\nFROM sys.server_principals\r\nWHERE name = \'sa\'','== 0','','SELECT name\r\nFROM sys.server_principals\r\nWHERE name = \'sa\'','There is no the sa account in the database.','There is the sa Login account in the database.Drop this user or rename et.','fail','name\n----\n\'sa\'',NULL,'2026-02-11 17:59:14'),(1744,202602,55,25,'AA_SqlServer_200_Fixed Server Role members for users','critical','PRIV','This test checks fixed server roles for analyst , developers and real persons. Fixed server roles could not be assigned to real person users ( Developer, Analyst users ) . Only Admin can use fixed server role.\r\n','','Select     count(*)   from      sys.server_role_members    where      (       suser_name(member_principal_id) like \'ODEABANK%.%\'    	AND       suser_name(member_principal_id) not like \'%admin%\'         AND       suser_name(member_principal_id) not like \'%t.coban%\'     )      OR (       suser_name(member_principal_id) like \'ODEABANK\\Cyberark_Intertech%\'     )      \r\n','== 0','','Select      suser_name(role_principal_id) + \'   \' + suser_name(member_principal_id)    from      sys.server_role_members    where      (       suser_name(member_principal_id) like \'ODEABANK%.%\'    	AND       suser_name(member_principal_id) not like \'%admin%\'         AND       suser_name(member_principal_id) not like \'%t.coban%\'     )      OR (       suser_name(member_principal_id) like \'ODEABANK\\Cyberark_Intertech%\'     )          \r\n','Fixed Server role usage is correct.\r\n','Fixed Server role usage is not correct.\r\n','pass',NULL,NULL,'2026-02-11 17:59:14'),(1745,202602,55,26,'AA_SqlServer_210_Database Role members for users','critical','PRIV','This test checks database role members for analyst and real person users. Database roles  except  db_datareader could not be assigned to real person users ( Developer, Analyst users ) .\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      EXEC sp_MSforeachdb \'\' USE [?]    INSERT INTO #TEMP   SELECT \'\'\'\'DB Name : \'\'\'\'+Cast (DB_NAME() as varchar)+\'\'\'\' Role Name : \'\'\'\'+USER_NAME(role_principal_id)  +\'\'\'\' User Name \'\'\'\'+  USER_NAME(member_principal_id)    from  sys.database_role_members   	Where   	(   	( USER_NAME(member_principal_id)  like \'\'\'\'%ODEABANK%.%\'\'\'\'  and   USER_NAME(member_principal_id)  not like \'\'\'\'%admin%\'\'\'\' )     	OR   	  (suser_name(member_principal_id) like \'\'\'\'%ODEABANK%Cyberark%\'\'\'\')       )    	AND   	DB_NAME() <> \'\'\'\'master\'\'\'\' and   	USER_NAME(role_principal_id) not in (\'\'\'\'db_datareader\'\'\'\',\'\'\'\'db_viewdefinition\'\'\'\',\'\'\'\'db_denydatareader\'\'\'\',\'\'\'\'db_deny_maas\'\'\'\');   \'\'      Select  count(*)  from #TEMP;   \'\r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      EXEC sp_MSforeachdb \'\' USE [?]    INSERT INTO #TEMP   SELECT \'\'\'\'DB Name : \'\'\'\'+Cast (DB_NAME() as varchar)+\'\'\'\' Role Name : \'\'\'\'+USER_NAME(role_principal_id)  +\'\'\'\' User Name \'\'\'\'+  USER_NAME(member_principal_id)    from  sys.database_role_members   	Where   (   	( USER_NAME(member_principal_id)  like \'\'\'\'%ODEABANK%.%\'\'\'\'  and   USER_NAME(member_principal_id)  not like \'\'\'\'%admin%\'\'\'\' )     	OR   	(suser_name(member_principal_id) like \'\'\'\'%ODEABANK%Cyberark%\'\'\'\')   )    	AND   	DB_NAME() <> \'\'\'\'master\'\'\'\' and   	USER_NAME(role_principal_id) not in  (\'\'\'\'db_datareader\'\'\'\',\'\'\'\'db_viewdefinition\'\'\'\',\'\'\'\'db_denydatareader\'\'\'\',\'\'\'\'db_deny_maas\'\'\'\');   \'\'      Select  * from #TEMP;   \'\r\n','Database role member usage for users  is correct\r\n','Database role member usage for users  is not correct\r\n','pass',NULL,NULL,'2026-02-11 17:59:14'),(1746,202602,55,27,'AA_SqlServer_220_2_Public Database Permissions','critical','PRIV','This test checks database permisions for public . Public is a special role and permissions should not be granted to public role.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP ( row varchar(500));          exec sp_MSforeachdb \'\'   USE