  `dimension_type` enum('all','severity','category') NOT NULL,
  `dimension_value` enum('all','caution','minor','major','critical','AUTH','PRIV','CONFIG','PATCH','AUDIT','ENCRYPT','ACCOUNT','OTHER') NOT NULL,
