DROP TABLE IF EXISTS `assessment_runs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `assessment_runs` (
  `run_id` bigint NOT NULL AUTO_INCREMENT,
  `run_month` int NOT NULL,
  `assessment_id` int NOT NULL,
  `asset_impact` enum('very_low','low','medium','high','critical') NOT NULL,
  `assessment_name` varchar(255) NOT NULL,
  `db_type` enum('oracle','mssql') NOT NULL,
  `status` enum('incomplete','success','error','unreachable') NOT NULL,
  `datasource_id` int NOT NULL,
  `datasource_name` varchar(150) NOT NULL,
  `benchmark_id` int unsigned NOT NULL,
  `benchmark_name` varchar(255) NOT NULL,
  `total_count` int DEFAULT NULL,
  `success_count` int DEFAULT NULL,
  `fail_count` int DEFAULT NULL,
  `error_count` int DEFAULT NULL,
  `success_pct` decimal(5,2) DEFAULT NULL,
  `risk` decimal(5,2) DEFAULT NULL,
  `asset_adjusted_risk` decimal(6,2) DEFAULT NULL,
  `asset_adjusted_risk_level` enum('low','medium','high','critical') DEFAULT NULL,
  `risk_level` enum('low','medium','high','critical') DEFAULT NULL,
  `executed_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `domain_run_id` bigint DEFAULT NULL,
  PRIMARY KEY (`run_id`,`run_month`),
  KEY `idx_runs_month` (`run_month`),
  KEY `idx_runs_assessment` (`assessment_id`)
) ENGINE=InnoDB AUTO_INCREMENT=76 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci
/*!50100 PARTITION BY RANGE (`run_month`)
