DROP TABLE IF EXISTS `assessments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `assessments` (
  `assessment_id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `datasource_id` int NOT NULL,
  `datasource_name` varchar(150) NOT NULL,
  `benchmark_id` int unsigned NOT NULL,
  `benchmark_name` varchar(255) NOT NULL,
  `db_type` enum('oracle','mssql') DEFAULT NULL,
  `asset_impact` enum('very_low','low','medium','high','critical') NOT NULL DEFAULT 'medium',
  `status` enum('active','inactive') NOT NULL DEFAULT 'active',
  `notes` text,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `domain_id` int DEFAULT NULL,
  `last_run_id` int DEFAULT NULL,
  PRIMARY KEY (`assessment_id`),
  KEY `idx_assessments_datasource` (`datasource_id`),
  KEY `idx_assessments_benchmark` (`benchmark_id`),
  KEY `idx_assessments_status` (`status`),
  KEY `idx_assessments_domain_id` (`domain_id`),
  KEY `idx_assessments_last_run_id` (`last_run_id`),
  CONSTRAINT `fk_assessments_benchmark` FOREIGN KEY (`benchmark_id`) REFERENCES `benchmarks` (`benchmark_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_assessments_datasource` FOREIGN KEY (`datasource_id`) REFERENCES `datasources` (`ds_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_assessments_domain` FOREIGN KEY (`domain_id`) REFERENCES `domains` (`domain_id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=15 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
