/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_bc_dbtype_match_ins` BEFORE INSERT ON `benchmark_checkpoints` FOR EACH ROW BEGIN
  DECLARE b_db_type VARCHAR(20);
  DECLARE c_db_type VARCHAR(20);

  SELECT db_type
    INTO b_db_type
    FROM benchmarks
   WHERE benchmark_id = NEW.benchmark_id;

  SELECT DB_Type
    INTO c_db_type
    FROM checkpoints
   WHERE Id = NEW.checkpoint_id;

  IF b_db_type IS NULL
     OR c_db_type IS NULL
     OR b_db_type <> c_db_type THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT =
      'db_type mismatch: benchmarks.db_type must equal checkpoints.DB_Type';
  END IF;
END */;;
DELIMITER ;
