/*!40000 ALTER TABLE `checkpoints` DISABLE KEYS */;
INSERT INTO `checkpoints` VALUES (4,'MSSQL-Chekpoint','mssql','major','OTHER','Test SQL','IF OBJECT_ID(\'tempdb..#tmp_failtest\') IS NOT NULL DROP TABLE #tmp_failtest;\r\nCREATE TABLE #tmp_failtest(id INT);\r\nINSERT INTO #tmp_failtest VALUES (1);\r\n','SELECT COUNT(*) FROM #tmp_failtest','> 0','IF OBJECT_ID(\'tempdb..#public_perms\') IS NOT NULL DROP TABLE #public_perms;\r\nCREATE TABLE #public_perms (\r\n    principal_name NVARCHAR(200),\r\n    permission_name NVARCHAR(200),\r\n    state_desc NVARCHAR(200),\r\n    class_desc NVARCHAR(200)\r\n);\r\n\r\nINSERT INTO #public_perms\r\nSELECT \r\n    sp.name,\r\n    perm.permission_name,\r\n    perm.state_desc,\r\n    perm.class_desc\r\nFROM sys.server_permissions AS perm\r\nJOIN sys.server_principals AS sp\r\n     ON perm.grantee_principal_id = sp.principal_id\r\nWHERE sp.name = \'public\';','SELECT * FROM #public_perms;','','','','2025-11-26 08:20:17','2025-12-18 08:48:09'),(5,'AA_SqlServer_010_Supported SQL Server version','mssql','critical','PATCH','This test checks whether your current SQL Server version is a vendor-supported version.  Microsoft does not provide security fixes or software updates to unsupported software versions','','SELECT cast(ISNULL(SERVERPROPERTY(\'ProductMajorVersion\'),0) as int)   ','>=11','','SELECT \'Product Major version \' +  cast(ISNULL(SERVERPROPERTY(\'ProductMajorVersion\'),\'Null\' ) as  char ) ','The version of the database is acceptable.','The version of the database is not acceptable. The database version should SQL Sever 2012 or upper.','','2025-11-26 11:42:02','2026-01-11 16:33:37'),(6,'AA_SqlServer_020_Disable the sa Login Account','mssql','critical','ACCOUNT','This test checks if the \'sa\' Login Account is disabled. The sa account is a widely known and often widely used SQL Server account with sysadmin privileges. Enforcing this control reduces the probability of an attacker executing brute force attacks against a well-known principal.','','SELECT  count(*)\r\nFROM sys.server_principals\r\nWHERE sid = 0x01\r\nAND is_disabled = 0','== 0','','SELECT \'sa user name : \'+ name+\' is disabled : \' +  cast( is_disabled as char)\r\nFROM sys.server_principals\r\nWHERE sid = 0x01\r\n','sa Login Account is disabled','Disable sa login account','','2025-11-26 11:47:15','2026-01-15 18:03:15'),(7,'AA_SqlServer_025_sa Change password','mssql','critical','ACCOUNT','This test checks that sa password change . The sa password should be changed in every two days','','select datediff( day,  modify_date , getdate() ) FROM sys.server_principals\r\nWHERE sid = 0x01  ','< 3','','select datediff( day,  modify_date , getdate() ) FROM sys.server_principals\r\nWHERE sid = 0x01 ','sa password was changed in two days','','','2025-11-26 13:50:56','2026-01-11 16:33:37'),(8,'AA_SqlServer_030_Ensure no Login exists with sa Login Account','mssql','critical','ACCOUNT','The \'sa\' account is a well-known account.  Well-known account names provide an easier target for attack. The lack of the sa account helps reduce the risk of an attack to this built-in account.','','SELECT count(*)\r\nFROM sys.server_principals\r\nWHERE name = \'sa\'','== 0','','SELECT name\r\nFROM sys.server_principals\r\nWHERE name = \'sa\'','There is no the sa account in the database.','There is the sa Login account in the database.Drop this user or rename et.','','2025-11-26 13:53:49','2026-01-11 16:33:37'),(9,'AA_SqlServer_040_Rename the sa Login Account','mssql','major','ACCOUNT','The \'sa\' account is a well-known account.  Well-known account names provide an easier target for attack.  Renaming the sa account helps reduce the risk of an attack to this built-in account.','','SELECT count(*)\r\nFROM sys.server_principals\r\nWHERE sid = 0x01 and name=\'sa\'','== 0','','SELECT name\r\nFROM sys.server_principals\r\nWHERE sid = 0x01','sa Login Account is renamed','sa Login Account is not renamed. Rename this account','','2025-11-26 13:55:49','2026-01-11 16:33:37'),(10,'AA_SqlServer_050_Disable Ad hoc distributed queries option','mssql','minor','CONFIG','Adhoc queries allow undefined access to remote database sources.  Access to untrusted databases could result in execution of malicious applications and/or a compromise of local data confidentiality and integrity. The DBA will configure the database to disable access from the database to objects stored externally to the database on the local host unless mission and/or operationally required and documented.\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Ad Hoc Distributed Queries\'','== 0','','SELECT name + \' Value : \'+ cast( value as varchar ) + \' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'Ad Hoc Distributed Queries\'','Ad Hoc Distributed Queries is disabled','Ad Hoc Distributed Queries is not disabled. Disable this option','','2025-11-26 13:58:11','2026-02-19 12:48:14'),(11,'AA_SqlServer_060_Disable CLR option','mssql','minor','CONFIG','The clr_enabled parameter configures SQL Server to allow or disallow use of Command Language Runtime objects.  CLR objects is managed code that integrates with the .NET Framework.  This is a more secure method than external stored procedures, although it still contains some risk.  Where no external application execution requirements are required, disallowing use of any improves the overall security posture of the database.\r\n\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'clr enabled\'','== 0','','SELECT name + \' Value : \'+ cast( value as varchar ) + \' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'clr enabled\'','CLR option is disabled','CLR option is not disabled. Disable this option','','2025-11-26 13:59:56','2026-02-19 12:48:31'),(12,'AA_SqlServer_070_Disable Cross db ownership chaining option','mssql','major','CONFIG','Cross database ownership chaining allows permissions to objects to be assigned by users other than the Information Owner.  This allows access to objects that are not authorized directly by the Information Owner based on job functions defined by the owner.  Unauthorized access may lead to a compromise of data integrity or confidentiality. The DBA will ensure database privileges are assigned via roles and not directly assigned to database accounts. Privileges may be assigned directly to application owner accounts where the DBMS does not otherwise support access via roles.\r\n\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'cross db ownership chaining\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'cross db ownership chaining\'','Cross db ownership chaining  option is disabled','Cross db ownership chaining option  is not disabled. Disable this option','','2025-11-26 17:24:03','2026-01-11 16:33:37'),(13,'AA_SqlServer_080_Disable Database Mail XPs option','mssql','major','CONFIG','SQL Mail accepts incoming database commands via email. This can introduce malicious codes or viruses into the SQL server environment.','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Database Mail XPs\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \'Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'Database Mail XPs\'','Database Mail XPs option is disabled','Database Mail XPs option  is not disabled. Disable this option','','2025-11-26 17:26:17','2026-01-11 16:33:37'),(14,'AA_SqlServer_100_Disable xp_cmdshell Server Configuration option','mssql','major','CONFIG','The xp_cmdshell extended stored procedures allows execution of host executables outside the controls of database access permissions.  This access may be exploited by malicious users who have compromised the integrity of the SQL Server database process to control the host operating system to perpetrate additional malicious activity. The DBA should disable the use of external procedures by the database unless it is mission critical or operationally required','','SELECT CAST(value as int) +\r\n       CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'xp_cmdshell\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) +\r\n\' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'xp_cmdshell\'','xp_cmdshell Server Configuration option is disabled','xp_cmdshell Server Configuration option is not disabled. This option must be disabled','','2025-11-26 17:28:21','2026-01-11 16:33:37'),(15,'AA_SqlServer_110_Disable Remote Access option','mssql','major','CONFIG','The remote access option controls the execution of local stored procedures on remote\r\nservers or remote stored procedures on local server.Functionality can be abused to launch a Denial-of-Service (DoS) attack on remote servers\r\nby off-loading query processing to a target.\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'remote access\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \' Value in use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'remote access\'','Remote Access option is disabled','Remote Access option  is not disabled. Disable this option','','2025-11-26 17:29:55','2026-01-11 16:33:37'),(16,'AA_SqlServer_120_Disable Remote Admin Connections option','mssql','major','CONFIG','The remote admin connections option controls whether a client application on a remote\r\ncomputer can use the Dedicated Administrator Connection (DAC).The Dedicated Administrator Connection (DAC) lets an administrator access a running\r\nserver to execute diagnostic functions or Transact-SQL statements, or to troubleshoot\r\nproblems on the server, even when the server is locked or running in an abnormal state\r\nand not responding to a SQL Server Database Engine connection. In a cluster scenario, the\r\nadministrator may not actually be logged on to the same node that is currently hosting the\r\nSQL Server instance and thus is considered \"remote\". Therefore, this setting should usually\r\nbe enabled (1) for SQL Server failover clusters; otherwise it should be disabled (0) which is\r\nthe default.\r\n','','execute sp_executesql N\'\r\n\r\nDECLARE @x int;\r\n\r\nSELECT @x=isnull(CAST(value as int) + CAST(value_in_use as int),100)\r\nFROM sys.configurations\r\nWHERE name = \'\'remote admin connections\'\'\r\n\r\nIF @x = 100\r\n       SELECT 0 ;\r\nELSE \r\n   SELECT CAST(value as int) + CAST(value_in_use as int) \r\n   FROM sys.configurations\r\n   WHERE name = \'\'remote admin connections\'\'\r\n\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \' Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'remote admin connections\'','Remote Admin Connections option is disabled','Remote Admin Connections option  is not disabled. Disable this option','','2025-11-26 17:32:56','2026-01-11 16:33:37'),(17,'AA_SqlServer_130_Disable Ole Automation Procedures option','mssql','minor','CONFIG','This test checks if Ole Automation Procedures option is disabled. Ole Automation Procedures option allows SQL Server users to execute functions external to SQL Server. Enabling this option will increase the attack surface of SQL Server and allow users to execute functions in the security context of SQL Server. We recommend that the Ole Automation Procedures option to be disabled when it is not document as a requirement.\r\n\r\n','','SELECT CAST(value as int) + CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Ole Automation Procedures\'','== 0','','SELECT name + \' Value : \'+cast( value as varchar ) + \'Value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'Ole Automation Procedures\'',' Ole Automation Procedures option is disabled',' Ole Automation Procedures option  is not disabled. Disable this option','','2025-11-26 17:34:54','2026-01-11 16:33:37'),(18,'AA_SqlServer_140_Disable Scan for Startup Procedures option','mssql','minor','CONFIG','This test checks if scan for startup procedures is disabled. This feature causes SQL Server to scan for and automatically run all stored procedures that are set to execute upon service startup. If there are no user-defined stored procedures set to execute when SQL server starts, we recommend this feature to be disabled.\r\n\r\n','','SELECT CAST(value as int) +\r\n       CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'scan for startup procs\'','== 0','','SELECT name + \' value : \'+cast( value as varchar ) +\r\n\' value in Use : \'+cast( value_in_use  as varchar)\r\nFROM sys.configurations\r\nWHERE name = \'scan for startup procs\'','Scan for Startup Procedures  option is disabled','Scan for Startup Procedures  option  is not disabled. Disable this option','','2025-11-26 17:36:20','2026-01-11 16:33:37'),(19,'AA_SqlServer_150_Disable database trustworthy status','mssql','major','CONFIG','The TRUSTWORTHY database setting restricts access to database resources by databases that contain assemblies with the EXTERNAL_ACCESS or UNSAFE permission settings and modules that use impersonation of accounts assigned elevated privileges.  Unless all assemblies and code for the database have been reviewed, especially in the case where databases have been detached and attached between server instances, leaving the TRUSTWORTHY status to off can help reduce threats from malicious assemblies or modules.','','SELECT count(name)\r\nFROM sys.databases\r\nWHERE is_trustworthy_on = 1\r\nAND name != \'msdb\';','== 0','','SELECT name\r\nFROM sys.databases\r\nWHERE is_trustworthy_on = 1\r\nAND name != \'msdb\';','database trustworthy status is disabled','database trustworthy status is not disabled. Disable this option','','2025-11-27 13:03:28','2026-01-11 16:33:37'),(20,'Checkpoint başarıyla oluşturuldu.','mssql','major','CONFIG','This test checks if SQL Server Instance is not advertised by the SQL Server Browser service. To maintain a higher level of protection for database instances, we recommend that SQL Server Instance be hidden when it is not required. Please note that this test does not include Clustered Instances as turning off this feature may cause issues with the Clustered environment.\r\n\r\n','','execute sp_executesql N\'\r\n\r\nDECLARE @getValue INT\r\n\r\nEXEC master.sys.xp_instance_regread\r\n@rootkey = N\'\'HKEY_LOCAL_MACHINE\'\',\r\n@key = N\'\'SOFTWARE\\Microsoft\\Microsoft SQL Server\\MSSQLServer\\SuperSocketNetLib\'\',\r\n@value_name = N\'\'HideInstance\'\',\r\n@value = @getValue OUTPUT\r\n\r\nSELECT isnull(@getvalue,0)\'','==1','','execute sp_executesql N\'\r\n\r\nDECLARE @getValue INT\r\n\r\nEXEC master.sys.xp_instance_regread\r\n@rootkey = N\'\'HKEY_LOCAL_MACHINE\'\',\r\n@key = N\'\'SOFTWARE\\Microsoft\\Microsoft SQL Server\\MSSQLServer\\SuperSocketNetLib\'\',\r\n@value_name = N\'\'HideInstance\'\',\r\n@value = @getValue OUTPUT\r\n\r\nSELECT isnull(@getvalue,0)\'','SQL Server Instance is  hidden.\r\n','SQL Server Instance is not hidden. Hide the instance','','2025-11-27 13:10:53','2026-01-11 16:33:37'),(21,'AA_SqlServer_160_Hide SQL Server Instance','mssql','major','CONFIG','This test checks if SQL Server Instance is not advertised by the SQL Server Browser service. To maintain a higher level of protection for database instances, we recommend that SQL Server Instance be hidden when it is not required. Please note that this test does not include Clustered Instances as turning off this feature may cause issues with the Clustered environment.\r\n\r\n','','execute sp_executesql N\'\r\n\r\nDECLARE @getValue INT\r\n\r\nEXEC master.sys.xp_instance_regread\r\n@rootkey = N\'\'HKEY_LOCAL_MACHINE\'\',\r\n@key = N\'\'SOFTWARE\\Microsoft\\Microsoft SQL Server\\MSSQLServer\\SuperSocketNetLib\'\',\r\n@value_name = N\'\'HideInstance\'\',\r\n@value = @getValue OUTPUT\r\n\r\nSELECT isnull(@getvalue,0)\'','==1','','execute sp_executesql N\'\r\n\r\nDECLARE @getValue INT\r\n\r\nEXEC master.sys.xp_instance_regread\r\n@rootkey = N\'\'HKEY_LOCAL_MACHINE\'\',\r\n@key = N\'\'SOFTWARE\\Microsoft\\Microsoft SQL Server\\MSSQLServer\\SuperSocketNetLib\'\',\r\n@value_name = N\'\'HideInstance\'\',\r\n@value = @getValue OUTPUT\r\n\r\nSELECT isnull(@getvalue,0)\'','SQL Server Instance is  hidden.','SQL Server Instance is not hidden. Hide the instance','','2025-11-27 14:20:51','2026-01-11 16:33:37'),(22,'AA_SqlServer_170_Windows Authentication','mssql','major','AUTH','This test checks that the authentication mode is set to Windows authentication only.  Windows provides a more robust authentication mechanism than SQL Server authentication.','',' SELECT cast( SERVERPROPERTY(\'IsIntegratedSecurityOnly\') as int) ','==1','','SELECT cast( SERVERPROPERTY(\'IsIntegratedSecurityOnly\') as varchar)','The authentication mode is set to Windows authentication only. ','The authentication mode is not set to Windows authentication only.','','2025-11-27 14:24:46','2026-01-11 16:35:17'),(23,'AA_SqlServer_180_No Guest User Accounts','mssql','major','ACCOUNT','This test checks for the existence of guest user accounts with CONNECT permission in database other than master, msdb and tempdb.  This test also exclude databases that are flagged as distributor. If the GUEST user exists and a specific login has not been granted to a database, a login will be mapped to GUEST. The presence of the GUEST user allows all logins to access the database.\r\n','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP  ( row int);\r\n\r\nEXEC sp_MSforeachdb \'\' USE [?]\r\n	INSERT INTO #TEMP\r\n	SELECT count(*) \r\n	FROM sys.database_permissions\r\n	WHERE [grantee_principal_id] = DATABASE_PRINCIPAL_ID(\'\'\'\'guest\'\'\'\')\r\n	AND [state_desc] LIKE \'\'\'\'GRANT%\'\'\'\'\r\n	AND [permission_name] = \'\'\'\'CONNECT\'\'\'\'\r\n	AND DB_NAME() NOT IN (\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'msdb\'\'\'\') ;\r\n\'\'\r\n\r\nSelect sum(row) from #TEMP;\r\ndrop table #TEMP;\r\n\'','== 0','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP  ( row varchar(500));\r\n\r\nEXEC sp_MSforeachdb \'\' USE  [?] \r\n	INSERT INTO #TEMP\r\n	SELECT \'\'\'\' DB NAME : \'\'\'\' + Cast (DB_NAME() as varchar) + \'\'\'\' guest user has CONNECT permission \'\'\'\'\r\n	FROM sys.database_permissions\r\n	WHERE [grantee_principal_id] = DATABASE_PRINCIPAL_ID(\'\'\'\'guest\'\'\'\')\r\n	AND [state_desc] LIKE \'\'\'\'GRANT%\'\'\'\'\r\n	AND [permission_name] = \'\'\'\'CONNECT\'\'\'\'\r\n	AND DB_NAME() NOT IN (\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'msdb\'\'\'\') ;\r\n\'\'\r\n\r\nSelect * from #TEMP;\r\ndrop table #TEMP;\r\n\'','There is no guest user with CONNECT permission. ','There are   guest users with CONNECT permission. Remove these users','','2025-11-27 14:36:44','2026-01-11 16:47:42'),(24,'AA_SqlServer_190_Public server role permision','mssql','critical','PRIV','public is a special fixed server role containing all logins. Unlike other fixed server roles,\r\npermissions can be changed for the public role. In keeping with the principle of least\r\nprivileges, the public server role should not be used to grant permissions at the server\r\nscope as these would be inherited by all users.\r\n\r\nEvery SQL Server login belongs to the public role and cannot be removed from this role.\r\nTherefore, any permissions granted to this role will be available to all logins unless they\r\nhave been explicitly denied to specific logins or user-defined server roles.','','Select \r\n  count (permission_name) \r\nfrom \r\n  sys.server_permissions \r\nwhere \r\n  SUSER_NAME(grantee_principal_id) = \'public\' \r\n  and permission_name not in (\'VIEW ANY DATABASE\', \'CONNECT\')\r\n','== 0','','Select \r\n  permission_name \r\nfrom \r\n  sys.server_permissions \r\nwhere \r\n  SUSER_NAME(grantee_principal_id) = \'public\' \r\n  and permission_name not in (\'VIEW ANY DATABASE\', \'CONNECT\')\r\n\r\n','No server permissions are granted to public.','Some server permissions are granted to public.','','2025-11-27 14:40:39','2026-01-11 16:33:38'),(25,'AA_SqlServer_200_Fixed Server Role members for users','mssql','critical','PRIV','This test checks fixed server roles for analyst , developers and real persons. Fixed server roles could not be assigned to real person users ( Developer, Analyst users ) . Only Admin can use fixed server role.\r\n','','Select     count(*)   from      sys.server_role_members    where      (       suser_name(member_principal_id) like \'ODEABANK%.%\'    	AND       suser_name(member_principal_id) not like \'%admin%\'         AND       suser_name(member_principal_id) not like \'%t.coban%\'     )      OR (       suser_name(member_principal_id) like \'ODEABANK\\Cyberark_Intertech%\'     )      \r\n','== 0','','Select      suser_name(role_principal_id) + \'   \' + suser_name(member_principal_id)    from      sys.server_role_members    where      (       suser_name(member_principal_id) like \'ODEABANK%.%\'    	AND       suser_name(member_principal_id) not like \'%admin%\'         AND       suser_name(member_principal_id) not like \'%t.coban%\'     )      OR (       suser_name(member_principal_id) like \'ODEABANK\\Cyberark_Intertech%\'     )          \r\n','Fixed Server role usage is correct.\r\n','Fixed Server role usage is not correct.\r\n','','2025-11-29 09:00:30','2026-01-11 16:33:38'),(26,'AA_SqlServer_210_Database Role members for users','mssql','critical','PRIV','This test checks database role members for analyst and real person users. Database roles  except  db_datareader could not be assigned to real person users ( Developer, Analyst users ) .\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      EXEC sp_MSforeachdb \'\' USE [?]    INSERT INTO #TEMP   SELECT \'\'\'\'DB Name : \'\'\'\'+Cast (DB_NAME() as varchar)+\'\'\'\' Role Name : \'\'\'\'+USER_NAME(role_principal_id)  +\'\'\'\' User Name \'\'\'\'+  USER_NAME(member_principal_id)    from  sys.database_role_members   	Where   	(   	( USER_NAME(member_principal_id)  like \'\'\'\'%ODEABANK%.%\'\'\'\'  and   USER_NAME(member_principal_id)  not like \'\'\'\'%admin%\'\'\'\' )     	OR   	  (suser_name(member_principal_id) like \'\'\'\'%ODEABANK%Cyberark%\'\'\'\')       )    	AND   	DB_NAME() <> \'\'\'\'master\'\'\'\' and   	USER_NAME(role_principal_id) not in (\'\'\'\'db_datareader\'\'\'\',\'\'\'\'db_viewdefinition\'\'\'\',\'\'\'\'db_denydatareader\'\'\'\',\'\'\'\'db_deny_maas\'\'\'\');   \'\'      Select  count(*)  from #TEMP;   \'\r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP  ( row varchar(500));      EXEC sp_MSforeachdb \'\' USE [?]    INSERT INTO #TEMP   SELECT \'\'\'\'DB Name : \'\'\'\'+Cast (DB_NAME() as varchar)+\'\'\'\' Role Name : \'\'\'\'+USER_NAME(role_principal_id)  +\'\'\'\' User Name \'\'\'\'+  USER_NAME(member_principal_id)    from  sys.database_role_members   	Where   (   	( USER_NAME(member_principal_id)  like \'\'\'\'%ODEABANK%.%\'\'\'\'  and   USER_NAME(member_principal_id)  not like \'\'\'\'%admin%\'\'\'\' )     	OR   	(suser_name(member_principal_id) like \'\'\'\'%ODEABANK%Cyberark%\'\'\'\')   )    	AND   	DB_NAME() <> \'\'\'\'master\'\'\'\' and   	USER_NAME(role_principal_id) not in  (\'\'\'\'db_datareader\'\'\'\',\'\'\'\'db_viewdefinition\'\'\'\',\'\'\'\'db_denydatareader\'\'\'\',\'\'\'\'db_deny_maas\'\'\'\');   \'\'      Select  * from #TEMP;   \'\r\n','Database role member usage for users  is correct\r\n','Database role member usage for users  is not correct\r\n','','2025-11-29 09:03:43','2026-01-11 16:33:38'),(27,'AA_SqlServer_220_2_Public Database Permissions','mssql','critical','PRIV','This test checks database permisions for public . Public is a special role and permissions should not be granted to public role.\r\n','','execute sp_executesql N\'   CREATE TABLE #TEMP ( row varchar(500));          exec sp_MSforeachdb \'\'   USE [?]   iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'public\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\'\'\'\',\'\'\'\'master\'\'\'\',\'\'\'\'tempdb\'\'\'\',\'\'\'\'model\'\'\'\')   AND OBJECT_NAME(MAJOR_iD) NOT LiKE (\'\'\'\'%fn_cdc_get_net_changes_application_data%\'\'\'\')   AND NOT (OBJECT_SCHEMA_NAME(MAJOR_iD) = \'\'\'\'cdc\'\'\'\' and PERMiSSiON_NAME=\'\'\'\'SELECT\'\'\'\')   AND NOT (PERMiSSiON_NAME IN (\'\'\'\'REFERENCES\'\'\'\',\'\'\'\'SEND\'\'\'\',   \'\'\'\'VIEW ANY COLUMN ENCRYPTION KEY DEFINITION\'\'\'\',   \'\'\'\'VIEW ANY COLUMN MASTER KEY DEFINITION\'\'\'\' ) and OBJECT_SCHEMA_NAME(MAJOR_iD) IS NULL)   AND STATE_DESC=\'\'\'\'GRANT\'\'\'\'   ;   \'\'   select count(*) from #TEMP;   \'\r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP ( row varchar(500));          exec sp_MSforeachdb \'\'   USE [?]   iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   USER_NAME(GRANTEE_PRiNCiPAL_iD) iN(\'\'\'\'public\'\'\'\' )   AND Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) <> \'\'\'\'sys\'\'\'\'   AND DB_NAME() NOT iN (\'\'\'\'msdb\