achdb \'\'   USE [?]   iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   STATE_DESC like \'\'\'\'%WITH_GRANT%\'\'\'\'   ;   \'\'   select count(*) from #TEMP;   \'\r\n','== 0','','execute sp_executesql N\'   CREATE TABLE #TEMP ( row varchar(500));      exec sp_MSforeachdb \'\'   USE [?]   iNSERT iNTO #TEMP   SELECT   \'\'\'\' DB Name : \'\'\'\'+ DB_NAME() +   \'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +   \'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +   \'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )   FROM   sys.database_permissions   WHERE   STATE_DESC like \'\'\'\'%WITH_GRANT%\'\'\'\'   ;   \'\'   select * from #TEMP;   \'\r\n','There are no permissions with grant option.\r\n','There are some persmissions  with grant option.\r\n','','2025-12-01 08:56:08','2026-01-11 16:33:38'),(37,'AA_SqlServer_290_No Permissions with GRANT Option','mssql','major','PRIV','','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP  ( row varchar(500));\r\n\r\nexec sp_msforeachdb \'\'\r\nUSE [?]  \r\niNSERT iNTO #TEMP\r\nSELECT\r\n\'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +\r\n\'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +\r\n\'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +\r\n\'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )\r\nFROM\r\nsys.database_permissions\r\nWHERE\r\nSTATE_DESC like \'\'\'\'%WITH_GRANT%\'\'\'\'\r\n;\r\n\'\'\r\nselect  count(*)  from #TEMP;\r\n\' ','== 0','','execute sp_executesql N\'\r\nCREATE TABLE #TEMP  ( row varchar(500));\r\n\r\nexec sp_msforeachdb \'\'\r\nUSE [?]  \r\niNSERT iNTO #TEMP\r\nSELECT\r\n\'\'\'\' DB Name : \'\'\'\'+ DB_NAME()  +\r\n\'\'\'\' Permission Name : \'\'\'\' + PERMiSSiON_NAME +\r\n\'\'\'\' Schema Name : \'\'\'\' + Coalesce (OBJECT_SCHEMA_NAME(MAJOR_iD),\'\'\'\' \'\'\'\' ) +\r\n\'\'\'\' Object Name : \'\'\'\' + Coalesce (OBJECT_NAME(MAJOR_iD) ,\'\'\'\' \'\'\'\' )\r\nFROM\r\nsys.database_permissions\r\nWHERE\r\nSTATE_DESC like \'\'\'\'%WITH_GRANT%\'\'\'\'\r\n;\r\n\'\'\r\nselect * from #TEMP;\r\n\' ','There are no permissions with grant option.\r\n','There are some persmissions  with grant option.\r\n','','2025-12-01 09:03:19','2026-01-11 16:33:38'),(38,'AA_SqlServer_300_No Access To General Extended procedures','mssql','major','PRIV','This test checks for the existence of, and user permissions on, extended stored procedures.  Either these procedures should be completely dropped, or access to them should be strictly limited. xp_cmdshell, xp_enumgroups, xp_grantlogin ,xp_logevent, xp_logininfo,    xp_msver, xp_revokelogin, xp_sprintf, xp_sqlmaint, xp_sscanf\r\n','','SELECT \r\ncount(*) \r\nFROM \r\n  [master].sys.system_objects o \r\n  JOIN [master].sys.database_permissions p ON o.object_id = p.major_id \r\n  JOIN [master].sys.database_principals u ON p.grantee_principal_id = u.principal_id \r\nWHERE \r\n    o.name in ( \r\n	\'xp_cmdshell\', \r\n	\'xp_enumgroups\', \r\n    \'xp_grantlogin\' ,\r\n	\'xp_logevent\', \r\n	\'xp_logininfo\', \r\n    \'xp_msver\', \r\n	\'xp_revokelogin\', \r\n	\'xp_sprintf\', \r\n    \'xp_sqlmaint\', \r\n	\'xp_sscanf\' )\r\n  AND p.type = \'EX\' ','== 0','','SELECT \r\n  \'Principal : \'+u.name  COLLATE DATABASE_DEFAULT +\r\n  \' Extended Procedure Name : \'+o.name COLLATE DATABASE_DEFAULT +\r\n  \' Type : \'+ u.type_desc COLLATE DATABASE_DEFAULT \r\nFROM \r\n  [master].sys.system_objects o \r\n  JOIN [master].sys.database_permissions p ON o.object_id = p.major_id \r\n  JOIN [master].sys.database_principals u ON p.grantee_principal_id = u.principal_id \r\nWHERE \r\n    o.name in ( \r\n	\'xp_cmdshell\', \r\n	\'xp_enumgroups\', \r\n    \'xp_grantlogin\' ,\r\n	\'xp_logevent\', \r\n	\'xp_logininfo\', \r\n    \'xp_msver\', \r\n	\'xp_revokelogin\', \r\n	\'xp_sprintf\', \r\n    \'xp_sqlmaint\', \r\n	\'xp_sscanf\' )\r\n  AND p.type = \'EX\' ','There are no permissions on general extended stored procedures\r\n','There are some persmissions permissions on general extended stored procedures.\r\n','','2025-12-01 09:05:02','2026-01-11 16:50:14'),(39,'AA_SqlServer_310_No Access to OLE Automation procedures','mssql','major','CONFIG','This test checks for the existence of,and user permissions on OLE automation extended stored procedures.  Either these procedures should be completely dropped, or access to them should be strictly limited.      \r\n','','SELECT CAST(value as int) +\r\n       CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Ole Automation Procedures\'   \r\n','== 0','','SELECT CAST(value as int) +\r\n       CAST(value_in_use as int)\r\nFROM sys.configurations\r\nWHERE name = \'Ole Automation Procedures\'\r\n  \r\n','OLE Automation procedures  option is disabled\r\n','OLE Automation procedures  option  is not disabled. Disable this option\r\n','','2025-12-01 09:12:30','2026-01-11 16:33:38'),(40,'AA_SqlServer_320_No Access to Registry Access Extended procedures','mssql','minor','PRIV','This test checks for the existence of, and user permissions on, registry access extended stored procedures.  Either these procedures should be completely dropped, or access to them should be strictly limited. xp_reg%,xp_instance_reg%\r\n','','SELECT \r\ncount(*) \r\nFROM \r\n  [master].sys.system_objects o \r\n  JOIN [master].sys.database_permissions p ON o.object_id = p.major_id \r\n  JOIN [master].sys.database_principals u ON p.grantee_principal_id = u.principal_id \r\nWHERE \r\n( o.name LIKE \'xp_reg%\' OR o.name LIKE \'xp_instance_reg%\')\r\n  AND p.type = \'EX\' ','== 0','','SELECT \r\n  \'Principal : \'+u.name  COLLATE DATABASE_DEFAULT +\r\n  \' Extended Procedure Name : \'+o.name COLLATE DATABASE_DEFAULT +\r\n  \' Type : \'+ u.type_desc COLLATE DATABASE_DEFAULT \r\nFROM \r\n  [master].sys.system_objects o \r\n  JOIN [master].sys.database_permissions p ON o.object_id = p.major_id \r\n  JOIN [master].sys.database_principals u ON p.grantee_principal_id = u.principal_id \r\nWHERE \r\n( o.name LIKE \'xp_reg%\' OR o.name LIKE \'xp_instance_reg%\')\r\n  AND p.type = \'EX\' ','There are no permissions on registry access extended stored procedures\r\n','There are some persmissions permissions on registry access extended stored procedures\r\n','','2025-12-01 09:15:12','2026-02-19 13:21:45'),(41,'AA_SqlServer_330_Revoke public login from SQL Server agent proxy account','mssql','major','PRIV','The public database role contains every user in the msdb database. SQL Agent proxies   define a security context in which a job step can run.Granting access to SQL Agent proxies for the public role would allow all users to utilize the proxy which may have high privileges. This would likely break the principle of least   privileges.\r\n','','SELECT count(*)\r\nFROM msdb.dbo.sysproxylogin spl\r\nJOIN sys.database_principals dp\r\nON dp.sid = spl.sid\r\nJOIN msdb.dbo.sysproxies sp\r\nON sp.proxy_id = spl.proxy_id\r\nWHERE principal_id = USER_ID(\'public\')','== 0','','SELECT \'proxyname : \'+CAST(sp.name  as varchar)\r\nFROM msdb.dbo.sysproxylogin spl\r\nJOIN sys.database_principals dp\r\nON dp.sid = spl.sid\r\nJOIN msdb.dbo.sysproxies sp\r\nON sp.proxy_id = spl.proxy_id\r\nWHERE principal_id = USER_ID(\'public\')','There are no public permissions on SQL Server agent proxy account\r\n','There are some public permissions on SQL Server agent proxy account\r\n','','2025-12-01 09:17:21','2026-01-11 16:33:38'),(42,'AA_SqlServer_340_No Individual User Access To syscomment and sp_helptext','mssql','minor','PRIV','This test checks for grants on SYSCOMMENTS.TEXT.  Such grants allow any user to read the text comments associated with a database object, making the text publicly viewable.\r\n','','SELECT count(*)\r\nFROM msdb.dbo.sysproxylogin spl\r\nJOIN sys.database_principals dp\r\nON dp.sid = spl.sid\r\nJOIN msdb.dbo.sysproxies sp\r\nON sp.proxy_id = spl.proxy_id\r\nWHERE principal_id = USER_ID(\'public\')\r\n','== 0','','SELECT count(*)\r\nFROM msdb.dbo.sysproxylogin spl\r\nJOIN sys.database_principals dp\r\nON dp.sid = spl.sid\r\nJOIN msdb.dbo.sysproxies sp\r\nON sp.proxy_id = spl.proxy_id\r\nWHERE principal_id = USER_ID(\'public\')','There are no public permissions on SQL Server agent proxy account','There are some public permissions on SQL Server agent proxy account','','2025-12-01 09:19:41','2026-01-11 16:33:38'),(43,'AA_SqlServer_350_User Password Policy Is Checked','mssql','critical','ACCOUNT','This test checks that CHECK_POLICY is enabled for all users.  Enabling CHECK_POLICY ensures that Windows passwords policies are enforced.','','select count(*) from sys.sql_logins  \r\nwhere \r\nis_policy_checked=0 and\r\nname not like \'##%\'','== 0','','select name from sys.sql_logins  \r\nwhere \r\nis_policy_checked=0 and\r\nname not like \'##%\'','CHECK_POLICY is enabled for all users','CHECK_POLICY is not enabled for all users','','2025-12-01 09:24:24','2026-01-11 16:33:38'),(44,'AA_SqlServer_360_CHECK_EXPIRATION Is Checked','mssql','critical','ACCOUNT','This test checks that CHECK_EXPIRATION is enabled for all users.  Passwords that have been in use for long periods of time are likely to become known to unauthorized users.\r\n','','select count(*) from sys.sql_logins     where    is_expiration_checked=0 and   name not like \'##%\'\r\n','== 0','','select name from sys.sql_logins     where    is_expiration_checked=0 and   name not like \'##%\'\r\n','CHECK_EXPIRATION is enabled for all users\r\n','CHECK_EXPIRATION is not enabled for all users\r\n','','2025-12-01 09:53:41','2026-01-11 16:33:38'),(45,'AA_Oracle_001_Version','oracle','critical','PATCH','This test cheks Database version whether is acceptable version.','\r\n','select count(substr(version,1,4)) from v$instance  where substr(version,1,4) > \'12.1\'','== 1','','select version from v$instance','The installed Oracle  version is in acceptable version\r\n','The installed Oracle  version is not acceptable version ; it  is recommended that you upgrade this oracle instance to  at least 12.2 or higher version.','Imported from CSV: tests-cvs.csv','2025-12-18 08:51:45','2026-01-11 16:33:38'),(46,'AA_Oracle_010_SQL92_SECURITY_True','oracle','minor','CONFIG','The SQL92_SECURITY parameter setting TRUE requires that a user must also be granted the SELECT object privilege before being able to perform UPDATE or DELETE operations on tables that have WHERE or SET clauses. The setting should have a value of TRUE.   CIS Oracle Database 2.2.16','','SELECT count(*)   FROM V$SYSTEM_PARAMETER   WHERE UPPER(NAME)=\'SQL92_SECURITY\' and UPPER(VALUE) =\'TRUE\'','== 1','','SELECT UPPER(VALUE)   FROM V$SYSTEM_PARAMETER   WHERE UPPER(NAME)=\'SQL92_SECURITY\'','The SQL92_SECURITY  parameter value is acceptable\r\n','The SQL92_SECURITY  parameter value is  not  acceptable. The parameter must be TRUE','Imported from CSV: tests-cvs.csv','2025-12-18 08:51:45','2026-02-19 12:41:48'),(47,'AA_Oracle_020_UTL_FILE_DIR','oracle','critical','CONFIG','This test checks the value of the UTL_FILE_DIR parameter.  The UTL_FILE package allows host file access from within the database using the permissions and privileges assigned to the Oracle database process or service.  This package should be used with caution.  All files accessible to using this package are equally accessible to any database user with execute permissions to the UTL_FILE package.  When UTL_FILE_DIR is set to \'*\', then all directories accessible to the Oracle database process, typically the Oracle installation account, are accessible via the UTL_FILE package This setting effectively turns off directory access checking, and makes any directory accessible to the UTL_FILE functions. The UTL_FILE_DIR list should specify only authorized and protected directories and should not include only fully specified path names.','','SELECT COUNT (*)     FROM V$PARAMETER    WHERE      UPPER (VALUE) LIKE \'%*%\'          AND UPPER (NAME) = \'UTL_FILE_DIR\'','== 0','',' SELECT  \'PARAMETER NAME: \'||NAME ||\'   VALUE : \'||VALUE     FROM V$PARAMETER    WHERE UPPER (NAME)= \'UTL_FILE_DIR\'','The UTL_FILE_DIR  parameter value is acceptable\r\n','The  UTL_FILE_DIR parameter value is  not  acceptable. The parameter must not contain * ','Imported from CSV: tests-cvs.csv','2025-12-18 08:51:45','2026-01-11 16:33:38'),(48,'AA_Oracle_030_GLOBAL_NAME_True','oracle','minor','CONFIG','This test checks the value of the GLOBAL_NAMES parameter.  The GLOBAL_NAMES parameter specifies the requirement to use the full Oracle global name in order to reference it in a database link.  Requiring the full global name protects remote database from inadvertent access. CIS Oracle Database 2.2.3','','SELECT count(*)   FROM V$SYSTEM_PARAMETER   WHERE UPPER(NAME)=\'GLOBAL_NAMES\' and UPPER(VALUE) =\'TRUE\'','== 1','','SELECT UPPER(VALUE)   FROM V$SYSTEM_PARAMETER   WHERE UPPER(NAME)=\'GLOBAL_NAMES\' ','The GLOBAL_NAMES parameter value is acceptable\r\n','The GLOBAL_NAMES  parameter value is  not  acceptable. The parameter must be TRUE','Imported from CSV: tests-cvs.csv','2025-12-18 08:51:45','2026-01-11 16:33:38'),(49,'AA_Oracle_040_O7_DICTIONARY_ACCESSIBILITY_False','oracle','major','CONFIG','This test checks the value of the O7_DICTIONARY_ACCESSIBILITY parameter.  Oracle 8 provides the parameter O7_DICTIONARY_ACCESSIBILITY to prevent accounts with the privilege SELECT ANY TABLE from selecting the data dictionary tables. Setting this parameter to FALSE helps restrict access to sensitive data in the data dictionary such as the encrypted passwords.    CIS 2.2.10','','SELECT count(*)   FROM V$SYSTEM_PARAMETER   WHERE UPPER(NAME)=\'O7_DICTIONARY_ACCESSIBILITY\' and UPPER(VALUE) =\'FALSE\'','== 1','','SELECT UPPER(VALUE)   FROM V$SYSTEM_PARAMETER   WHERE UPPER(NAME)=\'O7_DICTIONARY_ACCESSIBILITY\'','The O7_DICTIONARY_ACCESSIBILITY parameter value is acceptable\r\n','The O7_DICTIONARY_ACCESSIBILITY  parameter value is  not  acceptable. The parameter must be FALSE','Imported from CSV: tests-cvs.csv','2025-12-18 08:51:45','2026-01-11 16:41:06'),(50,'AA_Oracle_050_OS_ROLES_False','oracle','minor','CONFIG','This test checks the value of the OS_ROLES parameter.  The OS_ROLES configuration parameter, when enabled, allows permissions to be granted by OS group membership, which is controlled outside of the database access controls.   CIS 2.2.5','','SELECT count(*)   FROM V$SYSTEM_PARAMETER   WHERE UPPER(NAME)=\'OS_ROLES\' and UPPER(VALUE) =\'FALSE\'','== 1','','SELECT UPPER(VALUE)   FROM V$SYSTEM_PARAMETER   WHERE UPPER(NAME)=\'OS_ROLES\'','The OS_ROLES parameter value is acceptable\r\n','The OS_ROLES  parameter value is  not  acceptable. The parameter must be FALSE','Imported from CSV: tests-cvs.csv','2025-12-18 08:51:45','2026-01-11 16:33:38'),(51,'AA_Oracle_060_REMOTE_OS_AUTHENT_False','oracle','minor','CONFIG','This test checks the value of the REMOTE_OS_AUTHENT parameter.  Setting this value to TRUE allows operating system authentication over an insecure connection. Trusting remote operating systems can allow a user to impersonate another operating system user and connect to the database without having to supply a password. If REMOTE_OS_AUTHENT is set to true, the only information a remote user needs to connect to the database is the name of any user whose account is setup to be authenticated by the operating system.    CIS 2.2.8','','SELECT count(*)   FROM V$SYSTEM_PARAMETER   WHERE UPPER(NAME)=\'REMOTE_OS_AUTHENT\' and UPPER(VALUE) =\'FALSE\'','== 1','','SELECT UPPER(VALUE)   FROM V$SYSTEM_PARAMETER   WHERE UPPER(NAME)=\'REMOTE_OS_AUTHENT\'','The REMOTE_OS_AUTHENT parameter value is acceptable\r','The REMOTE_OS_AUTHENT  parameter value is  not  acceptable. The parameter must be FALSE','Imported from CSV: tests-cvs.csv','2025-12-18 08:51:45','2026-01-11 16:33:38'),(52,'AA_Oracle_070_REMOTE_OS_ROLES_False','oracle','minor','CONFIG','This test checks the value of the REMOTE_OS_ROLES parameter.  Setting REMOTE_OS_ROLES to TRUE allows operating system groups to control Oracle roles. The default value of FALSE causes roles to be identified and managed by the database. If REMOTE_OS_ROLE is set to TRUE, a remote user could impersonate another operating system user over a network connection. It is a security risk to use operating system role authentication for network clients.   CIS 2.2.9','','SELECT count(*)   FROM V$SYSTEM_PARAMETER   WHERE UPPER(NAME)=\'REMOTE_OS_ROLES\' and UPPER(VALUE) =\'FALSE\'','== 1','','SELECT UPPER(VALUE)   FROM V$SYSTEM_PARAMETER   WHERE UPPER(NAME)=\'REMOTE_OS_ROLES\'','The REMOTE_OS_ROLES parameter value is acceptable\r','The REMOTE_OS_ROLES  parameter value is  not  acceptable. The parameter must be FALSE','Imported from CSV: tests-cvs.csv','2025-12-18 08:51:45','2026-01-11 16:33:38'),(53,'AA_Oracle_080_RESOURCE_LIMIT_True','oracle','minor','CONFIG','This test checks the value of the RESOURCE_LIMIT parameter.  If Oracle resource limits are disabled (set to FALSE), any profile limits that are set will be ignored.  NOTE: This does not apply to password resources.   CIS Oracle Database 2.2.18','','SELECT count(*)   FROM V$SYSTEM_PARAMETER   WHERE UPPER(NAME)=\'RESOURCE_LIMIT\' and UPPER(VALUE) =\'TRUE\'','== 1','','SELECT UPPER(VALUE)   FROM V$SYSTEM_PARAMETER   WHERE UPPER(NAME)=\'RESOURCE_LIMIT\'','The RESOURCE_LIMIT parameter value is acceptable\r','The RESOURCE_LIMIT  parameter value is  not  acceptable. The parameter must be TRUE','Imported from CSV: tests-cvs.csv','2025-12-18 08:51:45','2026-01-11 16:33:38'),(54,'AA_Oracle_090__TRACE_FILES_PUBLIC_False','oracle','major','CONFIG','This test checks the value of the _TRACE_FILES_PUBLIC parameter.  The _TRACE_FILES_PUBLIC parameter is used to make trace files used for debugging database applications and events available to all database users. Use of this capability precludes the discrete assignment of privileges based on job function.  Additionally, its use may provide access to external files and data to unauthorized users. The value for the _TRACE_FILES_PUBLIC parameter by default is false when it is not set.   If the parameter does not exist or is set to FALSE, this is not a finding.      CIS 2.2.17','','select sum(a) from    ( SELECT count(*) a   FROM V$SYSTEM_PARAMETER   WHERE UPPER(NAME) = \'_TRACE_FILES_PUBLIC\'    union all   SELECT count(*) a   FROM V$SYSTEM_PARAMETER   WHERE UPPER(NAME)=\'_TRACE_FILES_PUBLIC\' and value=\'FALSE\')','!= 1','','SELECT UPPER(VALUE)   FROM V$SYSTEM_PARAMETER   WHERE UPPER(NAME)=\'_TRACE_FILES_PUBLIC\'','The _TRACE_FILES_PUBLIC parameter value is acceptable\r\n','The _TRACE_FILES_PUBLIC  parameter value is  not  acceptable. The parameter must be FALSE  or must not be defined','Imported from CSV: tests-cvs.csv','2025-12-18 08:51:45','2026-01-11 16:33:38'),(55,'AA_Oracle_110_PASSWORD_VERIFY_FUNCTION','oracle','critical','ACCOUNT','This test checks the value of the PASSWORD_VERIFY_FUNCTION parameter for all profiles.  The PASSWORD_VERIFY_FUNCTION value specifies a PL/SQL function to be used for password verification when users who are assigned this profile login to a database. This function can be used to validate password strength by requiring passwords to pass a strength test written in PL/SQL. The function must be locally available for execution on the database to which this profile applies. Oracle provides a default script (utlpwdmg.sql), but you can also create your own function. The password verification function must be owned by SYS. The default setting for this profile parameter is NULL, meaning no password verification is performed.   CIS Oracle Database 3.8','','SELECT count(*)   FROM DBA_PROFILES   WHERE RESOURCE_NAME=\'PASSWORD_VERIFY_FUNCTION\'   AND (LIMIT = \'DEFAULT\' OR LIMIT = \'NULL\' OR LIMIT is NULL)','== 0','','SELECT \'Profile: \'||PROFILE||\' Resource Name: \'||RESOURCE_NAME   FROM DBA_PROFILES   WHERE RESOURCE_NAME=\'PASSWORD_VERIFY_FUNCTION\'   AND (LIMIT = \'DEFAULT\' OR LIMIT = \'NULL\'   OR LIMIT is NULL )','The PASSWORD_VERIFY_FUNCTION parameter is correctly set for all profiles\r','The PASSWORD_VERIFY_FUNCTION parameter is  not correctly set','Imported from CSV: tests-cvs.csv','2025-12-18 08:51:45','2026-01-11 16:33:38'),(56,'AA_Oracle_120_Only DBA Access To LINK$','oracle','major','PRIV','This test checks for users or roles with permission to SYS.LINK$ table.  Access to table SYS.LINK$ should be restricted because database link passwords are stored unencrypted in this table. This test excludes privileges granted to the system predefined grantee (DBA, SYS, SYSTEM, DV_SECANALYST).  Grantee with DBA roles is also excluded.   CIS Oracle Database 4.5.3','','SELECT COUNT (*)     FROM DBA_TAB_PRIVS    WHERE TABLE_NAME = \'LINK$\'  and GRANTEE not in (\'DV_SECANALYST\')','== 0','','SELECT \'Grantee : \'||GRANTEE||\' , \'||\'PRIVILEGE : \'||PRIVILEGE   FROM DBA_TAB_PRIVS   WHERE TABLE_NAME=\'LINK$\' and GRANTEE not in (\'DV_SECANALYST\')','The LINK$  table grant is correctly set .\r\n','The LINK$  table grant is not correctly set . Revoke all grants fron this table.','Imported from CSV: tests-cvs.csv','2025-12-18 08:51:45','2026-02-19 12:43:31'),(57,'AA_Oracle_130_11_No authorization to BECOME USER','oracle','major','PRIV','This test checks for grants to users of the system privilege BECOME USER . This privilege allows a user to inherit or alter the rights of another Oracle user; this is a powerful privilege that should only be granted when absolutely necessary.   CIS Oracle Database 4.5.3','','SELECT count(*)   FROM DBA_SYS_PRIVS   WHERE PRIVILEGE=\'BECOME USER\'   AND GRANTEE NOT IN (\'DBA\',\'SYS\',\'IMP_FULL_DATABASE\')','== 0','','SELECT \'Grantee : \'||GRANTEE||\', Privilege : \'||PRIVILEGE    FROM DBA_SYS_PRIVS   WHERE PRIVILEGE=\'BECOME USER\'   AND GRANTEE NOT IN (\'DBA\',\'SYS\',\'IMP_FULL_DATABASE\')','The  BECOME USER  grant is correctly set .\r\n','The  BECOME USER grant is not correctly set . ','Imported from CSV: tests-cvs.csv','2025-12-18 08:51:45','2026-02-19 12:43:47'),(58,'AA_Oracle_130_12_No authorization to BECOME USER','oracle','minor','PRIV','This test checks for grants to users of the system privilege BECOME USER . This privilege allows a user to inherit or alter the rights of another Oracle user; this is a powerful privilege that should only be granted when absolutely necessary.   CIS Oracle Database 5.2.9','','SELECT count(*)     FROM DBA_SYS_PRIVS    WHERE     PRIVILEGE = \'BECOME USER\'          AND GRANTEE NOT IN (SELECT USERNAME                                FROM DBA_USERS                               WHERE ORACLE_MAINTAINED = \'Y\')          AND GRANTEE NOT IN (SELECT ROLE                                FROM DBA_ROLES                               WHERE ORACLE_MAINTAINED = \'Y\')          AND GRANTEE not in (\'ETL\')','== 0','','SELECT \'Grantee : \'||GRANTEE||\', Privilege : \'||PRIVILEGE      FROM DBA_SYS_PRIVS    WHERE     PRIVILEGE = \'BECOME USER\'          AND GRANTEE NOT IN (SELECT USERNAME                                FROM DBA_USERS                               WHERE ORACLE_MAINTAINED = \'Y\')          AND GRANTEE NOT IN (SELECT ROLE                                FROM DBA_ROLES                               WHERE ORACLE_MAINTAINED = \'Y\')           AND GRANTEE not in (\'ETL\')','The  BECOME USER  grant is correctly set .\r','The  BECOME USER grant is not correctly set . ','Imported from CSV: tests-cvs.csv','2025-12-18 08:51:45','2026-01-11 16:33:38'),(59,'AA_Oracle_140_11_No authorization to ALTER USER','oracle','major','PRIV','This test checks for grants to users of the system privilege ALTER USER . This privilege allows a user to inherit or alter the rights of another Oracle user; this is a powerful privilege that should only 