--
-- Table structure for table `datasources`
--

DROP TABLE IF EXISTS `datasources`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `datasources` (
  `ds_id` int NOT NULL AUTO_INCREMENT,
  `ds_name` varchar(150) NOT NULL,
  `description` varchar(500) DEFAULT NULL,
  `db_type` enum('oracle','mssql','postgres','mysql') NOT NULL,
  `host` varchar(255) NOT NULL,
  `port` int NOT NULL,
  `auth_mode` enum('sql','windows') NOT NULL DEFAULT 'sql',
  `domain_user_id` int unsigned DEFAULT NULL,
  `domain` varchar(150) DEFAULT NULL,
  `username` varchar(128) DEFAULT NULL,
  `password` varchar(255) DEFAULT NULL,
  `instance_name` varchar(200) DEFAULT NULL,
  `database_name` varchar(200) DEFAULT NULL,
  `oracle_service_name` varchar(200) DEFAULT NULL,
  `oracle_sid` varchar(100) DEFAULT NULL,
  `connection_property` varchar(500) DEFAULT NULL,
  `custom_url` varchar(500) DEFAULT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`ds_id`),
  UNIQUE KEY `ds_name` (`ds_name`),
  KEY `ix_ds_type` (`db_type`),
  KEY `ix_ds_host` (`host`,`port`),
  KEY `fk_datasources_domain_user` (`domain_user_id`),
  CONSTRAINT `fk_datasources_domain_user` FOREIGN KEY (`domain_user_id`) REFERENCES `domain_users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=19 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

